+import { Link } from 'react-router-dom';
+
+import { ROUTES } from '@/constants/routes';
+import type { DegreeDTO } from '@/model/DegreeDTO';
+import type { ItemDTO } from '@/model/TrainingDepartureDTO';
+import { InfoPopover } from '@/components/ui/popover/InfoPopover';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+import { DEGREE_TYPE_LABELS } from '../../LearnerCertificatesList/constants';
+
+import './CandidateDegreeListPopover.scss';
+
+interface CandidateDegreeListPopoverProps {
+  learnerId: string;
+  degrees: DegreeDTO[];
+  equivalences: ItemDTO[] | null;
+}
+
+export function CandidateDegreeListPopover({
+  learnerId,
+  degrees,
+  equivalences,
+}: Readonly<CandidateDegreeListPopoverProps>) {
+  const listHasMoreThanFiveElements = degrees.length > 5;
+
+  const degreesList = listHasMoreThanFiveElements ? degrees.slice(4) : degrees;
+
+  return (
+    <InfoPopover
+      triggerLabel="Afficher la liste des diplômes"
+      iconName="FileText"
+    >
+      <div className="CandidateDegreeList CandidateDegreeList__popover">
+        <InfoPopover.Close
+          ariaLabel="Fermer la liste des diplômes"
+          className="CandidateDegreeList__buttonClose"
+        >
+          <SvgIcon name="XIcon" />
+        </InfoPopover.Close>
+
+        <ul className="CandidateDegreeList__content__list">
+          {degreesList.map((degree) => {
+            return (
+              <li
+                key={degree.id}
+                className="CandidateDegreeList__content__list__item"
+              >
+                {`${DEGREE_TYPE_LABELS[degree.type]} - [${degree.blocCode}] - ${degree.blocDescription}`}
+              </li>
+            );
+          })}
+
+          {equivalences?.map((equivalence) => {
+            return (
+              <li
+                key={equivalence.id}
+                className="CandidateDegreeList__content__list__item"
+              >
+                {`[${equivalence.code}] (E) - ${equivalence.name}`}
+              </li>
+            );
+          })}
+        </ul>
+
+        <Link
+          to={`${ROUTES.learner.path}/${learnerId}/diplomes-certificats`}
+          className="CandidateDegreeList__content__link"
+        >
+          Voir la fiche de l'apprenant pour plus d'informations
+        </Link>
+      </div>
+    </InfoPopover>
+  );
+}

