+import { describe, beforeEach, afterEach, test, expect } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import CostsSummary, { type CostsSummaryProps } from '../CostsSummary';
+import costs from '@/mocks/costs.json';
+
+const defaultProps: CostsSummaryProps = {
+  loading: false,
+  apiErrors: null,
+  costs: costs.content as CostsSummaryProps['costs'],
+  currentEntity: 'modulePath',
+  updateCosts: vi.fn(),
+};
+
+function renderComponent(props = defaultProps) {
+  return render(<CostsSummary {...props} />);
+}
+
+describe('CostsSummary', () => {
+  beforeEach(() => {
+    vi.useFakeTimers();
+    vi.setSystemTime(new Date('2021-07-24T00:00:00.000Z'));
+  });
+
+  afterEach(() => {
+    vi.useRealTimers();
+  });
+
+  test('should render', async () => {
+    await renderComponent();
+
+    await expect
+      .element(page.getByRole('columnheader', { name: /coût pédagogique/i }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByRole('columnheader', { name: /frais de vie/i }))
+      .toBeInTheDocument();
+    await expect.element(page.getByRole('columnheader', { name: /salaire/i })).toBeInTheDocument();
+    await expect
+      .element(page.getByRole('columnheader', { name: /allocations/i }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByRole('columnheader', { name: /charges sociales/i }))
+      .toBeInTheDocument();
+    await expect.element(page.getByRole('columnheader', { name: /total/i })).toBeInTheDocument();
+
+    await expect.element(page.getByRole('rowheader', { name: 'TOTAL' })).toBeInTheDocument();
+    await expect.element(page.getByText('4 398 €')).toBeInTheDocument();
+  });
+
+  test('should render "environ 2 ans" on the mostRecentUpdate date', async () => {
+    vi.setSystemTime(new Date('2021-09-24T00:00:00.000Z'));
+    await renderComponent();
+
+    await expect
+      .element(
+        page.getByRole('button', {
+          name: /environ 2 ans/i,
+        }),
+      )
+      .toBeInTheDocument();
+  });
+
+  test('should render "plus de 2 ans" on the mostRecentUpdate date', async () => {
+    vi.setSystemTime(new Date('2021-12-24T00:00:00.000Z'));
+    await renderComponent();
+
+    await expect
+      .element(
+        page.getByRole('button', {
+          name: /plus de 2 ans/i,
+        }),
+      )
+      .toBeInTheDocument();
+  });
