+import { Link } from 'react-router-dom';
+
+import type { TrainingDTO } from '@/model/TrainingEligibilityDTO';
+import { ROUTES } from '@/constants/routes';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+import { Tooltip } from '@/components/ui/tooltip/Tooltip';
+import { TargetPath } from '@/model/BillingEnum';
+
+interface ViewTrainingLinkProps {
+  item: TrainingDTO;
+}
+
+export function ViewTrainingLink({ item }: Readonly<ViewTrainingLinkProps>) {
+  let trainingUrl: string;
+
+  if (item.type === TargetPath.EVALUATION) {
+    trainingUrl = `${ROUTES.evaluation.path}/${item.id}`;
+  } else {
+    trainingUrl = `${ROUTES.modulePath.path}/${item.id}`;
+  }
+
+  const viewLabel = item.type === TargetPath.EVALUATION ? "Voir l'évaluation" : 'Voir le module';
+
+  const noAccessLabel =
+    item.type === TargetPath.EVALUATION
+      ? "Vous n'avez pas accès à cette évaluation"
+      : "Vous n'avez pas accès à ce module";
+
+  return item.id ? (
+    <Link
+      to={trainingUrl}
+      className="TableView__cell__link"
+      aria-label={viewLabel}
+      title={viewLabel}
+      target="_blank"
+      rel="noopener noreferrer"
+    >
+      <SvgIcon name="Eye" />
+    </Link>
+  ) : (
+    <Tooltip
+      content={noAccessLabel}
+      placement="left"
+      asChild
+    >
+      <button
+        type="button"
+        className="TableView__cell__button"
+        aria-label={noAccessLabel}
+      >
+        <SvgIcon
+          name="Eye"
+          fill="currentColor"
+        />
+      </button>
+    </Tooltip>
+  );
+}

