+
+import { Tooltip } from '../Tooltip';
+
+describe('<Tooltip />', () => {
+  test('renders children inside the trigger', async () => {
+    await render(
+      <Tooltip
+        ariaLabel="Display more information"
+        content="Tooltip content"
+        delay={0}
+      >
+        Trigger label
+      </Tooltip>,
+    );
+
+    await expect
+      .element(page.getByRole('button', { name: 'Display more information' }))
+      .toBeInTheDocument();
+    await expect.element(page.getByText('Trigger label')).toBeInTheDocument();
+  });
+
+  test('shows tooltip content on hover than hides on unhover', async () => {
+    await render(
+      <Tooltip
+        ariaLabel="Display more information"
+        content="Tooltip content"
+        delay={0}
+      >
+        Trigger label
+      </Tooltip>,
+    );
+
+    const trigger = page.getByRole('button', { name: 'Display more information' });
+
+    await trigger.hover();
+    await expect.element(page.getByRole('tooltip', { name: 'Tooltip content' })).toBeVisible();
+
+    await trigger.unhover();
+    await expect
+      .element(page.getByRole('tooltip', { name: 'Tooltip content' }))
+      .not.toBeInTheDocument();
+  });
+
+  test('shows tooltip content when using an external trigger with asChild', async () => {
+    await render(
+      <Tooltip
+        asChild
+        content="Tooltip content"
+        delay={0}
+      >
+        <button type="button">External trigger</button>
+      </Tooltip>,
+    );
+
+    const trigger = page.getByRole('button', { name: 'External trigger' });
+
+    await expect.element(trigger).toBeInTheDocument();
+    await trigger.hover();
+    await expect.element(page.getByRole('tooltip', { name: 'Tooltip content' })).toBeVisible();
+  });
+
+  test('returns children without tooltip trigger when content is empty', async () => {
+    await render(
+      <Tooltip content="">
+        <span>Trigger label</span>
+      </Tooltip>,
+    );
+
+    await expect.element(page.getByText('Trigger label')).toBeInTheDocument();
+    await expect.element(page.getByRole('button')).not.toBeInTheDocument();
+    await expect.element(page.getByRole('tooltip')).not.toBeInTheDocument();
+  });
+});

