+import { Tooltip as TooltipPrimitive } from '@base-ui/react/tooltip';
+import cs from 'classnames';
+
+import type { Side } from '../baseUiTypes';
+import { ArrowSvg } from '@/components/ui/svg/base-ui/ArrowSvg';
+
+import './Tooltip.scss';
+
+interface BaseTooltipProps {
+  content: React.ReactNode;
+  placement?: Side;
+  delay?: number;
+  className?: string;
+}
+
+type TooltipProps = BaseTooltipProps &
+  (
+    | {
+        /**
+         * When true, merges trigger props onto the child element instead of wrapping it in a button.
+         * Use this when children is already an interactive element. Default to false.
+         */
+        asChild: true;
+        children: React.ReactElement;
+        ariaLabel?: never;
+        triggerClassName?: never;
+      }
+    | {
+        asChild?: false;
+        children: React.ReactNode;
+        ariaLabel?: string;
+        triggerClassName?: string;
+      }
+  );
+
+export function Tooltip({
+  children,
+  content: tooltipContent,
+  placement = 'top',
+  delay = 300,
+  className,
+  ariaLabel,
+  asChild = false,
+  triggerClassName,
+}: Readonly<TooltipProps>) {
+  if (!tooltipContent) {
+    return children;
+  }
+
+  return (
+    <TooltipPrimitive.Provider>
+      <TooltipPrimitive.Root>
+        {asChild ? (
+          <TooltipPrimitive.Trigger
+            render={children as React.ReactElement}
+            delay={delay}
+          />
+        ) : (
+          <TooltipPrimitive.Trigger
+            className={cs('Tooltip__trigger', triggerClassName)}
+            delay={delay}
+            aria-label={ariaLabel}
+          >
+            {children}
+          </TooltipPrimitive.Trigger>
+        )}
+        <TooltipPrimitive.Portal>
+          <TooltipPrimitive.Positioner
+            className="Tooltip__positioner"
+            side={placement}
+            sideOffset={10}
+          >
+            <TooltipPrimitive.Popup
+              role="tooltip"
+              className={cs('Tooltip__popup', className)}
+            >
+              <TooltipPrimitive.Arrow className="Arrow">
+                <ArrowSvg />
+              </TooltipPrimitive.Arrow>
+              {tooltipContent}
+            </TooltipPrimitive.Popup>
+          </TooltipPrimitive.Positioner>
+        </TooltipPrimitive.Portal>
+      </TooltipPrimitive.Root>
+    </TooltipPrimitive.Provider>
+  );
+}

