+import { describe, expect, test, vi } from 'vitest';
+import { page } from 'vitest/browser';
+import { render } from 'vitest-browser-react';
+import type { RegisterOptions } from 'react-hook-form';
+import { useForm } from 'react-hook-form';
+
+import { renderWithForm } from '@/test/browser-test-utils/renderWithForm';
+import type { LabelAndValueType } from '@/helpers/commonTypes';
+import { InputCheckboxGroupV2 } from '../InputCheckboxGroupV2';
+
+type FormValues = {
+  trainingModes: string[];
+};
+
+type InputCheckboxGroupV2FormProps = {
+  options?: LabelAndValueType[];
+  defaultValues?: FormValues;
+  onSubmit?: (data: FormValues) => void | Promise<void>;
+  rules?: RegisterOptions<FormValues, 'trainingModes'>;
+};
+
+const defaultOptions = [
+  { label: 'On-site', value: 'onsite' },
+  { label: 'Remote', value: 'remote' },
+  { label: 'Hybrid', value: 'hybrid', disabled: true },
+] satisfies LabelAndValueType[];
+
+function InputCheckboxGroupV2Form({
+  options = defaultOptions,
+  defaultValues = { trainingModes: [] },
+  onSubmit,
+  rules,
+}: Readonly<InputCheckboxGroupV2FormProps>) {
+  const { control, handleSubmit } = useForm<FormValues>({
+    defaultValues,
+  });
+
+  async function handleFormSubmit(data: FormValues) {
+    await onSubmit?.(data);
+  }
+
+  return (
+    <form onSubmit={handleSubmit(handleFormSubmit)}>
+      <InputCheckboxGroupV2
+        control={control}
+        name="trainingModes"
+        label="Training modes"
+        options={options}
+        rules={rules}
+      />
+      <button type="submit">Submit</button>
+    </form>
+  );
+}
+
+describe('<InputCheckboxGroupV2 />', () => {
+  test('renders the checkbox group and respects initial selected values', async () => {
+    await renderWithForm(
+      <InputCheckboxGroupV2
+        name="trainingModes"
+        label="Training modes"
+        options={defaultOptions}
+      />,
+      {
+        defaultValues: {
+          trainingModes: ['onsite'],
+        },
+      },
+    );
+
+    await expect.element(page.getByRole('group', { name: 'Training modes' })).toBeInTheDocument();
+    await expect.element(page.getByRole('checkbox', { name: 'On-site' })).toBeChecked();
+    await expect.element(page.getByRole('checkbox', { name: 'Remote' })).not.toBeChecked();
+    await expect.element(page.getByRole('checkbox', { name: 'Hybrid' })).toBeDisabled();
+  });
+
+  test('submits the updated selected values after user interactions', async () => {
+    const onSubmit = vi.fn();
+
+    await render(
+      <InputCheckboxGroupV2Form
+        defaultValues={{ trainingModes: ['onsite'] }}
+        onSubmit={onSubmit}
+      />,
+    );
+
+    const onsiteCheckbox = page.getByRole('checkbox', { name: 'On-site' });
+    const remoteCheckbox = page.getByRole('checkbox', { name: 'Remote' });
+
+    await remoteCheckbox.click();
+    await onsiteCheckbox.click();
+    await page.getByRole('button', { name: 'Submit' }).click();
+
+    await expect.element(onsiteCheckbox).not.toBeChecked();
+    await expect.element(remoteCheckbox).toBeChecked();
+
+    expect(onSubmit).toHaveBeenCalledTimes(1);
+    expect(onSubmit).toHaveBeenCalledWith({ trainingModes: ['remote'] });
+  });
+
+  test('submits every checked option when multiple checkboxes are selected', async () => {
+    const onSubmit = vi.fn();
+
+    await render(
+      <InputCheckboxGroupV2Form
+        options={[
+          { label: 'On-site', value: 'onsite' },
+          { label: 'Remote', value: 'remote' },
+          { label: 'Hybrid', value: 'hybrid' },
+        ]}
+        defaultValues={{ trainingModes: [] }}
+        onSubmit={onSubmit}
+      />,
+    );
+
+    const onsiteCheckbox = page.getByRole('checkbox', { name: 'On-site' });
+    const hybridCheckbox = page.getByRole('checkbox', { name: 'Hybrid' });
+    const remoteCheckbox = page.getByRole('checkbox', { name: 'Remote' });
+
+    await onsiteCheckbox.click();
+    await hybridCheckbox.click();
+    await remoteCheckbox.click();
+
+    await expect.element(onsiteCheckbox).toBeChecked();
+    await expect.element(hybridCheckbox).toBeChecked();
+    await expect.element(remoteCheckbox).toBeChecked();
+
+    await page.getByRole('button', { name: 'Submit' }).click();
+
+    await expect
+      .poll(() => onSubmit)
+      .toHaveBeenCalledWith({
+        trainingModes: ['onsite', 'hybrid', 'remote'],
+      });
+  });
+
+  test('shows a validation error when submitted without any selection', async () => {
+    const errorMessageTest = 'Select at least one training mode';
+
+    await render(
+      <InputCheckboxGroupV2Form
+        rules={{
+          validate: function validate(value) {
+            return Array.isArray(value) && value.length > 0 ? true : errorMessageTest;
+          },
+        }}
+      />,
+    );
+
+    const checkboxGroup = page.getByRole('group', { name: 'Training modes' });
+    await page.getByRole('button', { name: 'Submit' }).click();
+
+    await expect.element(checkboxGroup.getByText(errorMessageTest)).toBeVisible();
+  });
+});

