+import type { DocumentFile, FileDTO, OneDriveDocumentFileDTO } from '@/model/FileDTO';
+
+export type DocumentFileData = Pick<
+  FileDTO,
+  | 'createdBy'
+  | 'createdDate'
+  | 'deletable'
+  | 'lastModifiedBy'
+  | 'lastModifiedDate'
+  | 'locked'
+  | 'uploaded'
+> & {
+  label: string;
+  key: string;
+  itemKey: string;
+  local?: boolean;
+  oneDriveId?: string;
+  nodes: DocumentFileData[];
+};
+
+export function formatDocumentFile(data: DocumentFile[]): DocumentFileData[] {
+  if (!data?.length) {
+    return [];
+  }
+  const finalDataArray: DocumentFileData[] = [];
+  const firstItem = data[0];
+
+  if (firstItem && isOneDriveDocumentFileDTO(firstItem)) {
+    if (firstItem.folders.length) {
+      const formattedItem = _formatData(firstItem.folders);
+      finalDataArray.push(...formattedItem);
+    }
+
+    if (firstItem.files.length) {
+      const formattedItem = _formatData(firstItem.files);
+      finalDataArray.push(...formattedItem);
+    }
+  } else if (firstItem && !isOneDriveDocumentFileDTO(firstItem)) {
+    const formattedItem = _formatData(data);
+    finalDataArray.push(...formattedItem);
+  }
+
+  return finalDataArray;
+}
+
+function _formatData(fileItems: DocumentFile[]): DocumentFileData[] {
+  if (!fileItems?.length) {
+    return [];
+  }
+
+  return fileItems.map((item) => {
+    const fileItem = item as FileDTO;
+
+    const formattedData: DocumentFileData = {
+      label: fileItem.name,
+      key: fileItem.id,
+      createdBy: fileItem.createdBy,
+      createdDate: fileItem.createdDate,
+      deletable: fileItem.deletable,
+      lastModifiedBy: fileItem.lastModifiedBy,
+      lastModifiedDate: fileItem.lastModifiedDate,
+      locked: fileItem.locked,
+      uploaded: fileItem.uploaded,
+      itemKey: fileItem.id,
+      nodes: [],
+    };
+
+    if (isOneDriveDocumentFileDTO(item)) {
+      const folderNodes = item.folders.length > 0 ? _formatData(item.folders) : [];
+      const fileNodes = item.files.length > 0 ? _formatData(item.files) : [];
+
+      formattedData.nodes = [...folderNodes, ...fileNodes];
+      formattedData.local = item.local;
+      formattedData.oneDriveId = item.oneDriveId;
+    }
+
+    return formattedData;
+  });
+}
+
+function isOneDriveDocumentFileDTO(file: DocumentFile): file is OneDriveDocumentFileDTO {
+  return file && 'oneDriveId' in file;
+}

