+    await expect.element(page.getByText('Nested')).not.toBeVisible();
+    await expect.element(page.getByText('Deep')).not.toBeVisible();
+
+    await page.getByText('Root').click();
+    await expect.element(page.getByText('Nested')).toBeVisible();
+    await expect.element(page.getByText('Deep')).not.toBeVisible();
+
+    await page.getByText('Nested').click();
+    await expect.element(page.getByText('Deep')).toBeVisible();
+  });
