+import { useState } from 'react';
+import { Accordion } from '@base-ui/react/accordion';
+
+import './_TreeAccordion.scss';
+
+export interface TreeAccordionNode<TNode> {
+  key: string;
+  nodes?: TNode[];
+}
+
+export interface TreeAccordionItemParams<TItem extends TreeAccordionNode<TItem>> {
+  item: TItem;
+  level: number;
+  hasNodes: boolean;
+  isOpen: boolean;
+}
+
+interface TreeAccordionProps<TItem extends TreeAccordionNode<TItem>> {
+  items: TItem[];
+  renderItem: (params: TreeAccordionItemParams<TItem>) => React.ReactNode;
+}
+
+interface TreeAccordionLevelProps<
+  TItem extends TreeAccordionNode<TItem>,
+> extends TreeAccordionProps<TItem> {
+  level: number;
+}
+
+/**
+ * Controlled recursive accordion built on Base UI primitives.
+ * Designed to replace `react-simple-tree-menu` for nested tree structures.
+ *
+ * Exposes open state via `renderItem` so consumers can adapt their UI
+ * (e.g. swap folder icons, show/hide toggles) without managing state themselves.
+ */
+export function TreeAccordion<TItem extends TreeAccordionNode<TItem>>({
+  items,
+  renderItem,
+}: Readonly<TreeAccordionProps<TItem>>) {
+  return (
+    <TreeAccordionLevel
+      items={items}
+      level={0}
+      renderItem={renderItem}
+    />
+  );
+}
+
+function TreeAccordionLevel<TItem extends TreeAccordionNode<TItem>>({
+  items,
+  level,
+  renderItem,
+}: Readonly<TreeAccordionLevelProps<TItem>>) {
+  const [openItems, setOpenItems] = useState<string[]>([]);
+
+  if (!items.length) {
+    return null;
+  }
+
+  return (
+    <Accordion.Root
+      multiple
+      value={openItems}
+      onValueChange={setOpenItems}
+      className="TreeAccordion"
+    >
+      {items.map((item) => {
+        const hasNodes = !!item.nodes?.length;
+        const isOpen = openItems.includes(item.key);
+
+        if (!hasNodes) {
+          return (
+            <div
+              key={item.key}
+              className="TreeAccordion__leaf"
+            >
+              {renderItem({
+                item,
+                level,
+                hasNodes,
+                isOpen: false,
+              })}
+            </div>
+          );
+        }
+
+        return (
+          <Accordion.Item
+            key={item.key}
+            value={item.key}
+            className="TreeAccordion__item"
+          >
+            <Accordion.Header className="TreeAccordion__header">
+              <Accordion.Trigger
+                nativeButton={false}
+                className="TreeAccordion__trigger"
+                render={(triggerProps) => {
+                  // nativeButton set to `false` requires an explicit non-button element via render.
+                  // A <div> is intentional: this accordion wraps full row layouts (block-level),
+                  // which are invalid as children of a <button> per the HTML spec.
+                  return (
+                    <div {...triggerProps}>{renderItem({ item, level, hasNodes, isOpen })}</div>
+                  );
+                }}
+              />
+            </Accordion.Header>
+
+            <Accordion.Panel
+              keepMounted
+              className="TreeAccordion__panel"
+            >
+              <TreeAccordionLevel
+                items={item.nodes ?? []}
+                level={level + 1}
+                renderItem={renderItem}
+              />
+            </Accordion.Panel>
+          </Accordion.Item>
+        );
+      })}
+    </Accordion.Root>
+  );
+}

