+import { describe, expect, test } from 'vitest';
+
+import { isDefaultFilterValue } from '../filterValueGuards';
+
+describe('isDefaultFilterValue()', () => {
+  test('returns false when defaultFilterValue is undefined', () => {
+    expect(isDefaultFilterValue('foo', undefined)).toBe(false);
+  });
+
+  // ----- primitive vs primitive -----
+
+  test('returns true when string values are equal', () => {
+    expect(isDefaultFilterValue('PRESENTIEL', 'PRESENTIEL')).toBe(true);
+  });
+
+  test('returns false when string values differ', () => {
+    expect(isDefaultFilterValue('DISTANCIEL', 'PRESENTIEL')).toBe(false);
+  });
+
+  test('returns true when comparing a number and its string equivalent', () => {
+    expect(isDefaultFilterValue(42, '42')).toBe(true);
+  });
+
+  test('returns true when boolean and its string equivalent match', () => {
+    expect(isDefaultFilterValue(true, 'true')).toBe(true);
+  });
+
+  // ----- array vs array -----
+
+  test('returns true when both arrays have the same items', () => {
+    expect(isDefaultFilterValue(['A', 'B'], ['A', 'B'])).toBe(true);
+  });
+
+  test('returns true when both arrays have the same items in different order', () => {
+    expect(isDefaultFilterValue(['B', 'A'], ['A', 'B'])).toBe(true);
+  });
+
+  test('returns false when arrays differ in content', () => {
+    expect(isDefaultFilterValue(['A', 'C'], ['A', 'B'])).toBe(false);
+  });
+
+  test('returns false when arrays differ in length', () => {
+    expect(isDefaultFilterValue(['A'], ['A', 'B'])).toBe(false);
+  });
+
+  test('returns false when defaultFilterValue is an empty array', () => {
+    expect(isDefaultFilterValue([], [])).toBe(false);
+    expect(isDefaultFilterValue(['A'], [])).toBe(false);
+  });
+
+  // ----- type mismatch -----
+
+  test('returns false when value is an array and defaultFilterValue is a primitive', () => {
+    expect(isDefaultFilterValue(['A'], 'A')).toBe(false);
+  });
+
+  test('returns false when value is a primitive and defaultFilterValue is an array', () => {
+    expect(isDefaultFilterValue('A', ['A'])).toBe(false);
+  });
+});

