+function isPrimitive(val: unknown): val is string | number | boolean {
+  return typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean';
+}
+
+export function isDefaultFilterValue(value: unknown, defaultFilterValue: unknown): boolean {
+  if (defaultFilterValue === undefined) {
+    return false;
+  }
+
+  if (isPrimitive(value) && isPrimitive(defaultFilterValue)) {
+    return String(value) === String(defaultFilterValue);
+  }
+
+  if (Array.isArray(value) && Array.isArray(defaultFilterValue)) {
+    if (defaultFilterValue.length === 0) {
+      return false;
+    }
+
+    if (defaultFilterValue.length !== value.length) {
+      return false;
+    }
+
+    const defaultStrings = new Set(defaultFilterValue.map(String));
+    return value.every((val) => defaultStrings.has(String(val)));
+  }
+
+  return false;
+}

