+import { type Control, useFieldArray } from 'react-hook-form';
+
+import Button from '../../common/Button/Button';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+import type { MarketSegmentInput } from '../types';
+import { MARKET_SEGMENT_OPTIONS } from '@/model/MarketSegment';
+import InputDateV2 from '../../common/InputDate/InputDateV2';
+import InputSelectV2 from '../../common/InputSelect/InputSelectV2';
+
+export type MarketSegmentsInputsFormData = {
+  marketSegmentsInputs: MarketSegmentInput[];
+};
+
+interface MarketSegmentsInputsProps<T extends MarketSegmentsInputsFormData> {
+  control: T extends MarketSegmentsInputsFormData ? Control<T> : never;
+  name: T extends MarketSegmentsInputsFormData ? keyof T : never;
+  disabled?: boolean;
+  required?: boolean;
+}
+
+export function MarketSegmentsInputs<T extends MarketSegmentsInputsFormData>({
+  control: externalControl,
+  name,
+  disabled = false,
+  required = true,
+}: Readonly<MarketSegmentsInputsProps<T>>) {
+  const control = externalControl as Control<MarketSegmentsInputsFormData>;
+
+  const { fields, append, remove } = useFieldArray<MarketSegmentsInputsFormData>({
+    control,
+    name,
+  });
+
+  // ----- rendering -----
+
+  return (
+    <div className="SettingsForm__blockWrapper">
+      {fields.map((field, index) => {
+        return (
+          <div
+            className="SettingsForm__block"
+            key={field.id}
+          >
+            <div className="ModelFormView__row">
+              <InputSelectV2
+                className="ModelFormView__formField"
+                control={control}
+                label="Segment"
+                name={`${name}.${index}.segment`}
+                options={MARKET_SEGMENT_OPTIONS}
+                placeholder="Sélectionner un segment..."
+                disabled={disabled}
+                required={required}
+              />
+
+              <InputDateV2
+                className="ModelFormView__formField"
+                name={`${name}.${index}.startDate`}
+                control={control}
+                label="Date de début"
+                forMoment
+                disabled={disabled}
+                required={required}
+              />
+
+              <InputDateV2
+                className="ModelFormView__formField"
+                name={`${name}.${index}.endDate`}
+                control={control}
+                label="Date de fin"
+                forMoment
+                disabled={disabled}
+                required={required}
+              />
+
+              {(fields.length > 1 || !required) && (
+                <button
+                  type="button"
+                  onClick={() => remove(index)}
+                  className="SettingsForm__deleteBlocListBtn"
+                  title="Supprimer ce segment"
+                >
+                  <SvgIcon
+                    name="CircleX"
+                    size={30}
+                  />
+                </button>
+              )}
+            </div>
+          </div>
+        );
+      })}
+
+      <Button
+        type="button"
+        customClassName="SettingsForm__addAllowance"
+        appearance="blue-default"
+        onClick={() =>
+          append({
+            segment: null,
+            startDate: '',
+            endDate: '',
+          })
+        }
+        disabled={disabled}
+      >
+        <Button.TextIcon>+</Button.TextIcon>
+        <Button.Text>Ajouter un segment</Button.Text>
+      </Button>
+    </div>
+  );
+}

