+import {
+  LabelisationSection,
+  type LabelisationSectionProps,
+} from '../components/LabelisationSection';
+
+const defaultProps: LabelisationSectionProps = {
+  canUpdateLabeling: true,
+  labelings: {},
+  isUserOf: false,
+  marketSegment: 'PM_BUNDLE_1',
+  trainingAgencyId: 'agency-1',
+};
+
+const labelingsWithData: TrainingAgencyLabelingsByMode = {
+  [TrainingMode.PRESENTIEL]: {
+    labelingStatus: 'ALLOWED',
+    startDate: '2024-01-01',
+    endDate: '2025-01-01',
+    territory: [],
+    jurisprudence: [],
+  },
+};
+
+function renderComponent(props = defaultProps) {
+  return renderWithProviders(<LabelisationSection {...props} />, {
+    withQueryClient: true,
+    withRouter: false,
+  });
+}
+
+describe('<LabelisationSection />', () => {
+  test('should not render update button when canUpdateLabeling is false', async () => {
+    await renderComponent({ ...defaultProps, canUpdateLabeling: false });
+
+    await expect
+      .element(page.getByRole('button', { name: /labellisation/i }))
+      .not.toBeInTheDocument();
+  });
+
+  test('should render "Créer" button and empty state when labelings is empty', async () => {
+    await renderComponent();
+
+    await expect
+      .element(page.getByRole('button', { name: 'Créer une labellisation' }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByText('Aucune demande de labellisation en cours'))
+      .toBeInTheDocument();
+  });
+
+  test('should render "Modifier" button and labelings information when labelings has data', async () => {
+    await renderComponent({ ...defaultProps, labelings: labelingsWithData });
+
+    await expect
+      .element(page.getByRole('button', { name: 'Modifier la labellisation' }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByText('Aucune demande de labellisation en cours'))
+      .not.toBeInTheDocument();
+
+    await expect.element(page.getByText('Label : Présentiel')).toBeInTheDocument();
+    await expect
+      .element(page.getByText('Date de validité : du 01-01-2024 au 01-01-2025'))
+      .toBeInTheDocument();
+    await expect.element(page.getByText('Statut : Accordé')).toBeInTheDocument();
+  });
+
+  test('should open modal when update button is clicked and close it when close button is clicked', async () => {
+    await renderComponent();
+
+    await page.getByRole('button', { name: 'Créer une labellisation' }).click();
+
+    const modalHeading = page.getByRole('heading', {
+      name: /créer une demande de labellisation - marché public - lot 1/i,
+    });
+    await expect.element(modalHeading).toBeInTheDocument();
+
+    await page.getByRole('button', { name: /fermer la fenêtre/i }).click();
+    await expect.element(modalHeading).not.toBeInTheDocument();
+  });
+});

