+import { useState } from 'react';
+
+import type { TrainingAgencyLabelingsByMode } from '@/model/TrainingAgencyDTO';
+import { MARKET_SEGMENT, type MarketSegment } from '@/model/MarketSegment';
+import { isEmpty } from '@/helpers/utils/objectUtils';
+import Button from '../../common/Button/Button';
+import { TrainingModeInfosBlocList } from './TrainingModeInfosBlocList';
+import Modal from '../../common/Modal/Modal';
+import { EditLabelingOfForm } from '../ModalForms/EditLabelingOfForm';
+
+export interface LabelisationSectionProps {
+  canUpdateLabeling: boolean;
+  labelings: TrainingAgencyLabelingsByMode | undefined;
+  isUserOf: boolean;
+  marketSegment: MarketSegment;
+  trainingAgencyId: string;
+}
+
+export function LabelisationSection({
+  canUpdateLabeling,
+  labelings = {},
+  isUserOf,
+  marketSegment,
+  trainingAgencyId,
+}: Readonly<LabelisationSectionProps>) {
+  const [isLabelingModalOpen, setLabelingModalOpen] = useState(false);
+
+  // ----- computed -----
+
+  const tabLabel = MARKET_SEGMENT[marketSegment].label;
+
+  const labelingButtonText = isEmpty(labelings)
+    ? 'Créer une labellisation'
+    : 'Modifier la labellisation';
+
+  const editLabelingModalTitle = isEmpty(labelings)
+    ? `Créer une demande de labellisation - ${tabLabel}`
+    : `Modifier la demande de labellisation - ${tabLabel}`;
+
+  return (
+    <>
+      <div className="Of__labeling">
+        <div className="Of__labeling__head">
+          <span className="Of__labeling__title">Labellisation</span>
+          {canUpdateLabeling && (
+            <Button
+              type="button"
+              appearance="blue-default"
+              customClassName="Of__labeling__update"
+              onClick={() => setLabelingModalOpen(true)}
+            >
+              <Button.Icon iconName="Pencil" />
+              <Button.Text>{labelingButtonText}</Button.Text>
+            </Button>
+          )}
+        </div>
+
+        {isEmpty(labelings) ? (
+          <div className="Of__labeling__item Of__labeling__item--empty">
+            <p>Aucune demande de labellisation en cours</p>
+          </div>
+        ) : (
+          <TrainingModeInfosBlocList
+            labelings={labelings}
+            isUserOf={isUserOf}
+          />
+        )}
+      </div>
+
+      <Modal
+        isOpen={isLabelingModalOpen}
+        closeHandler={() => setLabelingModalOpen(false)}
+        contentLabel={editLabelingModalTitle}
+        title={editLabelingModalTitle}
+      >
+        <EditLabelingOfForm
+          labelings={labelings}
+          marketSegment={marketSegment}
+          trainingAgencyId={trainingAgencyId}
+          closeModalHandler={() => setLabelingModalOpen(false)}
+        />
+      </Modal>
+    </>
+  );
+}

