+import { describe, expect, test } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import { Tabs } from '../Tabs';
+
+describe('<Tabs />', () => {
+  test('renders all tab labels', async () => {
+    await render(
+      <Tabs>
+        <Tabs.Item label="Tab One">Content One</Tabs.Item>
+        <Tabs.Item label="Tab Two">Content Two</Tabs.Item>
+        <Tabs.Item label="Tab Three">Content Three</Tabs.Item>
+      </Tabs>,
+    );
+
+    await expect.element(page.getByRole('tab', { name: 'Tab One' })).toBeInTheDocument();
+    await expect.element(page.getByRole('tab', { name: 'Tab Two' })).toBeInTheDocument();
+    await expect.element(page.getByRole('tab', { name: 'Tab Three' })).toBeInTheDocument();
+  });
+
+  test('shows first tab panel by default', async () => {
+    await render(
+      <Tabs>
+        <Tabs.Item label="Tab One">Content One</Tabs.Item>
+        <Tabs.Item label="Tab Two">Content Two</Tabs.Item>
+        <Tabs.Item label="Tab Three">Content Three</Tabs.Item>
+      </Tabs>,
+    );
+
+    await expect.element(page.getByText('Content One')).toBeInTheDocument();
+    await expect.element(page.getByText('Content Two')).not.toBeInTheDocument();
+    await expect.element(page.getByText('Content Three')).not.toBeInTheDocument();
+  });
+
+  test('switches panel on tab click', async () => {
+    await render(
+      <Tabs>
+        <Tabs.Item label="Tab One">Content One</Tabs.Item>
+        <Tabs.Item label="Tab Two">Content Two</Tabs.Item>
+        <Tabs.Item label="Tab Three">Content Three</Tabs.Item>
+      </Tabs>,
+    );
+
+    await page.getByRole('tab', { name: 'Tab Two' }).click();
+
+    await expect.element(page.getByText('Content One')).not.toBeInTheDocument();
+    await expect.element(page.getByText('Content Two')).toBeInTheDocument();
+    await expect.element(page.getByText('Content Three')).not.toBeInTheDocument();
+
+    await page.getByRole('tab', { name: 'Tab Three' }).click();
+
+    await expect.element(page.getByText('Content One')).not.toBeInTheDocument();
+    await expect.element(page.getByText('Content Two')).not.toBeInTheDocument();
+    await expect.element(page.getByText('Content Three')).toBeInTheDocument();
+  });
+
+  test('opens the tab matching defaultValue', async () => {
+    await render(
+      <Tabs defaultValue="1">
+        <Tabs.Item label="Tab One">Content One</Tabs.Item>
+        <Tabs.Item label="Tab Two">Content Two</Tabs.Item>
+        <Tabs.Item label="Tab Three">Content Three</Tabs.Item>
+      </Tabs>,
+    );
+
+    await expect.element(page.getByText('Content One')).not.toBeInTheDocument();
+    await expect.element(page.getByText('Content Two')).toBeInTheDocument();
+    await expect.element(page.getByText('Content Three')).not.toBeInTheDocument();
+  });
+
+  test('flattens items wrapped in Fragments', async () => {
+    const showExtras = true;
+
+    await render(
+      <Tabs>
+        <Tabs.Item label="Tab One">Content One</Tabs.Item>
