+@use '/src/styles/settings' as *;
+
+.Tabs {
+  width: 100%;
+}
+
+.Tabs__list {
+  display: flex;
+  align-items: center;
+  width: 100%;
+  border-bottom: 2px solid $color-secondary;
+  isolation: isolate;
+}
+
+.Tabs__tab {
+  --tabs-slant-size: 1.1rem;
+  --tabs-background-color: #{$color-gallery};
+
+  position: relative;
+  display: block;
+  flex-grow: 1;
+  padding: 1rem 2rem 1rem 1.6rem;
+  margin-left: calc(-1 * var(--tabs-slant-size));
+  font-family: inherit;
+  font-size: 1rem;
+  font-weight: bold;
+  color: $color-saltbox;
+  text-align: center;
+  text-transform: uppercase;
+  cursor: pointer;
+  background-color: transparent;
+  border: none;
+  isolation: isolate;
+  transition: color 200ms ease-out;
+
+  &:before {
+    position: absolute;
+    inset: 0;
+    z-index: -2;
+    content: '';
+    background-color: var(--tabs-background-color);
+    clip-path: polygon(
+      0% 0%,
+      calc(100% - var(--tabs-slant-size)) 0%,
+      100% 100%,
+      var(--tabs-slant-size) 100%
+    );
+    transition: background-color 200ms ease-out;
+  }
+
+  &:after {
+    position: absolute;
+    top: 0;
+    left: 0;
+    z-index: -1;
+    width: calc(var(--tabs-slant-size) + 2px);
+    height: 100%;
+    pointer-events: none;
+    content: '';
+    background-color: $color-white;
+    clip-path: polygon(
+      0% 0%,
+      2px 0%,
+      calc(var(--tabs-slant-size) + 2px) 100%,
+      var(--tabs-slant-size) 100%
+    );
+  }
+
+  &[data-active] {
+    --tabs-background-color: #{$color-secondary};
+    z-index: 1;
+
+    color: $color-white;
+  }
+
+  &:first-child {
+    padding-left: 0.8rem;
+    margin-left: 0;
+
+    &:before {
+      clip-path: polygon(0% 0%, calc(100% - var(--tabs-slant-size)) 0%, 100% 100%, 0% 100%);
