+import { Children, Fragment, isValidElement, type ReactElement } from 'react';
+import { Tabs as BaseTabs } from '@base-ui/react/tabs';
+import cs from 'classnames';
+
+import './Tabs.scss';
+
+interface TabsProps {
+  children: React.ReactNode;
+  className?: string;
+  /**
+   * The default value. Use when the component is not controlled.
+   * When the value is `null`, no Tab will be active.
+   * @default '0'
+   */
+  defaultValue?: string;
+  /**
+   * Whether to keep the HTML element in the DOM while the panel is hidden.
+   * @default false
+   */
+  keepMounted?: boolean;
+}
+
+export function Tabs({
+  children,
+  className,
+  defaultValue = '0',
+  keepMounted = false,
+}: Readonly<TabsProps>) {
+  const items = _flattenItems(children);
+
+  return (
+    <BaseTabs.Root
+      defaultValue={defaultValue}
+      className={cs('Tabs', className)}
+    >
+      <BaseTabs.List className="Tabs__list">
+        {items.map((child, index) => {
+          const value = String(index);
+
+          return (
+            <BaseTabs.Tab
+              key={value}
+              value={value}
+              className="Tabs__tab"
+            >
+              {child.props.label}
+            </BaseTabs.Tab>
+          );
+        })}
+      </BaseTabs.List>
+
+      {items.map((child, index) => {
+        const value = String(index);
+
+        return (
+          <BaseTabs.Panel
+            key={value}
+            value={value}
+            keepMounted={keepMounted}
+            className="Tabs__panel"
+          >
+            {child.props.children}
+          </BaseTabs.Panel>
+        );
+      })}
+    </BaseTabs.Root>
+  );
+}
+
+interface ItemProps {
+  label: string;
+  children?: React.ReactNode;
+}
+
+Tabs.Item = function Item(_props: Readonly<ItemProps>) {
+  // This component is never rendered directly
+  return null;
+};
+
+// Recursively unwraps Fragments so callers can group `Tabs.Item` children
+// with `<>…</>` (e.g. for conditional rendering) without items being dropped.
+function _flattenItems(children: React.ReactNode): ReactElement<ItemProps>[] {
+  return Children.toArray(children).flatMap((child) => {
+    if (!isValidElement(child)) {
+      return [];
+    }
+
+    if (child.type === Fragment) {
+      return _flattenItems((child.props as { children: React.ReactNode }).children);
+    }
+
+    if (child.type === Tabs.Item) {
+      return [child as ReactElement<ItemProps>];
+    }
+
+    return [];
+  });
+}

