+import type { SearchModulePathDTO } from '@/model/ModulePathDTO';
+import type { TableColumn } from '../common/TableView/TableView';
+import type { FilterInput } from '@/model/FilterInput';
+import { ROUTES } from '@/constants/routes';
+import { InputType } from '@/model/InputTypeEnum';
+import { PathStatusLabel } from '@/model/PathStatusEnum';
+import { TrainingModeLabel } from '@/model/TrainingMode';
+import { RoleTypes } from '@/enums/authorization';
+import { usePermissionFromRole } from '@/hooks/usePermissionFromRole';
+import { date } from '@/helpers/formats/formatDateHelpers';
+import CellWithStatusLabel from '../common/TableView/CellWithStatusLabel';
+import CellWithLinkAndTooltipBtn from '../common/TableView/CellWithLinkAndTooltipBtn';
+import { searchModuleHandler } from '@/hooks/data/modules/fetchHandlers/searchModuleHandler';
+import {
+  listFilterModuleSearchInput,
+  listFilterTrainingAgencySearchInput,
+} from '@/inputs-generator/listFilterSearchInputs';
+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import { MarketSegmentTag } from './components/MarketSegmentTag';
+
+export function useModulePathsListTable() {
+  const isAdminUser = usePermissionFromRole([RoleTypes.ADMIN, RoleTypes.SYSTEM, RoleTypes.IPERIA]);
+
+  const canFilterTrainingAgency = usePermissionFromRole([
+    RoleTypes.ADMIN,
+    RoleTypes.SYSTEM,
+    RoleTypes.IPERIA,
+    RoleTypes.SU_UDD,
+  ]);
+
+  const tableColumns: Array<TableColumn<SearchModulePathDTO>> = [
+    {
+      name: 'N°',
+      sortKey: 'code',
+      cellRenderer: ({ code, marketSegment }) => {
+        return (
+          <div>
+            {code}
+            {marketSegment && <MarketSegmentTag marketSegment={marketSegment} />}
+          </div>
+        );
+      },
+      style: {
+        width: '10%',
+      },
+    },
+    {
+      name: 'Parcours module',
+      sortKey: 'module.code',
+      cellRenderer: ({ module }) => `[${module.code ?? '-'}] ${module.description ?? '-'}`,
+      style: {
+        width: '23%',
+      },
+    },
+    {
+      name: 'OF',
+      sortKey: 'trainingAgency.legalPerson.name',
+      contentKey: 'trainingAgency.legalPersonDto.name',
+      visible: isAdminUser,
+      style: {
+        width: '10%',
+      },
+    },
+    {
+      name: 'Date début',
+      sortKey: 'startDate',
+      cellRenderer: ({ startDate }) => date.toFR(startDate, '-'),
+      style: {
+        width: '10%',
+      },
+    },
+    {
+      name: 'Date fin',
+      sortKey: 'endDate',
+      cellRenderer: ({ endDate }) => date.toFR(endDate, '-'),
+      style: {
+        width: '10%',
+      },
+    },
+    {
+      name: 'Villes',
+      sortKey: 'city',
+      cellRenderer: (data) => {
+        const uniqCities: Set<string> = new Set();
+        (data.addresses ?? []).forEach((address) => {
+          uniqCities.add(
+            address.city.toLowerCase().replaceAll(/\b\w/g, (letter) => letter.toUpperCase()),
+          );
+        });
+        return uniqCities.size > 0 ? Array.from(uniqCities).join(', ') : '-';
+      },
+      isSortable: false,
+      style: {
+        width: '10%',
+      },
+    },
+    {
+      name: 'Départements',
+      sortKey: 'departments',
+      cellRenderer: (data) => {
+        const uniqDepartments: Set<string> = new Set();
+        (data.addresses ?? []).forEach((address) => {
+          if (address.department) {
+            uniqDepartments.add(`${address.department.code} - ${address.department.value}`);
+          }
+        });
+        return uniqDepartments.size > 0 ? (
+          <ul>
+            {Array.from(uniqDepartments).map((department) => (
+              <li key={department}>{department}</li>
+            ))}
+          </ul>
+        ) : (
+          '-'
+        );
+      },
+      style: {
+        width: '10%',
+      },
+      isSortable: false,
+    },
+    {
+      name: 'Statut',
+      sortKey: 'status',
+      cellRenderer: (data) => CellWithStatusLabel(data, PathStatusLabel),
+      style: {
+        textAlign: 'center',
+        width: '12%',
+      },
+    },
+    {
+      name: '',
+      sortKey: 'id',
+      cellRenderer: (data) => (
+        <CellWithLinkAndTooltipBtn
+          title="Voir la fiche de ce parcours module"
+          data={data}
+          pathName={ROUTES.modulePath.path}
+        />
+      ),
+      isSortable: false,
+      style: {
+        width: 100,
+      },
+    },
+  ];
+
+  const filterInputs: Array<FilterInput> = [
+    {
+      type: InputType.NUMBER,
+      label: 'N°',
+      name: 'modulePathCode',
+      settings: {
+        decimalScale: 0,
+        allowNegative: false,
+      },
+      blankOption: false,
+    },
+    listFilterModuleSearchInput('moduleId', 'Module', searchModuleHandler),
+
+    ...(canFilterTrainingAgency ? [listFilterTrainingAgencySearchInput('trainingAgencyCode')] : []),
+    {
+      type: InputType.MULTI_SELECT,
+      blankOption: false,
+      label: 'Statut',
+      name: 'statuses',
+      options: getInputSelectOptions(PathStatusLabel),
+      simpleValue: true,
+    },
+    {
+      type: InputType.MULTI_SELECT,
+      blankOption: false,
+      label: 'Type de formation',
+      name: 'types',
+      htmlAttributes: {
+        placeholder: 'Type de formation',
+      },
+      options: getInputSelectOptions(TrainingModeLabel),
+      simpleValue: true,
+    },
+    {
+      type: InputType.DATE,
+      blankOption: false,
+      label: 'Date',
+      name: 'date',
+      forMoment: true,
+    },
+    {
+      type: InputType.DATE,
+      blankOption: false,
+      label: 'De date de début',
+      name: 'startDateMin',
+      forMoment: true,
+    },
+    {
+      type: InputType.DATE,
+      blankOption: false,
+      label: "Jusqu'à date de début",
+      name: 'startDateMax',
+      forMoment: true,
+    },
+    {
+      type: InputType.DATE,
+      blankOption: false,
+      label: 'De date de fin',
+      name: 'endDateMin',
+      forMoment: true,
+    },
+    {
+      type: InputType.DATE,
+      label: "Jusqu'à date de fin",
+      name: 'endDateMax',
+      forMoment: true,
+      blankOption: false,
+    },
+  ];
+
+  return {
+    tableColumns,
+    filterInputs,
+  };
+}

