+import cs from 'classnames';
+
+import type { LabelAndValueType } from '@/helpers/commonTypes';
+
+import './_RadioSlider.scss';
+
+export interface RadioSliderBaseProps<TLabel = React.ReactNode, TValue = string> {
+  /**
+   * The name to set for radio inputs, can be used to retrieve value from a form submission
+   */
+  name: string;
+  /**
+   * An array containing value and label pair for each options of the slider
+   * @note that the value disabled can be set to disable only certain option
+   */
+  options: LabelAndValueType<TLabel, TValue>[];
+  /**
+   * Optional visual label for the entire RadioSlider component.
+   */
+  label?: string;
+  /**
+   * Optional classname to add to the root element
+   */
+  className?: string;
+  /**
+   * Optional if set to true, the all slider will be disabled
+   */
+  disabled?: boolean;
+  /**
+   * Currently selected value — agnostic of the source (RHF, local state, etc.).
+   */
+  selectedValue: TValue | undefined;
+  /**
+   * Called with the new value when the selection changes.
+   */
+  onChange: (value: TValue) => void;
+}
+
+export function RadioSlider<TLabel extends React.ReactNode, TValue extends string>({
+  name,
+  options,
+  className,
+  disabled,
+  selectedValue,
+  onChange,
+  label,
+}: Readonly<RadioSliderBaseProps<TLabel, TValue>>) {
+  const selected = options.findIndex((option) => option.value === selectedValue);
+  const labelId = label ? `${name}-label` : undefined;
+
+  return (
+    <div
+      role="radiogroup"
+      aria-labelledby={labelId}
+      className={cs('RadioSlider__group', className)}
+      data-testid="radio-slider"
+    >
+      {label && (
+        <span
+          id={labelId}
+          className="RadioSlider__label"
+        >
+          {label}
+        </span>
+      )}
+
+      <div className="RadioSlider">
+        {selected !== -1 && (
+          <div
+            className="RadioSlider__indicator"
+            style={{
+              width: `calc(${100 / options.length}% - var(--padding))`,
+              transform: `translateX(${selected * 100}%)`,
+            }}
+          />
+        )}
+
+        {options.map((item) => {
+          const id = `radio-${name}-${item.value}`;
+
+          return (
+            <label
+              htmlFor={id}
+              key={id}
+              className="RadioSlider__item"
+            >
+              <input
+                type="radio"
+                id={id}
+                name={name}
+                disabled={disabled || item.disabled}
+                value={item.value}
+                checked={item.value === selectedValue}
+                onChange={() => onChange(item.value)}
+              />
+              {item.label}
+            </label>
+          );
+        })}
+      </div>
+    </div>
+  );
+}

