+import cs from 'classnames';
+import { Link, type LinkProps } from 'react-router-dom';
+
+import { SvgIcon, type SvgIconName } from '@/components/ui/svg/SvgIcon';
+import './IconButton.scss';
+
+type IconLinkColor = 'astral';
+
+type IconLinkBaseProps = {
+  icon: SvgIconName;
+  to: LinkProps['to'];
+  color?: IconLinkColor;
+  iconSize?: number;
+  className?: string;
+  title?: string;
+};
+
+type IconLinkWithLabel = IconLinkBaseProps & {
+  label: string;
+  ariaLabel?: string;
+  children?: never;
+};
+
+type IconLinkWithoutLabel = IconLinkBaseProps & {
+  label?: never;
+  ariaLabel: string;
+  children?: never;
+};
+
+type IconLinkWithAccessibleChildren = IconLinkBaseProps & {
+  label?: never;
+  ariaLabel?: never;
+  children: React.ReactNode;
+};
+
+type IconLinkProps = IconLinkWithLabel | IconLinkWithoutLabel | IconLinkWithAccessibleChildren;
+
+export function IconLink({
+  icon,
+  to,
+  label,
+  ariaLabel,
+  className,
+  color = 'astral',
+  iconSize = 20,
+  title,
+  children,
+}: Readonly<IconLinkProps>) {
+  return (
+    <Link
+      to={to}
+      aria-label={ariaLabel}
+      title={title ?? ariaLabel ?? label}
+      className={cs('IconButton', `IconButton--${color}`, className)}
+    >
+      <SvgIcon
+        name={icon}
+        size={iconSize}
+      />
+      {label && <span className="IconButton__label">{label}</span>}
+      {children}
+    </Link>
+  );
+}

