+import { describe, expect, test } from 'vitest';
+import { page } from 'vitest/browser';
+import { render } from 'vitest-browser-react';
+
+import { Banner } from '../Banner';
+
+const BANNER_VARIANT_CASES = [
+  { variant: 'info' as const, role: 'status', iconClass: 'lucide-info' },
+  { variant: 'success' as const, role: 'status', iconClass: 'lucide-circle-check' },
+  { variant: 'warning' as const, role: 'alert', iconClass: 'lucide-triangle-alert' },
+  { variant: 'error' as const, role: 'alert', iconClass: 'lucide-circle-alert' },
+];
+
+describe('Banner', () => {
+  describe.each(BANNER_VARIANT_CASES)('$variant variant', ({ variant, role, iconClass }) => {
+    test(`sets role="${role}" and aria-live="polite"`, async () => {
+      await render(<Banner variant={variant}>Content</Banner>);
+
+      const banner = page.getByRole(role);
+      await expect.element(banner).toHaveAttribute('aria-live', 'polite');
+    });
+
+    test('renders the variant icon', async () => {
+      const { container } = await render(<Banner variant={variant}>Content</Banner>);
+
+      expect(container.querySelector(`.${iconClass}`)).toBeInTheDocument();
+    });
+
+    test('renders children content', async () => {
+      await render(<Banner variant={variant}>Banner message</Banner>);
+
+      await expect.element(page.getByText('Banner message')).toBeInTheDocument();
+    });
+  });
+
+  describe('Banner.Disclosure', () => {
+    test('hides children until summary is clicked', async () => {
+      await render(
+        <Banner variant="info">
+          Always visible{' '}
+          <Banner.Disclosure trigger={<strong>more</strong>}>
+            <div>Hidden content</div>
+          </Banner.Disclosure>
+        </Banner>,
+      );
+
+      await expect.element(page.getByText('Hidden content')).not.toBeVisible();
+
+      await page.getByText('more').click();
+
+      await expect.element(page.getByText('Hidden content')).toBeVisible();
+    });
+
+    test('collapses again on a second click', async () => {
+      await render(
+        <Banner variant="info">
+          Always visible{' '}
+          <Banner.Disclosure trigger={<strong>more</strong>}>
+            <div>Hidden content</div>
+          </Banner.Disclosure>
+        </Banner>,
+      );
+
+      const trigger = page.getByText('more');
+
+      await trigger.click();
+      await expect.element(page.getByText('Hidden content')).toBeVisible();
+
+      await trigger.click();
+      await expect.element(page.getByText('Hidden content')).not.toBeVisible();
+    });
+
+    test('renders open from the start when defaultOpen is true', async () => {
+      await render(
+        <Banner variant="info">
+          Always visible{' '}
+          <Banner.Disclosure
+            trigger={<strong>more</strong>}
+            defaultOpen
+          >
+            <div>Hidden content</div>
+          </Banner.Disclosure>
+        </Banner>,
+      );
+
+      await expect.element(page.getByText('Hidden content')).toBeVisible();
+    });
+  });
+});

