+import cs from 'classnames';
+
+import { BANNER_VARIANTS, type BannerVariant } from './variants';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+
+import './Banner.scss';
+
+interface BannerProps {
+  variant: BannerVariant;
+  children: React.ReactNode;
+  className?: string;
+}
+
+export function Banner({ variant, children, className }: Readonly<BannerProps>) {
+  const { iconName, role } = BANNER_VARIANTS[variant];
+
+  return (
+    <div
+      className={cs('Banner', `Banner--${variant}`, className)}
+      role={role}
+      aria-live="polite"
+    >
+      <SvgIcon
+        name={iconName}
+        size={20}
+        className="Banner__icon"
+      />
+      <div className="Banner__content">{children}</div>
+    </div>
+  );
+}
+
+interface BannerDisclosureProps {
+  trigger: React.ReactNode;
+  children: React.ReactNode;
+  defaultOpen?: boolean;
+}
+
+Banner.Disclosure = function BannerDisclosure({
+  trigger,
+  children,
+  defaultOpen = false,
+}: Readonly<BannerDisclosureProps>) {
+  return (
+    <details open={defaultOpen}>
+      <summary>
+        {trigger}
+        <SvgIcon
+          name="ChevronDown"
+          size={16}
+          aria-hidden
+        />
+      </summary>
+      {children}
+    </details>
+  );
+};

