+import type { ModulePathLabelingEligibilityResult } from '@/model/ModulePathLabelingEligibilityResult';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import {
+  getExactlyOneAllowedLabeling,
+  isFullyIneligible,
+} from '../utils/labelingEligibilityHelpers';
+import { TechnicalErrorBanner } from './banners/TechnicalErrorBanner';
+import { SingleOptionInfoBanner } from './banners/SingleOptionInfoBanner';
+import { InvalidWithReasonsBanner } from './banners/InvalidWithReasonsBanner';
+
+import './LabelingEligibilityBannerMessage.scss';
+
+interface LabelingEligibilityBannerMessageProps {
+  modulePathLabeling: ModulePathLabelingEligibilityResult | undefined;
+  modulePathLabelingCheckError: ApiErrors;
+}
+
+export function LabelingEligibilityBannerMessage({
+  modulePathLabeling,
+  modulePathLabelingCheckError,
+}: Readonly<LabelingEligibilityBannerMessageProps>) {
+  if (modulePathLabelingCheckError) {
+    return <TechnicalErrorBanner error={modulePathLabelingCheckError} />;
+  }
+
+  const uniqueEligibleFound = getExactlyOneAllowedLabeling(modulePathLabeling?.eligibleLabelings);
+
+  const invalidEligibilityReasons = modulePathLabeling?.invalidEligibilityReasons ?? null;
+
+  const hasRecoverableInvalidReasons =
+    !!invalidEligibilityReasons?.length && !isFullyIneligible(invalidEligibilityReasons);
+
+  return (
+    <div className="LabelingEligibilityBannerMessage">
+      {uniqueEligibleFound && (
+        <SingleOptionInfoBanner
+          marketSegment={uniqueEligibleFound.marketSegment}
+          labeling={uniqueEligibleFound.labeling}
+        />
+      )}
+
+      {hasRecoverableInvalidReasons && (
+        <InvalidWithReasonsBanner reasons={invalidEligibilityReasons} />
+      )}
+    </div>
+  );
+}

