+import { describe, expect, test } from 'vitest';
+
+import { TrainingMode } from '@/model/TrainingMode';
+import { getExactlyOneAllowedLabeling, isFullyIneligible } from '../labelingEligibilityHelpers';
+import type { LabelingsByMarketSegment } from '@/model/TrainingAgencyDTO';
+
+describe('isFullyIneligible', () => {
+  test('should return true when invalidReasons is null', () => {
+    expect(isFullyIneligible(null)).toBe(true);
+  });
+
+  test('should return true when invalidReasons is empty', () => {
+    expect(isFullyIneligible([])).toBe(true);
+  });
+
+  test('should return true when only fully ineligible reasons are present', () => {
+    expect(isFullyIneligible(['wrong_labeling_status', 'wrong_training_mode'])).toBe(true);
+  });
+
+  test('should return false when wrong_labeling_period is present', () => {
+    expect(isFullyIneligible(['wrong_labeling_period'])).toBe(false);
+  });
