+import type { LabelingEligibilityInvalidReason } from '@/model/ModulePathLabelingEligibilityResult';
+import type { LabelingDTO } from '@/model/LabelingDTO';
+import type { MarketSegment } from '@/model/MarketSegment';
+import type { LabelingsByMarketSegment } from '@/model/TrainingAgencyDTO';
+
+/**
+ * Returns true when there are no recoverable invalid reasons.
+ * Treats `null`, `undefined`, or an empty list as "no recoverable reason found",
+ * which is handled as fully ineligible by this helper.
+ *
+ * Recoverable reasons are contextual cases such as wrong period or wrong department.
+ */
+export function isFullyIneligible(
+  invalidReasons: LabelingEligibilityInvalidReason[] | null,
+): boolean {
+  return !invalidReasons?.some((reason) => {
+    return reason === 'wrong_labeling_period' || reason === 'wrong_labeling_department';
+  });
+}
+
+type ExactlyOneAllowedLabeling = {
+  marketSegment: MarketSegment;
+  labeling: LabelingDTO;
+};
+
+/**
+ * Retrieves the unique ALLOWED labeling if exactly one exists across all market segments and training modes.
+ * Returns null if there are no ALLOWED labelings OR if there are multiple ALLOWED labelings.
+ */
+export function getExactlyOneAllowedLabeling(
+  labelingsBySegment: LabelingsByMarketSegment | null | undefined,
+): ExactlyOneAllowedLabeling | null {
+  if (!labelingsBySegment) {
+    return null;
+  }
+
+  let allowedLabeling: ExactlyOneAllowedLabeling | null = null;
+
+  const labelingsBySegmentEntries = Object.entries(labelingsBySegment);
+
+  for (const [marketSegment, labelingsByMode] of labelingsBySegmentEntries) {
+    if (!labelingsByMode) {
+      continue;
+    }
+
+    for (const labeling of Object.values(labelingsByMode)) {
+      if (labeling?.labelingStatus !== 'ALLOWED') {
+        continue;
+      }
+
+      // A second ALLOWED labeling means there is no unique eligible labeling.
+      if (allowedLabeling) {
+        return null;
+      }
+
+      allowedLabeling = {
+        marketSegment: marketSegment as MarketSegment,
+        labeling,
+      };
+    }
+  }
+
+  return allowedLabeling;
+}

