+            result: invalidDepartmentResult,
+          },
+          { status: 200 },
+        );
+      }
+
+      if (requestBody.moduleId === MODULE_ID_UNIQUE_ELIGIBLE_LABELING) {
+        return HttpResponse.json(
+          {
+            result: uniqEligibleLabelingResultMock,
+          },
+          { status: 200 },
+        );
+      }
+
+      let fallbackResult = {
+        ...eligibleLabelingResultMock,
+        eligibilityStatus: 'UNKNOWN',
+      };
+
+      if (hasInvalidStartDay) {
+        fallbackResult = invalidPeriodAndDepartmentResult;
+      } else if (hasStartDay) {
+        fallbackResult = uniqEligibleLabelingResultMock;
+      } else if (hasWrongTrainingMode) {
+        fallbackResult = invalidTrainingModeResult;
+      } else if (hasRequiredFields) {
+        fallbackResult = eligibleLabelingResultMock;
+      }
+
+      return HttpResponse.json(
+        {
+          result: fallbackResult,
+        },
+        { status: 200 },
+      );
+    }),
+  ),
