+describe('function buildTrainingMoments()', () => {
+  it('should return an empty array when no moments are provided', () => {
+    expect(buildTrainingMoments({})).toEqual([]);
+    expect(buildTrainingMoments({ SYNCHRONOUS: [], ASYNCHRONOUS: undefined })).toEqual([]);
+  });
+
+  it('should filter out null results from formatMomentValues', () => {
+    const result = buildTrainingMoments({
+      SYNCHRONOUS: [{} as SyncInPersonMomentValues, mockSyncMoment],
