+    expect(result).toHaveLength(1);
+    expect(result[0]).toMatchObject({ morningStart: '05/05/1994T10:00', placeId: 'placeId' });
+  });
+
+  it('should combine synchronous and asynchronous moments in sync-first order', () => {
+    const result = buildTrainingMoments({
+      SYNCHRONOUS: [mockSyncMoment],
+      ASYNCHRONOUS: mockAsyncMoment,
+    });
+
+    expect(result).toHaveLength(2);
+    expect(result[0]).toMatchObject({ morningStart: '05/05/1994T10:00', placeId: 'placeId' });
+    expect(result[0]).not.toHaveProperty('startDay');
+    expect(result[1]).toMatchObject({ startDay: '01/01/1992', endDay: '10/10/1992' });
+  });
+
+  it('should skip the draft hours fallback when mode is "preview"', () => {
+    const noHoursSync = {
+      ...mockSyncMoment,
+      morningStart: undefined,
+      afternoonStart: undefined,
+    };
