+    const [result] = buildTrainingMoments({ SYNCHRONOUS: [noHoursSync] }, { mode: 'preview' });
+
+    expect(result).not.toHaveProperty('morningStart');
+    expect(result).not.toHaveProperty('morningEnd');
+    expect(result).toMatchObject({ startDay: '05/05/1994', placeId: 'placeId' });
+  });
+});

