+import type { TrainingMomentInput } from '@/model/TrainingMomentDTO';
+import type { BuildMode, ModulePathFormData } from '../types';
+import { formatMomentValues } from './formatMomentValues';
+
+/**
+ * Builds the TrainingMomentInput[] payload from the form moments (both timings).
+ */
+export function buildTrainingMoments(
+  moments: ModulePathFormData['moments'],
+  options: { mode?: BuildMode } = {},
+): TrainingMomentInput[] {
+  const { mode = 'submit' } = options;
+
+  const result: TrainingMomentInput[] = [];
+
+  if (moments.SYNCHRONOUS) {
+    moments.SYNCHRONOUS.forEach((moment) => {
+      const formatted = formatMomentValues(moment, mode);
+      if (formatted !== null) {
+        result.push(formatted);
+      }
+    });
+  }
+
+  if (moments.ASYNCHRONOUS) {
+    const formatted = formatMomentValues(moments.ASYNCHRONOUS, mode);
+    if (formatted !== null) {
+      result.push(formatted);
+    }
+  }
+
+  return result;
+}

