+    const moreInfoElement = page.getByRole('button', { name: /plus d'information/i });
+    await expect.element(moreInfoElement).toBeInTheDocument();
+  });
+
+  test('should render an invoice line without recommendation information', async () => {
+    const updateProps = {
+      ...defaultProps,
+      items: [mockItems.content[6]] as unknown as BillDTO[],
