+import endpoints from '@/constants/api-endpoints';
+import { getRequestHeaders, HttpVerb } from '@/helpers/http';
+
+export function searchEmployersHandler(
+  searchTerms: string,
+  { signal }: { signal?: AbortSignal } = {},
+): Promise<Response> {
+  return fetch(endpoints.employers.url, {
+    method: HttpVerb.POST,
+    headers: getRequestHeaders(),
+    body: JSON.stringify({
+      firstNameLastName: searchTerms,
+      actived: true,
+      criteria: {
+        index: 0,
+        size: 100,
+        column: 'physicalPerson.lastName',
+        direction: 'asc',
+      },
+    }),
+    signal,
+  });
+}

