+import endpoints from '@/constants/api-endpoints';
+import type { MandateOperationDTO } from '@/model/MandateOperationDTO';
+import { useListQuery } from '@/hooks/useListQuery';
+
+export function useListMandateOperation() {
+  const result = useListQuery<MandateOperationDTO>(endpoints.mandateOperations, {
+    defaultSearchParams: {
+      sortedColumn: 'code',
+      sortingOrder: 'desc',
+    },
+    filtersNames: [
+      'searchText',
+      'code',
+      'modulePathId',
+      'evaluationId',
+      'learnerId',
+      'employerId',
+      'paymentCode',
+      'trainingType',
+      'billed',
+      'upcomingPayment',
+      'enabledLivingCostsBilling',
+      'marketTypes',
+    ],
+  });
+
+  return result;
+}

