+
+    expect(result.current.shouldShowMarketTypeFilter).toBe(true);
+    expect(result.current.readableMarketTypes).toEqual(['CALL_FOR_TENDER', 'PUBLIC_MARKET']);
+  });
+
+  test('should hide market type filter when user can read only call for tender', async () => {
+    const { result } = await renderHookWithProviders(() => useMarketTypeFilterAccess(), {
+      preloadedState: {
+        login: {
+          ...baseUser,
+          permissions: [PermissionTypes.MARKET_TYPES_CALL_FOR_TENDER_READ],
