+    expect(result.current.readableMarketTypes).toEqual(['CALL_FOR_TENDER']);
+  });
+
+  test('should hide market type filter when user can read only public market', async () => {
+    const { result } = await renderHookWithProviders(() => useMarketTypeFilterAccess(), {
+      preloadedState: {
+        login: {
