+          permissions: [PermissionTypes.MARKET_TYPES_PUBLIC_MARKET_READ],
+        },
+      },
+    });
+
+    expect(result.current.shouldShowMarketTypeFilter).toBe(false);
+    expect(result.current.readableMarketTypes).toEqual(['PUBLIC_MARKET']);
+  });
+
+  test('should hide market type filter when user cannot read any market type', async () => {
+    const { result } = await renderHookWithProviders(() => useMarketTypeFilterAccess(), {
+      preloadedState: {
+        login: baseUser,
+      },
+    });
+
+    expect(result.current.shouldShowMarketTypeFilter).toBe(false);
+    expect(result.current.readableMarketTypes).toEqual([]);
+  });
+});

