+import type { MarketType } from '@/model/MarketSegment';
+import { PermissionTypes } from '@/enums/authorization';
+import { usePermission } from '@/hooks/usePermission';
+
+export function useMarketTypeFilterAccess() {
+  const canReadTenderMarketType = usePermission(PermissionTypes.MARKET_TYPES_CALL_FOR_TENDER_READ);
+  const canReadPublicMarketType = usePermission(PermissionTypes.MARKET_TYPES_PUBLIC_MARKET_READ);
+
+  const accessByMarketType = {
+    CALL_FOR_TENDER: canReadTenderMarketType,
+    PUBLIC_MARKET: canReadPublicMarketType,
+  } satisfies Record<MarketType, boolean>;
+
+  const accessByMarketKeys = Object.keys(accessByMarketType) as MarketType[];
+  const readableMarketTypes = accessByMarketKeys.filter(
+    (marketType) => accessByMarketType[marketType],
+  );
+
+  const shouldShowMarketTypeFilter = readableMarketTypes.length > 1;
+
+  return {
+    shouldShowMarketTypeFilter,
+    readableMarketTypes,
+  };
+}

