+// oxlint-disable no-console
+
+import http from 'node:http';
+import https from 'node:https';
+import { createReadStream, existsSync, readFileSync } from 'node:fs';
+import { stat } from 'node:fs/promises';
+import path from 'node:path';
+import dotenv from 'dotenv';
+
+dotenv.config();
+
+const ROOT = path.resolve(import.meta.dirname, '..');
+const DIST_DIR = path.join(ROOT, 'public/iperia-front');
+const INDEX_HTML = path.join(DIST_DIR, 'index.html');
+const KEY_PATH = path.join(ROOT, 'config/iperia.dev.local.key');
+const CERT_PATH = path.join(ROOT, 'config/iperia.dev.local.crt');
+const API_PROXY_PREFIXES = ['/api', '/authenticate', '/isAuthenticated', '/actuator', '/user'];
+
+const HOST = process.env.HOST || '0.0.0.0';
+const PORT = Number.parseInt(process.env.PORT || '8888', 10);
+const API_HOST = process.env.API_HOST;
+
+if (!existsSync(INDEX_HTML)) {
+  console.error(
+    `No production build found at ${path.relative(ROOT, DIST_DIR)}. Run \`pnpm build\` first.`,
+  );
+  process.exit(1);
+}
+
+if (!existsSync(KEY_PATH) || !existsSync(CERT_PATH)) {
+  console.error(`Missing HTTPS certs at ${KEY_PATH} / ${CERT_PATH}.`);
+  process.exit(1);
+}
+
+if (!API_HOST) {
+  console.warn(
+    `API_HOST is not set; ${API_PROXY_PREFIXES.map((p) => `${p}/*`).join(', ')} requests will return 502.`,
+  );
+}
+
+function isProxiedPath(url) {
+  const pathOnly = url.split('?')[0];
+
+  return API_PROXY_PREFIXES.some(
+    (prefix) => pathOnly === prefix || pathOnly.startsWith(prefix + '/'),
+  );
+}
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.map': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.gif': 'image/gif',
+  '.webp': 'image/webp',
+  '.ico': 'image/x-icon',
+  '.woff': 'font/woff',
+  '.woff2': 'font/woff2',
+  '.ttf': 'font/ttf',
+  '.txt': 'text/plain; charset=utf-8',
+};
+
+function contentTypeFor(logicalPath) {
+  const ext = path.extname(logicalPath).toLowerCase();
+
+  return MIME_TYPES[ext] ?? 'application/octet-stream';
+}
+
+function resolveSafe(urlPath) {
+  let decoded;
+  try {
+    decoded = decodeURIComponent(urlPath.split('?')[0]);
+  } catch {
+    return null;
+  }
+
+  const candidate = path.normalize(path.join(DIST_DIR, decoded));
+  if (candidate !== DIST_DIR && !candidate.startsWith(DIST_DIR + path.sep)) {
+    return null;
+  }
+
+  return candidate;
+}
+
+function acceptsEncoding(header, name) {
+  if (!header) {
+    return false;
+  }
+
+  const tokens = header.split(',').map((t) => t.trim());
+
+  for (const token of tokens) {
+    const [coding, ...params] = token.split(';').map((s) => s.trim());
+    if (coding !== name && coding !== '*') {
+      continue;
+    }
+
+    const q = params.find((p) => p.startsWith('q='));
+    if (q && Number.parseFloat(q.slice(2)) === 0) {
+      return false;
+    }
+
+    return true;
+  }
+
+  return false;
+}
+
+async function fileSize(p) {
+  try {
+    const s = await stat(p);
+
+    return s.isFile() ? s.size : null;
+  } catch {
+    return null;
+  }
+}
+
+async function pickEncodedFile(absPath, acceptEncoding) {
+  if (acceptsEncoding(acceptEncoding, 'br')) {
+    const size = await fileSize(absPath + '.br');
+
+    if (size !== null) {
+      return { file: absPath + '.br', encoding: 'br', size };
+    }
+  }
+
+  if (acceptsEncoding(acceptEncoding, 'gzip')) {
+    const size = await fileSize(absPath + '.gz');
+
+    if (size !== null) {
+      return { file: absPath + '.gz', encoding: 'gzip', size };
+    }
+  }
+
+  const size = await fileSize(absPath);
+  if (size !== null) {
+    return { file: absPath, encoding: null, size };
+  }
+
+  return null;
+}
+
+function send(res, status, body) {
+  res.writeHead(status, { 'content-type': 'text/plain; charset=utf-8' });
+  res.end(body);
+}
+
+function proxyApi(req, res) {
+  if (!API_HOST) {
+    send(res, 502, 'API_HOST not configured.');
+    return;
+  }
+
+  let target;
+  try {
+    target = new URL(API_HOST);
+  } catch {
+    send(res, 502, 'API_HOST is not a valid URL.');
+    return;
+  }
+
+  const driver = target.protocol === 'https:' ? https : http;
+  const basePath = target.pathname.replace(/\/$/, '');
+  const upstreamPath = basePath + req.url;
+
+  const headers = { ...req.headers, host: target.host };
+
+  const upstream = driver.request(
+    {
+      protocol: target.protocol,
+      hostname: target.hostname,
+      port: target.port || (target.protocol === 'https:' ? 443 : 80),
+      method: req.method,
+      path: upstreamPath,
+      headers,
+    },
+    (upstreamRes) => {
+      res.writeHead(upstreamRes.statusCode ?? 502, upstreamRes.headers);
+      upstreamRes.pipe(res);
+    },
+  );
+
+  upstream.on('error', (err) => {
+    if (!res.headersSent) {
+      send(res, 502, `Upstream error: ${err.message}`);
+    } else {
+      res.destroy();
+    }
+  });
+
+  req.pipe(upstream);
+}
+
+async function serveStatic(req, res) {
+  let urlPath = req.url.split('?')[0];
+  if (urlPath === '' || urlPath.endsWith('/')) {
+    urlPath += 'index.html';
+  }
+
+  const candidate = resolveSafe(urlPath);
+  if (!candidate) {
+    send(res, 400, 'Bad request.');
+    return;
+  }
+
+  let target = null;
+  const candidateSize = await fileSize(candidate);
+  if (candidateSize !== null) {
+    target = candidate;
+  } else if ((req.method === 'GET' || req.method === 'HEAD') && !path.extname(candidate)) {
+    target = INDEX_HTML;
+  }
+
+  if (!target) {
+    send(res, 404, 'Not found.');
+    return;
+  }
+
+  const picked = await pickEncodedFile(target, req.headers['accept-encoding'] || '');
+  if (!picked) {
+    send(res, 404, 'Not found.');
+    return;
+  }
+
+  const headers = {
+    'content-type': contentTypeFor(target),
+    'content-length': picked.size,
+    'cache-control': 'no-cache',
+    vary: 'Accept-Encoding',
+  };
+  if (picked.encoding) {
+    headers['content-encoding'] = picked.encoding;
+  }
+
+  res.writeHead(200, headers);
+  if (req.method === 'HEAD') {
+    res.end();
+    return;
+  }
+  createReadStream(picked.file).pipe(res);
+}
+
+const server = https.createServer(
+  { key: readFileSync(KEY_PATH), cert: readFileSync(CERT_PATH) },
+  (req, res) => {
+    if (isProxiedPath(req.url)) {
+      proxyApi(req, res);
+      return;
+    }
+
+    serveStatic(req, res).catch((err) => {
+      console.error(err);
+      if (!res.headersSent) {
+        send(res, 500, 'Internal server error.');
+      } else {
+        res.destroy();
+      }
+    });
+  },
+);
+
+server.listen(PORT, HOST, () => {
+  console.log(`Preview (real production build) running at https://${HOST}:${PORT}`);
+  console.log(`Serving ${path.relative(ROOT, DIST_DIR)}`);
+  if (API_HOST) {
+    for (const prefix of API_PROXY_PREFIXES) {
+      console.log(`Proxying ${prefix}/* -> ${API_HOST}`);
+    }
+  }
+});

