+import { useQueryClient, type QueryClient } from '@tanstack/react-query';
+import { useForm, useFieldArray } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import type { MailTemplateDTO } from '@/model/MailTemplateDTO';
+import type { DocumentTemplateDTO } from '@/model/DocumentTemplateDTO';
+import { eventFormSchema, type EventFormData } from './eventFormValidationSchema';
+import { EMPTY_COMMENT_ITEM, EMPTY_DOCUMENT_ITEM, EMPTY_MAIL_ITEM } from './eventFormDefault';
+import { EVENT_ACTION, EVENT_ACTION_OPTIONS } from '../constants';
+import { MARKET_SEGMENT_OPTIONS } from '@/model/MarketSegment';
+import { EventTriggerLabel, EventTargetLabel } from '@/model/EventTriggerTypeEnum';
