+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import ModelFormView from '../../common/ModelFormView/ModelFormView';
+import Button from '../../common/Button/Button';
+import ButtonGroup from '../../common/ButtonGroup/ButtonGroup';
+import LoaderOverlay from '../../common/LoaderOverlay/LoaderOverlay';
+import { FormSectionCard } from '@/components/ui/form/FormSectionCard';
+import InputTextV2 from '../../common/InputText/InputTextV2';
+import InputMultiSelectV2 from '../../common/InputMultiSelect/InputMultiSelectV2';
+import { InputCheckboxGroupV2 } from '../../common/InputCheckbox/InputCheckboxGroupV2';
+import InputSearchV2 from '../../common/InputSearch/InputSearchV2';
+import { formatEventFormData, formatEventTemplateInput } from './helpers';
+import { useGetEventTemplate } from '@/hooks/data/events/useGetEventTemplate';
+import { searchMailTemplateHandler } from '@/hooks/data/events/fetchHandlers/searchMailTemplateHandler';
+import { searchDocumentTemplateHandler } from '@/hooks/data/documentTemplates/fetchHandlers/searchDocumentTemplateHandler';
+import { useUpdateEventTemplate } from '@/hooks/data/events/useUpdateEventTemplate';
+import { useCreateEventTemplate } from '@/hooks/data/events/useCreateEventTemplate';
+
+interface EventFormProps {
+  eventId?: string;
+  closeModalHandler: () => void;
+  invalidateEventsListCache: (queryClient?: QueryClient) => Promise<void>;
+}
+
+export function EventForm({
+  eventId,
+  closeModalHandler,
+  invalidateEventsListCache,
+}: Readonly<EventFormProps>) {
+  const queryClient = useQueryClient();
+
+  // ----- data -----
+
+  const {
+    isFetching: isEventTemplateFetching,
+    data: eventTemplateData,
+    error: eventTemplateError,
+  } = useGetEventTemplate(eventId);
+
+  // ----- form -----
+
+  const {
+    control,
+    handleSubmit,
+    watch,
+    trigger,
+    formState: { isSubmitted },
+  } = useForm({
+    resolver: zodResolver(eventFormSchema),
+    values: eventTemplateData
+      ? formatEventFormData(eventTemplateData)
+      : ({
+          name: '',
+          category: '',
+          triggers: [],
+          actions: [],
+          marketSegments: [],
+          mails: [EMPTY_MAIL_ITEM],
+          documents: [EMPTY_DOCUMENT_ITEM],
+          comments: [EMPTY_COMMENT_ITEM],
+        } satisfies EventFormData),
+  });
+
+  const {
+    fields: mailFields,
+    append: appendMail,
+    remove: removeMail,
+  } = useFieldArray({ control, name: 'mails' });
+
+  const {
+    fields: documentFields,
+    append: appendDocument,
+    remove: removeDocument,
+  } = useFieldArray({ control, name: 'documents' });
+
+  const {
+    fields: commentFields,
+    append: appendComment,
+    remove: removeComment,
+  } = useFieldArray({ control, name: 'comments' });
+
+  const actions = watch('actions');
+
+  // ----- mutations hooks -----
+
+  const {
+    isPending: isCreatingEventTemplate,
+    error: createEventTemplateError,
+    mutate: createEventTemplate,
+  } = useCreateEventTemplate({
+    onSuccess: () => {
+      closeModalHandler();
+      void invalidateEventsListCache(queryClient);
+    },
+  });
+
+  const {
+    isPending: isUpdatingEventTemplate,
+    error: updateEventTemplateError,
+    mutate: updateEventTemplate,
+  } = useUpdateEventTemplate({
+    eventId: eventId!, // safe cast since this hook is only used when eventId is defined
+    onSuccess: () => {
+      closeModalHandler();
+      void invalidateEventsListCache(queryClient);
+    },
+  });
+
+  // ----- handlers -----
+
+  function handleFormSubmit(values: EventFormData) {
+    const params = formatEventTemplateInput(values);
+
+    if (eventId) {
+      updateEventTemplate(params);
+    } else {
+      createEventTemplate(params);
+    }
+  }
+
+  const isMutationPending = isCreatingEventTemplate || isUpdatingEventTemplate;
+  const loadingMessage = `${eventId ? 'Édition' : 'Création'} de l'évènement en cours...`;
+
+  // ----- rendering -----
+
+  return (
+    <div className="EventFormContainer">
+      <div className="EventForm">
+        {isEventTemplateFetching && (
+          <LoaderOverlay loadingText="Récupération de l'évènement en cours..." />
+        )}
+        {isMutationPending && <LoaderOverlay loadingText={loadingMessage} />}
+
+        <ModelFormView
+          apiErrors={eventTemplateError || createEventTemplateError || updateEventTemplateError}
+          apiErrorTitle={`Une erreur est survenue lors de ${
+            eventId ? "l'édition" : 'la création'
+          } de l'évènement :`}
+        >
+          <form
+            className="EventForm__form"
+            onSubmit={handleSubmit(handleFormSubmit)}
+            noValidate
+          >
+            <div className="ModelFormView__fieldsets">
+              <div className="ModelFormView__row">
+                <InputTextV2
+                  className="ModelFormView__formField"
+                  control={control}
+                  name="name"
+                  label="Titre"
+                  placeholder="Saisissez un titre"
+                  required
+                />
+                <InputTextV2
+                  className="ModelFormView__formField"
+                  control={control}
+                  name="category"
+                  label="Catégorie"
+                  required
+                />
+              </div>
+
+              <div className="ModelFormView__row">
+                <InputMultiSelectV2
+                  className="ModelFormView__formField"
+                  control={control}
+                  name="triggers"
+                  label="Déclencheur(s)"
+                  options={getInputSelectOptions(EventTriggerLabel)}
+                />
+              </div>
+
+              <div className="ModelFormView__row">
+                <InputCheckboxGroupV2
+                  className="ModelFormView__formField"
+                  control={control}
+                  name="marketSegments"
+                  label="Segment de marché"
+                  options={MARKET_SEGMENT_OPTIONS}
+                  itemsDirection="row"
+                  appearance="boxed"
+                />
+              </div>
+
+              <div className="ModelFormView__row">
+                <InputCheckboxGroupV2
+                  className="ModelFormView__formField"
+                  control={control}
+                  name="actions"
+                  label="Type d'action"
+                  appearance="boxed"
+                  options={EVENT_ACTION_OPTIONS}
+                  required
+                />
+              </div>
+            </div>
+
+            {actions?.includes(EVENT_ACTION.MAILS.value) && (
+              <div className="ModelFormView__row">
+                <div className="ModelFormView__formField">
+                  {mailFields.map((field, index) => {
+                    const removeMailHandler =
+                      mailFields.length > 1 ? () => removeMail(index) : undefined;
+
+                    return (
+                      <FormSectionCard
+                        key={field.id}
+                        className="EventFormSectionCard"
+                        title="Envoi de mail"
+                        onRemove={removeMailHandler}
+                        ariaLabel={`Supprimer l'envoi de mail ${index + 1}`}
+                      >
+                        <div className="ModelFormView__row">
+                          <InputSearchV2<MailTemplateDTO, EventFormData>
+                            control={control}
+                            name={`mails.${index}.id`}
+                            label="Modèle de mail"
+                            loadOptionsHandler={searchMailTemplateHandler}
+                            httpResponseFormatter={(json) => {
+                              return getResultFromResponse(json).map((mailTemplate) => ({
+                                label: mailTemplate.title,
+                                value: mailTemplate.id,
+                              }));
+                            }}
+                            placeholder="Rechercher un template de mail..."
+                            noResultsText="Aucun template de mail trouvé."
+                            className="ModelFormView__formField"
+                          />
+
+                          <InputMultiSelectV2
+                            control={control}
+                            name={`mails.${index}.targets`}
+                            label="Destinataire(s)"
+                            options={getInputSelectOptions(EventTargetLabel)}
+                            handleChange={() => {
+                              if (isSubmitted) {
+                                void trigger(`mails.${index}.additionalTargets`);
+                              }
+                            }}
+                            className="ModelFormView__formField"
+                          />
+                        </div>
+
+                        <div className="ModelFormView__row">
+                          <InputTextV2
+                            control={control}
+                            name={`mails.${index}.additionalTargets`}
+                            label="Destinataire(s) libre(s)"
+                            handleChange={() => {
+                              if (isSubmitted) {
+                                void trigger(`mails.${index}.targets`);
+                              }
+                            }}
+                            className="ModelFormView__formField"
+                          />
+                        </div>
+                      </FormSectionCard>
+                    );
+                  })}
+
+                  <Button
+                    onClick={() => appendMail(EMPTY_MAIL_ITEM)}
+                    appearance="blue-default"
+                  >
+                    <Button.TextIcon>+</Button.TextIcon>
+                    <Button.Text>Ajouter un mail</Button.Text>
+                  </Button>
+                </div>
+              </div>
+            )}
+
+            {actions?.includes(EVENT_ACTION.DOCUMENTS.value) && (
+              <div className="ModelFormView__row">
+                <div className="ModelFormView__formField">
+                  {documentFields.map((field, index) => {
+                    const removeDocumentHandler =
+                      documentFields.length > 1 ? () => removeDocument(index) : undefined;
+
+                    return (
+                      <FormSectionCard
+                        key={field.id}
+                        className="EventFormSectionCard"
+                        title="Génération de documents"
+                        onRemove={removeDocumentHandler}
+                        ariaLabel={`Supprimer la génération de document ${index + 1}`}
+                      >
+                        <div className="ModelFormView__row">
+                          <InputSearchV2<DocumentTemplateDTO, EventFormData>
+                            control={control}
+                            name={`documents.${index}.id`}
+                            label="Modèle de document"
+                            loadOptionsHandler={searchDocumentTemplateHandler}
+                            httpResponseFormatter={(json) => {
+                              return getResultFromResponse(json).map((documentTemplate) => ({
+                                label: documentTemplate.title,
+                                value: documentTemplate.id,
+                              }));
+                            }}
+                            placeholder="Rechercher un template de document..."
+                            noResultsText="Aucun template de document trouvé."
+                            className="ModelFormView__formField"
+                          />
+
+                          <InputMultiSelectV2
+                            control={control}
+                            name={`documents.${index}.targets`}
+                            label="Destinataire(s)"
+                            options={getInputSelectOptions(EventTargetLabel)}
+                            className="ModelFormView__formField"
+                          />
+                        </div>
+
+                        {field.documentInvalid && (
+                          <div className="EventForm__additionalMessage">
+                            Le modèle de document utilisé n'existe plus ou n'est plus valide, il
+                            faudrait le mettre à jour ou le remplacer
+                          </div>
+                        )}
+                      </FormSectionCard>
+                    );
+                  })}
+
+                  <Button
+                    onClick={() => appendDocument(EMPTY_DOCUMENT_ITEM)}
+                    appearance="blue-default"
+                  >
+                    <Button.TextIcon>+</Button.TextIcon>
+                    <Button.Text>Ajouter un document</Button.Text>
+                  </Button>
+                </div>
+              </div>
+            )}
+
+            {actions?.includes(EVENT_ACTION.COMMENTS.value) && (
+              <div className="ModelFormView__row">
+                <div className="ModelFormView__formField">
+                  {commentFields.map((field, index) => {
+                    const removeCommentHandler =
+                      commentFields.length > 1 ? () => removeComment(index) : undefined;
+
+                    return (
