+import { z } from 'zod';
+
+import { EVENT_ACTION } from '../constants';
+import { EventTargetType, EventTriggerType } from '@/model/EventTriggerTypeEnum';
+import { MARKET_SEGMENT_KEYS } from '@/model/MarketSegment';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type EventFormData = z.infer<typeof eventFormSchema>;
+
+// ----- schema -----
+
+const mailItemSchema = z.object({
+  id: z.object({ label: z.string(), value: z.string() }).nullable().optional(),
+  targets: z.array(z.enum(EventTargetType)).optional(),
+  additionalTargets: z.string().optional(),
+});
+
+const documentItemSchema = z.object({
+  id: z.object({ label: z.string(), value: z.string() }).nullable().optional(),
+  targets: z.array(z.enum(EventTargetType)).optional(),
+  documentInvalid: z.boolean().optional(),
+});
+
+const commentItemSchema = z.object({
+  title: z.string().optional(),
+  value: z.string().nullish(),
+  targets: z.array(z.enum(EventTargetType)).optional(),
+  code: z.string().nullish(),
+});
+
+export const eventFormSchema = z
+  .object({
+    name: z.string().min(1, FORM_ERROR_MESSAGES.name.required),
+    category: z.string().min(1, FORM_ERROR_MESSAGES.event.categoryRequired),
+    triggers: z.array(z.enum(EventTriggerType)).optional(),
+    marketSegments: z.array(z.enum(MARKET_SEGMENT_KEYS)).optional(),
+    actions: z
+      .array(
+        z.enum([
+          EVENT_ACTION.MAILS.value,
+          EVENT_ACTION.DOCUMENTS.value,
+          EVENT_ACTION.COMMENTS.value,
+        ]),
+      )
+      .min(1, FORM_ERROR_MESSAGES.event.actionRequired),
+    mails: z.array(mailItemSchema),
+    documents: z.array(documentItemSchema),
+    comments: z.array(commentItemSchema),
+  })
+  .superRefine((values, ctx) => {
+    if (values.actions.includes(EVENT_ACTION.MAILS.value)) {
+      values.mails.forEach((mail, index) => {
+        if (!mail.id) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.email.modelRequired,
+            path: ['mails', index, 'id'],
+          });
+        }
+
+        if ((!mail.targets || mail.targets.length === 0) && !mail.additionalTargets) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.event.recipientsAtLeastOne,
+            path: ['mails', index, 'targets'],
+          });
+
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.event.recipientsAtLeastOne,
+            path: ['mails', index, 'additionalTargets'],
+          });
+        }
+      });
+    }
+
+    if (values.actions.includes(EVENT_ACTION.DOCUMENTS.value)) {
+      values.documents.forEach((doc, index) => {
+        if (!doc.id) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.documentTemplate.modelRequired,
+            path: ['documents', index, 'id'],
+          });
+        }
+
+        if (!doc.targets || doc.targets.length === 0) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.event.recipientsRequired,
+            path: ['documents', index, 'targets'],
+          });
+        }
+      });
+    }
+
+    if (values.actions.includes(EVENT_ACTION.COMMENTS.value)) {
+      values.comments.forEach((comment, index) => {
+        if (!comment.title) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.comment.genericTitleRequired,
+            path: ['comments', index, 'title'],
+          });
+        }
+
+        if (!comment.targets || comment.targets.length === 0) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.event.recipientsRequired,
+            path: ['comments', index, 'targets'],
+          });
+        }
+      });
+    }
+  });

