+import type { EventTemplateDTO, EventTemplateInput } from '@/model/EventTemplatesDTO';
+import { EVENT_ACTION, type EventActionType } from '../constants';
+import type { EventFormData } from './eventFormValidationSchema';
+import { EMPTY_COMMENT_ITEM, EMPTY_DOCUMENT_ITEM, EMPTY_MAIL_ITEM } from './eventFormDefault';
+
+/**
+ * Formats a EventTemplateDTO into EventFormData to be used in a EventForm.
+ */
+export function formatEventFormData(eventTemplate: EventTemplateDTO): EventFormData {
+  const mails = eventTemplate.mails ?? [];
+  const documents = eventTemplate.documents ?? [];
+  const comments = eventTemplate.comments ?? [];
+
+  const hasMails = mails.length > 0;
+  const hasDocuments = documents.length > 0;
+  const hasComments = comments.length > 0;
+
+  return {
+    name: eventTemplate.name ?? '',
+    category: eventTemplate.category ?? '',
+    triggers: eventTemplate.triggers ?? [],
+    marketSegments: eventTemplate.marketSegments ?? [],
+    actions: [
+      ...(hasMails ? [EVENT_ACTION.MAILS.value] : []),
+      ...(hasDocuments ? [EVENT_ACTION.DOCUMENTS.value] : []),
+      ...(hasComments ? [EVENT_ACTION.COMMENTS.value] : []),
+    ],
+    mails: hasMails
+      ? mails.map((mail) => ({
+          id: {
+            label: mail.mailTemplate.title,
+            value: mail.mailTemplate.id,
+          },
+          targets: mail.targets,
+          additionalTargets: mail.additionalTargets,
+        }))
+      : [EMPTY_MAIL_ITEM],
+    documents: hasDocuments
+      ? documents.map((doc) => {
+          const documentTemplate = doc.document;
+
+          return {
+            id: documentTemplate
+              ? {
+                  label: documentTemplate.title,
+                  value: documentTemplate.id,
+                }
+              : undefined,
+            targets: doc.targets,
+            // Kept from legacy: flags the document as invalid when missing
+            ...(!documentTemplate && { documentInvalid: true }),
+          };
+        })
+      : [EMPTY_DOCUMENT_ITEM],
+    comments: hasComments ? comments : [EMPTY_COMMENT_ITEM],
+  } satisfies EventFormData;
+}
+
+/**
+ * Formats the EventFormData into an EventTemplateInput to be sent to the API.
+ */
+export function formatEventTemplateInput(values: EventFormData): EventTemplateInput {
+  function hasSelectedAction(fieldType: EventActionType) {
+    return values.actions.includes(fieldType);
+  }
+
+  const mails: EventTemplateInput['mails'] = hasSelectedAction('mails')
+    ? values.mails.map((mail) => ({
+        id: mail.id!.value, // safe because of validation schema
+        targets: mail.targets ?? [],
+        additionalTargets: mail.additionalTargets,
+      }))
+    : undefined;
+
+  const documents: EventTemplateInput['documents'] = hasSelectedAction('documents')
+    ? values.documents.map((document) => ({
+        id: document.id!.value, // safe because of validation schema
+        targets: document.targets ?? [],
+      }))
+    : undefined;
+
+  const comments: EventTemplateInput['comments'] = hasSelectedAction('comments')
+    ? values.comments.map((comment) => ({
+        title: comment.title!, // safe because of validation schema
+        value: comment.value || null,
+        targets: comment.targets ?? [],
+        code: comment.code || null,
+      }))
+    : undefined;
+
+  return {
+    name: values.name,
+    category: values.category,
+    triggers: values.triggers ?? [],
+    marketSegments: values.marketSegments ?? [],
+    mails,
+    documents,
+    comments,
+  } satisfies EventTemplateInput;
+}

