+  prod: 'prod',
+  test: 'test',
+} as const satisfies Record<BackendEnv, string>;
+
+type DatadogEnv = (typeof DATADOG_ENV_BY_BACKEND_ENV)[BackendEnv];
+
+const RUM_ENABLED_ENVS = ['dev', 'integ', 'prod'] as const satisfies DatadogEnv[];
+
+type RumEnabledEnv = (typeof RUM_ENABLED_ENVS)[number];
+
+export function isRumEnabledEnv(env: DatadogEnv): env is RumEnabledEnv {
+  return RUM_ENABLED_ENVS.includes(env as RumEnabledEnv);
+}

