+      .toBeInTheDocument();
+    await expect.element(page.getByText('Madame Camille USERS')).toBeInTheDocument();
+    await expect
+      .element(page.getByRole('heading', { name: 'Informations personnelles' }))
+      .toBeInTheDocument();
+    await expect.element(page.getByRole('heading', { name: 'Coordonnées' })).toBeInTheDocument();
+  });
+
+  testMsw('should display the last connection in Paris time zone', async () => {
+    await renderComponent();
+
+    await expect
+      .element(page.getByText('Dernière connexion : le 03-06-2026 à 09:37'))
+      .toBeInTheDocument();
+  });
+
+  testMsw('should display "Aucune connexion" when no last connection', async () => {
+    await renderComponent({
+      ...defaultProps,
+      // @ts-expect-error "lastConnexion set to undefined purposely to validate behavior"
+      content: { ...defaultProps.content, lastConnection: undefined },
+    });
+
+    await expect.element(page.getByText('Aucune connexion')).toBeInTheDocument();
+  });
+
+  testMsw('should render LoaderOverlay while loading', async () => {
+    await renderComponent({
+      ...defaultProps,
+      loading: true,
+    });
+
+    await expect.element(page.getByText('Chargement en cours...')).toBeInTheDocument();
+  });
+
+  testMsw('should display locked', async () => {
+    await renderComponent({
+      ...defaultProps,
+      content: { ...defaultProps.content, locked: true },
+    });
+
+    await expect.element(page.getByText(/Bloqué/i)).toBeInTheDocument();
+  });
+});

