+import { useEffect } from 'react';
+
+import { getErrorMessage as getApiWarnings } from '@/redux/actions/module-path.actions';
+import type { WarningsInfo } from '@/redux/reducers/module-path';
+import { useFeatureFlag } from '@/hooks/useFeatureFlag';
+import { useAppDispatch, useAppSelector } from '@/hooks/useReduxHooks';
+import type { MessageDTO } from '@/model/MessageDTO';
+
+interface UseLegacyWarningCodeMessageProps {
+  context: 'modulePath' | 'blocPath' | 'addTrainingDeparture';
+}
+
+/**
+ * @deprecated To be removed once the feature flag `messages:feature:hidden` is fully adopted
+ */
+export function useLegacyWarningCodeMessage({
+  context,
+}: Readonly<UseLegacyWarningCodeMessageProps>) {
+  const { enabled: isWarningCodeMessageHidden } = useFeatureFlag('messages:feature:hidden');
+
+  const dispatch = useAppDispatch();
+
+  /**
+   * Currently there are two reducers with the same name...: one generated dynamically (reducer-generator)
+   * and another explicitly declared in src/redux/reducers/module-path.
+   * This naming conflict causes inaccurate type inference, leading to potential issues with the Redux state.
+   * TODO: Refactor to gradually remove modulePath reducer to resolve the naming conflict and ensure accurate typing.
+   *
+   * Checking if there are warning objects in the 'modulePath.extra' reducer.
+   * These warning objects contain warning messages created in DB by ADMIN and override hard-coded messages
+   */
+  const warningExtraInfo = useAppSelector((state) => state.modulePath.extra) as WarningsInfo;
+
+  useEffect(
+    function fetchApiWarningsByContext() {
+      if (isWarningCodeMessageHidden) {
+        return;
+      }
+
+      if (context === 'modulePath') {
+        dispatch(getApiWarnings(1));
+        dispatch(getApiWarnings(2));
+      }
+
+      if (context === 'addTrainingDeparture') {
+        dispatch(getApiWarnings(3));
+      }
+
+      if (context === 'blocPath') {
+        dispatch(getApiWarnings(4));
+      }
+    },
+    [context, isWarningCodeMessageHidden],
+  );
+
+  function buildWarningMessage(warning?: MessageDTO) {
+    return {
+      isActive: Boolean(!isWarningCodeMessageHidden && warning?.actived),
+      message: _parseWarningMessage(warning?.message ?? ''),
+    };
+  }
+
+  const warningMessage1 = buildWarningMessage(warningExtraInfo.warning1);
+  const warningMessage2 = buildWarningMessage(warningExtraInfo.warning2);
+  const warningMessage3 = buildWarningMessage(warningExtraInfo.warning3);
+  const warningMessage4 = buildWarningMessage(warningExtraInfo.warning4);
+
+  return {
+    warningMessage1,
+    warningMessage2,
+    warningMessage3,
+    warningMessage4,
+  };
+}
+
+/**
+ * @legacy DB created warning messages that will override front hard-coded warning messages.
+ *
+ * @note Returning a plain string is safe here because <Messages />
+ * renders content as escaped text instead of injecting HTML.
+ *
+ * This removes the stored XSS risk introduced by the former `dangerouslySetInnerHTML` implementation.
+ * Anyway the hook is deprecated and scheduled for removal.
+ */
+function _parseWarningMessage(message: string) {
+  return message;
+}

