+import { describe, expect } from 'vitest';
+import { page } from 'vitest/browser';
+import { http, HttpResponse } from 'msw';
+import type { SetupWorker } from 'msw/browser';
+
+import { renderWithProviders } from '@/test/browser-test-utils/renderWithProviders';
+import { testMsw } from '@/test/browser-test-utils/test-extend';
+import modulePathAgenda from '@/redux/reducers/module-path/module-path-agenda';
+import modulePath from '@/redux/reducers/module-path';
+import modulePathFinalizeDate from '@/redux/reducers/module-path/module-path-finalize-date';
+import userReducer from '@/redux/reducers/user';
+import type { ModulePathDTO } from '@/model/ModulePathDTO';
+import type { SettingsState } from '@/redux/reducers/settings/settings';
+import type { LoginState } from '@/model/AuthenticatedUserDTO';
+import { PathStatus } from '@/model/PathStatusEnum';
+import endpoints from '@/constants/api-endpoints';
+import { PermissionTypes } from '@/enums/authorization';
+import { ModulePath } from '../ModulePath';
+import { modulePathFinancingControlMock } from '@/mocks/modulePath/publicMarket/modulePathFinancingControlMock';
+import { FINANCING_CONTROL_LABELS } from '../../common/FinancingControl/constants';
+
+const WRITE_PERMISSION = {
+  permissions: [PermissionTypes.MODULE_PATH_FINANCING_CONTROL_WRITE],
+} as Partial<LoginState>;
+
+function setupModulepathMswHandler(worker: SetupWorker, overrides: Partial<ModulePathDTO> = {}) {
+  worker.use(
+    http.get(endpoints.modulePath(':modulePathId'), () => {
+      return HttpResponse.json({
+        result: { ...modulePathFinancingControlMock, ...overrides },
+      });
+    }),
+  );
+}
+
+function renderModulePath(loginState = {} as Partial<LoginState>) {
+  return renderWithProviders(<ModulePath />, {
+    reducers: { modulePathAgenda, modulePath, modulePathFinalizeDate, user: userReducer },
+    preloadedState: {
+      login: {
+        permissions: [],
+        roles: [],
+        ...loginState,
+      } as LoginState,
+      settings: {
+        content: {
+          MAXIMUM_DAYS_TO_VALIDATE_ASSMAT_FINANCING_REQUEST: [{ value: '30' }],
+          MAXIMUM_DAYS_TO_VALIDATE_SPE_FINANCING_REQUEST: [{ value: '5' }],
+        },
+      } as SettingsState,
+    },
+    useReduxApiMiddleware: true,
+    pathname: '/modulePath/:modulePathId',
+    initialEntries: ['/modulePath/8078952635a66da17015a6707a5090000'],
+    withQueryClient: true,
+  });
+}
+
+describe('ModulePath financing control business rule visibility', () => {
+  // `exact` targets the action menu items only: the status tag shares the same
+  // label but its accessible name carries a trailing ` |` separator.
+  const koAction = page.getByRole('button', {
+    name: FINANCING_CONTROL_LABELS.INVALID,
+    exact: true,
+  });
+  const okAction = page.getByRole('button', { name: FINANCING_CONTROL_LABELS.VALID, exact: true });
+
+  describe('when financing control is EDITABLE (public market + write permission + eligible status)', () => {
+    testMsw(
+      'should display both actions when the path has not been controlled yet (FINANCING_REQUEST)',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker);
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect.element(koAction).toBeVisible();
+        await expect.element(okAction).toBeVisible();
+      },
+    );
+
+    testMsw(
+      'should only display the KO action when modulePath is already validated',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, { financingControl: { valid: true } });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect.element(koAction).toBeVisible();
+        await expect.element(okAction).not.toBeInTheDocument();
+      },
+    );
+
+    testMsw(
+      'should only display the OK action when modulePath is already refused',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, { financingControl: { valid: false } });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect.element(koAction).not.toBeInTheDocument();
+        await expect.element(okAction).toBeVisible();
+      },
+    );
+
+    testMsw(
+      'should display adequate actions when status is AWAITING_CONTENT_VALIDATION',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, {
+          status: PathStatus.AWAITING_CONTENT_VALIDATION,
+          financingControl: { valid: true },
+        });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect.element(koAction).toBeVisible();
+        await expect.element(okAction).not.toBeInTheDocument();
+      },
+    );
+
+    testMsw(
+      'should display an editable status TAG when status is still in the eligible window',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, {
+          status: PathStatus.AWAITING_CONTENT_VALIDATION,
+          financingControl: { valid: true },
+        });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        // Actionable status tag has an accessible name that ends with a separator " |"
+        await expect
+          .element(page.getByRole('button', { name: `${FINANCING_CONTROL_LABELS.VALID} |` }))
+          .toBeVisible();
+      },
+    );
+  });
+
+  describe('when financing control is NOT EDITABLE', () => {
+    testMsw(
+      'should hide both actions when the user lacks the write permission',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker);
+
+        await renderModulePath();
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect
+          .element(page.getByRole('button', { name: 'Synthèse du coût du PM' }))
+          .toBeVisible();
+        await expect.element(koAction).not.toBeInTheDocument();
+        await expect.element(okAction).not.toBeInTheDocument();
+      },
+    );
+
+    testMsw(
+      'should hide both actions when modulePath is not on a public market',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, { marketSegment: 'CALL_FOR_TENDER' });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect
+          .element(page.getByRole('button', { name: 'Synthèse du coût du PM' }))
+          .toBeVisible();
+        await expect.element(koAction).not.toBeInTheDocument();
+        await expect.element(okAction).not.toBeInTheDocument();
+      },
+    );
+
+    testMsw(
+      'should hide both actions and statusTag is readOnly when the status is past the eligible window (COMMITED)',
+      async ({ worker }) => {
+        setupModulepathMswHandler(worker, {
+          status: PathStatus.COMMITED,
+          financingControl: { valid: true },
+        });
+
+        await renderModulePath(WRITE_PERMISSION);
+
+        await expect.element(page.getByText('Parcours module N°1043300')).toBeVisible();
+        await page.getByRole('button', { name: 'Actions' }).click();
+
+        await expect
+          .element(page.getByRole('button', { name: 'Synthèse du coût du PM' }))
+          .toBeVisible();
+        await expect.element(koAction).not.toBeInTheDocument();
+        await expect.element(okAction).not.toBeInTheDocument();
+
+        // Status tag should be visible but not actionable.
+        await expect
+          .element(page.getByRole('button', { name: `${FINANCING_CONTROL_LABELS.VALID} |` }))
+          .not.toBeInTheDocument();
+        await expect.element(page.getByText(FINANCING_CONTROL_LABELS.VALID)).toBeVisible();
+      },
+    );
+  });
+});

