+function renderComponent(props: Partial<FinancingControlFormProps> = {}) {
+  return renderWithQuery(
+    <FinancingControlForm
+      modulePathId={MODULE_PATH_ID}
+      financingControl="VALID"
+      closeModalHandler={vi.fn()}
+      closeFinancingControlDetails={vi.fn()}
+      refreshData={vi.fn()}
+      {...props}
+    />,
+  );
+}
+
+describe('<FinancingControlForm />', () => {
+  testMsw(
+    'should display the right text confirmation when refusing the financing control',
+    async () => {
+      await renderComponent({ financingControl: 'INVALID' });
+
+      await expect
+        .element(
+          page.getByText(
+            'Veuillez indiquer les raisons pour lesquelles le parcours module doit être indiqué comme étant refusé au niveau du contrôle financier.',
+          ),
+        )
+        .toBeVisible();
+
+      await expect.element(page.getByRole('button', { name: /annuler/i })).toBeVisible();
+      await expect.element(page.getByRole('button', { name: /confirmer/i })).toBeVisible();
+    },
+  );
+
+  testMsw(
+    'should display the right text confirmation when validating the financing control',
+    async () => {
+      await renderComponent({ financingControl: 'VALID' });
+
+      await expect
+        .element(
+          page.getByText(
+            'Veuillez confirmer la validation du contrôle financier. Vous pouvez indiquer les raisons sur le champ commentaire (optionnel).',
+          ),
+        )
+        .toBeVisible();
+
+      await expect.element(page.getByRole('button', { name: /annuler/i })).toBeVisible();
+      await expect.element(page.getByRole('button', { name: /confirmer/i })).toBeVisible();
+    },
+  );
+
+  describe('Validation behavior', () => {
+    testMsw('should require a comment when refusing the financing control', async () => {
+      const closeModalHandler = vi.fn();
+      await renderComponent({ financingControl: 'INVALID', closeModalHandler });
+
+      await page.getByRole('button', { name: /confirmer/i }).click();
+
+      await expect
+        .element(page.getByText(FORM_ERROR_MESSAGES.comment.required))
+        .toBeInTheDocument();
+      expect(closeModalHandler).not.toHaveBeenCalled();
+    });
+
+    testMsw('should clear the comment error once a comment is filled', async () => {
+      await renderComponent({ financingControl: 'INVALID' });
+
+      await page.getByRole('button', { name: /confirmer/i }).click();
+      await expect
+        .element(page.getByText(FORM_ERROR_MESSAGES.comment.required))
+        .toBeInTheDocument();
+
+      await page.getByRole('textbox', { name: 'Commentaire' }).fill('Justification du refus');
+
+      await expect
+        .element(page.getByText(FORM_ERROR_MESSAGES.comment.required))
+        .not.toBeInTheDocument();
+    });
+
+    testMsw('should submit a refusal with its comment and close the modal', async ({ worker }) => {
+      let requestBody: unknown;
+      worker.use(
+        http.post(endpoints.modulePathFinancingControl(MODULE_PATH_ID), async ({ request }) => {
+          requestBody = await request.json();
+          return new HttpResponse(null, { status: 204 });
+        }),
+      );
+      const closeModalHandler = vi.fn();
+      const closeFinancingControlDetails = vi.fn();
+
+      await renderComponent({
+        financingControl: 'INVALID',
+        closeModalHandler,
+        closeFinancingControlDetails,
+      });
+
+      await page.getByRole('textbox', { name: 'Commentaire' }).fill('Refusé pour budget');
+      await page.getByRole('button', { name: /confirmer/i }).click();
+
+      await expect.poll(() => closeModalHandler).toHaveBeenCalledOnce();
+      await expect.poll(() => closeFinancingControlDetails).toHaveBeenCalledOnce();
+      expect(requestBody).toEqual({ valid: false, comment: 'Refusé pour budget' });
+    });
+
+    testMsw(
+      'should submit a validation without a comment when accepting the financing control',
+      async ({ worker }) => {
+        let requestBody: unknown;
+        worker.use(
+          http.post(endpoints.modulePathFinancingControl(MODULE_PATH_ID), async ({ request }) => {
+            requestBody = await request.json();
+            return new HttpResponse(null, { status: 204 });
+          }),
+        );
+
+        const closeModalHandler = vi.fn();
+        await renderComponent({ financingControl: 'VALID', closeModalHandler });
+
+        await page.getByRole('button', { name: /confirmer/i }).click();
+
+        await expect.poll(() => closeModalHandler).toHaveBeenCalledOnce();
+        expect(requestBody).toEqual({ valid: true, comment: null });
+      },
+    );
+
+    testMsw('should only close the current modal without submitting when cancelling', async () => {
+      const closeModalHandler = vi.fn();
+      const closeFinancingControlDetails = vi.fn();
+      await renderComponent({ closeModalHandler, closeFinancingControlDetails });
+
+      await page.getByRole('button', { name: /annuler/i }).click();
