+import { useGetEvents } from '@/hooks/data/historyEvent/useGetEvents';
+import { getLatestEventByType } from '../HistoryEvent/getLatestEventByType';
+import type { FinancingControlStatus, TrainingEventDTO } from '@/model/TrainingEventsDTO';
+import LoaderOverlay from '../LoaderOverlay/LoaderOverlay';
+import Messages from '../Messages/Messages';
+import { HistoryEventItem } from '../HistoryEvent/components/HistoryEventItem';
+import ButtonGroup from '../ButtonGroup/ButtonGroup';
+import Button from '../Button/Button';
+
+interface FinancingControlDetailsProps {
+  entityId: string;
+  canSeeEventHistory?: boolean;
+  closeModalHandler: () => void;
+  openFinancingControlDetails: (financingControl: FinancingControlStatus) => void;
+  openEventHistoryModal: () => void;
+}
+
+export function FinancingControlDetails({
+  entityId,
+  canSeeEventHistory,
+  closeModalHandler,
+  openFinancingControlDetails,
+  openEventHistoryModal,
+}: Readonly<FinancingControlDetailsProps>) {
+  const {
+    isPending,
+    error: getEventsError,
+    data: eventDatas,
+  } = useGetEvents<TrainingEventDTO>('modulePath', entityId);
+
+  const currentEvent = getLatestEventByType(eventDatas, 'FINANCING_CONTROL');
+
+  return (
+    <div className="FinancingControlDetails">
+      {isPending && (
+        <div className="FinancingControlDetails__loader">
+          <LoaderOverlay loadingText="Chargement des événements en cours..." />
+        </div>
+      )}
+
+      {getEventsError && (
+        <div className="FinancingControlDetails__apiError">
+          <Messages
+            content={getEventsError}
+            type="error"
+          />
+        </div>
+      )}
+
+      {currentEvent && (
+        <>
+          <h1>Dernier événement</h1>
+          <HistoryEventItem
+            context={'modulePath'}
+            eventDetail={currentEvent}
+          />
+          {canSeeEventHistory && (
+            <button
+              className="FinancingControlDetails__link"
+              title="Voir l'historique"
+              onClick={openEventHistoryModal}
+            >
+              Voir l'historique
+            </button>
+          )}
+        </>
+      )}
+
+      <hr />
+
+      <ButtonGroup
+        compacted
+        customCSSClassname="FinancingControlDetails__btnGroup"
+      >
+        <Button
+          type="button"
+          onClick={() => openFinancingControlDetails('VALID')}
+          appearance="blue-default"
+        >
+          <Button.Text>Marquer à nouveau OK</Button.Text>
+        </Button>
+
+        <div>
+          <Button onClick={closeModalHandler}>
+            <Button.Text>Annuler</Button.Text>
+          </Button>
+
+          <Button
+            type="button"
+            onClick={() => openFinancingControlDetails('INVALID')}
+            appearance="orange-inverted"
+          >
+            <Button.Text>Marquer comme KO</Button.Text>
+          </Button>
+        </div>
+      </ButtonGroup>
+    </div>
+  );
+}

