+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import type { FinancingControlStatus } from '@/model/TrainingEventsDTO';
+import {
+  type FinancingControlFormData,
+  financingControlFormSchema,
+} from './financingControlFormSchema';
+import ButtonGroup from '../ButtonGroup/ButtonGroup';
+import Button from '../Button/Button';
+import InputTextAreaV2 from '../InputTextArea/InputTextAreaV2';
+import { useUpdateFinancingControl } from '@/hooks/data/modulePath/financingControl/useUpdateFinancingControl';
+import { Banner } from '@/components/ui/banner/Banner';
+
+import './_FinancingControl.scss';
+
+export interface FinancingControlFormProps {
+  modulePathId: string;
+  financingControl: FinancingControlStatus | null;
+  closeModalHandler: () => void;
+  closeFinancingControlDetails: () => void;
+  refreshData: () => void;
+}
+
+export function FinancingControlForm({
+  modulePathId,
+  financingControl,
+  closeModalHandler,
+  closeFinancingControlDetails,
+  refreshData,
+}: Readonly<FinancingControlFormProps>) {
+  const {
+    register,
+    formState: { errors },
+    handleSubmit,
+  } = useForm({
+    resolver: zodResolver(financingControlFormSchema),
+    defaultValues: {
+      valid: financingControl === 'VALID',
+      comment: '',
+    } satisfies FinancingControlFormData,
+  });
+
+  const {
+    isPending: isUpdateFinancingControlPending,
+    error: updateFinancingControlError,
+    mutate: updateFinancingControlStatus,
+  } = useUpdateFinancingControl(modulePathId);
+
+  function submitHandler(values: FinancingControlFormData) {
+    updateFinancingControlStatus(
+      {
+        valid: values.valid,
+        comment: values.comment || null,
+      },
+      {
+        onSuccess: () => {
+          closeModalHandler();
+          closeFinancingControlDetails();
+          refreshData();
+        },
+      },
+    );
+  }
+
+  const financingControlModalMessage =
+    financingControl === 'INVALID'
+      ? `Veuillez indiquer les raisons pour lesquelles le parcours module doit être indiqué
+      comme étant refusé au niveau du contrôle financier.`
+      : `Veuillez confirmer la validation du contrôle financier. Vous pouvez indiquer
+      les raisons sur le champ commentaire (optionnel).`;
+
+  return (
+    <form
+      className="FinancingControl__modal"
+      onSubmit={handleSubmit(submitHandler)}
+    >
+      {updateFinancingControlError && (
+        <Banner variant="error">{updateFinancingControlError}</Banner>
+      )}
+
+      <p className="FinancingControl__message">{financingControlModalMessage}</p>
+
+      <div className="ModelFormView__row">
+        <div className="ModelFormView__formField">
+          <InputTextAreaV2
+            register={register('comment')}
+            rows={4}
+            errors={errors}
+            label="Commentaire"
+            placeholder="Saisissez un commentaire"
+            required={financingControl === 'INVALID'}
+          />
+        </div>
+      </div>
+
+      <ButtonGroup compacted>
+        <Button onClick={closeModalHandler}>
+          <Button.Text>Annuler</Button.Text>
+        </Button>
+        <Button
+          type="submit"
+          loading={isUpdateFinancingControlPending}
+          appearance="orange-inverted"
+        >
+          <Button.Text>Confirmer</Button.Text>
+        </Button>
+      </ButtonGroup>
+    </form>
+  );
+}

