+
+export function FinancingControlStatusTag({
+  isClikable,
+  valid,
+  onClick,
+}: Readonly<FinancingControlStatusTagProps>) {
+  const colorVariant: TagColor = valid ? 'forest-green' : 'chocolate-apricot';
+  const tagLabel = valid ? FINANCING_CONTROL_LABELS.VALID : FINANCING_CONTROL_LABELS.INVALID;
+
+  return (
+    <div className="FinancingControl__tagContainer">
+      {isClikable ? (
+        <Tag.Button
+          color={colorVariant}
+          title="Éditer le contrôle financier"
+          className="FinancingControl__tag"
+          onClick={onClick}
+        >
+          {`${tagLabel} |`}
+          <SvgIcon
+            name="Pencil"
+            className="FinancingControl__icon"
+          />
+        </Tag.Button>
+      ) : (
+        <Tag color={colorVariant}>{tagLabel}</Tag>
+      )}
+    </div>
+  );
+}

