+import { useState } from 'react';
+import type { FinancingControlStatus } from '@/model/TrainingEventsDTO';
+import type { ModalProps } from '../Modal/Modal';
+
+/**
+ * Custom hook for managing the financingControl modal.
+ * @returns An object containing the state and functions related
+ * to the financingControl modal.
+ */
+export function useFinancingControlModal() {
+  const [isOpen, setIsOpen] = useState(false);
+  const [financingControl, setFinancingControl] = useState<FinancingControlStatus | null>(null);
+
+  function openFinancingControlModal(status: FinancingControlStatus) {
+    setIsOpen(true);
+    setFinancingControl(status);
+  }
+
+  function closeFinancingControlModal() {
+    setIsOpen(false);
+    setFinancingControl(null);
+  }
+
+  const modalTitle = 'Contrôle financier';
+
+  const financingControlModalProps: ModalProps = {
+    isOpen,
+    closeHandler: closeFinancingControlModal,
+    contentLabel: modalTitle,
+    title: modalTitle,
+    customStyles: {
+      width: '700px',
+    },
+  };
+
+  return {
+    financingControl,
+    openFinancingControlModal,
+    closeFinancingControlModal,
+    financingControlModalProps,
+  };
+}

