+import { describe, it, expect } from 'vitest';
+
+import type { TrainingEventDTO } from '@/model/TrainingEventsDTO';
+import type { UserReferenceDTO } from '@/model/UserDTO';
+import { getLatestEventByType } from '../getLatestEventByType';
+
+const user = {
+  id: 'user-123',
+  displayName: 'John Doe',
+} satisfies UserReferenceDTO;
+
+function financingControlEvent(effectiveDate: string): TrainingEventDTO {
+  return {
+    user,
+    effectiveDate,
+    type: 'FINANCING_CONTROL',
+    metadata: { comment: null, status: 'VALID' },
+  };
+}
+
+function fundingStateEvent(effectiveDate: string): TrainingEventDTO {
+  return {
+    user,
+    effectiveDate,
+    type: 'FUNDING_STATE',
+    metadata: { comment: null, status: 'RENEWED' },
+  };
+}
+
+describe('getLatestEventByType()', () => {
+  it('returns undefined when events is undefined', () => {
+    expect(getLatestEventByType(undefined, 'FINANCING_CONTROL')).toBeUndefined();
+  });
+
+  it('returns undefined when no event matches the type', () => {
+    const events = [fundingStateEvent('2026-01-01')];
+    expect(getLatestEventByType(events, 'FINANCING_CONTROL')).toBeUndefined();
+  });
+
+  it('returns the only matching event', () => {
+    const event = financingControlEvent('2026-01-01');
+    expect(getLatestEventByType([event], 'FINANCING_CONTROL')).toEqual(event);
+  });
+
+  it('returns the most recent matching event regardless of order', () => {
+    const oldest = financingControlEvent('2026-01-01');
+    const latest = financingControlEvent('2026-03-15');
+    const middle = financingControlEvent('2026-02-10');
+
+    expect(getLatestEventByType([latest, oldest, middle], 'FINANCING_CONTROL')).toEqual(latest);
+  });
+
+  it('ignores events of other types when picking the latest', () => {
+    const financingControl = financingControlEvent('2026-01-01');
+    const newerFundingState = fundingStateEvent('2026-12-31');
+
+    expect(
+      getLatestEventByType([financingControl, newerFundingState], 'FINANCING_CONTROL'),
+    ).toEqual(financingControl);
+  });
+});

