+import { isAfter } from 'date-fns/isAfter';
+import { parseISO } from 'date-fns/parseISO';
+
+import type { TrainingEventDTO } from '@/model/TrainingEventsDTO';
+
+/**
+ * Returns the most recent event (by effectiveDate) of the given type,
+ * or undefined when there is none.
+ */
+export function getLatestEventByType<T extends TrainingEventDTO['type']>(
+  events: TrainingEventDTO[] | undefined,
+  type: T,
+): Extract<TrainingEventDTO, { type: T }> | undefined {
+  return events
+    ?.filter((event): event is Extract<TrainingEventDTO, { type: T }> => {
+      return event.type === type;
+    })
+    .reduce<Extract<TrainingEventDTO, { type: T }> | undefined>((latest, current) => {
+      if (!latest) {
+        return current;
+      }
+
+      return isAfter(parseISO(current.effectiveDate), parseISO(latest.effectiveDate))
+        ? current
+        : latest;
+    }, undefined);
+}

