+import { describe, expect, test, vi } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import { Dialog, type DialogProps } from '../Dialog';
+
+const TRIGGER_LABEL = 'Open';
+const DEFAULT_CLOSE_LABEL = 'Fermer la fenêtre';
+
+function renderDialog(props?: Partial<DialogProps>) {
+  return render(
+    <Dialog
+      title="Dialog title"
+      trigger={<button type="button">{TRIGGER_LABEL}</button>}
+      {...props}
+    >
+      Dialog content
+    </Dialog>,
+  );
+}
+
+describe('<Dialog />', () => {
+  test('opens dialog when trigger is clicked', async () => {
+    await renderDialog();
+
+    await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+  });
+
+  test('renders title as an <h2> heading and body content when open', async () => {
+    await renderDialog();
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+
+    await expect
+      .element(page.getByRole('heading', { name: 'Dialog title', level: 2 }))
+      .toBeVisible();
+    await expect.element(page.getByText('Dialog content')).toBeVisible();
+  });
+
+  test('closes dialog when close button in header is clicked', async () => {
+    await renderDialog();
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await page.getByRole('button', { name: DEFAULT_CLOSE_LABEL }).click();
+
+    await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+  });
+
+  test('renders open on mount with defaultOpen (uncontrolled)', async () => {
+    await renderDialog({ defaultOpen: true });
+
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+  });
+
+  test('calls onOpenChange when dialog is closed (controlled)', async () => {
+    const onOpenChange = vi.fn();
+
+    await render(
+      <Dialog
+        title="Dialog title"
+        open={true}
+        onOpenChange={onOpenChange}
+      >
+        Dialog content
+      </Dialog>,
+    );
+
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await page.getByRole('button', { name: DEFAULT_CLOSE_LABEL }).click();
+
+    expect(onOpenChange).toHaveBeenCalledWith(false, expect.anything());
+  });
+
+  test('uses a custom close label when provided', async () => {
+    const closeLabel = 'Close the window';
+
+    await renderDialog({ closeLabel });
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await page.getByRole('button', { name: closeLabel }).click();
+    await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+  });
+
+  test('applies custom styles to the popup', async () => {
+    await renderDialog({ styles: { maxWidth: '500px' }, open: true });
+
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await expect.element(page.getByRole('dialog')).toHaveStyle({ maxWidth: '500px' });
+  });
+
+  test('does not close on outside click by default', async () => {
+    await renderDialog();
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await _clickBackdrop();
+
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+  });
+
+  test('closes on outside click when closeOnOutsideClick is enabled', async () => {
+    await renderDialog({ closeOnOutsideClick: true });
+
+    await page.getByRole('button', { name: TRIGGER_LABEL }).click();
+    await expect.element(page.getByRole('dialog')).toBeVisible();
+
+    await _clickBackdrop();
+
+    await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+  });
+
+  test('renders a standalone nested dialog with its own backdrop while the parent is closed', async () => {
+    await render(
+      <Dialog
+        title="Parent dialog"
+        open={false}
+        nestedDialog={
+          <Dialog
+            title="Nested dialog"
+            open={true}
+            forceBackdrop={true}
+          >
+            Nested content
+          </Dialog>
+        }
+      >
+        Parent content
+      </Dialog>,
+    );
+
+    await expect
+      .element(page.getByRole('heading', { name: 'Nested dialog', level: 2 }))
+      .toBeVisible();
+    await expect.element(page.getByText('Nested content')).toBeVisible();
+
+    expect(document.querySelector('.Dialog__backdrop')).toBeInTheDocument();
+  });
+
+  describe('<Dialog.Close />', () => {
+    const CLOSE_LABEL = 'Close me';
+
+    test('closes the dialog when clicked', async () => {
+      await render(
+        <Dialog
+          title="Dialog title"
+          defaultOpen={true}
+        >
+          <Dialog.Close>{CLOSE_LABEL}</Dialog.Close>
+        </Dialog>,
+      );
+
+      await expect.element(page.getByRole('dialog')).toBeVisible();
+
+      await page.getByRole('button', { name: CLOSE_LABEL }).click();
+
+      await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+    });
+
+    test('with asChild, renders the child element directly without nesting a button', async () => {
+      await render(
+        <Dialog
+          title="Dialog title"
+          defaultOpen={true}
+        >
+          <Dialog.Close asChild>
+            <button type="button">{CLOSE_LABEL}</button>
+          </Dialog.Close>
+        </Dialog>,
+      );
+
+      const closeButton = page.getByRole('button', { name: CLOSE_LABEL });
+      await expect.element(closeButton).toBeVisible();
+
+      // Verify that the button is rendered directly without nesting inside another button
+      expect(closeButton.element().querySelector('button')).toBeNull();
+
+      await closeButton.click();
+
+      await expect.element(page.getByRole('dialog')).not.toBeInTheDocument();
+    });
+  });
+});
+
+/**
+ * Clicks near the top-left corner of the backdrop via `page.elementLocator`.
+ * A centered click can't be used: the backdrop is full-screen and the popup
+ * sits on top of it, so clicking the center would land inside the popup.
+ */
+async function _clickBackdrop() {
+  const backdrop = document.querySelector('.Dialog__backdrop');
+  if (!backdrop) {
+    throw new Error('Backdrop not found');
+  }
+
+  await page.elementLocator(backdrop).click({ position: { x: 10, y: 10 } });
+}

