+@use '/src/styles/settings' as *;
+
+/* Animation duration is exposed as a variable so consumers can override it. */
+:root {
+  --dialog-anim-duration: 200ms;
+}
+
+.Dialog {
+  &__backdrop {
+    position: fixed;
+    inset: 0;
+    min-height: 100dvh;
+    background-color: black;
+    opacity: 0.4;
+    transition: opacity 150ms;
+
+    /* iOS 26+: Ensure the backdrop covers the entire visible viewport. */
+    @supports (-webkit-touch-callout: none) {
+      position: absolute;
+    }
+
+    @media (prefers-color-scheme: dark) {
+      opacity: 0.5;
+    }
+
+    &[data-starting-style],
+    &[data-ending-style] {
+      opacity: 0;
+    }
+  }
+
+  &__popup {
+    position: fixed;
+    top: 50%;
+    left: 50%;
+    max-height: 90vh;
+    opacity: 1;
+    scale: calc(1 - 0.07 * var(--nested-dialogs, 0));
+    /*
+     * Individual transform properties so `scale` and `translate` animate independently.
+     * When a nested dialog opens, base-ui bumps --nested-dialogs; it's 0 otherwise, so the
+     * formula collapses to the normal centered position. Offset lives in `translate` (not `top`)
+     * so the shift is compositor-driven and smooth.
+     */
+    translate: -50% calc(-50% + 1.25rem * var(--nested-dialogs, 0));
+    transition:
+      translate var(--dialog-anim-duration) ease-out,
+      scale var(--dialog-anim-duration) ease-out,
+      opacity var(--dialog-anim-duration) ease-out;
+
+    &[data-starting-style],
+    &[data-ending-style] {
+      opacity: 0;
+      scale: 0.95;
+    }
+
+    /* Dim overlay so the stacked-back popup feels receded when a nested dialog is open. */
+    /* base-ui sets [data-nested-dialog-open] automatically. */
+    &[data-nested-dialog-open]::after {
+      position: absolute;
+      inset: 0;
+      pointer-events: none;
+      content: '';
+      background-color: $color-black;
+      opacity: calc(0.12 * var(--nested-dialogs));
+    }
+  }
+
+  /* Composed Dialog component styles */
+  display: flex;
+  flex-direction: column;
+  min-width: 320px;
+  max-width: 1280px;
+  background-color: $color-white;
+
+  &__header {
+    display: flex;
+    align-items: center;
+    height: 60px;
+    padding: 0 20px;
+    font-family: $font-bold;
+    color: $color-white;
+    text-transform: uppercase;
+    background-color: $color-primary;
+  }
+
+  &__pipe {
+    flex-shrink: 0;
+    width: 2px;
+    height: 35px;
+    margin-right: 25px;
+    background-color: $color-white;
+  }
+
