+import { useMutation } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { TargetPath } from '@/model/BillingEnum';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { FundingStateInput } from '@/model/TrainingEventsDTO';
+import endpoints from '@/constants/api-endpoints';
+import { fetcher } from '../queryClient';
+import { HttpVerb } from '@/helpers/http';
+
+interface UseUpdateFundingStateProps {
+  entityId: string;
+  context: `${TargetPath}`;
+  onSuccess?: () => void;
+}
+
+export function useUpdateFundingState({
+  entityId,
+  context,
+  onSuccess,
+}: Readonly<UseUpdateFundingStateProps>) {
+  const apiEndpoint =
+    context === 'MODULE_PATH'
+      ? endpoints.modulePathFundingState(entityId)
+      : endpoints.evaluationFundingState(entityId);
+
+  return useMutation<void, ApiErrors, FundingStateInput>({
+    mutationFn: (input) => {
+      return fetcher({
+        endpoint: apiEndpoint,
+        method: HttpVerb.POST,
+        params: { body: input },
+      });
+    },
+    onSuccess: () => {
+      toast.success('Le statut de financement a été mis à jour avec succès.');
+
+      if (onSuccess) {
+        onSuccess();
+      }
+    },
+  });
+}

