+/**
+ * Reshape the address value returned by `createFromModal` (legacy shape with a
+ * nested `value: { addressId }`) into the flat shape expected by InputAddressPlaceV2
+ * and `baseContactSchema` (`value` is the address id string, with a sibling `addressId`).
+ */
+export function formatModalAddressForV2(
+  addressValue: AddressInputValues,
+): LabelAndValueType & { addressId: string } {
+  const addressId =
+    typeof addressValue.value === 'string' ? addressValue.value : addressValue.value.addressId;
+
+  return {
+    label: addressValue.label,
+    value: addressId,
+    addressId,
+  };
+}

