+import {
+  useController,
+  type FieldValues,
+  type FieldPath,
+  type ControllerProps,
+} from 'react-hook-form';
+
+import { Switch, type SwitchBaseProps } from '@/components/ui/switch/Switch';
+
+export interface InputSwitchV2Props<
+  TFieldValues extends FieldValues = FieldValues,
+  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
+>
+  extends
+    Pick<ControllerProps<TFieldValues, TName>, 'name' | 'control' | 'rules'>,
+    Omit<SwitchBaseProps, 'name' | 'onChange' | 'checked' | 'fieldRef'> {
+  /**
+   * Optional callback triggered when the value changes
+   */
+  onChange?: (checked: boolean) => void;
+}
+
+/**
+ * RHF controlled toggle switch with sliding on/off labels.
+ */
+export function InputSwitchV2<
+  T extends FieldValues = FieldValues,
+  U extends FieldPath<T> = FieldPath<T>,
+>({
+  control,
+  name,
+  rules,
+  label,
+  variant,
+  onLabel,
+  offLabel,
+  className,
+  disabled,
+  onChange: handleChange,
+}: Readonly<InputSwitchV2Props<T, U>>) {
+  const { field, fieldState } = useController({
+    name,
+    control,
+    rules,
+  });
+
+  const errorMessage = fieldState.error?.message;
+
+  function handleCheckedChange(checked: boolean) {
+    field.onChange(checked);
+    handleChange?.(checked);
+  }
+
+  return (
+    <Switch
+      name={field.name}
+      checked={!!field.value}
+      onChange={handleCheckedChange}
+      onBlur={field.onBlur}
+      fieldRef={field.ref}
+      errorMessage={errorMessage}
+      label={label}
+      variant={variant}
+      onLabel={onLabel}
+      offLabel={offLabel}
+      className={className}
+      disabled={disabled}
+    />
+  );
+}

