+import { describe, expect, test, vi } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page, userEvent } from 'vitest/browser';
+import { useState } from 'react';
+
+import { Switch } from '../Switch';
+
+function ControlledSwitch({
+  initialChecked = false,
+  onChange,
+  ...props
+}: Readonly<
+  Partial<React.ComponentProps<typeof Switch>> & {
+    initialChecked?: boolean;
+  }
+>) {
+  const [checked, setChecked] = useState(initialChecked);
+
+  function handleChange(value: boolean) {
+    setChecked(value);
+    onChange?.(value);
+  }
+
+  return (
+    <Switch
+      name="test-switch"
+      label="Test label"
+      checked={checked}
+      onChange={handleChange}
+      {...props}
+    />
+  );
+}
+
+describe('<Switch />', () => {
+  describe('Rendering', () => {
+    test('renders the label and the switch element', async () => {
+      await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={false}
+          onChange={vi.fn()}
+        />,
+      );
+
+      await expect.element(page.getByText('Notifications')).toBeVisible();
+      await expect.element(page.getByRole('switch', { name: 'Notifications' })).toBeInTheDocument();
+    });
+  });
+
+  describe('Checked state', () => {
+    test('is checked when checked=true', async () => {
+      await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={true}
+          onChange={vi.fn()}
+        />,
+      );
+
+      await expect.element(page.getByRole('switch', { name: 'Notifications' })).toBeChecked();
+    });
+
+    test('is not checked when checked=false', async () => {
+      await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={false}
+          onChange={vi.fn()}
+        />,
+      );
+
+      await expect.element(page.getByRole('switch', { name: 'Notifications' })).not.toBeChecked();
+    });
+
+    test('reflects externally controlled value on rerender', async () => {
+      const { rerender } = await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={false}
+          onChange={vi.fn()}
+        />,
+      );
+
+      await expect.element(page.getByRole('switch', { name: 'Notifications' })).not.toBeChecked();
+
+      await rerender(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={true}
+          onChange={vi.fn()}
+        />,
+      );
+
+      await expect.element(page.getByRole('switch', { name: 'Notifications' })).toBeChecked();
+    });
+  });
+
+  describe('Toggle behavior', () => {
+    test('calls onChange with true when toggled on', async () => {
+      const handleChange = vi.fn();
+
+      await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={false}
+          onChange={handleChange}
+        />,
+      );
+
+      await page.getByRole('switch', { name: 'Notifications' }).click();
+
+      expect(handleChange).toHaveBeenCalledWith(true);
+    });
+
+    test('calls onChange with false when toggled off', async () => {
+      const handleChange = vi.fn();
+
+      await render(
+        <Switch
+          name="test-switch"
+          label="Notifications"
+          checked={true}
+          onChange={handleChange}
+        />,
+      );
+
+      await page.getByRole('switch', { name: 'Notifications' }).click();
+
+      expect(handleChange).toHaveBeenCalledWith(false);
+    });
+
+    test('toggles checked state on click', async () => {
