+
+      const switchInput = page.getByRole('switch', { name: 'Notifications' });
+
+      await expect.element(switchInput).not.toBeChecked();
+      await switchInput.click();
+      await expect.element(switchInput).toBeChecked();
+      await switchInput.click();
+      await expect.element(switchInput).not.toBeChecked();
+    });
+
+    test('toggles on Space key press', async () => {
+      await render(<ControlledSwitch label="Notifications" />);
+
+      const switchInput = page.getByRole('switch', { name: 'Notifications' });
