+   * The name of the switch, used for the input and error association
+   */
+  name: string;
+  /**
+   * Visual label to be displayed above or next to the switch component.
+   */
+  label: string;
+  /**
+   * Whether the switch is on. Should be controlled from outside the component.
+   */
+  checked: boolean;
+  /**
+   * Callback triggered when the switch is toggled, with the new state as argument
+   */
+  onChange?: (checked: boolean) => void;
+  /**
+   * Visual variant.
+   * - `labeled`: wide track with sliding on/off text inside, main label above.
+   * - `inline`: compact track with no inner text, main label placed to the right.
+   * @default 'labeled'
+   */
+  variant?: SwitchVariant;
+  /**
+   * Text displayed inside the track when on. Only used by the `labeled` variant.
+   * @default 'Activé'
+   */
+  onLabel?: string;
+  /**
+   * Text displayed inside the track when off. Only used by the `labeled` variant.
+   * @default 'Désactivé'
+   */
+  offLabel?: string;
+  /**
+   * Optional css class added to the component wrapper
+   */
+  className?: string;
+  /**
+   * Error message to display below the component in case of validation error
+   */
+  errorMessage?: string;
+  disabled?: boolean;
+  onBlur?: () => void;
+  fieldRef?: RefCallBack;
+}
+
+/**
+ * Toggle switch component built on the Base UI Switch primitive for native
+ * accessibility (role, keyboard handling, checked state).
+ * Comes in two variants: `labeled` (sliding on/off text, label above) and
+ * `inline` (compact, label on the right).
+ * Can be used standalone (controlled from outside) or integrated with RHF.
+ */
+export function Switch({
+  name,
+  checked,
+  onChange,
+  label,
+  variant = 'labeled',
+  onLabel = 'Activé',
+  offLabel = 'Désactivé',
+  className,
+  disabled,
+  errorMessage,
+  onBlur,
+  fieldRef,
+}: Readonly<SwitchBaseProps>) {
+  const fieldErrorId = `${name}-error`;
+
+  function handleCheckedChange(value: boolean) {
+    onChange?.(value);
+  }
+
+  const labelNode = <span className="Switch__label">{label}</span>;
+
+  const trackNode = (
+    <BaseSwitch.Root
+      name={name}
+      checked={checked}
+      onCheckedChange={handleCheckedChange}
+      disabled={disabled}
+      inputRef={fieldRef}
+      onBlur={onBlur}
+      aria-invalid={!!errorMessage}
+      aria-errormessage={errorMessage ? fieldErrorId : undefined}
+      className="Switch__track"
+    >
+      {variant === 'labeled' && (
+        <span
+          className="Switch__values"
+          data-on={onLabel}
+          data-off={offLabel}
+        />
+      )}
+      <BaseSwitch.Thumb className="Switch__thumb" />
+    </BaseSwitch.Root>
+  );
+
+  return (
+    <label
+      className={cs('Switch', `Switch--${variant}`, className, {
+        'Switch--state-error': errorMessage,
+      })}
+    >
+      <span className="Switch__control">
+        {variant === 'inline' ? (
+          <>
+            {trackNode}
+            {labelNode}
+          </>
+        ) : (
+          <>
+            {labelNode}
+            {trackNode}
+          </>
+        )}
+      </span>
+
+      {errorMessage && (
+        <p
+          id={fieldErrorId}
+          className="Switch__errorMessage"
+        >
+          {errorMessage}
+        </p>
+      )}
+    </label>
+  );
+}

