+@use '/src/styles/settings' as *;
+
+.Switch {
+  display: inline-flex;
+  flex-direction: column;
+}
+
+.Switch__control {
+  display: inline-flex;
+}
+
+.Switch--labeled .Switch__control {
+  flex-direction: column;
+}
+
+.Switch--inline .Switch__control {
+  flex-direction: row;
+  gap: 0.75rem;
+  align-items: center;
+}
+
+.Switch__label {
+  font-size: 1rem;
+  color: $color-primary;
+}
+
+.Switch--labeled .Switch__label {
+  display: block;
+  padding-bottom: 5px;
+  text-transform: uppercase;
+}
+
+.Switch__track {
+  position: relative;
+  display: inline-block;
+  height: 34px;
+  padding: 0;
+  margin-top: 2px;
+  cursor: pointer;
+  background-color: $color-alto;
+  border: 0;
+  border-radius: 34px;
+  transition: background-color 0.4s;
+
+  /* on state is black (palette dark) for the inline variant */
+  &[data-checked] {
+    background-color: $color-primary;
+  }
+
+  &:focus-visible {
+    outline: none;
+    box-shadow: 0 0 1px $color-secondary;
+  }
+
+  &[data-disabled] {
+    cursor: not-allowed;
+    opacity: 0.6;
+  }
+}
+
+.Switch--labeled .Switch__track {
+  width: 110px;
+
+  /* legacy variant keeps the orange on state */
+  &[data-checked] {
+    background-color: $color-secondary;
+  }
+}
+
+.Switch--inline .Switch__track {
+  width: 60px;
+  height: 32px;
+  margin-top: 0;
+}
+
+.Switch--state-error .Switch__track {
+  border: 1px solid $color-error;
+}
+
+.Switch__thumb {
+  position: absolute;
+  bottom: 4px;
+  left: 4px;
+  box-sizing: border-box;
+  width: 26px;
+  height: 26px;
+  background-color: $color-concrete;
+  border: 1px solid $color-primary;
+  border-radius: 50%;
+  transition: left 0.4s;
+}
+
+.Switch--labeled .Switch__track[data-checked] .Switch__thumb {
+  /* anchored to the right edge so the track can be any width */
+  left: calc(100% - 26px - 4px);
+}
+
+.Switch--inline {
+  .Switch__thumb {
+    width: 24px;
+    height: 24px;
+  }
+
+  .Switch__track[data-checked] .Switch__thumb {
+    left: calc(100% - 24px - 4px);
+  }
+}
+
+/* sliding on/off labels — labeled variant only */
+.Switch__values {
+  position: absolute;
+  top: 5px;
+  left: 0;
+  width: 100%;
+  height: 100%;
+  font-size: 1rem;
+  pointer-events: none;
+
+  &::after {
+    position: absolute;
+    right: 12px;
+    color: $color-primary;
+    content: attr(data-off);
+    opacity: 1;
+    transition: opacity 0.4s ease-in-out;
+  }
+
+  &::before {
+    position: absolute;
+    left: 12px;
+    /* on-label sits on the black track, so it is light */
+    color: $color-concrete;
+    content: attr(data-on);
+    opacity: 0;
+    transition: opacity 0.4s ease-in-out;
+  }
+}
+
+.Switch__track[data-checked] .Switch__values::after {
+  opacity: 0;
+}
+
+.Switch__track[data-checked] .Switch__values::before {
+  opacity: 1;
+}
+
+.Switch__errorMessage {
+  margin: 0;
+  color: $color-error;
+}

