+import { useMutation, useQueryClient } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { SettingInput } from '@/model/SettingsInput';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import { HttpVerb } from '@/helpers/http';
+import endpoints from '@/constants/api-endpoints';
+import { fetcher } from '../queryClient';
+import { invalidateGetSettings } from './useGetSettings';
+
+export function useUpdateSettings() {
+  const queryClient = useQueryClient();
+
+  const result = useMutation<void, ApiErrors, SettingInput['settings']>({
+    mutationFn: (settingsValue) => {
+      return fetcher({
+        endpoint: endpoints.settingSave,
+        method: HttpVerb.PUT,
+        params: {
+          body: {
+            settings: settingsValue,
+          } satisfies SettingInput,
+        },
+      });
+    },
+    onSuccess: () => {
+      toast.success('Paramètres modifiés avec succès.');
+      void invalidateGetSettings(queryClient);
+    },
+  });
+
+  return result;
+}

