+import * as duration from 'duration-fns';
+
+import type { SettingsParams } from '../types';
+import type { LearnerSettingFormData } from './learnerSettingsValidationSchema';
+import type { LearnerSettingsInput } from '@/model/SettingsInput';
+import { hasSettings } from '@/redux/reducers/settings/helpers';
+import { DEFAULT_PASSPORT_ACTIVATION_DATE } from '../constants';
+
+export function initializeLearnerSettingsFormData(
+  settingsData: SettingsParams,
+): LearnerSettingFormData {
+  const settings = settingsData.content;
+
+  const assmatQuota = (settings?.ASSMAT_QUOTA ?? []).map((quota) => ({
+    value: quota.value,
+    year: quota.endDate?.slice(0, 4) as string,
+  }));
+
+  const speQuota = (settings?.SPE_QUOTA ?? []).map((quota) => ({
+    value: quota.value,
+    year: quota.endDate?.slice(0, 4) as string,
+  }));
+
+  const passportActivationDate =
+    settings?.PASSPORT_ACTIVATION_DATE?.at(0)?.value ?? DEFAULT_PASSPORT_ACTIVATION_DATE;
+  const passportProviderEmail = settings?.PASSPORT_PDF_EMAIL_RECIPIENT?.at(0)?.value ?? null;
+  const modulePathOFRegistrationSetting = settings?.MODULE_PATH_OF_REGISTRATION_DELAY ?? [];
+  const blocPathOFRegistrationSetting = settings?.BLOC_PATH_OF_REGISTRATION_DELAY ?? [];
+
+  const modulePathRegistrationDelay = modulePathOFRegistrationSetting.map((delayDuration) => {
+    // Parse into Duration Obj than convert into days unit.
+    const durationInDays = delayDuration.value
+      ? duration.toDays(duration.parse(delayDuration.value))
+      : '';
+
+    return {
+      value: String(durationInDays),
+      startDate: delayDuration.startDate ?? '',
+      endDate: delayDuration.endDate ?? '',
+    };
+  });
+
+  const blocPathRegistrationDelay = blocPathOFRegistrationSetting.map((delayDuration) => {
+    const durationInDays = delayDuration.value
+      ? duration.toDays(duration.parse(delayDuration.value))
+      : '';
+
+    return {
+      value: String(durationInDays),
+      startDate: delayDuration.startDate ?? '',
+      endDate: delayDuration.endDate ?? '',
+    };
+  });
+
+  const mothmaActivation = hasSettings(settingsData, {
+    enabledAttributes: 'MOTHMA_ENABLED',
+  });
+  const trainingModeV1Enabled = hasSettings(settingsData, {
+    enabledAttributes: 'TRAINING_MODE_V1_ENABLED',
+  });
+  const enableTrainingHoursValidation = hasSettings(settingsData, {
+    enabledAttributes: 'TRAINING_HOURS_REGISTRATION_VALIDATION',
+  });
+  const enableTrainingPlanValidation = hasSettings(settingsData, {
+    enabledAttributes: 'TRAINING_PLAN_REGISTRATION_VALIDATION',
+  });
+
+  return {
+    mothmaEnabled: mothmaActivation,
+    trainingHoursRegistrationValidation: enableTrainingHoursValidation,
+    trainingPlanRegistrationValidation: enableTrainingPlanValidation,
+    trainingModeV1Enabled,
+    modulePathOFRegisterDelay: modulePathRegistrationDelay,
+    blocPathOFRegisterDelay: blocPathRegistrationDelay,
+    assmatQuota,
+    speQuota,
+    passportActivationDate,
+    passportProviderEmail,
+  } satisfies LearnerSettingFormData;
+}
+
+export function formatLearnerSettingsFormData(
+  values: LearnerSettingFormData,
+): LearnerSettingsInput {
+  const cleanedAssmatQuota = values.assmatQuota.filter(
+    (quota) => 'value' in quota && quota.value !== '',
+  );
+  const cleanedSpeQuota = values.speQuota.filter((quota) => 'value' in quota && quota.value !== '');
+
+  const settingsInput: LearnerSettingsInput = {
+    MOTHMA_ENABLED: [{ value: values.mothmaEnabled }],
+    TRAINING_HOURS_REGISTRATION_VALIDATION: [{ value: values.trainingHoursRegistrationValidation }],
+    TRAINING_PLAN_REGISTRATION_VALIDATION: [{ value: values.trainingPlanRegistrationValidation }],
+    TRAINING_MODE_V1_ENABLED: [{ value: values.trainingModeV1Enabled }],
+    MODULE_PATH_OF_REGISTRATION_DELAY: values.modulePathOFRegisterDelay.map((registration) => {
+      // Formatting into Duration Object in order to parse into duration ISO-8601
+      const durationDelay = {
+        days: Number(registration.value || 0),
+      };
+
+      return {
+        value: duration.toString(durationDelay),
+        startDate: registration.startDate || null,
+        endDate: registration.endDate || null,
+      };
+    }),
+    BLOC_PATH_OF_REGISTRATION_DELAY: values.blocPathOFRegisterDelay.map((registration) => {
+      const durationDelay = {
+        days: Number(registration.value || 0),
+      };
+
+      return {
+        value: duration.toString(durationDelay),
+        startDate: registration.startDate || null,
+        endDate: registration.endDate || null,
+      };
+    }),
