+import { z } from 'zod';
+import { isBefore } from 'date-fns/isBefore';
+import { isSameDay } from 'date-fns/isSameDay';
+import { parseISO } from 'date-fns/parseISO';
+
+import { areDatesOverlapping } from '@/helpers/validations/periods.validations';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type LearnerSettingFormData = z.infer<typeof learnerSettingsSchema>;
+
+// ----- schema -----
+
+const baseRegistrationDelaySchema = z.object({
+  value: z.string().min(1, FORM_ERROR_MESSAGES.settings.defaultDelay).prefault(''),
+  startDate: z.string().min(1, FORM_ERROR_MESSAGES.date.startDateRequired).prefault(''),
+  endDate: z.string().min(1, FORM_ERROR_MESSAGES.date.endDateRequired).prefault(''),
+});
+
+const learnerRegistrationDelaySchema = z
+  .array(baseRegistrationDelaySchema)
+  .superRefine((settings, ctx) => {
+    // overlapFound behavior (stop after first overlap)
+    let overlapFound = false;
+
+    for (let i = 0; i < settings.length && !overlapFound; i++) {
+      // j = i + 1 avoids double-checking pairs
+      for (let j = i + 1; j < settings.length; j++) {
+        if (areDatesOverlapping(settings[i], settings[j])) {
+          ctx.addIssue({
+            code: 'custom',
+            message: FORM_ERROR_MESSAGES.date.overlappingPeriods,
+            path: [j, 'startDate'],
+          });
+
+          overlapFound = true;
+          break;
+        }
+      }
+    }
+
+    settings.forEach((item, index) => {
+      if (!item.startDate || !item.endDate) {
+        return;
+      }
+
+      const startDate = parseISO(item.startDate);
+      const endDate = parseISO(item.endDate);
+
+      if (isSameDay(startDate, endDate)) {
+        ctx.addIssue({
+          code: 'custom',
+          message: FORM_ERROR_MESSAGES.date.identicalDates,
+          path: [index, 'endDate'],
+        });
+      }
+
+      if (isBefore(endDate, startDate)) {
+        ctx.addIssue({
+          code: 'custom',
+          message: FORM_ERROR_MESSAGES.date.endDateBeforeStartDate,
+          path: [index, 'endDate'],
+        });
+      }
+    });
+  });
+
+const quotaHoursSchema = z.object({
+  value: z.string().prefault(''),
+  year: z.string().prefault(''),
+});
+
+export const learnerSettingsSchema = z.object({
+  mothmaEnabled: z.boolean(),
+  trainingHoursRegistrationValidation: z.boolean(),
+  trainingPlanRegistrationValidation: z.boolean(),
+  trainingModeV1Enabled: z.boolean(),
+  modulePathOFRegisterDelay: learnerRegistrationDelaySchema,
+  blocPathOFRegisterDelay: learnerRegistrationDelaySchema,
+  assmatQuota: z.array(quotaHoursSchema),
+  speQuota: z.array(quotaHoursSchema),
+  passportActivationDate: z.string().prefault(''),
+  passportProviderEmail: z.string().nullable(),
+});

