+    await expect
+      .element(page.getByRole('textbox', { name: 'Charges sociales SPE' }))
+      .toHaveDisplayValue('10');
+    await expect
+      .element(page.getByRole('textbox', { name: 'Charges sociales ASSMAT' }))
+      .toHaveDisplayValue('10');
+  });
+
+  describe('form validation', () => {
+    testMsw('should show and clear validation errors progressively', async () => {
+      await renderApniSettingsForm();
+
+      const saveButton = page.getByRole('button', { name: 'Enregistrer' });
+      const socialChargesGroup = page.getByRole('group', { name: 'Charges sociales' });
+
+      const addSPEPeriodButton = socialChargesGroup
+        .getByRole('button', { name: 'Ajouter une période' })
+        .nth(0);
+      await addSPEPeriodButton.click();
+      await saveButton.click();
+
+      const newSPEValueInput = page.getByRole('textbox', { name: 'Charges sociales SPE' }).nth(1);
+      const newSPEStartDateInput = page.getByRole('textbox', { name: 'Date de début' }).nth(1);
+      const newSPEEndDateInput = page.getByRole('textbox', { name: 'Date de fin' }).nth(1);
+
+      await expect
+        .element(newSPEValueInput)
+        .toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.settings.fieldRequired);
+      await expect
+        .element(newSPEStartDateInput)
+        .toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.date.startDateRequired);
+      await expect
+        .element(newSPEEndDateInput)
+        .toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.date.endDateRequired);
+
+      // Trigger out of range error
+      await newSPEValueInput.fill('101');
+      await userEvent.tab();
+      await expect
+        .element(newSPEValueInput)
+        .toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.settings.numberOutOfRange);
+
+      // Fix value error
+      await newSPEValueInput.clear();
+      await newSPEValueInput.fill('15');
+      await expect
+        .element(newSPEValueInput)
+        .not.toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.settings.fieldRequired);
+
+      // Fix startDate error
+      await newSPEStartDateInput.fill('10122027');
+      await userEvent.tab();
+      await expect
+        .element(newSPEStartDateInput)
+        .not.toHaveAccessibleErrorMessage(FORM_ERROR_MESSAGES.date.startDateRequired);
+
+      // Fill endDate before startDate → trigger endDateBeforeStartDate error
