+
+export type ApniSettingFormData = z.infer<typeof apniSettingsSchema>;
+
+// ----- schema -----
+
+const baseSocialChargeSchema = baseDateRangeSchema.extend({
+  value: z
+    .string()
+    .min(1, FORM_ERROR_MESSAGES.settings.fieldRequired)
+    .prefault('')
+    .refine((value) => Number(value) <= 100, {
+      error: FORM_ERROR_MESSAGES.settings.numberOutOfRange,
+    }),
+});
+
+const socialChargeSchema = z.array(baseSocialChargeSchema).superRefine((settings, ctx) => {
+  addOverlappingPeriodsIssue(settings, ctx);
+
+  settings.forEach((item, index) => {
+    if (!item.startDate || !item.endDate) {
+      return;
+    }
+
+    const startDate = parseISO(item.startDate);
+    const endDate = parseISO(item.endDate);
+
+    if (isBefore(endDate, startDate)) {
+      ctx.addIssue({
+        code: 'custom',
+        message: FORM_ERROR_MESSAGES.date.endDateBeforeStartDate,
+        path: [index, 'endDate'],
+      });
+    }
+  });
+});
+
+export const apniSettingsSchema = z.object({
+  paymentToLearnerSwitchDate: z.string().nullish(),
+  socialChargesSPE: socialChargeSchema,
+  socialChargesASSMAT: socialChargeSchema,
+});

