+/**
+ * Adds a Zod issue on the first pair of overlapping date ranges found.
+ * Stops after the first overlap, flagging the later period's `startDate`.
+ */
+export function addOverlappingPeriodsIssue(
+  settings: DateRangeFormData[],
+  ctx: z.RefinementCtx,
+): void {
+  for (let i = 0; i < settings.length; i++) {
+    // j = i + 1 avoids double-checking pairs
+    for (let j = i + 1; j < settings.length; j++) {
+      if (areDatesOverlapping(settings[i], settings[j])) {
+        ctx.addIssue({
+          code: 'custom',
+          message: FORM_ERROR_MESSAGES.date.overlappingPeriods,
+          path: [j, 'startDate'],
+        });
+
+        return; // first overlap only
+      }
+    }
+  }
+}
