+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import type { SettingsSubFormProps } from '../types';
+import {
+  communicationSettingsSchema,
+  type CommunicationSettingsFormData,
+} from './communicationSettingsValidationSchema';
+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import { MESSAGE_TYPE_LABEL, type MessageType } from '../constants';
+import { SettingsErrorMessage } from '../SettingsErrorMessage';
+import { useUpdateSettings } from '@/hooks/data/settings/useUpdateSettings';
+import Fieldset from '../../common/ModelFormView/Fieldset/Fieldset';
+import ButtonGroup from '../../common/ButtonGroup/ButtonGroup';
+import Button from '../../common/Button/Button';
+import InputTextV2 from '../../common/InputText/InputTextV2';
+import InputTextAreaV2 from '../../common/InputTextArea/InputTextAreaV2';
+import InputSelectV2 from '../../common/InputSelect/InputSelectV2';
+import InputDateV2 from '../../common/InputDate/InputDateV2';
+import { formatCommunicationSettingsFormData } from './helpers';
+
+interface CommunicationSettingsFormProps extends SettingsSubFormProps {
+  userIsIperiaSu: boolean;
+}
+
+export function CommunicationSettingsForm({
+  settings,
+  userIsIperiaSu,
+}: Readonly<CommunicationSettingsFormProps>) {
+  // ----- hooks -----
+
+  const {
+    control,
+    register,
+    handleSubmit,
+    formState: { isDirty, errors },
+  } = useForm({
+    resolver: zodResolver(communicationSettingsSchema),
+    values: {
+      homeMessage: settings?.content?.HOME_PAGE_MESSAGE?.at(0)?.value ?? '',
+      infoTypeMessage: settings?.content?.INFORMATIVE_MESSAGE_TYPE?.at(0)?.value as MessageType,
+      infoMessage: settings?.content?.INFORMATIVE_MESSAGE_TEXT?.at(0)?.value ?? '',
+      startDateMessage: settings?.content?.INFORMATIVE_MESSAGE_TEXT?.at(0)?.startDate ?? '',
+      endDateMessage: settings?.content?.INFORMATIVE_MESSAGE_TEXT?.at(0)?.endDate ?? '',
+    } satisfies CommunicationSettingsFormData,
+  });
+
+  const { isPending, error: updateSettingsError, mutate: updateSettings } = useUpdateSettings();
+
+  // ----- handler -----
+
+  function submitHandler(formValue: CommunicationSettingsFormData) {
+    const settingsInput = formatCommunicationSettingsFormData(formValue);
+
+    updateSettings(settingsInput);
+  }
+
+  // ----- rendering -----
+
+  return (
+    <form
+      className="SettingsForm__panel"
+      onSubmit={handleSubmit(submitHandler)}
+      noValidate
+    >
+      <div className="SettingsForm__panel__content">
+        <SettingsErrorMessage error={updateSettingsError} />
+
+        {!userIsIperiaSu && (
+          <Fieldset title="Message d'accueil">
+            <div className="SettingsForm__block">
+              <InputTextV2
+                control={control}
+                name="homeMessage"
+                label="Message"
+              />
+            </div>
+          </Fieldset>
+        )}
+
+        <Fieldset title="Message informatif">
+          <div className="SettingsForm__block">
+            <div className="ModelFormView__row">
+              <InputTextAreaV2
+                register={register('infoMessage')}
+                label="Contenu du message"
+                errors={errors}
+                className="ModelFormView__formField"
+              />
+
+              <InputSelectV2
+                control={control}
+                name="infoTypeMessage"
+                label="Type de message"
+                options={getInputSelectOptions(MESSAGE_TYPE_LABEL)}
+                className="ModelFormView__formField"
+              />
+            </div>
+
+            <div className="ModelFormView__row">
+              <InputDateV2
+                control={control}
+                name="startDateMessage"
+                label="Date de début"
+                forMoment
+                className="ModelFormView__formField"
+              />
+
+              <InputDateV2
+                control={control}
+                name="endDateMessage"
+                label="Date de fin"
+                forMoment
+                className="ModelFormView__formField"
+              />
+            </div>
+          </div>
+        </Fieldset>
+      </div>
+
+      <ButtonGroup
+        customCSSClassname="SettingsForm__panel__buttons"
+        sticky
+      >
+        <Button
+          type="submit"
+          appearance="orange-inverted"
+          loading={isPending}
+          disabled={!isDirty}
+        >
+          <Button.Text>Enregistrer</Button.Text>
+        </Button>
+      </ButtonGroup>
+    </form>
+  );
+}

