+import { z } from 'zod';
+import { isAfter } from 'date-fns/isAfter';
+
+import { MESSAGE_TYPE_LABEL } from '../constants';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type CommunicationSettingsFormData = z.infer<typeof communicationSettingsSchema>;
+
+const MESSAGE_TYPE = Object.keys(MESSAGE_TYPE_LABEL) as Array<keyof typeof MESSAGE_TYPE_LABEL>;
+
+export const communicationSettingsSchema = z
+  .object({
+    homeMessage: z.string().nullish(),
+    infoMessage: z.string().nullish(),
+    infoTypeMessage: z.enum(MESSAGE_TYPE).nullish(),
+    startDateMessage: z.string().nullable().optional(),
+    endDateMessage: z.string().nullable().optional(),
+  })
+  .superRefine((values, ctx) => {
+    if (values.infoMessage?.trim() && !values.infoTypeMessage) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['infoTypeMessage'],
+        message: FORM_ERROR_MESSAGES.settings.infoTypeMessageRequired,
+      });
+    }
+
+    if (values.infoTypeMessage && !values.infoMessage?.trim()) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['infoMessage'],
+        message: FORM_ERROR_MESSAGES.settings.infoMessageRequired,
+      });
+    }
+
+    if (!values.startDateMessage && !values.endDateMessage) {
+      return;
+    }
+
+    if (!values.startDateMessage && values.endDateMessage) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['startDateMessage'],
+        message: FORM_ERROR_MESSAGES.date.startDateRequired,
+      });
+    }
+
+    if (
+      values.startDateMessage &&
+      values.endDateMessage &&
+      isAfter(values.startDateMessage, values.endDateMessage)
+    ) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['endDateMessage'],
+        message: FORM_ERROR_MESSAGES.date.endDateBeforeStartDate,
+      });
+    }
+  });

