+import type { CommunicationSettingsInput } from '@/model/SettingsInput';
+import type { CommunicationSettingsFormData } from './communicationSettingsValidationSchema';
+
+export function formatCommunicationSettingsFormData(
+  values: CommunicationSettingsFormData,
+): CommunicationSettingsInput {
+  const settingsInput: CommunicationSettingsInput = {
+    HOME_PAGE_MESSAGE: [
+      {
+        value: values.homeMessage ?? '',
+      },
+    ],
+    INFORMATIVE_MESSAGE_TYPE: [
+      {
+        value: values.infoTypeMessage || 'NONE',
+      },
+    ],
+    INFORMATIVE_MESSAGE_TEXT: [
+      {
+        value: values.infoMessage || '',
+        // @ts-expect-error: to keep the same legacy behaviour the date is not converted into string
+        startDate: values.startDateMessage || new Date(),
+        endDate: values.endDateMessage || null,
+      },
+    ],
+  };
+
+  return settingsInput;
+}

