+import { z } from 'zod';
+
+import {
+  baseDateRangeSchema,
+  baseOpenEndedDateRangeSchema,
+} from '@/helpers/validations/schemas/baseDateRangeSchema';
+import { addDateRangePeriodIssues } from '@/helpers/validations/settings.validations';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type BillingSettingFormData = z.infer<typeof billingSettingsSchema>;
+export type BillingSettingFormInput = z.input<typeof billingSettingsSchema>;
+export type FunderTrainingFormData = z.infer<typeof funderTrainingSchema>;
+
+type IssuerDocumentTemplateItem = z.input<typeof issuerDocumentTemplateSchema>;
+
+export const EMPTY_PERIOD_ITEM = {
+  startDate: '',
+  endDate: '',
+  value: '',
+};
+
+export const EMPTY_ISSUER_DOCUMENT_TEMPLATE_ITEM: IssuerDocumentTemplateItem = {
+  issuer: null,
+  template: null,
+  startDate: '',
+  endDate: '',
+};
+
+// ----- schemas -----
+
+const numericStringGreaterThanZero = z.string().refine((value) => Number(value) > 0, {
+  error: FORM_ERROR_MESSAGES.settings.atLeastOneLearnerPerGroup,
+});
+
+const allowanceSchema = baseOpenEndedDateRangeSchema.extend({
+  value: z.string().refine((value) => Number(value) > 0, {
+    error: FORM_ERROR_MESSAGES.settings.positiveAllowanceAmount,
+  }),
+});
+
+const thresholdSchema = baseOpenEndedDateRangeSchema.extend({
+  value: z.string().refine((value) => Number(value) > 0, {
+    error: FORM_ERROR_MESSAGES.settings.positiveThresholdAmount,
+  }),
+});
+
+const funderTrainingSchema = baseDateRangeSchema.extend({
+  value: z
+    .string()
+    .nullable()
+    .refine((val) => val !== null && val.trim().length > 0, {
+      error: FORM_ERROR_MESSAGES.settings.fieldRequired,
+    }),
+});
+
+const comboboxOptionSchema = z.object({
+  label: z.string(),
+  value: z.string(),
+});
+
+const issuerDocumentTemplateSchema = baseDateRangeSchema.extend({
+  issuer: comboboxOptionSchema.nullable().refine((value) => value !== null, {
+    error: FORM_ERROR_MESSAGES.issuer.required,
+  }),
+  template: comboboxOptionSchema.nullable().refine((value) => value !== null, {
+    error: FORM_ERROR_MESSAGES.documentTemplate.modelRequired,
+  }),
+});
+
+const administrativeFeeSchema = baseDateRangeSchema.extend({
+  value: z.string().refine((value) => Number(value) > 0, {
+    error: FORM_ERROR_MESSAGES.settings.positiveFeeAmount,
+  }),
+});
+
+const allowanceArraySchema = z.array(allowanceSchema).superRefine(addDateRangePeriodIssues);
+const thresholdArraySchema = z.array(thresholdSchema).superRefine(addDateRangePeriodIssues);
+const funderTrainingArraySchema = z
+  .array(funderTrainingSchema)
+  .superRefine(addDateRangePeriodIssues);
+const issuerDocumentTemplateArraySchema = z
+  .array(issuerDocumentTemplateSchema)
+  .superRefine(addDateRangePeriodIssues);
+const administrativeFeeArraySchema = z
+  .array(administrativeFeeSchema)
+  .superRefine(addDateRangePeriodIssues);
+
+export const billingSettingsSchema = z.object({
+  displayPaidDateInput: z.boolean(),
+  groupThresholdSpe: numericStringGreaterThanZero,
