+import { useListDocumentTemplate } from '@/hooks/data/documentTemplates/useListDocumentTemplate';
+import type { SettingsParams } from '../types';
+import type { BillingSettingFormData } from './billingSettingsValidationSchema';
+import type { SettingWithDateValueDTO } from '@/model/SettingsDTO';
+import { useSearchIssuers } from '@/hooks/data/issuer/useSearchIssuers';
+import { formatWithCodeAndName } from '@/helpers/formats/formatLabelHelpers';
+
+export function useBillingSettingsInitialization(settingsData: SettingsParams) {
+  const settings = settingsData.content;
+
+  const { data: listIssuers } = useSearchIssuers({ actived: true, pageSize: 100 });
+
+  const { data: listDocumentTemplates } = useListDocumentTemplate({ pageSize: 500 });
+
+  // ----- compute ------
+
+  const issuersListItems = listIssuers?.content ?? [];
+  const documentTemplatesListItems = listDocumentTemplates?.content ?? [];
+
+  const flippingValue = settings?.DISPLAY_PAID_BILL_INFORMATION?.at(0)?.value;
+
+  const assmatAllowances = settings?.AMOUNT_OF_ALLOWANCE_ASS_MAT ?? [];
+  const speAllowances = settings?.AMOUNT_OF_ALLOWANCE_SPE ?? [];
+  const thresholdCesuSpe = settings?.THRESHOLD_CESU_SPE ?? [];
+  const thresholdUrssafSpe = settings?.THRESHOLD_URSSAF_SPE ?? [];
+  const thresholdPajemploiSpe = settings?.THRESHOLD_PAJEMPLOI_SPE ?? [];
+  const thresholdPajemploiAssmat = settings?.THRESHOLD_PAJEMPLOI_ASS_MAT ?? [];
+  const funderTrainingSpePlan = settings?.FUNDER_TRAINING_SPE_PLAN ?? [];
+  const funderTrainingSpeCpf = settings?.FUNDER_TRAINING_SPE_CPF ?? [];
+  const funderLivingCostAssmat = settings?.FUNDER_LIVING_COST_ASSMAT ?? [];
+  const funderLivingCostSpe = settings?.FUNDER_LIVING_COST_SPE ?? [];
+  const funderTrainingAssmatPlan = settings?.FUNDER_TRAINING_ASSMAT_PLAN ?? [];
+  const funderTrainingAssmatCpf = settings?.FUNDER_TRAINING_ASSMAT_CPF ?? [];
+
+  const livingCostsBilling = settings?.LIVING_COSTS_BILLING?.at(0)?.value;
+
+  function mapIssuerSettings(items: SettingWithDateValueDTO[]) {
+    return items.map((issuer) => {
+      const currentIssuer = issuersListItems.find((item) => item.issuerId === issuer.name);
+      const issuerLabel = currentIssuer ? formatWithCodeAndName(currentIssuer.legalPersonDto) : '';
+      const currentDocumentTemplate = documentTemplatesListItems.find(
+        (item) => item.id === issuer.value,
+      );
+      const documentTemplateLabel = currentDocumentTemplate ? currentDocumentTemplate.title : '';
+
+      return {
+        issuer: {
+          label: issuerLabel,
+          value: issuer.name ?? '',
+        },
+        template: {
+          label: documentTemplateLabel,
+          value: issuer.value,
+        },
+        startDate: issuer.startDate ?? '',
+        endDate: issuer.endDate ?? '',
+      } satisfies BillingSettingFormData[
+        | 'issuerPedagogicExpensesCost'
+        | 'issuerLivingCost'][number];
+    });
+  }
+
+  const issuerPedagogicExpensesCost = mapIssuerSettings(
+    settings?.ISSUER_PEDAGOGIC_EXPENSES_COST ?? [],
+  );
+  const issuerLivingCost = mapIssuerSettings(settings?.ISSUER_LIVING_COST ?? []);
+
+  const administrativeFee = settings?.ADMINISTRATIVE_FEE ?? [];
+
+  const initialValues: BillingSettingFormData = {
+    displayPaidDateInput: flippingValue === 'true',
+    groupThresholdSpe: settings?.GROUP_THRESHOLD_SPE_PLAN?.at(0)?.value ?? '',
+    groupThresholdAssmat: settings?.GROUP_THRESHOLD_ASSMAT_PLAN?.at(0)?.value ?? '',
+    ceilingSpe: settings?.MODULE_PATH_BILLING_PLAN_SPE_THRESHOLD?.at(0)?.value ?? '',
+    ceilingAssmat: settings?.MODULE_PATH_BILLING_PLAN_ASSMAT_THRESHOLD?.at(0)?.value ?? '',
+    ceilingGlobal: settings?.MODULE_PATH_BILLING_PLAN_THRESHOLD?.at(0)?.value ?? '',
+    assmatAllowances: _mapSettingsToFormData(assmatAllowances),
+    speAllowances: _mapSettingsToFormData(speAllowances),
+    thresholdCesuSpe: _mapSettingsToFormData(thresholdCesuSpe),
+    thresholdUrssafSpe: _mapSettingsToFormData(thresholdUrssafSpe),
+    thresholdPajemploiSpe: _mapSettingsToFormData(thresholdPajemploiSpe),
+    thresholdPajemploiAssmat: _mapSettingsToFormData(thresholdPajemploiAssmat),
+    funderLivingCostAssmat: _mapSettingsToFormData(funderLivingCostAssmat),
+    funderLivingCostSpe: _mapSettingsToFormData(funderLivingCostSpe),
+    funderTrainingSpePlan: _mapSettingsToFormData(funderTrainingSpePlan),
+    funderTrainingSpeCpf: _mapSettingsToFormData(funderTrainingSpeCpf),
+    funderTrainingAssmatPlan: _mapSettingsToFormData(funderTrainingAssmatPlan),
+    funderTrainingAssmatCpf: _mapSettingsToFormData(funderTrainingAssmatCpf),
+    pedagogicCostsBillingYear: settings?.PEDAGOGIC_COSTS_BILLING_YEAR?.at(0)?.value ?? '',
+    livingCostsBillingYear: settings?.LIVING_COSTS_BILLING_YEAR?.at(0)?.value ?? '',
+    livingCostsBilling: livingCostsBilling === 'true',
+    issuerPedagogicExpensesCost,
+    issuerLivingCost,
+    administrativeFee: _mapSettingsToFormData(administrativeFee),
+  };
+
+  return {
+    initialValues,
+  };
+}
+
+function _mapSettingsToFormData(items: SettingWithDateValueDTO[]) {
+  return items.map((item) => ({
+    value: item.value,
+    startDate: item.startDate ?? '',
+    endDate: item.endDate ?? '',
+  })) satisfies BillingSettingFormData[
+    | 'assmatAllowances'
+    | 'thresholdCesuSpe'
+    | 'funderLivingCostAssmat'];
+}

