+import { useFieldArray, type Control } from 'react-hook-form';
+
+import type {
+  AverageCostFormData,
+  FinancingRequestAverageCostFormDataKey,
+  OpeningRequestSettingFormDataInput,
+} from '../openingRequestSettingsValidationSchema';
+import { OPENING_REQUEST_AVERAGE_COST_LABEL } from '@/components/presentational/SettingsForm/constants';
+import { FormSectionCard } from '@/components/ui/form/FormSectionCard';
+import InputNumberV2 from '@/components/presentational/common/InputNumber/InputNumberV2';
+import InputDateV2 from '@/components/presentational/common/InputDate/InputDateV2';
+import { AddFieldButton } from '@/components/ui/button/AddFieldButton';
+
+const EMPTY_AVERAGE_COST_ITEM: AverageCostFormData[number] = {
+  value: '',
+  startDate: '',
+  endDate: '',
+};
+
+interface AverageCostFieldArrayProps {
+  control: Control<OpeningRequestSettingFormDataInput>;
+  fieldKey: FinancingRequestAverageCostFormDataKey;
+}
+
+export function AverageCostFieldArray({ control, fieldKey }: Readonly<AverageCostFieldArrayProps>) {
+  const { fields, append, remove } = useFieldArray({
+    control,
+    name: fieldKey,
+  });
+
+  return (
+    <div className="FormSectionCard__container">
+      {fields.map((field, index) => {
+        const removeHandler = fields.length > 1 ? () => remove(index) : undefined;
+
+        return (
+          <FormSectionCard
+            key={field.id}
+            onRemove={removeHandler}
+            ariaLabel={`Supprimer cette période (${index + 1})`}
+          >
+            <div className="ModelFormView__row">
+              <InputNumberV2
+                className="FormSectionCard__field--grow"
+                control={control}
+                name={`${fieldKey}.${index}.value`}
+                label={OPENING_REQUEST_AVERAGE_COST_LABEL[fieldKey]}
+                settings={{
+                  decimalScale: 2,
+                }}
+                rightComponent="€"
+                required
+              />
+              <InputDateV2
+                control={control}
+                name={`${fieldKey}.${index}.startDate`}
+                label="Date de début"
+                forMoment
+                required
+              />
+              <InputDateV2
+                control={control}
+                name={`${fieldKey}.${index}.endDate`}
+                label="Date de fin"
+                forMoment
+              />
+            </div>
+          </FormSectionCard>
+        );
+      })}
+
+      <AddFieldButton
+        label="Ajouter une période"
+        onClick={() => append(EMPTY_AVERAGE_COST_ITEM)}
+      />
+    </div>
+  );
+}

