+import { z } from 'zod';
+import { isBefore } from 'date-fns/isBefore';
+import { parseISO } from 'date-fns/parseISO';
+
+import { baseOpenEndedDateRangeSchema } from '@/helpers/validations/schemas/baseDateRangeSchema';
+import { addOverlappingPeriodsIssue } from '@/helpers/validations/settings.validations';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type OpeningRequestSettingFormData = z.infer<typeof openingRequestSettingsSchema>;
+export type AverageCostFormData = z.infer<typeof averageCostSchema>;
+
+export type OpeningRequestSettingFormDataInput = z.input<typeof openingRequestSettingsSchema>;
+
+export type FinancingRequestAverageCostFormDataKey = keyof {
+  [K in keyof OpeningRequestSettingFormData as OpeningRequestSettingFormData[K] extends AverageCostFormData
+    ? K
+    : never]: unknown;
+};
+
+// ----- schema -----
+
+const baseAverageCostSchema = baseOpenEndedDateRangeSchema.extend({
+  value: z.string().min(1, FORM_ERROR_MESSAGES.settings.fieldRequired).prefault(''),
+});
+
+const averageCostSchema = z.array(baseAverageCostSchema).superRefine((settings, ctx) => {
+  addOverlappingPeriodsIssue(settings, ctx);
+
+  settings.forEach((item, index) => {
+    if (!item.startDate || !item.endDate) {
+      return;
+    }
+
+    const startDate = parseISO(item.startDate);
+    const endDate = parseISO(item.endDate);
+
+    if (isBefore(endDate, startDate)) {
+      ctx.addIssue({
+        code: 'custom',
+        message: FORM_ERROR_MESSAGES.date.endDateBeforeStartDate,
+        path: [index, 'endDate'],
+      });
+    }
+  });
+});
+
+export const openingRequestSettingsSchema = z.object({
+  maxDaysFundingRequestDelayAssmat: z
+    .string()
+    .min(1, FORM_ERROR_MESSAGES.settings.assmatFundingRequestDelayRequired),
+  maxDaysFundingRequestDelaySpe: z
+    .string()
+    .min(1, FORM_ERROR_MESSAGES.settings.speFundingRequestDelayRequired),
+  assmatAutomaticValidationDate: z.string().nullable(),
+  speAutomaticValidationDate: z.string().nullable(),
+  modulePathMaxDays: z.string().min(1, FORM_ERROR_MESSAGES.settings.moduleTrainingDurationRequired),
+  daysBeforeFirstMailNotification: z.string().optional(),
+  daysBeforeNewMailNotification: z.string().optional(),
+  automaticCancellation: z.string().optional(),
+  doPmAssmatAverageSalaryCost: averageCostSchema,
+  doPmAssmatLivingCost: averageCostSchema,
+  doPmAssmatAverageTrainerCost: averageCostSchema,
+  doPmSpeAverageTrainerCost: averageCostSchema,
+  doPmSpeLivingCost: averageCostSchema,
+  doPmAssmatAverageAllocationCost: averageCostSchema,
+  doPmSpeAverageAllocationCost: averageCostSchema,
+  doPmSpeAverageSalaryCost: averageCostSchema,
+  doAeAssmatNbrEstimatedPlan: averageCostSchema,
+  doAeSpeNbrEstimatedPlan: averageCostSchema,
+  doAeAssmatAverageSalaryCost: averageCostSchema,
+  doAeAssmatAverageTrainerCost: averageCostSchema,
+  doAeSpeAverageTrainerCost: averageCostSchema,
+  doAeAssmatLivingCost: averageCostSchema,
+  doAeSpeAverageSalaryCost: averageCostSchema,
+  doAeSpeLivingCost: averageCostSchema,
+  doAeAssmatAverageAllocationCost: averageCostSchema,
+  doAeSpeAverageAllocationCost: averageCostSchema,
+});

