+export function useAddDocumentTemplate({ onSuccess }: UseMutationCallbacks = {}) {
+  return useMutation<void, ApiErrors, DocumentTemplateFormValues>({
+    mutationFn: (template) => {
+      const { formData, searchParams } = buildDocumentTemplatePayload(template);
+
+      return fetcher({
+        endpoint: `${endpoints.documentTemplateSave}?${searchParams.toString()}`,
+        method: HttpVerb.POST,
+        params: {
+          body: formData,
+        },
+      });
+    },
+    onSuccess: (_, template) => {
+      toast.success(`Document [${template.title}] créé avec succès.`);
+      if (onSuccess) {
+        void onSuccess();
+      }
+    },
+  });
