+import { useState } from 'react';
+import { FormProvider, useForm, useFormContext, useWatch } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import type { PaymentListContext, PaymentsListFormData } from '../types';
+import {
+  paymentStatusSelectFormSchema,
+  type PaymentStatusSelectFormData,
+} from '../paymentStatusSelectFormSchema';
+import type { SearchPaymentDTO } from '@/model/PaymentDTO';
+import { PaymentStatus, PaymentStatusLabel } from '@/model/PaymentStatusEnum';
+import InputSelectV2 from '../../common/InputSelect/InputSelectV2';
+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import Button from '../../common/Button/Button';
+import { Dialog } from '@/components/ui/dialog/Dialog';
+import { PaymentStatusUpdateForm } from './PaymentStatusUpdateForm';
+
+interface PaymentStatusSelectFormProps {
+  context: Exclude<PaymentListContext, 'DOCUMENT'>;
+  items: SearchPaymentDTO[];
+  isPending: boolean;
+}
+
+export function PaymentStatusSelectForm({
+  context,
+  items,
+  isPending,
+}: Readonly<PaymentStatusSelectFormProps>) {
+  const [showPaymentModalStatus, setShowPaymentModalStatus] = useState(false);
+
+  const { control: paymentsListControl, reset: resetSelectedPaymentIds } =
+    useFormContext<PaymentsListFormData>();
+
+  const selectedPaymentIdsValues = useWatch({
+    control: paymentsListControl,
+    name: 'selectedPaymentIds',
+  });
+
+  const methods = useForm({
+    resolver: zodResolver(paymentStatusSelectFormSchema),
+    defaultValues: {
+      status: PaymentStatus.WAITING_FOR_PAYMENT,
+      paymentComment: [],
+    } satisfies PaymentStatusSelectFormData,
+  });
+
+  const { control } = methods;
+
+  const excludeKeyByContext: Record<PaymentStatusSelectFormProps['context'], `${PaymentStatus}`> = {
+    RIB: 'CHEQUE_LETTER',
+    CHEQUE: 'TRANSFERED',
+  };
+
+  return (
+    <div className="PaymentStatusFormContainer">
+      <FormProvider {...methods}>
+        <form
+          className="PaymentStatusForm"
+          noValidate
+        >
+          <InputSelectV2
+            className="PaymentStatusForm__statusSelection"
+            control={control}
+            name="status"
+            label="Nouveau statut"
+            options={getInputSelectOptions(PaymentStatusLabel, {
+              excludeKeys: [excludeKeyByContext[context]],
+            })}
+            isClearable={false}
+            isSearchable={false}
+          />
+
+          <Button
+            type="button"
+            onClick={() => setShowPaymentModalStatus(true)}
+            customClassName="PaymentStatusForm__submitButton"
+            appearance="orange-inverted"
+            loading={isPending}
+            disabled={!selectedPaymentIdsValues.length}
+          >
+            <Button.Text>Modifier</Button.Text>
+          </Button>
+
+          <Dialog
+            open={showPaymentModalStatus}
+            onOpenChange={setShowPaymentModalStatus}
+            title="Modification du statut des remboursements"
+            styles={{ maxHeight: '75vh' }}
+          >
+            <PaymentStatusUpdateForm
+              items={items}
+              paymentType={context}
+              selectedPaymentIds={selectedPaymentIdsValues}
+              closeModalCallback={() => setShowPaymentModalStatus(false)}
+              resetSelectedPaymentIds={resetSelectedPaymentIds}
+            />
+          </Dialog>
+        </form>
+      </FormProvider>
+    </div>
+  );
+}

