+import { useFormContext } from 'react-hook-form';
+import { toast } from 'react-hot-toast';
+
+import type { SearchPaymentDTO } from '@/model/PaymentDTO';
+import type { PaymentListContext } from '../types';
+import endpoints from '@/constants/api-endpoints';
+import ModelFormView from '../../common/ModelFormView/ModelFormView';
+import { Dialog } from '@/components/ui/dialog/Dialog';
+import ButtonGroup from '../../common/ButtonGroup/ButtonGroup';
+import Button from '../../common/Button/Button';
+import type { PaymentStatusSelectFormData } from '../paymentStatusSelectFormSchema';
+import type { PaymentStatusInput } from '@/model/MandateOperationStateCreateDTO';
+import { PaymentStatusLabel } from '@/model/PaymentStatusEnum';
+import { useEditPaymentStatus } from '@/hooks/data/payments/useEditPaymentStatus';
+import { invalidateListPayments } from '@/hooks/data/payments/useListPayments';
+import InputTextAreaV2 from '../../common/InputTextArea/InputTextAreaV2';
+
+interface PaymentStatusUpdateFormProps {
+  items: SearchPaymentDTO[];
+  paymentType: Exclude<PaymentListContext, 'DOCUMENT'>;
+  selectedPaymentIds: string[];
+  closeModalCallback: () => void;
+  resetSelectedPaymentIds: () => void;
+}
+
+export function PaymentStatusUpdateForm({
+  items,
+  paymentType,
+  selectedPaymentIds,
+  closeModalCallback,
+  resetSelectedPaymentIds,
+}: Readonly<PaymentStatusUpdateFormProps>) {
+  const {
+    register,
+    getValues,
+    handleSubmit,
+    formState: { errors },
+  } = useFormContext<PaymentStatusSelectFormData>();
+
+  const nextPaymentStatus = getValues('status');
+
+  const {
+    isPending,
+    error: editPaymentStatusError,
+    mutate: editPaymentStatus,
+  } = useEditPaymentStatus({
+    onSuccess: () => {
+      toast.success('Statuts des remboursements modifiés avec succès.');
+      closeModalCallback();
+      resetSelectedPaymentIds();
+
+      if (paymentType === 'RIB' || paymentType === 'CHEQUE') {
+        void invalidateListPayments(endpoints.payment);
+      }
+    },
+  });
+
+  function submitHandler(values: PaymentStatusSelectFormData) {
+    const paymentComments = selectedPaymentIds.reduce<PaymentStatusInput['paymentComments']>(
+      (acc, paymentId, index) => {
+        acc[paymentId] = values.paymentComment[index] || null;
+        return acc;
+      },
+      {},
+    );
+
+    editPaymentStatus({
+      status: values.status,
+      paymentComments,
+    });
+  }
+
+  return (
+    <ModelFormView
+      apiErrorTitle="Une erreur est survenue :"
+      apiErrors={editPaymentStatusError}
+    >
+      <div className="Payment__editStatusForm">
+        <Dialog.Description>
+          Vous vous apprêtez à modifier le statut de ce remboursement en :{' '}
+          <span className="status">{PaymentStatusLabel[nextPaymentStatus]}</span>
+        </Dialog.Description>
+
+        <div className="Payment__editStatusComments">
+          {selectedPaymentIds.map((selectedPaymentId, index) => {
+            const payment = items.find((item) => item.id === selectedPaymentId);
+
+            const paymentCommentError = errors?.paymentComment?.[index];
+            const fieldError = paymentCommentError
+              ? { [`paymentComment.${index}`]: paymentCommentError }
+              : undefined;
