+import { useState } from 'react';
+import { useSearchParams } from 'react-router';
+
+import type { SearchPaymentDTO } from '@/model/PaymentDTO';
+import type {
+  DateRangeFilter,
+  DefaultListFilter,
+  FilterFormData,
+} from '@/components/presentational/common/ListView/types';
+import type { MarketType } from '@/model/MarketSegment';
+import type { PaymentListContext } from '@/components/presentational/PaymentsList/types';
+import type { PaymentType } from '@/model/PaymentTypeEnum';
+import type { PaymentExportSearchInput } from '@/model/PaymentExportDTO';
+import endpoints from '@/constants/api-endpoints';
+import { useListQuery } from '@/hooks/useListQuery';
+import { OrderNames } from '@/constants/sorting';
+import { extractFilterQueryParams } from '@/helpers/routers/routingHelpers';
+import { queryClient as _queryClient } from '../queryClient';
+
+interface UseListPaymentsOptions extends DefaultListFilter {
+  context: PaymentListContext;
+  paymentType?: `${PaymentType}`;
+}
+
+export function useListPayments({ context, paymentType, ...extraParams }: UseListPaymentsOptions) {
+  const [searchParams] = useSearchParams();
+  const [marketType, setMarketType] = useState<MarketType | 'ALL'>('ALL');
+
+  const isDocumentContext = context === 'DOCUMENT';
+  const isChequeContext = context === 'CHEQUE';
+
+  const endpointUrl = isDocumentContext ? endpoints.paymentDocumentEdition : endpoints.payment;
+
+  const createdDateRangeMin = searchParams.get('createdDateRangeMin');
+  const createdDateRangeMax = searchParams.get('createdDateRangeMax');
+
+  const dateRangeFilter =
+    createdDateRangeMin || createdDateRangeMax
+      ? ({
+          min: createdDateRangeMin ?? null,
+          max: createdDateRangeMax ?? null,
+        } satisfies DateRangeFilter)
+      : undefined;
+
+  const paymentListFiltersNames: Array<keyof FilterFormData> = isDocumentContext
+    ? [
+        'code',
+        'modulePathId',
+        'evaluationId',
+        'learnerId',
+        'employerId',
+        'statuses',
+        'maxCode',
+        'minCode',
+      ]
+    : [
+        'modulePathId',
+        'evaluationId',
+        'learnerId',
+        'employerId',
+        'branch',
+        'statuses',
+        'minCode',
+        'maxCode',
+        ...(isChequeContext
+          ? (['chequeNumber', 'deliveryTag'] satisfies Array<keyof FilterFormData>)
+          : []),
+      ];
+
+  const queryParams = extractFilterQueryParams(searchParams, paymentListFiltersNames);
+  const filterValues = {
+    ...queryParams,
+    // Must be `undefined` (not `null`) when `marketTypes` or `createdDateRange` are absent,
+    // otherwise `hasActiveFilters` will not treat them as empty via `isEmpty` helper.
+    marketTypes: marketType === 'ALL' ? undefined : [marketType],
+    createdDateRange: dateRangeFilter,
+  } as PaymentExportSearchInput;
+
+  const result = useListQuery<SearchPaymentDTO>(endpointUrl, {
+    defaultSearchParams: {
+      sortedColumn: 'code',
+      sortingOrder: OrderNames.DESC,
+      ...extraParams,
+    },
+    extraBodyParams: {
+      type: paymentType,
+      createdDateRange: dateRangeFilter,
+      marketTypes: marketType === 'ALL' ? null : [marketType],
+    },
+    filtersNames: paymentListFiltersNames,
+  });
+
+  return {
+    ...result,
+    marketType,
+    setMarketType,
+    filterValues,
+  };
+}
+
+export function invalidateListPayments(listPaymentsEndpoint: string, queryClient = _queryClient) {
+  return queryClient.invalidateQueries({
+    queryKey: [listPaymentsEndpoint],
+  });
+}

