+import InputTextAreaV2 from '../../common/InputTextArea/InputTextAreaV2';
+
+interface ChangePaymentStatusConfirmationProps {
+  nextStatus: PaymentStatus;
+  isPending: boolean;
+  onConfirm: () => void;
+}
+
+export function ChangePaymentStatusConfirmation({
+  nextStatus,
+  isPending,
+  onConfirm,
+}: Readonly<ChangePaymentStatusConfirmationProps>) {
+  const {
+    register,
+    formState: { errors },
+  } = useFormContext<PaymentMailingFormData>();
