+        <span className="status">{PaymentStatusLabel[nextStatus]}</span>
+      </div>
+
+      <div className="ModelFormView__row">
+        <InputTextAreaV2
+          className="ModelFormView__formField"
+          register={register('paymentComment')}
+          label="Commentaire"
+          errors={errors}
+          placeholder="Saisissez un commentaire..."
+        />
+      </div>
+
+      <ButtonGroup compacted>
+        <Dialog.Close asChild>
+          <Button disabled={isPending}>
+            <Button.Text>Annuler</Button.Text>
+          </Button>
+        </Dialog.Close>
+        <Button
+          appearance="orange-inverted"
+          loading={isPending}
+          onClick={onConfirm}
+        >
+          <Button.Text>Confirmer</Button.Text>
+        </Button>
+      </ButtonGroup>
+    </div>
+  );
