+import { useFormContext } from 'react-hook-form';
+
+import type { PaymentDTO } from '@/model/PaymentDTO';
+import type { LabelAndValueType } from '@/helpers/commonTypes';
+import type { PaymentMailingFormData } from '../paymentDetailFormValidationSchema';
+import {
+  CHECK_LETTER_MAIL_TYPES_LABEL,
+  MAIL_TYPE_LABEL,
+  RECIPIENT_LABEL,
+  type MailRecipient,
+  type MailType,
+} from '@/model/MailDTO';
+import { date } from '@/helpers/formats/formatDateHelpers';
+import Loader from '../../common/Loader/Loader';
+import Button from '../../common/Button/Button';
+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import InputSelectV2 from '../../common/InputSelect/InputSelectV2';
+import { useChangeMailType, type MailsTagInput } from '@/hooks/data/payments/useChangeMailType';
+import { useGenerateMailExport } from '@/hooks/data/payments/useGenerateMailExport';
+import { invalidateGetPaymentDetail } from '@/hooks/data/payments/useGetPaymentDetail';
+
+interface PaymentMailingFormProps {
+  paymentId: string;
+  payment: PaymentDTO | undefined;
+  isChequePayment: boolean;
+}
+
+export function PaymentMailingForm({
+  paymentId,
+  payment,
+  isChequePayment,
+}: Readonly<PaymentMailingFormProps>) {
+  const { control } = useFormContext<PaymentMailingFormData>();
+
+  const { isPending: isChangeMailTypePending, mutate: changeMailType } = useChangeMailType();
+
+  const { isPending: isGenerateMailExportPending, mutate: generateMailExport } =
+    useGenerateMailExport();
+
+  function getMailSelectOptions(mailRecipient: MailRecipient): LabelAndValueType[] {
+    const paymentRecipient = payment?.recipient;
+
+    if (paymentRecipient === mailRecipient && isChequePayment) {
+      return getInputSelectOptions(CHECK_LETTER_MAIL_TYPES_LABEL);
+    }
+
+    return getInputSelectOptions(MAIL_TYPE_LABEL);
+  }
+
+  const recipientKeys = Object.keys(RECIPIENT_LABEL) as MailRecipient[];
+
+  return (
+    <>
+      <h4 className="InfosBlock__title">Envoi des courriers</h4>
+      <div className="CardInfoBlocks__row Payment__InfosBlock Payment__mailInfosBloc">
+        <div className="Payment__mailInfosHeader">
+          <span className="Payment__mailInfos__el">Destinataires</span>
+          <span className="Payment__mailInfos__el">Type de courrier</span>
+          <span className="Payment__mailInfos__el">Date de traitement</span>
+        </div>
+
+        {recipientKeys.map((recip) => {
+          const mail = (payment?.mails ?? []).find((mailItem) => mailItem.recipient === recip);
+
+          if (!mail) {
+            return null;
+          }
+
+          return (
+            <div
+              key={`type_${recip}`}
+              className="Payment__mailInfosRow"
+            >
+              <span className="Payment__mailInfos__el">{RECIPIENT_LABEL[mail.recipient]}</span>
+              <InputSelectV2
+                className="Payment__mailInfos__formField"
+                control={control}
+                name={`type.${mail.recipient}`}
+                label={`Type de courrier pour ${RECIPIENT_LABEL[mail.recipient]}`}
+                options={getMailSelectOptions(mail.recipient)}
+                handleChange={(mailType) => {
+                  const params: MailsTagInput = {
+                    mailId: mail.id,
+                    mailType: mailType?.value as MailType,
+                  };
+
+                  changeMailType(params, {
+                    onSuccess: () => {
+                      void invalidateGetPaymentDetail(paymentId);
+                    },
+                  });
+                }}
+                isClearable={false}
+                isLoading={isChangeMailTypePending}
+                hideLabel
+              />
+              <span className="Payment__mailInfos__el">
+                {date.toFR(mail.processingDate) || '-'}
+              </span>
+              <span className="Payment__mailInfos__button">
+                {(mail.type === 'LETTER' || mail.type === 'MAIL') && (
+                  <Button
+                    type="button"
+                    appearance="simple"
+                    disabled={isGenerateMailExportPending}
+                    onClick={() => generateMailExport(mail.id)}
+                  >
+                    <Button.Text>
+                      {isGenerateMailExportPending ? <Loader variant="dark" /> : 'Générer'}
+                    </Button.Text>
+                  </Button>
+                )}
+              </span>
+            </div>
+          );
+        })}
+      </div>
+    </>
+  );
+}

