+import type { PaymentDTO } from '@/model/PaymentDTO';
+import type { PaymentMailingFormData } from './paymentDetailFormValidationSchema';
+
+export function initializePaymentMailingFormData(
+  payment: PaymentDTO | undefined,
+): PaymentMailingFormData {
+  const mails = payment?.mails ?? [];
+
+  const initialTypeValues = mails.reduce<PaymentMailingFormData['type']>(
+    (acc, mail) => ({
+      ...acc,
+      [mail.recipient]: mail.type,
+    }),
+    {},
+  );
+
+  return {
+    paymentComment: payment?.comment ?? '',
+    type: initialTypeValues,
+  };
+}

