+import { z } from 'zod';
+
+import type { MailRecipient, MailType } from '@/model/MailDTO';
+import type { EntityStatus } from '@/helpers/statusTransitionWorkflow/types';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export interface PaymentMailingFormData {
+  paymentComment: string;
+  type: {
+    [key in MailRecipient]?: MailType;
+  };
+}
+
+const paymentMailingFormSchema = z.custom<PaymentMailingFormData>();
+
+export function createPaymentDetailFormSchema(paymentStatus: EntityStatus | '') {
+  return paymentMailingFormSchema.superRefine((values, ctx) => {
+    if (
+      (paymentStatus === 'ON_ERROR' || paymentStatus === 'CANCELLED') &&
+      !values.paymentComment.trim()
+    ) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['paymentComment'],
+        message: FORM_ERROR_MESSAGES.comment.required,
+      });
+    }
+  });
+}

