+import { describe, expect, test } from 'vitest';
+
+import {
+  formatRegistrationDelayDuration,
+  parseRegistrationDelayDuration,
+} from '../temporalDurationUtils';
+
+describe('function parseRegistrationDelayDuration', () => {
+  test('should return 0 for falsy input', () => {
+    expect(parseRegistrationDelayDuration(null)).toBe(0);
+    expect(parseRegistrationDelayDuration(undefined)).toBe(0);
+    expect(parseRegistrationDelayDuration('')).toBe(0);
+  });
+
+  test('should parse a days-only duration', () => {
+    expect(parseRegistrationDelayDuration('P0D')).toBe(0);
+    expect(parseRegistrationDelayDuration('P12D')).toBe(12);
+  });
+
+  test('should convert weeks to days instead of dropping them', () => {
+    expect(parseRegistrationDelayDuration('P1W')).toBe(7);
+    expect(parseRegistrationDelayDuration('P2W')).toBe(14);
+    expect(parseRegistrationDelayDuration('P1W3D')).toBe(10);
+  });
+});
+
+describe('function formatRegistrationDelayDuration', () => {
+  test('should format a number into a days-only ISO 8601 duration', () => {
+    expect(formatRegistrationDelayDuration(0)).toBe('P0D');
+    expect(formatRegistrationDelayDuration(12)).toBe('P12D');
+  });
+
+  test('should format a numeric string into a days-only ISO 8601 duration', () => {
+    expect(formatRegistrationDelayDuration('7')).toBe('P7D');
+  });
+});

