+import { parse as parseISODuration } from 'iso8601-duration';
+
+/**
+ * Parses an ISO 8601 duration and returns its total number of days.
+ * Returns `0` when the value is missing, matching the backend default.
+ *
+ * @note We only produce and expect `PnD` (days-only) durations, so `duration.days`
+ * is normally enough. As a safeguard against unexpected backend values, weeks are
+ * also converted to days (`P1W` -> 7 days) instead of being silently dropped.
+ */
+export function parseRegistrationDelayDuration(durationString: string | null | undefined): number {
+  if (!durationString) {
+    return 0;
+  }
+
+  const duration = parseISODuration(durationString);
+  return (duration.weeks ?? 0) * 7 + (duration.days ?? 0);
+}
+
+/**
+ * Formats a day count into an ISO 8601 duration containing only the days part
+ * (e.g. `P12D`), matching the format the backend expects.
+ */
+export function formatRegistrationDelayDuration(dayDurationValue: string | number): string {
+  const days = Number(dayDurationValue);
+
+  return `P${days}D`;
+}

