+import { useForm, useWatch, type FieldPath } from 'react-hook-form';
+
+export const SELECTION_FIELD = 'selectedIds';
+
+export interface SelectionFormValues {
+  [SELECTION_FIELD]: string[];
+}
+
+interface UseTableRowSelectionParams<TItem> {
+  /**
+   * The items to be displayed in the table. Used to determine which rows can be selected.
+   */
+  items: readonly TItem[];
+  /**
+   * Which rows can be selected. Drives both "select all" and per-row disabling. Defaults to all.
+   */
+  isSelectable?: (item: TItem) => boolean;
+  /**
+   * How to read a row's id. Defaults to `item.id`.
+   */
+  getItemId?: (item: TItem) => string;
+}
+
+export function useTableRowSelection<TItem extends { id: string }>({
+  items,
+  isSelectable = defaultIsSelectable,
+  getItemId = defaultGetItemId,
+}: Readonly<UseTableRowSelectionParams<TItem>>) {
+  const formMethods = useForm({
+    defaultValues: { [SELECTION_FIELD]: [] } as SelectionFormValues,
+  });
+
+  const { control, setValue, reset } = formMethods;
+
+  const checkedTableRowValues = useWatch({ control, name: SELECTION_FIELD });
+
+  const hasSelection = checkedTableRowValues.length > 0;
+
+  function toggleAllSelection() {
+    const nextSelectedIds = hasSelection ? [] : items.filter(isSelectable).map(getItemId);
+
+    setValue(SELECTION_FIELD, nextSelectedIds);
+  }
+
+  return {
+    control,
+    fieldName: SELECTION_FIELD as FieldPath<SelectionFormValues>,
+    checkedTableRowValues,
+    hasSelection,
+    isSelectable,
+    toggleAllSelection,
+    resetTableRowSelection: reset,
+    formMethods,
+  };
+}
+
+function defaultIsSelectable() {
+  return true;
+}
+
+function defaultGetItemId<TItem extends { id: string }>(item: TItem) {
+  return item.id;
+}

