+/**
+ * Returns the first usable string id found on the object, or undefined if none.
+ */
+export function getUsableId(value: unknown): string | undefined {
+  if (typeof value !== 'object' || value === null) {
+    return undefined;
+  }
+
+  const record = value as Record<string, unknown>;
+
+  for (const key of USABLE_ID_KEYS) {
+    const candidate = record[key];
+
+    if (typeof candidate === 'string' && candidate.length > 0) {
+      return candidate;
+    }
+  }
+
+  return undefined;
+}

