+
+/**
+ * useMutation for this imperative, user-triggered download. This reproduces the exact
+ * behavior of the legacy `file.actions.get` thunk: a preflight GET on the download endpoint,
+ * then opening the same endpoint URL in a new tab. Ignoring the response body.
+ */
+export function useGetFileLink() {
+  return useMutation<void, ApiErrors, string>({
+    mutationFn: (fileId) => {
+      return fetcher({
+        endpoint: endpoints.fileDownload(fileId),
+        method: HttpVerb.GET,
+      });
+    },
+    onSuccess: (_, fileId) => {
+      open(endpoints.fileDownload(fileId), '_blank', 'noopener noreferrer');
+    },
+  });
+}

