+import { useSearchParams } from 'react-router';
+
+import type { DocumentFile } from '@/model/FileDTO';
+import type { FilterFormData } from '@/components/presentational/common/ListView/types';
+import type { DocumentSubfolderFilterName } from '@/components/presentational/common/DocumentsList/constants';
+import { useListQuery } from '@/hooks/useListQuery';
+
+interface UseListDocumentsOptions {
+  /**
+   * The id of the entity the documents belong to (modulePath, blocPath, evaluation etc.),
+   * sent to the backend alongside the paginated search criteria.
+   */
+  entityId?: string;
+  /**
+   * Name of the URL filter used to restrict documents to a given sub-folder Differs per entity.
+   */
+  subfolderFilterName?: DocumentSubfolderFilterName;
+}
+
+/**
+ * A generic hook for fetching an entity's paginated document list.
+ * Intended to replace the legacy per-entity `documentsList` Redux actions
+ */
+export function useListDocuments(endpoint: string, options: UseListDocumentsOptions = {}) {
+  const { entityId, subfolderFilterName } = options;
+
+  const [searchParams] = useSearchParams();
+
+  const filtersNames: Array<keyof FilterFormData> = ['searchText', 'filename'];
+
+  if (subfolderFilterName) {
+    filtersNames.push(subfolderFilterName);
+  }
+
+  const result = useListQuery<DocumentFile>(endpoint, {
+    filtersNames,
+    extraBodyParams: { entityId },
+  });
+
+  const isfilteredDocuments = filtersNames.some((name) => Boolean(searchParams.get(name)));
+
+  return {
+    result,
+    isfilteredDocuments,
+  };
+}

