+import { useMutation } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { UseMutationCallbacks } from '../types';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { DocumentUploadEndpoint } from '@/hooks/data/documents/types/uploadEndpoint';
+import { HttpVerb } from '@/helpers/http';
+import { fetcher } from '../queryClient';
+
+export type UploadDocumentParams = {
+  file: File;
+  title: string;
+  deletable?: boolean;
+  subfolder?: string | null;
+};
+
+interface UploadWithEntityIdParams extends UploadDocumentParams {
+  entityId: string;
+}
+
+/**
+ * A generic hook for uploading a document to an entity.
+ * @param uploadEndpoint - The entity-specific base upload URL
+ */
+export function useUploadDocument(
+  uploadEndpoint: DocumentUploadEndpoint,
+  { onSuccess }: UseMutationCallbacks = {},
+) {
+  return useMutation<void, ApiErrors, UploadWithEntityIdParams>({
+    mutationFn: ({ file, title, entityId, deletable, subfolder }) => {
+      const formData = new FormData();
+      formData.append('file', file);
+      formData.append('title', title);
+
+      /**
+       * Query parameters appended to the upload endpoint URL.
+       */
+      const query: Record<string, string> = {
+        entityId,
+        deletable: String(deletable ?? false),
+      };
+
+      if (subfolder) {
+        query.subfolder = subfolder;
+      }
+
+      return fetcher({
+        endpoint: uploadEndpoint,
+        method: HttpVerb.POST,
+        params: {
+          body: formData,
+          query,
+        },
+      });
+    },
+    onSuccess: () => {
+      toast.success('Document importé avec succès.');
+      onSuccess?.();
+    },
+  });
+}

