+import { useEffect, useRef, useState } from 'react';
+
+/**
+ * Scroll distance (in px) the user must pass before the header becomes sticky.
+ */
+const DEFAULT_SCROLL_THRESHOLD_PX = 1200;
+
+/**
+ * Reveals a sticky header once the user has scrolled past a threshold.
+ *
+ * @param thresholdPx Scroll distance in px before the header sticks (default: 1200)
+ * @returns `sentinelRef` to attach to a top-of-page element, and `isSticky` state
+ */
+export function useStickyOnScroll(thresholdPx: number = DEFAULT_SCROLL_THRESHOLD_PX) {
+  const sentinelRef = useRef<HTMLDivElement>(null);
+  const [isSticky, setIsSticky] = useState(false);
+
+  useEffect(
+    function observeScrollSentinel() {
+      const sentinel = sentinelRef.current;
+
+      if (!sentinel) {
+        return;
+      }
+
+      const observer = new IntersectionObserver(
+        (entries) => {
+          const entry = entries.at(0);
+
+          if (entry) {
+            setIsSticky(!entry.isIntersecting);
+          }
+        },
+        {
+          rootMargin: `${thresholdPx}px 0px 0px 0px`,
+          threshold: 0,
+        },
+      );
+
+      observer.observe(sentinel);
+
+      return () => {
+        observer.disconnect();
+      };
+    },
+    [thresholdPx],
+  );
+
+  return { sentinelRef, isSticky };
+}

