+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+import { isValidPassword } from '@/helpers/utils/stringUtils';
+
+export const basePasswordChangeSchema = z
+  .object({
+    password: z.string().optional(),
+    passwordVerif: z.string().optional(),
+    previousPassword: z.string().optional(),
+  })
+  .superRefine((values, ctx) => {
+    if (!values.password) {
+      return;
+    }
+
+    if (!isValidPassword(values.password)) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['password'],
+        message: FORM_ERROR_MESSAGES.passwordField.rulesPolicy,
+      });
+    }
+
+    if (!values.passwordVerif) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['passwordVerif'],
+        message: FORM_ERROR_MESSAGES.passwordField.confirmNewPasswordRequired,
+      });
+    }
+
+    if (values.passwordVerif && values.passwordVerif !== values.password) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['passwordVerif'],
+        message: FORM_ERROR_MESSAGES.passwordField.matchRequired,
+      });
+    }
+
+    if (!values.previousPassword) {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['previousPassword'],
+        message: FORM_ERROR_MESSAGES.passwordField.oldAuthRequired,
+      });
+    }
+  });

