+import { describe, expect, test, vi } from 'vitest';
+import { page } from 'vitest/browser';
+import { http, HttpResponse } from 'msw';
+
+import { renderWithQuery } from '@/test/browser-test-utils/renderWithQuery';
+import { testMsw } from '@/test/browser-test-utils/test-extend';
+import { EnsureLatestFrontendVersionModal } from '../EnsureLatestFrontendVersionModal';
+import { VERSION_STATIC_FILE } from '@/constants/api-endpoints';
+
+describe('EnsureLatestFrontendVersionModal', () => {
+  test('should render nothing if no VERSION.txt exists', async () => {
+    const { container } = await renderWithQuery(<EnsureLatestFrontendVersionModal />);
+
+    await expect.element(container).toBeEmptyDOMElement();
+  });
+
+  testMsw(
+    "should render visible 'new version available' modal when actual version mismatches with VERSION.txt",
+    async ({ worker }) => {
+      worker.use(http.get(VERSION_STATIC_FILE, () => new HttpResponse('v1234.0.0')));
+      window.revision = {
+        version: 'v1.0.0',
+        hash: '1234abcd',
+        branch: '',
+        nextVersion: 'v1.0.0',
+      };
+
+      await renderWithQuery(<EnsureLatestFrontendVersionModal />);
+
+      await expect
+        .element(page.getByRole('dialog', { name: 'Nouvelle version disponible' }))
+        .toBeVisible();
+      await expect
+        .element(
+          page.getByText("Une nouvelle version de l'application est disponible (v1234.0.0)."),
+        )
+        .toBeVisible();
+    },
+  );
+
+  testMsw(
+    'should not render anything when actual version matches with VERSION.txt',
+    async ({ worker }) => {
+      worker.use(http.get(VERSION_STATIC_FILE, () => new HttpResponse('v1.0.0')));
+      window.revision = {
+        version: 'v1.0.0',
+        hash: '1234abcd',
+        branch: '',
+        nextVersion: 'v1.0.0',
+      };
+
+      await renderWithQuery(<EnsureLatestFrontendVersionModal />);
+
+      await expect
+        .element(page.getByRole('dialog', { name: 'Nouvelle version disponible' }))
+        .not.toBeInTheDocument();
+      await expect
+        .element(page.getByText("Une nouvelle version de l'application est disponible"))
+        .not.toBeInTheDocument();
+    },
+  );
+
+  testMsw(
+    'should render nothing when VERSION.txt matches apart from surrounding whitespace',
+    async ({ worker }) => {
+      worker.use(http.get(VERSION_STATIC_FILE, () => new HttpResponse('v1.0.0\n')));
+      window.revision = {
+        version: 'v1.0.0',
+        hash: '1234abcd',
+        branch: '',
+        nextVersion: 'v1.0.0',
+      };
+
+      const { queryClient } = await renderWithQuery(<EnsureLatestFrontendVersionModal />);
+
+      // Wait for the query to resolve so onSuccess has run before asserting absence,
+      // otherwise the negative assertion passes trivially while the fetch is still pending.
+      await vi.waitFor(() => {
+        expect(queryClient.getQueryData([VERSION_STATIC_FILE])).toBe('v1.0.0');
+      });
+
+      await expect
+        .element(page.getByRole('dialog', { name: 'Nouvelle version disponible' }))
+        .not.toBeInTheDocument();
+    },
+  );
+});

