+import evaluationMock from '@/mocks/evaluation.json';
+
+describe('EvaluationJury component', () => {
+  testMsw('should render', async () => {
+    const { container } = await renderWithProviders(<EvaluationJury />, {
+      preloadedState: {
+        login: {
+          roles: ['ADMIN'],
+        } as LoginState,
+      },
+      pathname: '/jury/:evaluationId',
+      initialEntries: ['/jury/eval123'],
+      useReducerGenerator: true,
+      useReduxApiMiddleware: true,
+      withQueryClient: true,
+    });
+
+    await expect.element(page.getByRole('heading', { name: 'Jury N°12079' })).toBeInTheDocument();
+
+    expect(container).toMatchSnapshot();
+  });
+});
+
+describe('Evaluation jury status transition', () => {
+  testMsw(
+    'should display out of workflow status when user have the required permission',
+    async ({ worker }) => {
+      worker.use(
+        http.get(endpoints.evaluation(':evaluationId'), () => {
+          return HttpResponse.json({
+            result: { ...evaluationMock, status: 'FINISHED' },
+          });
+        }),
+      );
+
+      await renderWithProviders(<EvaluationJury />, {
+        preloadedState: {
+          login: {
+            roles: ['ADMIN'],
+            permissions: [PermissionTypes.TRAINING_WORKFLOW_BYPASS_NOMINAL_TRANSITIONS],
+          } as LoginState,
+        },
+        pathname: '/jury/:evaluationId',
+        initialEntries: ['/jury/eval123'],
+        useReducerGenerator: true,
+        useReduxApiMiddleware: true,
+        withQueryClient: true,
+      });
+
+      await expect.element(page.getByRole('heading', { name: 'Jury N°12079' })).toBeInTheDocument();
+
+      const statusChangeInput = page.getByRole('combobox', {
+        name: /statut :/i,
+      });
+      await expect.element(statusChangeInput).toHaveDisplayValue('Terminé');
+
+      await statusChangeInput.click();
+
+      await expect
+        .element(
+          page.getByRole('option', {
+            name: /terminé/i,
+          }),
+        )
+        .toBeInTheDocument();
+      await expect
+        .element(
+          page.getByRole('option', {
+            name: /annulé/i,
+          }),
+        )
+        .toBeInTheDocument();
+
+      await expect
+        .element(
+          page.getByRole('option', {
+            name: /fin d'évaluation \(hors parcours\)/i,
+          }),
+        )
+        .toBeInTheDocument();
+    },
+  );
+});

