+import { useEffect } from 'react';
+import { datadogRum } from '@datadog/browser-rum';
+
+import type { AuthenticatedUserDTO } from '@/model/AuthenticatedUserDTO';
+import { useGetEnvironment } from '@/hooks/data/environment/useGetEnvironment';
+import { DATADOG_ENV_BY_BACKEND_ENV, isRumEnabledEnv } from '@/constants/datadog';
+
+export function useDataDogRUM(authenticatedUser: AuthenticatedUserDTO | undefined) {
+  const userId = authenticatedUser?.id;
+  const userName = authenticatedUser?.userName;
+
+  const { data: backendEnv } = useGetEnvironment();
+
+  useEffect(
+    function initDatadogRUM() {
+      if (process.env.NODE_ENV !== 'production') {
+        // no monitoring for local development
+        return;
+      }
+
+      const datadogEnv = backendEnv ? DATADOG_ENV_BY_BACKEND_ENV[backendEnv] : undefined;
+
+      if (datadogEnv && isRumEnabledEnv(datadogEnv)) {
+        datadogRum.init({
+          applicationId: DATADOG_APPLICATION_ID,
+          clientToken: DATADOG_CLIENT_TOKEN,
+          site: 'datadoghq.eu',
+          service: 'yoda',
+          env: datadogEnv,
+          version: IPERIA_FRONT_VERSION,
+          sessionSampleRate: 100,
+          sessionReplaySampleRate: 100,
+          trackUserInteractions: true,
+          defaultPrivacyLevel: 'mask-user-input',
+        });
+
+        datadogRum.startSessionReplayRecording();
+      }
+    },
+    [backendEnv],
+  );
+
+  useEffect(
+    function setDatadogUser() {
+      if (!userId) {
+        datadogRum.clearUser();
+        return;
+      }
+
+      datadogRum.setUser({
+        id: userId,
+        name: userName,
+      });
+    },
+    [userId, userName],
+  );
+}

