+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { HttpVerb } from '@/api/http/httpVerb';
+import type { ApiErrorMessage, EnhancedApiError } from '@/api/errors/types';
+import { getApiErrorMessages } from '@/api/errors/getApiErrorMessages';
+import { getFallbackErrorMessage } from '@/api/http/getFallbackErrorMessage';
+
+/**
+ * Convert a Response object into readable error messages for the user.
+ * @param response received by fetch interface
+ * @param method optional HTTP method used in the request
+ *
+ * @returns an ApiError from getApiErrorMessages function
+ * @throws Re-throws any non-Error exceptions that occur during processing
+ */
+export async function getApiErrorFromHttpResponse(
+  response: Response,
+  method?: HttpVerb,
+): Promise<ApiErrors> {
+  try {
+    // Any 5xx is a server-side failure: always surface the generic message,
+    // regardless of whether the response body can be parsed.
+    if (response.status >= 500) {
+      return getApiErrorMessages(getFallbackErrorMessage(response.status, method));
+    }
+
+    const errorPayload = (await response.json()) as ApiErrorMessage | EnhancedApiError | string;
+
+    return getApiErrorMessages(errorPayload);
+  } catch (err) {
+    if (err instanceof Error) {
+      // If JSON parsing fails, it falls back to generating a generic error message
+      // based on the response status code and HTTP method.
+      const errorMessage = getFallbackErrorMessage(response.status, method);
+
+      return getApiErrorMessages(errorMessage);
+    }
+    throw err;
+  }
+}

