+import { QueryCache, QueryClient } from '@tanstack/react-query';
+
+import { UNAUTHORIZED_ERROR } from '@/api/http/constants';
+import { QUERY_KEYS } from '@/api/queryClient/queryKeys';
+
+export function createQueryClient() {
+  const client = new QueryClient({
+    defaultOptions: {
+      queries: {
+        refetchOnWindowFocus: false,
+        retry: false,
+      },
+    },
+    queryCache: new QueryCache({
+      onSuccess: (data, query) => {
+        const onQuerySuccess = query.meta?.onSuccess;
+        if (typeof onQuerySuccess === 'function') {
+          onQuerySuccess(data);
+        }
+      },
+      onError: (error, query) => {
+        // If any query returns 401, invalidate the auth query to trigger the logout flow.
+        // Skip the auth query itself to avoid an infinite invalidation loop.
+        if (
+          error instanceof Error &&
+          error.message === UNAUTHORIZED_ERROR &&
+          !query.meta?.isAuthQuery
+        ) {
+          return client.invalidateQueries({
+            queryKey: QUERY_KEYS.isAuthenticated,
+          });
+        }
+
+        const onQueryError = query.meta?.onError;
+        if (typeof onQueryError === 'function') {
+          onQueryError(error);
+        }
+      },
+    }),
+  });
+
+  return client;
+}
+
+export const queryClient = createQueryClient();

