+import type { PropsWithChildren } from 'react';
+import { renderHook as browserRenderHook } from 'vitest-browser-react';
+import { QueryClientProvider } from '@tanstack/react-query';
+
+import { createQueryClient } from '@/api/queryClient/queryClient';
+import type { BrowserRenderOptions } from './types';
+
+/**
+ * Browser-mode render helper to render React hooks with a TanStack Query
+ * provider only (no Redux store).
+ *
+ * This function wraps the given hook in a QueryClientProvider, preloading
+ * its cache with `queryData`, allowing you to test hooks that use TanStack
+ * Query without a Redux store.
+ */
+export async function renderHookWithQueryClient<TProps, TResult>(
+  render: (initialProps: TProps | undefined) => TResult,
+  { queryData, ...renderOptions }: Pick<BrowserRenderOptions, 'queryData'> = {},
+) {
+  const queryClient = createQueryClient();
+
+  queryData?.forEach(({ queryKey, data }) => {
+    queryClient.setQueryData(queryKey, data);
+  });
+
+  const Wrapper = ({ children }: PropsWithChildren<unknown>) => {
+    return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
+  };
+
+  const renderResult = await browserRenderHook(render, {
+    wrapper: Wrapper,
+    ...renderOptions,
+  });
+
+  return {
+    queryClient,
+    ...renderResult,
+  };
+}

