+      .toBeInTheDocument();
+
+    await expect.element(page.getByRole('columnheader', { name: 'Dénomination' })).toBeVisible();
+    await expect
+      .element(page.getByRole('columnheader', { name: 'Date de naissance' }))
+      .toBeVisible();
+    await expect.element(page.getByRole('columnheader', { name: 'Adresse' })).toBeVisible();
+    await expect.element(page.getByRole('columnheader', { name: 'Code postal' })).toBeVisible();
+    await expect.element(page.getByRole('columnheader', { name: 'Ville' })).toBeVisible();
+    await expect.element(page.getByRole('columnheader', { name: 'Qualités' })).toBeVisible();
+
+    const firstRow = page.getByRole('row', { name: 'MIGOUNOVA Ekaterina' });
+
+    await expect.element(firstRow.getByText('1282992')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('24-06-1901')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('6 Avenue du Maréchal Juin')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('92100')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('BOULOGNE BILLANCOURT')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('walid.essaki@ekino.com')).toBeInTheDocument();
+    await expect.element(firstRow.getByText('1 qualité')).toBeInTheDocument();
+    await expect.element(firstRow.getByRole('link', { name: 'Voir' })).toBeInTheDocument();
+  });
+
+  testMsw('should hide the creation button without the write permission', async () => {
+    await renderPhysicalPersonsList();
+
+    await expect
+      .element(page.getByRole('heading', { name: 'Personnes physiques (2)' }))
+      .toBeInTheDocument();
+
+    await expect
+      .element(page.getByRole('link', { name: 'Créer une personne physique' }))
