+import { lazy, useState } from 'react';
+import { Controller, useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import InputSearchV2 from '@/components/presentational/common/InputSearch/InputSearchV2';
+import Button from '@/components/presentational/common/Button/Button';
+import Messages from '@/components/presentational/common/Messages/Messages';
+import LoaderOverlay from '@/components/presentational/common/LoaderOverlay/LoaderOverlay';
+import DocumentViewer from '@/components/presentational/DocumentViewer/DocumentViewer';
+import { SplitPanels } from '@/components/ui/splitPanels/SplitPanels';
+import { searchBillingHandler } from '@/hooks/data/bill/fetchHandlers/searchBillingHandler';
+import { getResultFromResponse } from '@/helpers/utils/jsonHelpers';
+import { useGetInvoiceGenerationContextByBillId } from '@/hooks/data/electronicInvoicing/useGetInvoiceGenerationContextByBillId';
+import { useGenerateInvoice } from '@/hooks/data/electronicInvoicing/useGenerateInvoice';
+import { editModeSchema, type EditModeFormData } from './editModeSchema';
+import type { ApiPaginationResult } from '@/model/ApiPaginationResult';
+import type { BillDTO } from '@/model/BillDTO';
+import type { LabelAndValueType } from '@/helpers/commonTypes';
+import { searchDocumentTemplateHandler } from '@/hooks/data/documentTemplates/fetchHandlers/searchDocumentTemplateHandler';
+import type { DocumentTemplateDTO } from '@/model/DocumentTemplateDTO';
+import { prettifyJson, toMessageContent } from './utils';
+import { RadioGroup } from '@/components/ui/radiogroup/RadioGroup';
+import { SegmentedOption } from '@/components/ui/radiogroup/components/SegmentedOption';
+
+const InputCodeEditor = lazy(
+  () => import('@/components/presentational/common/InputCodeEditor/InputCodeEditor'),
+);
+
+type ResultTab = 'pdf' | 'xml';
+
+export function ElectronicInvoicingDevtoolEditMode() {
+  const { control, setValue, watch, handleSubmit } = useForm<EditModeFormData>({
+    resolver: zodResolver(editModeSchema),
+    defaultValues: { bill: null, template: null, contextJson: '' },
+  });
+
+  const template = watch('template');
+  const [resultTab, setResultTab] = useState<ResultTab>('pdf');
+
+  // ----- data -----
+
+  const {
+    mutateAsync: getGenerationContext,
+    data: getGenerationContextData,
+    error: getGenerationContextError,
+    isPending: isGenerationContextPending,
+    reset: resetGetGenerationContext,
+  } = useGetInvoiceGenerationContextByBillId();
+
+  const {
+    mutate: generateInvoice,
+    data: generateInvoiceData,
+    error: generateInvoiceError,
+    isPending: isGenerateInvoicePending,
+    reset: resetGenerateInvoice,
+  } = useGenerateInvoice();
+
+  // ----- handlers -----
+
+  function handleTemplateChange(documentTemplate: LabelAndValueType | null) {
+    setValue('template', documentTemplate);
+
+    resetGenerateInvoice();
+  }
+
+  function handleBillChange(bill: LabelAndValueType | null) {
+    resetGetGenerationContext();
+    resetGenerateInvoice();
+
+    if (!bill) {
+      return;
+    }
+
+    // errors are surfaced through the hook's error state, so the rejection is swallowed here
+    void getGenerationContext(bill.value)
+      .then((generationContext) => {
+        setValue('template', {
+          label: generationContext.template.title,
+          value: generationContext.template.id,
+        });
+        setValue('contextJson', prettifyJson(generationContext.context));
+      })
+      .catch(() => {});
+  }
+
+  function handleReset() {
+    resetGenerateInvoice();
+
+    if (getGenerationContextData) {
+      setValue('contextJson', prettifyJson(getGenerationContextData.context));
+    }
+  }
+
+  function handleDownloadPdf() {
+    if (!generateInvoiceData?.pdf) {
+      return;
+    }
+
+    const url = URL.createObjectURL(generateInvoiceData.pdf);
+    const anchor = document.createElement('a');
+
+    anchor.href = url;
+    anchor.download = 'facture-preview.pdf';
+    anchor.click();
+
+    requestAnimationFrame(() => URL.revokeObjectURL(url));
+  }
+
+  const onSubmit = handleSubmit(({ template: templateOption, contextJson: json }) => {
+    setResultTab('pdf');
+
+    // errors are surfaced through the hook's error state, so the rejection is swallowed here
+    void generateInvoice({
+      templateId: templateOption?.value as string,
+      context: JSON.parse(json),
+    });
+  });
+
+  // ----- rendering -----
+
+  const leftPanel = (
+    <div className="ElectronicInvoicingDevtool--edit-mode__panel">
+      <header className="ElectronicInvoicingDevtool--edit-mode__panel__header">
+        <h3 className="ElectronicInvoicingDevtool--edit-mode__panel__title">
+          Template de la facture (contexte)
+        </h3>
+
+        <Button
+          type="button"
+          appearance="grey-default"
+          onClick={handleReset}
+          disabled={!template}
+        >
+          <Button.Icon iconName="RotateCcw" />
+          <Button.Text>Réinitialiser</Button.Text>
+        </Button>
+      </header>
+
+      <div className="ElectronicInvoicingDevtool--edit-mode__panel__body ElectronicInvoicingDevtool--edit-mode__panel__body--form">
+        {isGenerationContextPending && (
+          <LoaderOverlay loadingText="Récupération du contexte en cours..." />
+        )}
+
+        {getGenerationContextError && (
+          <Messages
+            type="error"
+            title="Une erreur est survenue lors de la récupération du contexte de la facture"
+            content={getGenerationContextError}
+          />
+        )}
+
+        <div className="ElectronicInvoicingDevtool--edit-mode__fields">
+          <InputSearchV2
+            label="Facture"
+            control={control}
+            name="bill"
+            loadOptionsHandler={searchBillingHandler}
+            httpResponseFormatter={(json: ApiPaginationResult<BillDTO>) =>
+              getResultFromResponse(json).map((billDto) => ({
+                label: billDto.billNumber,
+                value: billDto.id,
+                valueId: billDto.id,
+              }))
+            }
+            placeholder="ex. FACTURE-UDD-2026-00823"
+            noResultsText="Aucune facture trouvée."
+            onChange={(bill) => handleBillChange(bill)}
+          />
+
+          <InputSearchV2
+            label="Template"
+            control={control}
+            name="template"
+            loadOptionsHandler={searchDocumentTemplateHandler}
+            httpResponseFormatter={(json: ApiPaginationResult<DocumentTemplateDTO>) =>
+              getResultFromResponse(json).map((documentTemplate) => ({
+                label: documentTemplate.title,
+                value: documentTemplate.id,
+                valueId: documentTemplate.id,
+              }))
+            }
+            placeholder="Sélectionner un template..."
+            noResultsText="Aucun template trouvé."
+            onChange={(documentTemplate) => handleTemplateChange(documentTemplate)}
+          />
+        </div>
+
+        <Controller
+          name="contextJson"
+          control={control}
+          render={({ field, fieldState }) => (
+            <InputCodeEditor
+              name="contextJson"
+              language="json"
+              value={field.value}
+              onChange={(value?: string) => field.onChange(value ?? '')}
+              error={fieldState.error?.message}
+            />
+          )}
+        />
+      </div>
+
+      <div className="ElectronicInvoicingDevtool--edit-mode__submit__wrapper">
+        <Button
+          type="submit"
+          appearance="orange-inverted"
+          fluid
+          loading={isGenerateInvoicePending}
+        >
+          <Button.Text>
+            {isGenerateInvoicePending ? 'Génération du XML...' : 'Sauvegarder & Générer'}
+          </Button.Text>
+        </Button>
+      </div>
+    </div>
+  );
+
+  const rightPanel = (
+    <div className="ElectronicInvoicingDevtool--edit-mode__panel">
+      <header className="ElectronicInvoicingDevtool--edit-mode__panel__header">
+        {generateInvoiceData ? (
+          <>
+            <RadioGroup<React.ReactNode, ResultTab>
+              optionComponent={SegmentedOption}
+              colorVariant="orange"
+              name="resultTab"
+              options={[
+                { label: 'Rendu PDF', value: 'pdf' },
+                { label: 'XML Factur-X', value: 'xml' },
+              ]}
+              value={resultTab}
+              onChange={(value: ResultTab | null) => {
+                setResultTab(value ?? 'pdf');
+              }}
+            />
+
+            <Button
+              type="button"
+              appearance="grey-default"
+              onClick={handleDownloadPdf}
+              disabled={!generateInvoiceData}
+            >
+              <Button.Icon iconName="Download" />
+              <Button.Text>Télécharger le PDF</Button.Text>
+            </Button>
+          </>
+        ) : (
+          <h3 className="ElectronicInvoicingDevtool--edit-mode__panel__title">Résultat</h3>
+        )}
+      </header>
+
+      <div className="ElectronicInvoicingDevtool--edit-mode__panel__body ElectronicInvoicingDevtool--edit-mode__result">
+        {isGenerateInvoicePending && (
+          <LoaderOverlay loadingText={'Génération du PDF et extraction du XML Factur-X'} />
+        )}
+
+        {!isGenerateInvoicePending && !generateInvoiceData && (
+          <p className="ElectronicInvoicingDevtool--edit-mode__result__idle">
+            Cliquez sur Sauvegarder & Générer pour produire le PDF puis extraire le XML Factur-X.
+          </p>
+        )}
+
+        {generateInvoiceData && resultTab === 'pdf' && (
+          <DocumentViewer
+            mode="document-only"
+            file={generateInvoiceData.pdf}
+            documentUrl="#"
+            documentName="facture-preview.pdf"
+          />
+        )}
+
+        {generateInvoiceData &&
+          resultTab === 'xml' &&
+          !!generateInvoiceData.inspection.embeddedXml && (
+            <InputCodeEditor
+              readonly
+              language="xml"
+              name="factur-x-generated-xml"
+              value={generateInvoiceData.inspection.embeddedXml}
+            />
+          )}
+
+        {generateInvoiceData &&
+          resultTab === 'xml' &&
