+    http.get(endpoints.invoiceGenerationContextByBillId(':billId'), () =>
+      status === 200
+        ? HttpResponse.json({ result: body })
+        : HttpResponse.json({ message: 'Boom' }, { status }),
+    ),
+  );
+}
+
+function mockGeneration(worker: SetupWorker, { status = 200, delayMs = 0 } = {}) {
+  worker.use(
+    http.post(endpoints.invoiceGeneration(), async () => {
+      if (delayMs) {
+        await delay(delayMs);
+      }
+
+      return status === 200
+        ? HttpResponse.arrayBuffer(new ArrayBuffer(8), {
+            headers: { 'Content-Type': 'application/pdf' },
+          })
+        : HttpResponse.json({ message: 'Boom' }, { status });
+    }),
+  );
+}
+
+function mockInspection(worker: SetupWorker, { body = inspectionMock } = {}) {
+  worker.use(
+    http.post(endpoints.invoiceGenerationInspection(), () => HttpResponse.json({ result: body })),
+  );
+}
+
+function mockBillSearch(worker: SetupWorker, bill = billMock) {
+  worker.use(http.post(endpoints.billing, () => HttpResponse.json({ result: [bill] })));
+}
+
+function renderEditMode() {
+  return renderWithQuery(
+    <Suspense fallback={null}>
+      <ElectronicInvoicingDevtoolEditMode />
+    </Suspense>,
+  );
+}
+
+async function selectTemplate(label = TEMPLATE_LABEL) {
+  await searchAndSelectOption({
+    selectLabel: 'Template',
+    searchTerms: label,
+    itemLabel: label,
+  });
+}
+
+async function fillContext(value: string) {
+  await page.getByTestId('contextJson').fill(value);
+}
+
+async function generate() {
+  await page.getByRole('button', { name: 'Sauvegarder & Générer' }).click();
+}
+
+describe('<ElectronicInvoicingDevtoolEditMode />', () => {
+  testMsw('should render the idle state with the template form and prompt', async () => {
+    await renderEditMode();
+
+    await expect.element(page.getByText(IDLE_TEXT)).toBeVisible();
+    await expect.element(page.getByRole('combobox', { name: /Template/ })).toBeVisible();
+    await expect.element(page.getByRole('combobox', { name: 'Facture' })).toBeVisible();
+    await expect.element(page.getByRole('radio', { name: 'Rendu PDF' })).not.toBeInTheDocument();
+  });
+
+  testMsw(
+    'should let the user pick a template without prefilling the context',
+    async ({ worker }) => {
+      mockTemplateSearch(worker);
+
+      await renderEditMode();
+      await selectTemplate();
+
+      // the context is prefilled from the bill, not from the template selection
+      await expect.element(page.getByTestId('contextJson')).toHaveValue('');
+    },
+  );
+
+  testMsw('should generate the PDF then expose both result tabs', async ({ worker }) => {
+    mockTemplateSearch(worker);
+    mockGeneration(worker, { delayMs: 300 });
+    mockInspection(worker);
+
+    await renderEditMode();
+    await selectTemplate();
+    await fillContext('{}');
+    await generate();
+
+    await expect.element(page.getByText(GENERATION_LOADING)).toBeVisible();
+
+    await expect
+      .element(page.getByTestId('document-viewer'))
+      .toHaveTextContent('facture-preview.pdf');
+    await expect.element(page.getByRole('button', { name: 'Télécharger le PDF' })).toBeVisible();
+    await expect.element(page.getByRole('radio', { name: 'Rendu PDF' })).toBeChecked();
+    await expect.element(page.getByRole('radio', { name: 'XML Factur-X' })).not.toBeChecked();
+
+    await page.getByText('XML Factur-X', { exact: true }).click();
+
+    await expect.element(page.getByRole('radio', { name: 'XML Factur-X' })).toBeChecked();
+    await expect
+      .element(page.getByTestId('factur-x-generated-xml'))
+      .toHaveTextContent('GENERATED-FACTURX');
+  });
+
+  testMsw(
+    'should block generation and flag the template when none is selected',
+    async ({ worker }) => {
+      mockGeneration(worker);
+      mockInspection(worker);
+
+      await renderEditMode();
+      await fillContext('{}');
+      await generate();
+
+      await expect.element(page.getByText(TEMPLATE_ERROR)).toBeVisible();
+      await expect.element(page.getByText(GENERATION_LOADING)).not.toBeInTheDocument();
+      await expect.element(page.getByRole('radio', { name: 'Rendu PDF' })).not.toBeInTheDocument();
+    },
+  );
+
+  testMsw('should block generation when the JSON context is invalid', async ({ worker }) => {
+    mockTemplateSearch(worker);
+    mockGeneration(worker);
+    mockInspection(worker);
+
+    await renderEditMode();
+    await selectTemplate();
+    await fillContext('{ invalid json');
+    await generate();
+
+    await expect.element(page.getByText(JSON_ERROR)).toBeVisible();
+    await expect.element(page.getByRole('radio', { name: 'Rendu PDF' })).not.toBeInTheDocument();
+  });
+
+  testMsw(
+    'should show an error banner and keep the JSON when generation fails',
+    async ({ worker }) => {
+      mockTemplateSearch(worker);
+      mockGeneration(worker, { status: 500 });
+      mockInspection(worker);
+
+      await renderEditMode();
+      await selectTemplate();
+      await fillContext('{"number":"KEEP-ME"}');
+      await generate();
+
+      await expect.element(page.getByText(GENERATION_ERROR)).toBeVisible();
+      await expect.element(page.getByTestId('contextJson')).toHaveValue('{"number":"KEEP-ME"}');
+      await expect.element(page.getByRole('radio', { name: 'Rendu PDF' })).not.toBeInTheDocument();
+    },
+  );
+
+  testMsw('should prefill the context from a valid invoice number', async ({ worker }) => {
+    mockBillSearch(worker);
+    mockContextByBillId(worker);
+
+    await renderEditMode();
+    await searchAndSelectOption({
+      selectLabel: 'Facture',
+      searchTerms: 'F-001',
+      itemLabel: 'F-001',
+    });
+
+    await expect
+      .element(page.getByTestId('contextJson'))
+      .toHaveValue(JSON.stringify(contextMock.context, null, 2));
