+      mockContextByBillId(worker, { status: 404 });
+
+      await renderEditMode();
+      await searchAndSelectOption({
+        selectLabel: 'Facture',
+        searchTerms: 'F-001',
+        itemLabel: 'F-001',
+      });
+
+      await expect.element(page.getByText(CONTEXT_ERROR)).toBeVisible();
+      await expect.element(page.getByTestId('contextJson')).toHaveValue('');
+    },
