+import { Group, Panel, Separator } from 'react-resizable-panels';
+import cs from 'classnames';
+
+import './SplitPanels.scss';
+
+interface SplitPanelsProps {
+  left: React.ReactNode;
+  right: React.ReactNode;
+  /** Default size of the left panel, as a percentage of the group. */
+  defaultLeftSize?: number;
+  /** Minimum size of each panel, as a percentage of the group. */
+  minSize?: number;
+  className?: string;
+}
+
+export function SplitPanels({
+  left,
+  right,
+  defaultLeftSize = 50,
+  minSize = 20,
+  className,
+}: Readonly<SplitPanelsProps>) {
+  return (
+    <Group
+      orientation="horizontal"
+      className={cs('SplitPanels', className)}
+    >
+      <Panel
+        className="SplitPanels__panel"
+        defaultSize={`${defaultLeftSize}%`}
+        minSize={`${minSize}%`}
+      >
+        {left}
+      </Panel>
+
+      <Separator className="SplitPanels__handle" />
+
+      <Panel
+        className="SplitPanels__panel"
+        minSize={`${minSize}%`}
+      >
+        {right}
+      </Panel>
+    </Group>
+  );
+}

