+import { useMutation } from '@tanstack/react-query';
+
+import { fetcher } from '@/api/http/fetcher';
+import { blobFetcher } from '@/api/http/blobFetcher';
+import endpoints from '@/constants/api-endpoints';
+import { HttpVerb } from '@/api/http/httpVerb';
+import type { InvoiceInspectionDTO } from '@/model/InvoiceInspectionDTO';
+import type { InvoiceGenerationPayload } from '@/model/InvoiceGenerationDTO';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { BlobFetcherError } from '@/api/http/types';
+
+type GenerateInvoiceResult = {
+  pdf: Blob;
+  inspection: InvoiceInspectionDTO;
+};
+
+/**
+ * Generates a Factur-X invoice PDF from a JSON context, then extracts its
+ * embedded XML by reusing the inspection endpoint on the generated PDF.
+ */
+export function useGenerateInvoice() {
+  return useMutation<GenerateInvoiceResult, ApiErrors | BlobFetcherError, InvoiceGenerationPayload>(
+    {
+      mutationFn: async ({ templateId, context }) => {
+        const pdf = await blobFetcher({
+          endpoint: endpoints.invoiceGeneration(),
+          method: HttpVerb.POST,
+          headers: { Accept: 'application/pdf' },
+          body: { templateId, context },
+        });
+
+        const formData = new FormData();
+        formData.append(
+          'file',
+          new File([pdf], 'facture-preview.pdf', { type: 'application/pdf' }),
+        );
+
+        const inspection = await fetcher<InvoiceInspectionDTO, FormData>({
+          endpoint: endpoints.invoiceGenerationInspection(),
+          method: HttpVerb.POST,
+          params: { body: formData },
+        });
+
+        return { pdf, inspection };
+      },
+    },
+  );
+}

