+import { useQuery } from '@tanstack/react-query';
+
+import { fetcher } from '@/api/http/fetcher';
+import { blobFetcher } from '@/api/http/blobFetcher';
+import endpoints from '@/constants/api-endpoints';
+import { HttpVerb } from '@/api/http/httpVerb';
+import type { InvoiceInspectionDTO } from '@/model/InvoiceInspectionDTO';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { BlobFetcherError } from '@/api/http/types';
+import { QUERY_KEYS } from '@/api/queryClient/queryKeys';
+
+export function useInspectAndPreviewByBillId(billId?: string, fileId?: string) {
+  const {
+    data: billInspectionData,
+    error: billInspectionError,
+    isLoading: isBillInspectionLoading,
+  } = useQuery<InvoiceInspectionDTO, ApiErrors>({
+    queryKey: QUERY_KEYS.inspectInvoiceByBillId(billId as string),
+    queryFn: ({ signal }) =>
+      fetcher<InvoiceInspectionDTO>({
+        endpoint: endpoints.invoiceGenerationInspectionByBillId(billId as string),
+        method: HttpVerb.GET,
+        signal,
+      }),
+    enabled: !!billId,
+  });
+
+  const {
+    data: downloadBillData,
+    error: downloadBillError,
+    isLoading: isDownloadBillLoading,
+  } = useQuery<Blob, BlobFetcherError>({
+    queryKey: QUERY_KEYS.fileDownload(fileId as string),
+    queryFn: ({ signal }) =>
+      blobFetcher({
+        endpoint: endpoints.fileDownload(fileId as string),
+        method: HttpVerb.GET,
+        signal,
+      }),
+    enabled: !!fileId,
+  });
+
+  return {
+    data: {
+      billInspection: billInspectionData,
+      downloadedFile: downloadBillData,
+    },
+    error: {
+      billInspectionError: billInspectionError,
+      previewBillError: downloadBillError,
+    },
+    isLoading: {
+      isBillInspectionLoading,
+      isDownloadBillLoading,
+    },
+  };
+}

