+import type { BlobFetcherError } from '@/api/http/types';
+import type { ApiErrors } from '@/helpers/commonTypes';
+
+export function prettifyJson(value: unknown): string {
+  return JSON.stringify(value, null, 2);
+}
+
+export function toMessageContent(
+  error: ApiErrors | BlobFetcherError | null | undefined,
+): ApiErrors | undefined {
+  if (!error) {
+    return undefined;
+  }
+
+  if (typeof error === 'object' && error !== null && 'status' in error && 'error' in error) {
+    return error.error;
+  }
+
+  return error;
+}

