+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { DocumentTemplateDTO } from '@/model/DocumentTemplateDTO';
+
+export function useGetInvoiceGenerationContextByBillId() {
+  return useMutation<InvoiceGenerationContextDTO, ApiErrors, string>({
+    mutationFn: async (billId: string) => {
+      const invoiceGenerationContext = await fetcher<InvoiceGenerationContextDTO>({
+        endpoint: endpoints.invoiceGenerationContextByBillId(billId),
+        method: HttpVerb.GET,
+      });
+
+      const documentTemplate = await fetcher<DocumentTemplateDTO>({
+        endpoint: endpoints.documentTemplate(invoiceGenerationContext.templateId),
+        method: HttpVerb.GET,
+      });
+
+      return {
+        ...invoiceGenerationContext,
+        template: documentTemplate,
+      };
+    },
+  });
+}

