+import { lazy, Suspense } from 'react';
+
+import type { ResultTab } from './utils';
+import type { GenerateInvoiceResult } from '@/hooks/data/electronicInvoicing/useGenerateInvoice';
+import { RadioGroup } from '@/components/ui/radiogroup/RadioGroup';
+import { SegmentedOption } from '@/components/ui/radiogroup/components/SegmentedOption';
+import Button from '@/components/presentational/common/Button/Button';
+import Messages from '@/components/presentational/common/Messages/Messages';
+import LoaderOverlay from '@/components/presentational/common/LoaderOverlay/LoaderOverlay';
+import DocumentViewer from '@/components/presentational/DocumentViewer/DocumentViewer';
+
+const CodeEditor = lazy(async () => ({
+  default: (await import('@/components/ui/codeEditor/CodeEditor')).CodeEditor,
+}));
+
+interface InvoiceGenerationResultRightPanelProps {
+  generateInvoiceData: GenerateInvoiceResult | undefined;
+  resultTab: ResultTab;
+  setResultTab: (tab: ResultTab) => void;
+  isGenerateInvoicePending: boolean;
+}
+
+export function InvoiceGenerationResultRightPanel({
+  generateInvoiceData,
+  resultTab,
+  setResultTab,
+  isGenerateInvoicePending,
+}: Readonly<InvoiceGenerationResultRightPanelProps>) {
+  // ----- derived values -----
+
+  const isIdle = !isGenerateInvoicePending && !generateInvoiceData;
+
+  const xmlCodeEditorContentByTab = {
+    pdf: undefined,
+    'factur-x': generateInvoiceData?.inspection?.embeddedXml,
+    report: generateInvoiceData?.inspection?.report,
+  } satisfies Record<ResultTab, string | null | undefined>;
+
+  const xmlCodeEditorContent = xmlCodeEditorContentByTab[resultTab];
+
+  const isXmlContentMissing = !!generateInvoiceData && resultTab !== 'pdf' && !xmlCodeEditorContent;
+
+  // ----- handlers -----
+
+  function handleDownloadPdf() {
+    if (!generateInvoiceData?.pdf) {
+      return;
+    }
+
+    const url = URL.createObjectURL(generateInvoiceData.pdf);
+    const anchor = document.createElement('a');
+
+    anchor.href = url;
+    anchor.download = 'facture-preview.pdf';
+    anchor.click();
+
+    requestAnimationFrame(() => URL.revokeObjectURL(url));
+  }
+
+  return (
+    <div className="ElectronicInvoicingDevtool--edit-mode__panel">
+      <header className="ElectronicInvoicingDevtool--edit-mode__panel__header">
+        {generateInvoiceData ? (
+          <>
+            <RadioGroup<string, ResultTab>
+              optionComponent={SegmentedOption}
+              colorVariant="orange"
+              name="resultTab"
+              options={[
+                { label: 'Rendu PDF', value: 'pdf' },
+                { label: 'XML Factur-X', value: 'factur-x' },
+                { label: 'Rapport', value: 'report' },
+              ]}
+              value={resultTab}
+              onChange={(value) => {
+                setResultTab(value ?? 'pdf');
+              }}
+            />
+
+            <Button
+              type="button"
+              appearance="grey-default"
+              onClick={handleDownloadPdf}
+            >
+              <Button.Icon iconName="Download" />
+              <Button.Text>Télécharger le PDF</Button.Text>
+            </Button>
+          </>
+        ) : (
+          <h3 className="ElectronicInvoicingDevtool--edit-mode__panel__title">Résultat</h3>
+        )}
+      </header>
+
+      <div className="ElectronicInvoicingDevtool--edit-mode__panel__body ElectronicInvoicingDevtool--edit-mode__result">
+        {isGenerateInvoicePending && (
+          <LoaderOverlay loadingText={'Génération du PDF et extraction du XML Factur-X'} />
+        )}
+
+        {isIdle && (
+          <p className="ElectronicInvoicingDevtool--edit-mode__result__idle">
+            Cliquez sur Sauvegarder & Générer pour produire le PDF puis extraire le XML Factur-X.
+          </p>
+        )}
+
+        {generateInvoiceData && resultTab === 'pdf' && (
+          <DocumentViewer
+            mode="document-only"
+            file={generateInvoiceData.pdf}
+            documentUrl="#"
+            documentName="facture-preview.pdf"
+          />
+        )}
+
+        {generateInvoiceData && xmlCodeEditorContent && (
+          <Suspense fallback={<LoaderOverlay loadingText="Chargement du CodeEditor..." />}>
+            <CodeEditor
+              readOnly
+              language="xml"
+              name="generated-xml"
+              value={xmlCodeEditorContent}
+              height="100%"
+            />
+          </Suspense>
+        )}
+
+        {isXmlContentMissing && (
+          <Messages
+            type="info"
+            content="Aucune donnée XML n'a pu être extraite du PDF généré."
+          />
+        )}
+      </div>
+    </div>
+  );
+}

