+@use '/src/styles/settings' as *;
+
+.ElectronicInvoicingDevtool {
+  &Container {
+    width: 100%;
+    max-width: $desktopBreakpoint;
+    margin: 80px auto;
+
+    .CardView__body {
+      padding: 0;
+    }
+  }
+
+  /* ----- shared panel layout (read & edit modes) ----- */
+
+  &--read-mode__panel,
+  &--edit-mode__panel {
+    display: flex;
+    flex-direction: column;
+    width: 100%;
+    height: 100%;
+  }
+
+  &--read-mode__panel__header,
+  &--edit-mode__panel__header {
+    display: flex;
+    gap: 12px;
+    align-items: center;
+    justify-content: space-between;
+    min-height: 52px;
+    padding: 8px 20px;
+    font-size: px-to-rem(13);
+    font-weight: bold;
+    color: $color-primary;
+    text-transform: uppercase;
+    background-color: white;
+    border-bottom: 1px solid $color-dustygray;
+  }
+
+  &--read-mode__panel__header:last-of-type,
+  &--edit-mode__panel__header:first-of-type {
+    padding: 0px 20px;
+  }
+
+  &--read-mode__panel__body,
+  &--edit-mode__panel__body {
+    position: relative;
+    display: flex;
+    flex: 1;
+    flex-direction: column;
+    min-height: 0;
+    overflow: auto;
+
+    .documentViewer {
+      flex: 1;
+      margin-top: 0;
+      overflow: auto;
+    }
+
+    .react-pdf__Document {
+      width: 100%;
+    }
+
+    .CodeEditor,
+    [id='factur-x-xml'],
+    [id='factur-x-generated-xml'],
+    [id='contextJson'] {
+      flex: 1;
+      min-height: 0;
+    }
+
+    .Messages {
+      border-radius: 0;
+    }
+  }
+
+  /* ----- read mode ----- */
+
+  &--read-mode {
+    &__bill-form {
+      display: flex;
+      column-gap: 12px;
+      align-items: end;
+      padding: 12px 20px;
+
+      .InputUpload {
+        width: 300px;
+      }
+
+      .InputUpload__dropzone {
+        gap: 0;
+        max-height: 38px;
+      }
+
+      &__separator {
+        color: $color-dustygray;
+      }
+    }
+
+    &__result {
+      height: 70vh;
+      background-color: $color-gallery;
+
+      &--empty {
+        display: flex;
+        align-items: center;
+        justify-content: center;
+        color: $color-dustygray;
+      }
+    }
+
+    &__panels {
+      border-top: 1px solid $color-dustygray;
+    }
+
+    &__panel__header .RadioGroup {
+      width: 200px;
+
+      & .SegmentedOption:not(.SegmentedOption--state-selected) {
+        color: $color-secondary;
+        border-color: $color-secondary;
+        opacity: 1;
+      }
+    }
+  }
+
+  /* ----- edit mode ----- */
+
+  &--edit-mode {
+    display: flex;
+    flex-direction: column;
+
+    .Messages {
+      margin-bottom: 0;
+      border-radius: 0;
+    }
+
+    &__panel__header {
+      .Button {
+        transform-origin: right;
+        scale: 0.8;
+      }
+
+      & .SegmentedOption:not(.SegmentedOption--state-selected) {
+        color: $color-secondary;
+        border-color: $color-secondary;
+        opacity: 1;
+      }
+    }
+
+    &__panel__title {
+      margin: 0;
+      font-size: px-to-rem(13);
+      font-weight: bold;
+    }
+
+    &__form {
+      height: 70vh;
+      background-color: $color-gallery;
+      border-top: 1px solid $color-dustygray;
+    }
+
+    &__fields {
+      display: flex;
+      gap: 16px;
+      padding: 10px 12px;
+
+      > * {
+        flex: 1;
+      }
+    }
+
+    &__tabs {
+      display: flex;
+      gap: 8px;
+    }
+
+    &__result {
+      background-color: $color-gallery;
+
+      &__idle {
+        max-width: 320px;
+        margin: auto;
+        color: $color-dustygray;
+        text-align: center;
+      }
+    }
+
+    &__submit__wrapper {
+      padding: 12px;
+    }
+  }
+}

