+import {
+  useController,
+  type FieldValues,
+  type FieldPath,
+  type ControllerProps,
+} from 'react-hook-form';
+
+import { CodeEditor, type CodeEditorBaseProps } from '@/components/ui/codeEditor/CodeEditor';
+
+export interface InputCodeEditorV2Props<
+  TFieldValues extends FieldValues = FieldValues,
+  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
+>
+  extends
+    Pick<ControllerProps<TFieldValues, TName>, 'name' | 'control' | 'rules'>,
+    Omit<
+      CodeEditorBaseProps,
+      'name' | 'value' | 'onChange' | 'onBlur' | 'errorMessage' | 'fieldRef'
+    > {
+  /**
+   * Optional callback triggered when the content changes
+   */
+  onChange?: (value: string) => void;
+}
+
+/**
+ * RHF controlled code editor with syntax highlighting.
+ */
+export function InputCodeEditorV2<
+  T extends FieldValues = FieldValues,
+  U extends FieldPath<T> = FieldPath<T>,
+>({
+  control,
+  name,
+  rules,
+  onChange: handleChange,
+  label,
+  language,
+  readOnly,
+  ...codeEditorProps
+}: Readonly<InputCodeEditorV2Props<T, U>>) {
+  const { field, fieldState } = useController({
+    name,
+    control,
+    rules,
+  });
+
+  function handleValueChange(value: string) {
+    field.onChange(value);
+    handleChange?.(value);
+  }
+
+  return (
+    <CodeEditor
+      {...codeEditorProps}
+      name={field.name}
+      value={field.value ?? ''}
+      onChange={handleValueChange}
+      onBlur={field.onBlur}
+      fieldRef={field.ref}
+      label={label}
+      language={language}
+      readOnly={readOnly}
+      errorMessage={fieldState.error?.message}
+    />
+  );
+}

