+import MonacoEditor from '@monaco-editor/react';
+import cs from 'classnames';
+import type { RefCallBack } from 'react-hook-form';
+
+import './_CodeEditor.scss';
+
+type CodeEditorLanguage = 'json' | 'freemarker2' | 'xml';
+
+export interface CodeEditorBaseProps {
+  /**
+   * The name of the editor, used as a fallback accessible name (`aria-label`) when no `label` is provided
+   */
+  name: string;
+  /**
+   * Content of the editor. Should be controlled from outside the component.
+   */
+  value: string;
+  /**
+   * Callback triggered when the content changes, with the new content as argument.
+   * Left out in read only mode.
+   */
+  onChange?: (value: string) => void;
+  /**
+   * Optional label text added before the component
+   */
+  label?: string;
+  /**
+   * The aria label for the editor's textarea (when it is focused).
+   */
+  ariaLabel?: string;
+  /**
+   * Syntax highlighting language
+   * @default 'json'
+   */
+  language?: CodeEditorLanguage;
+  /**
+   * Whether the content can be edited
+   */
+  readOnly?: boolean;
+  /**
+   * Height of the editor
+   * @default '300px'
+   */
+  height?: string;
+  /**
+   * Optional css class added to the component wrapper
+   */
+  className?: string;
+  /**
+   * Error message to display below the component in case of validation error
+   */
+  errorMessage?: string;
+  disabled?: boolean;
+  required?: boolean;
+  onBlur?: () => void;
+  fieldRef?: RefCallBack;
+}
+
+/**
+ * Code editor component built on the Monaco editor primitive for syntax highlighting and code edition.
+ * Can be used standalone (controlled from outside) or integrated with a form.
+ */
+export function CodeEditor({
+  name,
+  value,
+  onChange,
+  label,
+  ariaLabel,
+  language = 'json',
+  readOnly,
+  height = '300px',
+  className,
+  errorMessage,
+  disabled,
+  required,
+  onBlur,
+  fieldRef,
+}: Readonly<CodeEditorBaseProps>) {
+  function handleChange(newValue?: string) {
+    onChange?.(newValue ?? '');
+  }
+
+  return (
+    <div
+      ref={fieldRef}
+      onBlur={onBlur}
+      className={cs('CodeEditor', className, {
+        'CodeEditor--state-error': errorMessage,
+        'CodeEditor--state-disabled': disabled,
+      })}
+    >
+      {/*
+        Monaco-editor doesn't expose a labelable native element for `htmlFor`/`id`.
+        Its internal textarea is aria-labeled via `options.ariaLabel`, so this label is visual only.
+      */}
+      {label && (
+        <label className="CodeEditor__label">
+          {label}
+          {required && <span className="RequiredField">{'*'}</span>}
+        </label>
+      )}
+
+      <div
+        className="CodeEditor__editor"
+        data-testid="monaco-editor"
+      >
+        <MonacoEditor
+          width="100%"
+          height={height}
+          language={language}
+          theme="vs-light"
+          value={value}
+          onChange={handleChange}
+          options={{
+            autoIndent: 'full',
+            readOnly,
+            minimap: { enabled: false },
+            /**
+             * Falls back to `label` then `name` so the editor always has an accessible name,
+             * since Monaco's internal textarea cannot be associated with the visual `<label>`
+             * via `htmlFor`/`id`.
+             */
+            ariaLabel: ariaLabel ?? label ?? name,
+          }}
+        />
+      </div>
+
+      {errorMessage && <p className="CodeEditor__errorMessage">{errorMessage}</p>}
+    </div>
+  );
+}

