+  path.includes(<span class="s">'ajout'</span>) ||
+  path.includes(<span class="s">'modification'</span>) ||
+  path.includes(<span class="s">'creation'</span>) ||
+  path.includes(<span class="s">'login'</span>) ||
+  path.includes(<span class="s">'recherche'</span>) ||
+  path.includes(<span class="s">'suivi'</span>) ||
+  path.includes(<span class="s">'inscription'</span>)
