+import { describe, expect, test } from 'vitest';
+
+import type { NavMenuContext } from '../utils';
+import { getSubListClassName, SUB_LIST_CLASSNAME } from '../utils';
+
+function buildContext(overrides: Partial<NavMenuContext> = {}): NavMenuContext {
+  return {
+    currentPath: '/',
+    navigationDirection: 'HORIZONTAL',
+    hasActiveInfoMessage: false,
+    topLevelCount: 10,
+    ...overrides,
+  };
+}
+
+describe('function getSubListClassName()', () => {
+  test('should return the base class when navigation direction is VERTICAL', () => {
+    const context = buildContext({ navigationDirection: 'VERTICAL', topLevelCount: 10 });
+
+    expect(getSubListClassName(5, 2, context)).toBe(SUB_LIST_CLASSNAME.base);
+  });
+
+  test('should return the spread class when the sub menu has more than 8 children', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(9, 2, context)).toBe(SUB_LIST_CLASSNAME.spread);
+  });
+
+  test('should return the left class when there are 4 or fewer top level items', () => {
+    const context = buildContext({ topLevelCount: 4 });
+
+    expect(getSubListClassName(5, 2, context)).toBe(SUB_LIST_CLASSNAME.left);
+  });
+
+  test('should return the center class when the sub menu has 3 or fewer children', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(3, 2, context)).toBe(SUB_LIST_CLASSNAME.center);
+  });
+
+  test('should return the left class when index is before the middle and below the crowded threshold', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(5, 2, context)).toBe(SUB_LIST_CLASSNAME.left);
+  });
+
+  test('should return the center class when index is before the middle but at or above the crowded threshold', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(5, 4, context)).toBe(SUB_LIST_CLASSNAME.center);
+  });
+
+  test('should return the center class when index is after the middle and the sub menu has 4 or fewer children', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(4, 6, context)).toBe(SUB_LIST_CLASSNAME.center);
+  });
+
+  test('should return the right class when index is after the middle and the sub menu has more than 4 children', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(5, 7, context)).toBe(SUB_LIST_CLASSNAME.right);
+  });
+
+  test('should return the base class when index is exactly the middle', () => {
+    const context = buildContext({ topLevelCount: 10 });
+
+    expect(getSubListClassName(5, 5, context)).toBe(SUB_LIST_CLASSNAME.base);
+  });
+});

