+import type { MenuOrientation } from '@/model/AuthenticatedUserDTO';
+
+export interface NavMenuContext {
+  currentPath: string;
+  navigationDirection: MenuOrientation | undefined;
+  hasActiveInfoMessage: boolean;
+  topLevelCount: number;
+}
+
+const WIDE_SUB_MENU_THRESHOLD = 8;
+const CROWDED_MENU_THRESHOLD = 4;
+const NARROW_SUB_MENU_THRESHOLD = 3;
+const CENTERED_SUB_MENU_THRESHOLD = 4;
+
+export const SUB_LIST_CLASSNAME = {
+  base: 'HeaderNav__subList',
+  left: 'HeaderNav__subList__left',
+  center: 'HeaderNav__subList__center',
+  right: 'HeaderNav__subList__right',
+  spread: 'HeaderNav__subList__spread',
+} as const;
+
+/**
+ * Legacy Horizontal sub menus are absolutely positioned over the full header width,
+ * so their content has to be pushed towards the parent item to stay readable.
+ */
+export function getSubListClassName(
+  childCount: number,
+  index: number,
+  context: NavMenuContext,
+): string {
+  const { navigationDirection, topLevelCount } = context;
+
+  if (navigationDirection === 'VERTICAL') {
+    return SUB_LIST_CLASSNAME.base;
+  }
+
+  if (childCount > WIDE_SUB_MENU_THRESHOLD) {
+    return SUB_LIST_CLASSNAME.spread;
+  }
+
+  if (topLevelCount <= CROWDED_MENU_THRESHOLD) {
+    return SUB_LIST_CLASSNAME.left;
+  }
+
+  if (childCount <= NARROW_SUB_MENU_THRESHOLD) {
+    return SUB_LIST_CLASSNAME.center;
+  }
+
+  const middleIndex = topLevelCount / 2;
+
+  if (index < middleIndex) {
+    return index < CROWDED_MENU_THRESHOLD ? SUB_LIST_CLASSNAME.left : SUB_LIST_CLASSNAME.center;
+  }
+
+  if (index > middleIndex) {
+    return childCount <= CENTERED_SUB_MENU_THRESHOLD
+      ? SUB_LIST_CLASSNAME.center
+      : SUB_LIST_CLASSNAME.right;
+  }
+
+  return SUB_LIST_CLASSNAME.base;
+}

