+import { NumericFormat } from 'react-number-format';
+
+import type { BillDTO } from '@/model/BillDTO';
+import type { BillLine } from '@/components/presentational/common/ServiceBilling/types';
+
+import './BillDescription.scss';
+
+export interface BillDescriptionProps {
+  title: string;
+  lines: BillLine[];
+  expenseDetails?: BillDTO['expenseDetails'] | null;
+}
+
+export function BillDescription({ title, lines, expenseDetails }: Readonly<BillDescriptionProps>) {
+  const billedLines = lines.filter((line): line is Required<BillLine> => {
+    return !!line.amount && line.amount > 0;
+  });
+
+  return (
+    <div className="BillDescription">
+      <span className="BillDescription__title">{title}</span>
+
+      {billedLines.map((line) => {
+        return (
+          <span
+            key={line.label}
+            className="BillDescription__charge"
+          >
+            <span className="BillDescription__charge__label">{line.label}</span>
+            <BillAmount value={line.amount} />
+          </span>
+        );
+      })}
+
+      {(expenseDetails ?? []).map((expense) => {
+        return (
+          <span
+            key={expense.id}
+            className="BillDescription__expense"
+          >
+            <span className="BillDescription__charge__label">{`- ${expense.displayLine} : `}</span>
+            <BillAmount value={expense.amount} />
+          </span>
+        );
+      })}
+    </div>
+  );
+}
+
+function BillAmount({ value }: Readonly<{ value: number }>) {
+  return (
+    <NumericFormat
+      value={value}
+      displayType="text"
+      thousandSeparator=" "
+      suffix=" €"
+      decimalScale={2}
+    />
+  );
+}

