+import type { BillType, SearchBillDTO } from '@/model/BillDTO';
+import type { BillLine } from '@/components/presentational/common/ServiceBilling/types';
+import { BILLED_SERVICE, getBilledServiceCosts, isBilledServiceType } from '@/model/BilledService';
+import {
+  BILL_TYPE_LABEL,
+  BUY_TYPE_COMPLEMENT,
+} from '@/components/presentational/common/ServiceBilling/constants';
+
+export function getModulePathBillLines(data: SearchBillDTO): BillLine[] {
+  return [
+    { label: 'Frais pédagogiques :', amount: data.costs.pedagogic },
+    { label: 'Frais techniques :', amount: data.technicalExpense },
+    { label: 'Frais réels :', amount: data.costs.expense },
+    { label: 'Frais de vie :', amount: data.costs.life },
+    ...getBilledServiceLines(data),
+  ];
+}
+
+export function getEvaluationBillLines(data: SearchBillDTO): BillLine[] {
+  return [
+    { label: 'Frais pédagogiques :', amount: data.costs.pedagogic },
+    { label: 'Frais de vie :', amount: data.costs.life },
+    { label: 'Frais techniques :', amount: data.technicalExpense },
+    ...getBilledServiceLines(data),
+  ];
+}
+
+function getBilledServiceLines(data: SearchBillDTO): BillLine[] {
+  const billedServiceCosts = getBilledServiceCosts(data.costs);
+
+  return data.costTypes.filter(isBilledServiceType).map((billedService) => {
+    return {
+      label: `${BILLED_SERVICE[billedService].label} :`,
+      amount: billedServiceCosts[billedService].ttc,
+    };
+  });
+}
+
+export function getBillTitle<Tdata extends Pick<SearchBillDTO, 'invoiceCredit' | 'buyType'>>(
+  data: Tdata,
+) {
+  // Since the backend does not provide the BillType in the SearchBillDTO, (for now)
+  // we derive it from the invoiceCredit boolean to standardize the title generation logic.
+  const billType: BillType = data.invoiceCredit ? 'CREDIT' : 'INVOICE';
+
+  return `${BILL_TYPE_LABEL[billType]} ${BUY_TYPE_COMPLEMENT[data.buyType]}`;
+}
+
+export function getBillDescriptionTitle(data: SearchBillDTO) {
+  return [getBillTitle(data), data.learnerSector, data.trainingPlan].filter(Boolean).join(' ');
+}

