+import type { LabelAndValueType } from '@/helpers/commonTypes';
+import type { IconMeta } from './types';
+import { SvgIcon, type SvgIconName } from '@/components/ui/svg/SvgIcon';
+import { RadioGroup } from '@/components/ui/radiogroup/RadioGroup';
+import { SegmentedOption } from '@/components/ui/radiogroup/components/SegmentedOption';
+
+const ALL_OPTION_VALUE = 'ALL';
+
+interface SegmentedFilterGroupProps<TValue extends string> {
+  name: string;
+  label: string;
+  /**
+   * Options specific to this filter, excluding the "ALL" option which is added automatically.
+   * When an option's meta.iconName is set, its label is rendered with the matching icon.
+   */
+  options: LabelAndValueType<React.ReactNode, TValue, Partial<IconMeta>>[];
+  value: TValue | 'ALL';
+  onChange: (value: TValue | 'ALL') => void;
+  /**
+   * Optional custom label for the "ALL" option. Defaults to a "Tous" label with a grid icon.
+   */
+  allOptionLabel?: string;
+  allOptionIconName?: SvgIconName;
+  className?: string;
+}
+
+/**
+ * Segmented radio group with a built-in "ALL" option, used to filter lists by type.
+ */
+export function SegmentedFilterGroup<TValue extends string>({
+  name,
+  label,
+  options,
+  value,
+  onChange,
+  allOptionLabel = 'Tous',
+  allOptionIconName = 'LayoutGrid',
+  className,
+}: Readonly<SegmentedFilterGroupProps<TValue>>) {
+  const segmentedOptions = options.map((option) => ({
+    label: (
+      <OptionLabel
+        label={option.label}
+        iconName={option.meta?.iconName}
+      />
+    ),
+    value: option.value,
+  }));
+
+  return (
+    <div className={className}>
+      <RadioGroup<React.ReactNode, TValue | 'ALL'>
+        name={name}
+        label={label}
+        optionComponent={SegmentedOption}
+        colorVariant="white"
+        options={[
+          {
+            label: (
+              <OptionLabel
+                label={allOptionLabel}
+                iconName={allOptionIconName}
+              />
+            ),
+            value: ALL_OPTION_VALUE,
+          },
+          ...segmentedOptions,
+        ]}
+        value={value}
+        onChange={(newValue) => onChange(newValue ?? ALL_OPTION_VALUE)}
+      />
+    </div>
+  );
+}
+
+function OptionLabel({
+  label,
+  iconName,
+}: Readonly<{
+  label: React.ReactNode;
+  iconName?: SvgIconName;
+}>) {
+  if (!iconName) {
+    return label;
+  }
+
+  return (
+    <>
+      <SvgIcon
+        name={iconName}
+        size={16}
+      />
+      {label}
+    </>
+  );
+}

