+import { useState } from 'react';
+
+import { TargetPathLabel, type TargetPath } from '@/model/BillingEnum';
+import type {
+  ServiceBillingInput,
+  ServiceBillingPreviewDTO,
+} from '@/model/ServiceBillingPreviewDTO';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import { Dialog } from '@/components/ui/dialog/Dialog';
+import { ServiceBillTraining } from './components/ServiceBillTraining';
+import { ServiceBillLearnerSelection } from './components/ServiceBillLearnerSelection';
+import Messages from '../Messages/Messages';
+import LoaderOverlay from '../LoaderOverlay/LoaderOverlay';
+import Button from '../Button/Button';
+import ButtonGroup from '../ButtonGroup/ButtonGroup';
+
+import './_ServiceBillGenerationPreview.scss';
+
+interface ServiceBillGenerationPreviewProps {
+  context: `${TargetPath}`;
+  isPending: boolean;
+  serviceBillingPreview: ServiceBillingPreviewDTO | undefined;
+  serviceBillingPreviewError: ApiErrors;
+  serviceBillingMutation: {
+    isPending: boolean;
+    error: ApiErrors;
+    generate: (input: ServiceBillingInput) => void;
+    reset: () => void;
+  };
+}
+
+export function ServiceBillGenerationPreview({
+  context,
+  isPending,
+  serviceBillingPreview,
+  serviceBillingPreviewError,
+  serviceBillingMutation,
+}: Readonly<ServiceBillGenerationPreviewProps>) {
+  const [selectedIds, setSelectedIds] = useState<string[]>([]);
+
+  const isTrainingPreview = !!serviceBillingPreview?.training;
+  const isLearnerSelectionPreview = !!serviceBillingPreview?.trainingDepartures;
+  const serviceBillingError = serviceBillingPreviewError || serviceBillingMutation.error;
+
+  // ----- handlers ------
+
+  function toggleTrainingDeparture(trainingDepartureId: string) {
+    setSelectedIds((currentIds) => {
+      return currentIds.includes(trainingDepartureId)
+        ? currentIds.filter((id) => id !== trainingDepartureId)
+        : [...currentIds, trainingDepartureId];
+    });
+  }
+
+  function generateBill() {
+    if (isTrainingPreview) {
+      const trainingId = serviceBillingPreview.training.id;
+
+      const serviceBillingInputByContext = {
+        MODULE_PATH: { modulePathId: trainingId },
+        EVALUATION: { evaluationId: trainingId },
+      } as const satisfies Record<`${TargetPath}`, ServiceBillingInput>;
+
+      serviceBillingMutation.generate(serviceBillingInputByContext[context]);
+    } else if (isLearnerSelectionPreview) {
+      serviceBillingMutation.generate({ trainingDepartureIds: selectedIds });
+    }
+  }
+
+  // ----- rendering ------
+
+  if (isPending) {
+    return (
+      <div className="ServiceBillGenerationPreview">
+        <LoaderOverlay loadingText="Chargement de la prévisualisation en cours..." />
+      </div>
+    );
+  }
+
+  return (
+    <div className="ServiceBillGenerationPreview">
+      {serviceBillingError && (
+        <Messages
+          type="error"
+          customCSSClassname="ServiceBillGenerationPreview__error"
+          content={serviceBillingError}
+        />
+      )}
+
+      {isTrainingPreview && (
+        <ServiceBillTraining
+          targetLabel={TargetPathLabel[context]}
+          training={serviceBillingPreview.training}
+        />
+      )}
+
+      {isLearnerSelectionPreview && (
+        <ServiceBillLearnerSelection
+          trainingDepartures={serviceBillingPreview.trainingDepartures}
+          selectedIds={selectedIds}
+          onToggle={toggleTrainingDeparture}
+        />
+      )}
+
+      <ButtonGroup
+        compacted
+        customCSSClassname="ServiceBillGenerationPreview__actions"
+      >
+        {serviceBillingPreviewError ? (
+          <Dialog.Close asChild>
+            <Button appearance="orange-inverted">
+              <Button.Text>Fermer</Button.Text>
+            </Button>
+          </Dialog.Close>
+        ) : (
+          <>
+            <Dialog.Close asChild>
+              <Button appearance="orange-default">
+                <Button.Text>Annuler</Button.Text>
+              </Button>
+            </Dialog.Close>
+
+            <Button
+              type="button"
+              appearance="orange-inverted"
+              disabled={isLearnerSelectionPreview && selectedIds.length === 0}
+              loading={serviceBillingMutation.isPending}
+              onClick={generateBill}
+            >
+              <Button.Text>Valider et générer les factures</Button.Text>
+            </Button>
+          </>
+        )}
+      </ButtonGroup>
+    </div>
+  );
+}

