+import { describe, expect, test, vi } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import { Checkbox, type CheckboxProps } from '../Checkbox';
+
+const LABEL = 'This is a checkbox label';
+
+function renderCheckbox(props?: Partial<CheckboxProps>) {
+  return render(
+    <Checkbox
+      checked={false}
+      onCheckedChange={() => {}}
+      {...props}
+    >
+      {LABEL}
+    </Checkbox>,
+  );
+}
+
+describe('<Checkbox />', () => {
+  test('renders children as the accessible name', async () => {
+    await renderCheckbox();
+
+    await expect.element(page.getByRole('checkbox', { name: LABEL })).toBeVisible();
+  });
+
+  test('reflects the checked prop', async () => {
+    await renderCheckbox({ checked: true });
+
+    await expect.element(page.getByRole('checkbox')).toBeChecked();
+  });
+
+  test('calls onCheckedChange with the next state when clicked', async () => {
+    const onCheckedChange = vi.fn();
+
+    await renderCheckbox({ onCheckedChange });
+
+    await page.getByRole('checkbox').click();
+
+    expect(onCheckedChange).toHaveBeenCalledWith(true);
+  });
+
+  test('toggles when the label text beside the box is clicked', async () => {
+    const onCheckedChange = vi.fn();
+
+    await renderCheckbox({ onCheckedChange });
+
+    await page.getByText(LABEL).click();
+
+    expect(onCheckedChange).toHaveBeenCalledWith(true);
+  });
+
+  test('does not call onCheckedChange when disabled', async () => {
+    const onCheckedChange = vi.fn();
+
+    await renderCheckbox({ onCheckedChange, disabled: true });
+
+    await page.getByRole('checkbox').click({ force: true });
+
+    expect(onCheckedChange).not.toHaveBeenCalled();
+  });
+});

