+import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox';
+import cs from 'classnames';
+
+import { CheckIcon } from '@/components/ui/svg/base-ui/CheckIcon';
+import { HorizontalRuleIcon } from '@/components/ui/svg/base-ui/HorizontalRuleIcon';
+
+import './Checkbox.scss';
+
+export interface CheckboxProps {
+  /**
+   * Whether the checkbox is ticked. Controlled from outside the component.
+   */
+  checked: boolean;
+  /**
+   * Called with the next checked state when the user toggles the checkbox.
+   */
+  onCheckedChange: (checked: boolean) => void;
+  /**
+   * Content rendered beside the box, inside the label. The slot is a flex item
+   * that grows, so its inner layout belongs entirely to the consumer: a plain
+   * string for a simple label, or a full row of nodes.
+   */
+  children: React.ReactNode;
+  /**
+   * Identifies the field when a form is submitted.
+   */
+  name?: string;
+  /**
+   * The value submitted with the form when the checkbox is ticked.
+   */
+  value?: string;
+  /**
+   * Mixed state: neither ticked nor unticked. Renders a dash instead of a tick.
+   */
+  indeterminate?: boolean;
+  disabled?: boolean;
+  className?: string;
+}
+
+/**
+ * Checkbox built on the Base UI Checkbox primitive for native accessibility
+ * (role, keyboard handling, checked state). The primitive renders a hidden
+ * `<input>` beside the box, so the checkbox still takes part in form submission
+ * and the wrapping `<label>` associates with it implicitly.
+ *
+ * @remarks
+ * The CSS block is `CheckboxField`, not `Checkbox`: the legacy
+ * `InputCheckbox/Checkbox.scss` already owns the global `.Checkbox` classes and
+ * both stylesheets load app-wide. Rename this block once that one is retired.
+ */
+export function Checkbox({
+  checked,
+  onCheckedChange,
+  children,
+  name,
+  value,
+  disabled,
+  indeterminate = false,
+  className,
+}: Readonly<CheckboxProps>) {
+  return (
+    <label
+      className={cs('CheckboxField', className, {
+        'CheckboxField--disabled': disabled,
+      })}
+    >
+      <BaseCheckbox.Root
+        name={name}
+        value={value}
+        checked={checked}
+        disabled={disabled}
+        indeterminate={indeterminate}
+        onCheckedChange={(nextChecked) => {
+          onCheckedChange(nextChecked);
+        }}
+        className="CheckboxField__box"
+      >
+        <BaseCheckbox.Indicator className="CheckboxField__indicator">
+          {indeterminate ? (
+            <HorizontalRuleIcon className="CheckboxField__icon" />
+          ) : (
+            <CheckIcon className="CheckboxField__icon" />
+          )}
+        </BaseCheckbox.Indicator>
+      </BaseCheckbox.Root>
+
+      <span className="CheckboxField__content">{children}</span>
+    </label>
+  );
+}

