+export const serviceBillingPreviewHandlers: Array<BrowserHandler> = [
+  mswSetup.disable(
+    http.post(endpoints.billingTrainingSupervisionPreview, async ({ request }) => {
+      const requestBody = (await request.json()) as ServiceBillingPreviewInput;
+
+      const isFlexiAutomie =
+        'modulePathId' in requestBody && requestBody.modulePathId === 'FLEXI_AUTONOMIE';
+
+      let trainingSupervisionBillPreviewMock: ServiceBillingPreviewDTO =
+        billingPreviewOnTrainingMock;
+
+      if (isFlexiAutomie) {
+        trainingSupervisionBillPreviewMock = billingPreviewOnTrainingDepartureMock;
+      }
+
+      await delay(1000);
+      return HttpResponse.json({ result: trainingSupervisionBillPreviewMock }, { status: 200 });
+    }),
+  ),
+
+  mswSetup.disable(
+    http.post(endpoints.billingTrainingSupervision, () => {
+      return new HttpResponse(null, { status: 200 });
+    }),
+  ),
+
+  mswSetup.disable(
+    http.post(endpoints.billingAdministrativeControl, () => {
+      return new HttpResponse(null, { status: 200 });
+    }),
+  ),
+];

