+import { describe, test, expect } from 'vitest';
+import { resolveBillCreditAction } from '../billCreditRules';
+import type { BillCreditPermissions, BillCreditTarget } from '../types';
+
+const NO_PERMISSIONS: BillCreditPermissions = {
+  PEDAGOGIC: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+  TRAINING_SUPERVISION: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+  ADMINISTRATIVE_CONTROL: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+};
+
+function buildPermissions(overrides: Partial<BillCreditPermissions>): BillCreditPermissions {
+  return { ...NO_PERMISSIONS, ...overrides };
+}
+
+describe('resolveBillCreditAction', () => {
+  describe('no matching family', () => {
+    test('should return null when costTypes match no rule', () => {
+      const bill: BillCreditTarget = {
+        childId: null,
+        childPreview: false,
+        invoiceCredit: false,
+        costTypes: ['LIFE'],
+      };
+
+      expect(resolveBillCreditAction(bill, NO_PERMISSIONS)).toBeNull();
+    });
+  });
+
+  describe('PEDAGOGIC family credit costTypes (PEDAGOGIC, EXPENSE, MISCELLANEOUS)', () => {
+    test.each(['PEDAGOGIC', 'EXPENSE', 'MISCELLANEOUS'] as const)(
+      'should return GENERATE_CREDIT for %s costType when canGenerateCredit is true and childId is null',
+      (costType) => {
+        const bill: BillCreditTarget = {
+          childId: null,
+          childPreview: false,
+          invoiceCredit: false,
+          costTypes: [costType],
+        };
+        const permissions = buildPermissions({
+          PEDAGOGIC: { canGenerateCredit: true, canGenerateBillFromCredit: false },
+        });
+
+        expect(resolveBillCreditAction(bill, permissions)).toEqual({
+          type: 'GENERATE_CREDIT',
+          family: 'PEDAGOGIC',
+        });
+      },
+    );
+
+    test('should return null when canGenerateCredit is false', () => {
+      const bill: BillCreditTarget = {
+        childId: null,
+        childPreview: false,
+        invoiceCredit: false,
+        costTypes: ['PEDAGOGIC'],
+      };
+
+      expect(resolveBillCreditAction(bill, NO_PERMISSIONS)).toBeNull();
+    });
+
+    test('should return null when childId is set, even if canGenerateCredit is true', () => {
+      const bill: BillCreditTarget = {
+        childId: '123',
+        childPreview: false,
+        invoiceCredit: false,
+        costTypes: ['PEDAGOGIC'],
+      };
+      const permissions = buildPermissions({
+        PEDAGOGIC: { canGenerateCredit: true, canGenerateBillFromCredit: false },
+      });
+
+      expect(resolveBillCreditAction(bill, permissions)).toBeNull();
+    });
+  });
+
+  describe('PEDAGOGIC family bill-from-credit branch', () => {
+    test('should return GENERATE_BILL_FROM_CREDIT when childId is null and canGenerateBillFromCredit is true', () => {
+      const bill: BillCreditTarget = {
+        childId: null,
+        childPreview: false,
+        invoiceCredit: true,
+        costTypes: ['PEDAGOGIC'],
+      };
+      const permissions = buildPermissions({
+        PEDAGOGIC: { canGenerateCredit: false, canGenerateBillFromCredit: true },
+      });
+
+      expect(resolveBillCreditAction(bill, permissions)).toEqual({
+        type: 'GENERATE_BILL_FROM_CREDIT',
+        family: 'PEDAGOGIC',
+      });
+    });
+
+    test('should return GENERATE_BILL_FROM_CREDIT when childId is set but childPreview is true', () => {
+      const bill: BillCreditTarget = {
+        childId: '789',
+        childPreview: true,
+        invoiceCredit: true,
+        costTypes: ['PEDAGOGIC'],
+      };
+      const permissions = buildPermissions({
+        PEDAGOGIC: { canGenerateCredit: false, canGenerateBillFromCredit: true },
+      });
+
+      expect(resolveBillCreditAction(bill, permissions)).toEqual({
+        type: 'GENERATE_BILL_FROM_CREDIT',
+        family: 'PEDAGOGIC',
+      });
+    });
+
+    test('should return null when childId is set and childPreview is false', () => {
+      const bill: BillCreditTarget = {
+        childId: '123',
+        childPreview: false,
+        invoiceCredit: true,
+        costTypes: ['PEDAGOGIC'],
+      };
+      const permissions = buildPermissions({
+        PEDAGOGIC: { canGenerateCredit: false, canGenerateBillFromCredit: true },
+      });
+
+      expect(resolveBillCreditAction(bill, permissions)).toBeNull();
