+import type { SearchBillDTO } from '@/model/BillDTO';
+import type { BillCreditFamily, BillCreditPermissions } from '../types';
+import Button from '@/components/presentational/common/Button/Button';
+import { resolveBillCreditAction } from '../billCreditRules';
+import { BILL_CREDIT_ACTION_LABEL } from '../constants';
+
+interface BillCreditActionButtonProps {
+  data: SearchBillDTO;
+  permissions: BillCreditPermissions;
+  onGenerateCredit: (family: BillCreditFamily) => void;
+  onGenerateBillFromCredit: (family: BillCreditFamily) => void;
+}
+
+export function BillCreditActionButton({
+  data,
+  permissions,
+  onGenerateCredit,
+  onGenerateBillFromCredit,
+}: Readonly<BillCreditActionButtonProps>) {
+  const action = resolveBillCreditAction(data, permissions);
+
+  if (!action) {
+    return null;
+  }
+
+  const handler = action.type === 'GENERATE_CREDIT' ? onGenerateCredit : onGenerateBillFromCredit;
+
+  return (
+    <Button
+      type="button"
+      onClick={() => handler(action.family)}
+      customClassName="TableView__cell__button OfModulesList__editBtn"
+      appearance="simple"
+    >
+      <Button.Text>{BILL_CREDIT_ACTION_LABEL[action.type]}</Button.Text>
+    </Button>
+  );
+}

