+import { PermissionTypes } from '@/enums/authorization';
+import { usePermission } from '@/hooks/usePermission';
+import type { BillCreditPermissions } from '../types';
+
+/**
+ * Maps the user permissions to the credit generation and
+ * "bill-from-credit" generation actions of each bill family.
+ * Call it once per list, not per row.
+ */
+export function useBillCreditPermissions() {
+  const canManageBilling = usePermission(PermissionTypes.BILLING_WRITE);
+  const canCreditTrainingSupervision = usePermission(
+    PermissionTypes.BILLING_TRAINING_SUPERVISION_CREDIT,
+  );
+  const canGenerateTrainingSupervisionBill = usePermission(
+    PermissionTypes.BILLING_TRAINING_SUPERVISION_GENERATE,
+  );
+  const canCreditAdministrativeControl = usePermission(
+    PermissionTypes.BILLING_ADMINISTRATIVE_CONTROL_CREDIT,
+  );
+  const canGenerateAdministrativeControlBill = usePermission(
+    PermissionTypes.BILLING_ADMINISTRATIVE_CONTROL_GENERATE,
+  );
+
+  return {
+    PEDAGOGIC: {
+      canGenerateCredit: canManageBilling,
+      // Legacy rule: generating a bill from a pedagogic credit is not permission-gated.
+      canGenerateBillFromCredit: true,
+    },
+    TRAINING_SUPERVISION: {
+      canGenerateCredit: canCreditTrainingSupervision,
+      canGenerateBillFromCredit: canGenerateTrainingSupervisionBill,
+    },
+    ADMINISTRATIVE_CONTROL: {
+      canGenerateCredit: canCreditAdministrativeControl,
+      canGenerateBillFromCredit: canGenerateAdministrativeControlBill,
+    },
+  } satisfies BillCreditPermissions;
+}

