+import { useState } from 'react';
+
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { BillCreditFamily } from '../types';
+import type { UseMutationCallbacks } from '@/api/http/types';
+import { useCreateBillCredit } from '@/hooks/data/bill/useCreateBillCredit';
+import { useGenerateTrainingSupervisionCredit } from '@/hooks/data/bill/billedService/useGenerateTrainingSupervisionCredit';
+import { useGenerateAdministrativeControlCredit } from '@/hooks/data/bill/billedService/useGenerateAdministrativeControlCredit';
+
+type BillCreditContext = { modulePathId: string } | { evaluationId: string };
+
+type BillCreditTargetState = {
+  billId: string;
+  family: BillCreditFamily;
+};
+type BillCreditMutation = {
+  isPending: boolean;
+  error: ApiErrors;
+  generateCredit: (billId: string) => void;
+};
+
+interface UseServiceBillCreditGenerationParams {
+  context: BillCreditContext;
+  invalidateListBilling: () => Promise<void>;
+}
+
+export function useServiceBillCreditGeneration({
+  context,
+  invalidateListBilling,
+}: UseServiceBillCreditGenerationParams) {
+  const [target, setTarget] = useState<BillCreditTargetState | null>(null);
+  const [isDialogOpen, setIsDialogOpen] = useState(false);
+
+  function openDialog(billId: string, family: BillCreditFamily) {
+    setTarget({ billId, family });
+    setIsDialogOpen(true);
+  }
+
+  function closeDialog() {
+    // `target` is kept so the dialog keeps its content during the exit animation.
+    setIsDialogOpen(false);
+  }
+
+  const mutationCallbacks: UseMutationCallbacks = {
+    onSuccess: () => {
+      void invalidateListBilling();
+    },
+    onSettled: closeDialog,
+  };
+
+  const pedagogicBillCredit = useCreateBillCredit(mutationCallbacks);
+  const trainingSupervisionBillCredit = useGenerateTrainingSupervisionCredit(mutationCallbacks);
+  const administrativeControlBillCredit = useGenerateAdministrativeControlCredit(mutationCallbacks);
+
+  const creditMutationByFamily = {
+    PEDAGOGIC: {
+      isPending: pedagogicBillCredit.isPending,
+      error: pedagogicBillCredit.error,
+      generateCredit: (billId: string) => {
+        pedagogicBillCredit.mutate({ id: billId, ...context });
+      },
+    },
+    TRAINING_SUPERVISION: {
+      isPending: trainingSupervisionBillCredit.isPending,
+      error: trainingSupervisionBillCredit.error,
+      generateCredit: trainingSupervisionBillCredit.mutate,
+    },
+    ADMINISTRATIVE_CONTROL: {
+      isPending: administrativeControlBillCredit.isPending,
+      error: administrativeControlBillCredit.error,
+      generateCredit: administrativeControlBillCredit.mutate,
+    },
+  } satisfies Record<BillCreditFamily, BillCreditMutation>;
+
+  const activeMutation = target ? creditMutationByFamily[target.family] : null;
+
+  return {
+    confirmCreditGenerationDialog: {
+      isOpen: isDialogOpen,
+      open: openDialog,
+      close: closeDialog,
+    },
+    isGenerateCreditPending: activeMutation?.isPending ?? false,
+    generateCreditError: activeMutation?.error,
+    generateCredit: () => {
+      if (target) {
+        activeMutation?.generateCredit(target.billId);
+      }
+    },
+  };
+}

