+import { useState } from 'react';
+
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { BillCreditFamily, ServiceBillGenerationEntity } from '../types';
+import type { BilledService } from '@/model/BilledService';
+import type {
+  ServiceBillingPreviewDTO,
+  ServiceBillingPreviewInput,
+} from '@/model/ServiceBillingPreviewDTO';
+import { usePreviewTrainingSupervisionBill } from '@/hooks/data/bill/billedService/usePreviewTrainingSupervisionBill';
+import { usePreviewAdministrativeControlBill } from '@/hooks/data/bill/billedService/usePreviewAdministrativeControlBill';
+
+type BilledServicePreviewMutation = ReturnType<
+  typeof usePreviewTrainingSupervisionBill | typeof usePreviewAdministrativeControlBill
+>;
+
+type CreditToBillTargetState = {
+  billId: string;
+  billCode: string;
+  trainingDepartureId: string | null;
+  family: BillCreditFamily;
+};
+type BillFromCreditMutation = {
+  isPending: boolean;
+  data: ServiceBillingPreviewDTO | undefined;
+  error: ApiErrors;
+} | null;
+
+export function useServiceBillGenerationFromCredit(entity: ServiceBillGenerationEntity) {
+  const [target, setTarget] = useState<CreditToBillTargetState | null>(null);
+  const [isDialogOpen, setIsDialogOpen] = useState(false);
+  const [showPedagogicBillModal, setShowPedagogicBillModal] = useState(false);
+
+  const previewTrainingSupervisionBill = usePreviewTrainingSupervisionBill();
+  const previewAdministrativeControlBill = usePreviewAdministrativeControlBill();
+
+  function openDialog(billTargetState: CreditToBillTargetState) {
+    setTarget(billTargetState);
+
+    if (billTargetState.family === 'PEDAGOGIC') {
+      setShowPedagogicBillModal(true);
+    } else {
+      const previewMutationByService = {
+        TRAINING_SUPERVISION: previewTrainingSupervisionBill,
+        ADMINISTRATIVE_CONTROL: previewAdministrativeControlBill,
+      } satisfies Record<BilledService, BilledServicePreviewMutation>;
+
+      const previewInput: ServiceBillingPreviewInput = billTargetState.trainingDepartureId
+        ? { trainingDepartureIds: [billTargetState.trainingDepartureId] }
+        : entity;
+
+      setIsDialogOpen(true);
+      previewMutationByService[billTargetState.family].mutate(previewInput);
+    }
+  }
+
+  function closeDialog() {
