+import type { CostType } from '@/model/BillDTO';
+import type {
+  BillCreditAction,
+  BillCreditFamily,
+  BillCreditPermissions,
+  BillCreditTarget,
+} from './types';
+
+type BillCreditRule = {
+  family: BillCreditFamily;
+  costTypes: CostType[];
+  /**
+   * Family guard applied on top of the permission, on the "bill from credit" branch only.
+   */
+  isBillFromCreditTargetAllowed: (bill: BillCreditTarget) => boolean;
+};
+
+/**
+ * A bill belongs to a single family, so the first matching rule wins.
+ */
+const BILL_CREDIT_RULES = [
+  {
+    family: 'PEDAGOGIC',
+    costTypes: ['PEDAGOGIC', 'EXPENSE', 'MISCELLANEOUS'],
+    isBillFromCreditTargetAllowed: (bill) => {
+      // keep the legacy behavior for pedagogic bill from credit
+      return bill.childId === null || bill.childPreview;
+    },
+  },
+  {
+    family: 'TRAINING_SUPERVISION',
+    costTypes: ['TRAINING_SUPERVISION'],
+    isBillFromCreditTargetAllowed: () => {
+      return true;
+    },
+  },
+  {
+    family: 'ADMINISTRATIVE_CONTROL',
+    costTypes: ['ADMINISTRATIVE_CONTROL'],
+    isBillFromCreditTargetAllowed: () => {
+      return true;
+    },
+  },
+] satisfies BillCreditRule[];
+
+/**
+ * Single source of truth for the credit action a bill row may offer:
+ * a credit on an invoice, a bill on a credit, or nothing at all.
+ */
+export function resolveBillCreditAction(
+  bill: BillCreditTarget,
+  permissions: BillCreditPermissions,
+): BillCreditAction | null {
+  const rule = BILL_CREDIT_RULES.find((candidate) => {
+    return candidate.costTypes.some((costType) => bill.costTypes.includes(costType));
+  });
+
+  if (!rule) {
+    return null;
+  }
+
+  const { canGenerateCredit, canGenerateBillFromCredit } = permissions[rule.family];
+
+  if (bill.invoiceCredit) {
+    return canGenerateBillFromCredit && rule.isBillFromCreditTargetAllowed(bill)
+      ? { type: 'GENERATE_BILL_FROM_CREDIT', family: rule.family }
+      : null;
+  }
+
+  return canGenerateCredit && bill.childId === null
+    ? { type: 'GENERATE_CREDIT', family: rule.family }
+    : null;
+}

