+/**
+ * ServiceBillingPreviewInput happens to use the same interface as ServiceBillingInput
+ * But we keep it separate since they are used by two different services (preview/generate)
+ */
 export type ServiceBillingInput =
   | { trainingDepartureIds: string[]; modulePathId?: never; evaluationId?: never }
