+import { describe, test, expect } from 'vitest';
+
+import type { BillCostsDTO } from '@/model/BillDTO';
+import { getInvoiceCostLines } from '../helpers';
+
+const mockCosts: BillCostsDTO = {
+  administrative: 0,
+  expense: 45,
+  pedagogic: 300,
+  life: 120,
+  miscellaneous: 0,
+  administrativeControl: { ttc: 50, ht: 41.67, vat: 8.33 },
+  trainingSuperVision: { ttc: 370, ht: 308.33, vat: 61.67 },
+  total: 465,
+};
+
+describe('function getInvoiceCostLines()', () => {
+  test('should return the training supervision detail when the bill costType is training supervision', () => {
+    expect(getInvoiceCostLines(mockCosts, ['TRAINING_SUPERVISION'])).toEqual([
+      { label: 'Montant de prestation ingénierie pédagogique (TTC) :', amount: 370 },
+      { label: 'Montant HT :', amount: 308.33 },
+      { label: 'TVA (20%) :', amount: 61.67 },
+    ]);
+  });
+
+  test('should return the administrative control detail when the bill costType is administrative control', () => {
+    expect(getInvoiceCostLines(mockCosts, ['ADMINISTRATIVE_CONTROL'])).toEqual([
+      { label: 'Montant de prestation contrôle administratif (TTC) :', amount: 50 },
+      { label: 'Montant HT :', amount: 41.67 },
+      { label: 'TVA (20%) :', amount: 8.33 },
+    ]);
+  });
+
+  test('should return the direct costs in display order, whatever the cost types order', () => {
+    expect(getInvoiceCostLines(mockCosts, ['EXPENSE', 'PEDAGOGIC', 'LIFE'])).toEqual([
+      { label: 'Frais pédagogiques :', amount: 300 },
+      { label: 'Frais de vie :', amount: 120 },
+      { label: 'Frais réels :', amount: 45 },
+    ]);
+  });
+
+  test('should ignore direct costs absent from the cost types', () => {
+    expect(getInvoiceCostLines(mockCosts, ['PEDAGOGIC'])).toEqual([
+      { label: 'Frais pédagogiques :', amount: 300 },
+    ]);
+  });
+
+  test('should ignore direct costs with a zero amount', () => {
+    expect(getInvoiceCostLines(mockCosts, ['PEDAGOGIC', 'MISCELLANEOUS'])).toEqual([
+      { label: 'Frais pédagogiques :', amount: 300 },
+    ]);
+  });
+
+  test('should keep negative direct costs for a credit bill', () => {
+    expect(getInvoiceCostLines({ ...mockCosts, pedagogic: -300 }, ['PEDAGOGIC'])).toEqual([
+      { label: 'Frais pédagogiques :', amount: -300 },
+    ]);
+  });
+
+  test('should return no line when there is no cost type', () => {
+    expect(getInvoiceCostLines(mockCosts, [])).toEqual([]);
+  });
+});

