+import { z } from 'zod';
+
+import { baseComboboxSchema } from '@/helpers/validations/schemas/baseComboboxSchema';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export const baseInvoiceFormSchema = z.object({
+  issuerId: baseComboboxSchema.refine((value) => value !== null, {
+    error: FORM_ERROR_MESSAGES.issuer.required,
+  }),
+  validationDate: z.iso.date({
+    error: FORM_ERROR_MESSAGES.date.issueDateRequired,
+  }),
+  trainingPlan: z.enum(['PLAN']),
+});
+
+/**
+ * We can't extends a discriminated union schema directly, so we use this helper
+ * function to apply the target path assignee rule.
+ */
+export function applyTargetPathAssigneeRule<T extends z.ZodRawShape>(baseSchema: z.ZodObject<T>) {
+  return z.discriminatedUnion('targetPath', [
+    baseSchema.extend({
+      targetPath: z.literal('MODULE_PATH'),
+      modulePathId: baseComboboxSchema.refine((value) => value !== null, {
+        error: FORM_ERROR_MESSAGES.bill.modulePathRequired,
+      }),
+      evaluationId: z.never().optional(),
+    }),
+    baseSchema.extend({
+      targetPath: z.literal('EVALUATION'),
+      modulePathId: z.never().optional(),
+      evaluationId: baseComboboxSchema.refine((value) => value !== null, {
+        error: FORM_ERROR_MESSAGES.bill.evaluationRequired,
+      }),
+    }),
+  ]);
+}

