+import type { BillCostsDTO, BillDTO, CostType } from '@/model/BillDTO';
+import type { TrainingMode } from '@/model/TrainingMode';
+import type { SalesInvoiceFormInputData } from './SalesInvoiceForm/salesInvoiceFormSchema';
+import type { InvoiceCostLine } from './types';
+import {
+  getBilledServiceCost,
+  isBilledServiceType,
+  type BilledService,
+} from '@/model/BilledService';
+import { EvaluationTypeLabel } from '@/model/EvaluationTypeEnum';
+import {
+  BILLED_SERVICE_TRAINING_MODE,
+  COST_TYPE_LABEL,
+  type BilledServiceTrainingMode,
+} from '@/components/presentational/common/ServiceBilling/constants';
+import { formatWithCodeAndName } from '@/helpers/formats/formatLabelHelpers';
+import { BILLED_SERVICE_TTC_LABEL, LEGACY_COST_TYPES } from './constants';
+
+function isCostType(costType: CostType): costType is Exclude<CostType, BilledService> {
+  return !isBilledServiceType(costType);
+}
+
+function isBilledServiceTrainingMode(
+  trainingMode: `${TrainingMode}`,
+): trainingMode is BilledServiceTrainingMode {
+  return BILLED_SERVICE_TRAINING_MODE.includes(trainingMode as BilledServiceTrainingMode);
+}
+
+export function getSalesInvoiceFormInitialValues(
+  data: BillDTO | undefined,
+): SalesInvoiceFormInputData {
+  const billedService = data?.costTypes?.find(isBilledServiceType) ?? null;
+  const costType = data?.costTypes?.find(isCostType) ?? null;
+
+  const learner = data?.trainingDeparture?.learner;
+
+  // Legacy SellBillingForm field mapping for learner sector
+  const learnerSector = (data?.learnerSector as SalesInvoiceFormInputData['learnerSector']) ?? null;
+
+  const commonValues = {
+    billType: 'SELL',
+    issuerId: data?.issuer
+      ? {
+          label: formatWithCodeAndName(data.issuer.legalPersonDto),
+          value: data.issuer.issuerId,
+        }
+      : null,
+    validationDate: data?.validationDate ?? '',
+    billedService,
+    trainingPlan: 'PLAN',
+    costType,
+    learnerId: learner
+      ? {
+          label: `${learner.lastname} ${learner.firstname}`,
+          value: learner.id,
+        }
+      : null,
+    learnerSector,
+  } satisfies Partial<SalesInvoiceFormInputData>;
+
+  if (data?.evaluationId) {
+    return {
+      ...commonValues,
+      targetPath: 'EVALUATION',
+      evaluationId: {
+        label: `${data.evaluationCode} - [${data.blocCode}] ${EvaluationTypeLabel[data.evaluationType]}`,
+        value: data.evaluationId,
+      },
+      trainingMode: 'PRESENTIEL', // Evaluation is always Presentiel
+    } satisfies SalesInvoiceFormInputData;
+  }
+
+  return {
+    ...commonValues,
+    targetPath: 'MODULE_PATH',
+    modulePathId: data?.modulePathId
+      ? {
+          label: `[${data.modulePathCode}] ${data.moduleName}`,
+          value: data.modulePathId,
+        }
+      : null,
+    trainingMode:
+      data?.modulePathType && isBilledServiceTrainingMode(data.modulePathType)
+        ? data.modulePathType
+        : null,
+  } satisfies SalesInvoiceFormInputData;
+}
+
+/**
+ * Builds the cost lines displayed in the invoice cost detail.
+ *
+ * A billed service bill details its single service (TTC, HT, VAT); otherwise the direct costs
+ * (legacy pedagogic and life costs) are listed in a fixed order, keeping only those present in
+ * `costTypes` with a non-zero amount.
+ */
+export function getInvoiceCostLines(
+  billCost: BillCostsDTO | undefined,
+  costTypes: CostType[] = [],
+): InvoiceCostLine[] {
+  if (!billCost) {
+    return [];
+  }
+
+  const billedService = costTypes.find(isBilledServiceType);
+
+  if (billedService) {
+    const { ttc, ht, vat } = getBilledServiceCost(billCost, billedService);
+
+    return [
+      { label: BILLED_SERVICE_TTC_LABEL[billedService], amount: ttc },
+      { label: 'Montant HT :', amount: ht },
+      { label: 'TVA (20%) :', amount: vat },
+    ];
+  }
+
+  const selectedCostTypes = new Set(costTypes);
+  const amounts = getDirectCostAmounts(billCost);
+
+  const selectedDirectCostLines = LEGACY_COST_TYPES.filter(
+    (costType) => selectedCostTypes.has(costType) && !!amounts[costType],
+  ).map((costType) => ({
+    label: `${COST_TYPE_LABEL[costType]} :`,
+    amount: amounts[costType],
+  }));
+
+  return selectedDirectCostLines;
+}
+
+function getDirectCostAmounts(costs: BillCostsDTO) {
+  return {
+    PEDAGOGIC: costs.pedagogic,
+    LIFE: costs.life,
+    EXPENSE: costs.expense,
+    MISCELLANEOUS: costs.miscellaneous,
+  } satisfies Record<Exclude<CostType, BilledService>, number>;
+}

