+import { useEffect, useEffectEvent } from 'react';
+import { useSearchParams } from 'react-router';
+
+interface UseResetOutOfRangePageParams {
+  currentPage: number;
+  totalPages: number;
+  /**
+   * Whether `totalPages` comes from the current criteria. With `keepPreviousData`,
+   * the query still exposes the previous result while the new one is in flight,
+   * so clamping on it would use stale totals.
+   */
+  isTotalPagesFresh: boolean;
+}
+
+/**
+ * Resets `currentPage` to 1 when the URL points past the last available page.
+ * Guards criteria changes that bypass the filter form (extra body params, filter
+ * tag removal) and stale deep links, which would otherwise render an empty list.
+ */
+export function useResetOutOfRangePage({
+  currentPage,
+  totalPages,
+  isTotalPagesFresh,
+}: UseResetOutOfRangePageParams) {
+  const [, setSearchParams] = useSearchParams();
+
+  const resetCurrentPage = useEffectEvent(() => {
+    setSearchParams(
+      (params) => {
+        params.set('currentPage', '1');
+
+        return params;
+      },
+      { replace: true },
+    );
+  });
+
+  useEffect(
+    function resetPageWhenOutOfRange() {
+      if (!isTotalPagesFresh || totalPages < 1 || currentPage <= totalPages) {
+        return;
+      }
+
+      resetCurrentPage();
+    },
+    [isTotalPagesFresh, currentPage, totalPages],
+  );
+}

