+import type { ApiErrorCodes } from './apiErrorCodes';
+import type { ApiErrorMessage, EnhancedApiError, NestRecordArrayType } from './types';
+
+export function isEnhancedApiError(
+  err: EnhancedApiError | ApiErrorMessage,
+): err is EnhancedApiError {
+  return typeof err === 'object' && 'code' in err && 'message' in err;
+}
+
+export function isLegacyApiError(err: EnhancedApiError | ApiErrorMessage): err is ApiErrorMessage {
+  return typeof err === 'object' && 'messages' in err;
+}
+
+export function isArrayRecord(
+  record: ApiErrorMessage['messages'],
+): record is Record<ApiErrorCodes, string[]> {
+  return Object.values(record).every((value) => Array.isArray(value));
+}
+
+export function isStringOrNumberRecord(
+  record: ApiErrorMessage['messages'],
+): record is Record<ApiErrorCodes, Record<string, string | number>> {
+  return Object.values(record).every(
+    (innerRecord) =>
+      !Array.isArray(innerRecord) &&
+      typeof innerRecord === 'object' &&
+      innerRecord !== null &&
+      // oxlint-disable-next-line no-unsafe-argument
+      Object.values(innerRecord).every(
+        (value) => typeof value === 'string' || typeof value === 'number',
+      ),
+  );
+}
+
+export function isNestRecord(record: ApiErrorMessage['messages']): record is NestRecordArrayType {
+  return Object.values(record).every(
+    (innerRecord) =>
+      !Array.isArray(innerRecord) &&
+      typeof innerRecord === 'object' &&
+      innerRecord !== null &&
+      // oxlint-disable-next-line no-unsafe-argument
+      Object.values(innerRecord).every((value) => Array.isArray(value)),
+  );
+}
+
+/**
+ * Retrieves the enhanced API error message from the message key.
+ */
+export function getEnhancedApiErrorMessage(
+  rawMessage: string,
+  apiErrorCode: ApiErrorCodes,
+): string {
+  const regex = /\(errors\s*=\s*(\{.*\})\)/;
+  const isLegacyJsonMatch = regex.test(rawMessage);
+
+  if (isLegacyJsonMatch) {
+    return `Erreur inconnue : ${apiErrorCode}`;
+  }
+  return rawMessage;
+}

