+import type { ModulePathInvalidLabelingMetadata } from '@/api/errors/types';
+import { useFeatureFlag } from '@/hooks/useFeatureFlag';
+import Messages from '@/components/presentational/common/Messages/Messages';
+
+interface ModulePathStatusWarningProps {
+  warnings: ModulePathInvalidLabelingMetadata[];
+}
+
+export function ModulePathStatusWarning({ warnings }: Readonly<ModulePathStatusWarningProps>) {
+  const { enabled: isStatusUpdateWarningsEnabled } = useFeatureFlag(
+    'modulepath:status:typed-warnings',
+  );
+
+  if (!isStatusUpdateWarningsEnabled || warnings.length === 0) {
+    return null;
+  }
+
+  return (
+    <Messages
+      type="warning"
+      content={
+        <div className="ModulePath__invalidContentDisclaimer">
+          Attention, ce parcours module ne respecte pas les conditions de labellisation :
+          <ul>
+            {warnings.map((warning) => {
+              return <li key={warning.code}>{warning.message}</li>;
+            })}
+          </ul>
+        </div>
+      }
+      scrollIntoView={false}
+    />
+  );
+}

