+    await renderWithQuery(<MassiveUploadForm {...defaultProps} />);
+
+    await expect.element(page.getByText('Poids maximal autorisé : 10 Mo')).toBeInTheDocument();
+    await expect
+      .element(page.getByRole('combobox', { name: 'Type de document' }))
+      .toBeInTheDocument();
+    await expect.element(page.getByRole('combobox', { name: /apprenants/i })).toBeInTheDocument();
+    await expect.element(page.getByLabelText('Nom du fichier à importer')).toBeInTheDocument();
+    await expect.element(page.getByLabelText('Importer un fichier')).toBeInTheDocument();
+    await expect
+      .element(page.getByRole('button', { name: 'Téléverser le document' }))
+      .toBeInTheDocument();
+  });
