+    await expect
+      .element(
+        page.getByRole('combobox', {
+          name: /apprenants/i,
+        }),
+      )
+      .toBeEnabled();
+
+    await expect.element(page.getByText(/gingembre grace/i)).toBeInTheDocument();
+    await expect.element(page.getByText(/akre annick mireille/i)).toBeInTheDocument();
+    await expect.element(page.getByText(/camillas karima/i)).toBeInTheDocument();
+    await expect.element(page.getByText(/koita shuei/i)).toBeInTheDocument();
+
+    await expect
+      .element(
+        page.getByRole('button', {
+          name: /supprimer gingembre grace/i,
+        }),
+      )
+      .toBeInTheDocument();
+    await expect
+      .element(
+        page.getByRole('button', {
+          name: /supprimer akre annick mireille/i,
+        }),
+      )
+      .toBeInTheDocument();
