+import type { ModulePathDTO } from '@/model/ModulePathDTO';
+import { ROUTES } from '@/constants/routes';
+import { PathStatusLabel } from '@/model/PathStatusEnum';
+import { Link } from '@/components/ui/link/Link';
+import InfosBlock from '../common/InfosBlock/InfosBlock';
+
+interface ModulePathBlocInfosProps {
+  content: ModulePathDTO;
+}
+
+export function ModulePathBlocInfos({ content }: Readonly<ModulePathBlocInfosProps>) {
+  const blocsPart = (content.blocPaths ?? []).map((currentBlocPath) => {
+    const blocPathStatus = currentBlocPath?.status || '';
+
+    const blocRow = (
+      <div>
+        <Link
+          to={`${ROUTES.blocPath.path}/${currentBlocPath.id}`}
+          className="ModulePath__bloc"
+          title="Voir le parcours bloc"
+        >
+          {`PB n°${currentBlocPath?.code || ''} - [${currentBlocPath?.bloc?.code || ''}] ${currentBlocPath?.bloc?.description || ''}`}
+        </Link>
+        {blocPathStatus ? ` - ${PathStatusLabel[blocPathStatus]}` : ''}
+      </div>
+    );
+
+    return ['', blocRow];
+  });
+
+  return (
+    <div className="CardInfoBlocks__row">
+      <InfosBlock
+        title="Parcours Bloc"
+        colNumber={1}
+        dataSets={blocsPart}
+      />
+    </div>
+  );
+}

