+import { isAfter } from 'date-fns/isAfter';
+import { isBefore } from 'date-fns/isBefore';
+import { parseISO } from 'date-fns/parseISO';
+
+import type { ModulePathDTO } from '@/model/ModulePathDTO';
+import type { ModulePathTrainerState } from './types';
+import { TRAINER_STATUS_ICON, TRAINER_STATUS_LABEL } from './constants';
+import { Link } from '@/components/ui/link/Link';
+import { ROUTES } from '@/constants/routes';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+import InfosBlock from '../common/InfosBlock/InfosBlock';
+
+interface ModulePathTrainerStatusProps {
+  content: ModulePathDTO;
+  canUpdateTrainerStatus: boolean;
+  toggleShowModalTrainerStatus: (currentTrainer: ModulePathTrainerState | null) => void;
+}
+
+export function ModulePathTrainerStatus({
+  content,
+  canUpdateTrainerStatus,
+  toggleShowModalTrainerStatus,
+}: Readonly<ModulePathTrainerStatusProps>) {
+  const trainers = (content.trainers ?? []).map((currentTrainer) => {
+    const status = currentTrainer.trainerStatus.status;
+    const trainerName = `${currentTrainer.physicalPersonDto.firstName} ${currentTrainer.physicalPersonDto.lastName}`;
+    const trainerStatusStartDate = currentTrainer.trainerStatus.startDate || '';
+    const trainerStatusEndDate = currentTrainer.trainerStatus.endDate || '';
+
+    const modulePathStartDate = content.startDate;
+    const modulePathEndDate = content.endDate;
+
+    let statusIconName = TRAINER_STATUS_ICON[status];
+    let statusLabel = TRAINER_STATUS_LABEL[status];
+
+    function startAfterModulePathStartDate() {
+      return isAfter(parseISO(trainerStatusStartDate), parseISO(modulePathStartDate));
+    }
+
+    function endBeforeModulePathEndDate() {
+      return isBefore(parseISO(trainerStatusEndDate), parseISO(modulePathEndDate));
+    }
+
+    if (
+      (trainerStatusStartDate && !trainerStatusEndDate && startAfterModulePathStartDate()) ||
+      (trainerStatusEndDate && !trainerStatusStartDate && endBeforeModulePathEndDate()) ||
+      (trainerStatusStartDate &&
+        trainerStatusEndDate &&
+        (startAfterModulePathStartDate() || endBeforeModulePathEndDate()))
+    ) {
+      statusIconName = TRAINER_STATUS_ICON['REJECTED'];
+      statusLabel = TRAINER_STATUS_LABEL['REJECTED'];
+    }
+
+    const trainerRow = (
+      <span
+        className="ModulePath__trainer"
+        key={currentTrainer.id}
+      >
+        {canUpdateTrainerStatus ? (
+          <button
+            type="button"
+            className="ModulePath__trainer__status"
+            onClick={() =>
+              toggleShowModalTrainerStatus({
+                id: currentTrainer.id,
+                status: currentTrainer.trainerStatus.status,
+                startDate: currentTrainer.trainerStatus.startDate || null,
+                endDate: currentTrainer.trainerStatus.endDate || null,
+                moduleId: content.module.id,
+              })
+            }
+            aria-label={`Modifier le statut du formateur ${trainerName}`}
+            title={`Modifier le statut du formateur ${trainerName}`}
+          >
+            <SvgIcon
+              name={statusIconName}
+              size={20}
+            />
+            {statusLabel}
+          </button>
+        ) : (
+          <span className="ModulePath__trainer__statusLabel">
+            <SvgIcon
+              name={statusIconName}
+              size={20}
+            />
+            <span>{statusLabel}</span>
+          </span>
+        )}
+
+        <span className="ModulePath__trainer__name">
+          <Link
+            to={`${ROUTES.trainer.path}/${currentTrainer.id}/modules`}
+            className="TableView__cell__link"
+            title="Voir le formateur"
+          >
+            {trainerName}
+          </Link>
+        </span>
+      </span>
+    );
+
+    return ['', trainerRow];
+  });
+
+  return (
+    <InfosBlock
+      title="Formateur(s)"
+      colNumber={1}
+      dataSets={trainers}
+    />
+  );
+}

