+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+
+import type { ModulePathTrainerState } from '../ModulePath/types';
+import {
+  updateModuleTrainerFormSchema,
+  type UpdateModuleTrainerFormData,
+} from './updateModuleTrainerFormSchema';
+import { getInputSelectOptions } from '@/helpers/utils/enumUtils';
+import { TRAINER_STATUS_LABEL } from '../ModulePath/constants';
+import InputSelectV2 from '../common/InputSelect/InputSelectV2';
+import InputDateV2 from '../common/InputDate/InputDateV2';
+import Messages from '../common/Messages/Messages';
+import Button from '@/components/presentational/common/Button/Button';
+import ButtonGroup from '@/components/presentational/common/ButtonGroup/ButtonGroup';
+import { useUpdateModulesTrainer } from '@/hooks/data/trainer/useUpdateModulesTrainer';
+
+import './UpdateModuleTrainerForm.scss';
+
+interface UpdateModuleTrainerFormProps {
+  trainer: ModulePathTrainerState | null;
+  onSubmitSuccess: () => void;
+}
+
+export function UpdateModuleTrainerForm({
+  trainer,
+  onSubmitSuccess,
+}: Readonly<UpdateModuleTrainerFormProps>) {
+  const { control, handleSubmit } = useForm({
+    resolver: zodResolver(updateModuleTrainerFormSchema),
+    defaultValues: {
+      status: trainer?.status ?? 'SUGGESTED',
+      startDate: trainer?.startDate ?? '',
+      endDate: trainer?.endDate ?? '',
+    } satisfies UpdateModuleTrainerFormData,
+  });
+
+  const {
+    isPending,
+    error: updateModuleTrainerError,
+    mutate: updateModuleTrainer,
+  } = useUpdateModulesTrainer({
+    onSuccess: onSubmitSuccess,
+  });
+
+  function updateModuleTrainerHandler(values: UpdateModuleTrainerFormData) {
+    if (!trainer) {
+      return;
+    }
+
+    updateModuleTrainer({
+      trainerId: trainer.id,
+      moduleId: trainer.moduleId,
+      status: values.status,
+      startDate: values.startDate || null,
+      endDate: values.endDate || null,
+    });
+  }
+
+  return (
+    <form
+      className="UpdateModuleTrainerForm"
+      onSubmit={handleSubmit(updateModuleTrainerHandler)}
+      noValidate
+    >
+      {updateModuleTrainerError && (
+        <Messages
+          type="error"
+          content={updateModuleTrainerError}
+          scrollIntoView={false}
+        />
+      )}
+
+      <div className="UpdateModuleTrainerForm__row">
+        <InputSelectV2
+          control={control}
+          name="status"
+          label="Statut"
+          options={getInputSelectOptions(TRAINER_STATUS_LABEL)}
+        />
+
+        <InputDateV2
+          control={control}
+          name="startDate"
+          label="Début de validité"
+          forMoment
+        />
+        <InputDateV2
+          control={control}
+          name="endDate"
+          label="Fin de validité"
+          forMoment
+        />
+      </div>
+
+      <ButtonGroup>
+        <Button
+          type="submit"
+          customClassName="UpdateModuleTrainerForm__btn"
+          appearance="orange-inverted"
+          loading={isPending}
+        >
+          <Button.Text>Modifier</Button.Text>
+        </Button>
+      </ButtonGroup>
+    </form>
+  );
+}

