+import { z } from 'zod';
+import { isBefore } from 'date-fns/isBefore';
+
+import { TRAINER_STATUS } from '@/model/TrainerStatusValue';
+import { FORM_ERROR_MESSAGES } from '@/constants/formErrorMessages';
+
+export type UpdateModuleTrainerFormData = z.infer<typeof updateModuleTrainerFormSchema>;
+
+export const updateModuleTrainerFormSchema = z
+  .object({
+    status: z.enum(TRAINER_STATUS, {
+      error: FORM_ERROR_MESSAGES.module.statusRequired,
+    }),
+    startDate: z.string().optional().nullable(),
+    endDate: z.string().optional().nullable(),
+  })
+  .refine(
+    (value) => {
+      if (value.startDate && value.endDate) {
+        return isBefore(value.startDate, value.endDate);
+      }
+      return true;
+    },
+    {
+      path: ['endDate'],
+      message: FORM_ERROR_MESSAGES.date.endDateBeforeStartDate,
+    },
+  );

