+import { useMutation } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { TrainerStatusValue } from '@/model/TrainerStatusValue';
+import type { UseMutationCallbacks } from '@/api/http/types';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import endpoints from '@/constants/api-endpoints';
+import { fetcher } from '@/api/http/fetcher';
+import { HttpVerb } from '@/api/http/httpVerb';
+
+type TrainerModuleInput = {
+  moduleId: string;
+  status: TrainerStatusValue;
+  startDate: string | null;
+  endDate: string | null;
+};
+
+interface UpdateModuleTrainerInput extends TrainerModuleInput {
+  trainerId: string;
+}
+
+export function useUpdateModulesTrainer({ onSuccess }: UseMutationCallbacks = {}) {
+  return useMutation<void, ApiErrors, UpdateModuleTrainerInput>({
+    mutationFn: ({ trainerId, ...trainerModuleInput }) => {
+      return fetcher({
+        endpoint: endpoints.trainerModules(trainerId),
+        method: HttpVerb.PUT,
+        params: {
+          body: trainerModuleInput,
+        },
+      });
+    },
+    onSuccess: () => {
+      toast.success('Statut du module modifié avec succès.');
+
+      if (onSuccess) {
+        onSuccess();
+      }
+    },
+  });
+}

