+import { describe, expect } from 'vitest';
+import { page } from 'vitest/browser';
+import { http, HttpResponse } from 'msw';
+
+import { renderWithQuery } from '@/test/browser-test-utils/renderWithQuery';
+import { testMsw } from '@/test/browser-test-utils/test-extend';
+import type { AuthenticatedUserDTO } from '@/model/AuthenticatedUserDTO';
+import { FundersList } from '../FundersList';
+import { RoleTypes } from '@/enums/authorization';
+import { ROUTES } from '@/constants/routes';
+import { createAuthenticatedUserQuery } from '@/test/browser-test-utils/queryData';
+import endpoints from '@/constants/api-endpoints';
+import { searchFunderDtoMock } from '@/mocks/funder/searchFunderDtoMock';
+
+function renderFundersList(userLogin?: Partial<AuthenticatedUserDTO>) {
+  return renderWithQuery(<FundersList />, {
+    pathname: ROUTES.fundersList.path,
+    initialEntries: [ROUTES.fundersList.path],
+    queryData: createAuthenticatedUserQuery({
+      roles: [RoleTypes.ADMIN],
+      ...userLogin,
+    }),
+  });
+}
+
+describe('FundersList', () => {
+  testMsw('should render FundersList table', async ({ worker }) => {
+    worker.use(
+      http.post(endpoints.funders, () => {
+        return HttpResponse.json({ result: searchFunderDtoMock });
+      }),
+    );
+
+    await renderFundersList();
+
+    await expect.element(page.getByRole('columnheader', { name: 'N°' })).toBeInTheDocument();
+    await expect
+      .element(page.getByRole('columnheader', { name: 'Dénomination' }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByRole('columnheader', { name: 'Département' }))
+      .toBeInTheDocument();
+    await expect.element(page.getByRole('columnheader', { name: 'Région' })).toBeInTheDocument();
+
+    await expect
+      .element(page.getByRole('cell', { name: 'APNI Prestation Service', exact: true }))
+      .toBeInTheDocument();
+    await expect
+      .element(page.getByRole('cell', { name: 'Maxime Financier', exact: true }))
+      .toBeInTheDocument();
+  });
+
+  testMsw('should render create button when user has permission', async () => {
+    await renderFundersList();
+
+    const createBtn = page.getByRole('link', { name: 'Créer un financeur' });
+
+    await expect.element(createBtn).toBeInTheDocument();
+    await expect.element(createBtn).toHaveAttribute('href', '/ajout-financeur');
+  });
+
+  testMsw('should not render create button without permission', async () => {
+    await renderFundersList({ roles: [] });
+
+    await expect
+      .element(page.getByRole('link', { name: 'Créer un financeur' }))
+      .not.toBeInTheDocument();
+  });
+});

