+import { useState } from 'react';
+import { useLocation } from 'react-router';
+
+import type { SearchFunderDTO } from '@/model/FunderDTO';
+import type { FilterInput } from '@/model/FilterInput';
+import type { TableColumn } from '../common/TableView/TableView';
+import { ROUTES } from '@/constants/routes';
+import { DEPARTMENT_OPTIONS } from '@/constants/departments';
+import regions from '@/constants/regions';
+import List from '../common/List/List';
+import { InputType } from '@/model/InputTypeEnum';
+import { RoleTypes } from '@/enums/authorization';
+import { useListFunders } from '@/hooks/data/funders/useListFunders';
+import { useDeleteFunder } from '@/hooks/data/funders/useDeleteFunder';
+import { TableActionCell } from '@/components/ui/tableView/TableActionCell';
+import { Dialog } from '@/components/ui/dialog/Dialog';
