+import { usePermissionFromRole } from '@/hooks/usePermissionFromRole';
+
+import './_FundersList.scss';
+
+export function FundersList() {
+  const location = useLocation();
+
+  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
+  const [selectedFunder, setSelectedFunder] = useState<SearchFunderDTO | null>(null);
+
+  // ----- custom hooks -----
+
+  const canCreateFunder = usePermissionFromRole([
+    RoleTypes.ADMIN,
+    RoleTypes.SYSTEM,
+    RoleTypes.PL,
+    RoleTypes.SU_PL,
+  ]);
+
+  const hasDeletePermission = usePermissionFromRole([
+    RoleTypes.ADMIN,
+    RoleTypes.SYSTEM,
+    RoleTypes.SU_PL,
+  ]);
+
+  const {
+    loading: isFunderPending,
+    apiErrors: funderApiErrors,
+    totalElements,
+    invalidateQueries: invalidateFunderCache,
+    ...listProps
+  } = useListFunders();
+
+  const {
+    isPending: isDeleteFunderPending,
+    mutate: deleteFunder,
+    error: deleteFunderError,
+  } = useDeleteFunder({
+    onSuccess: () => {
+      setIsDeleteDialogOpen(false);
+      void invalidateFunderCache();
+    },
+  });
+
+  // ----- handlers -----
+
+  function deleteFunderHandler() {
+    if (selectedFunder) {
+      deleteFunder({ funderId: selectedFunder.funderId });
+    }
+  }
+
+  const selectedFunderName = selectedFunder?.legalPersonDto.name ?? '';
+  const isFunderListPath = location.pathname === ROUTES.fundersList.path;
+
+  // The legacy research tab list does not render the delete action.
+  // Keep the same behavior here.
+  const canDeleteFunder = isFunderListPath && hasDeletePermission;
+
+  const tableColumns: TableColumn<SearchFunderDTO>[] = [
+    {
+      name: 'N°',
+      sortKey: 'code',
+      contentKey: 'legalPersonDto.code',
+    },
+    {
+      name: 'Dénomination',
+      sortKey: 'name',
+      contentKey: 'legalPersonDto.name',
+    },
+    {
+      name: 'Département',
+      sortKey: 'address',
+      cellRenderer: (data) => {
+        const department = data.legalPersonDto?.addresses?.at(0)?.department;
+
+        if (!department) {
+          return '-';
+        }
+        return `${department.code} - ${department.value}`;
+      },
+      isSortable: false,
+    },
+    {
+      name: 'Région',
+      sortKey: 'addresses.zipCode',
+      contentKey: 'legalPersonDto.addresses[0].region.value',
+    },
+    {
+      name: '',
+      sortKey: 'link',
+      cellRenderer: (data) => {
+        return (
+          <TableActionCell
+            editTitle="Voir le financeur"
+            editTo={`${ROUTES.funder.path}/${data.funderId}`}
+            canDelete={canDeleteFunder}
+            deleteTitle={`Supprimer le financeur ${data.legalPersonDto.name}`}
+            onDelete={() => {
+              setSelectedFunder(data);
+              setIsDeleteDialogOpen(true);
+            }}
+          />
+        );
+      },
+      isSortable: false,
+    },
+  ];
+
+  const filterInputs: FilterInput[] = [
+    {
+      type: InputType.NUMBER,
+      label: 'N°',
+      name: 'code',
+      settings: {
+        decimalScale: 0,
+        allowNegative: false,
+      },
+    },
+    { type: InputType.TEXT, label: 'Nom', name: 'name' },
+    { type: InputType.TEXT, label: 'Ville', name: 'city' },
+    { type: InputType.TEXT, label: 'Code postal', name: 'zipCode' },
+    {
+      type: InputType.MULTI_SELECT,
+      label: 'Départements',
+      name: 'departments',
+      options: DEPARTMENT_OPTIONS,
+      simpleValue: true,
+    },
+    {
+      type: InputType.MULTI_SELECT,
+      label: 'Régions',
+      name: 'regions',
+      options: regions,
+      simpleValue: true,
+    },
+  ];
+
+  // ----- rendering -----
+
+  return (
+    <div className="FundersListContainer">
+      <div className="FundersList">
+        <List
+          {...listProps}
+          loading={isFunderPending}
+          apiErrors={funderApiErrors || deleteFunderError}
+          headerContent={isFunderListPath ? `Financeurs (${totalElements})` : ''}
+          CSSScope="FundersList"
+          sortingScope="legalPerson"
+          tableColumns={tableColumns}
+          filterInputs={isFunderListPath ? filterInputs : []}
+          createBtnTitle={canCreateFunder ? 'Créer un financeur' : null}
+          createBtnLink={ROUTES.funderAdd.path}
+        />
+      </div>
+
+      <Dialog
+        open={isDeleteDialogOpen}
+        onOpenChange={setIsDeleteDialogOpen}
+        title="Confirmer la suppression du financeur"
+      >
+        <YesOrNoConfirmationModal
+          textMessage={`Voulez-vous supprimer le financeur ${selectedFunderName} ?`}
+          isPending={isDeleteFunderPending}
+          actionConfirmationHandler={deleteFunderHandler}
+        />
+      </Dialog>
+    </div>
+  );
+}

