+import { useMutation } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { UseMutationCallbacks } from '@/api/http/types';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import endpoints from '@/constants/api-endpoints';
+import { fetcher } from '@/api/http/fetcher';
+import { HttpVerb } from '@/api/http/httpVerb';
+
+type DeleteParams = {
+  funderId: string;
+};
+
+export function useDeleteFunder({ onSuccess }: UseMutationCallbacks) {
+  return useMutation<void, ApiErrors, DeleteParams>({
+    mutationFn: ({ funderId }) => {
+      return fetcher({
+        endpoint: endpoints.funderDelete(funderId),
+        method: HttpVerb.PUT,
+      });
+    },
+    onSuccess: () => {
+      toast.success('Financeur supprimé avec succès.');
+
+      if (onSuccess) {
+        onSuccess();
+      }
+    },
+  });
+}

