+import { useQuery } from '@tanstack/react-query';
+
+import type { FunderDTO } from '@/model/FunderDTO';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import endpoints from '@/constants/api-endpoints';
+import { QUERY_KEYS } from '@/api/queryClient/queryKeys';
+import { fetcher } from '@/api/http/fetcher';
+import { HttpVerb } from '@/api/http/httpVerb';
+
+export function useGetFunder(funderId: string | undefined) {
+  return useQuery<FunderDTO, ApiErrors>({
+    queryKey: QUERY_KEYS.funder(funderId as string),
+    queryFn: ({ signal }) => {
+      return fetcher({
+        endpoint: endpoints.funder(funderId as string),
+        method: HttpVerb.GET,
+        signal,
+      });
+    },
+    enabled: !!funderId,
+  });
+}

