+import { useState } from 'react';
+
+import type { ModulePathDTO } from '@/model/ModulePathDTO';
+import { Dialog } from '@/components/ui/dialog/Dialog';
+import { SvgIcon } from '@/components/ui/svg/SvgIcon';
+import { RoleTypes } from '@/enums/authorization';
+import { usePermissionFromRole } from '@/hooks/usePermissionFromRole';
+import { AssociateModuleOfForm } from '../../AssociateModuleOfForm/AssociateModuleOfForm';
+import { MODULE_STATUS_ICON, TRAINER_STATUS_LABEL } from '../constants';
+
+import './ModulePathTitleStatus.scss';
+
+interface ModulePathTitleStatusProps {
+  canUpdateModule: boolean;
+  content: ModulePathDTO | undefined;
+  onSubmitSuccess: () => void;
+}
+
+export function ModulePathTitleStatus({
+  canUpdateModule,
+  content,
+  onSubmitSuccess,
+}: Readonly<ModulePathTitleStatusProps>) {
+  const [isDialogOpen, setIsDialogOpen] = useState(false);
+
+  const allowEdit = usePermissionFromRole([
+    RoleTypes.ADMIN,
+    RoleTypes.SU_UDD,
+    RoleTypes.FINANCEMENT,
+    RoleTypes.SYSTEM,
+  ]);
+
+  const moduleStatus = content?.module?.status ?? 'SUGGESTED';
+  const moduleStatusLabel = TRAINER_STATUS_LABEL[moduleStatus];
+
+  if (!content?.module) {
+    return null;
+  }
+
+  if (!canUpdateModule) {
+    return (
+      <span className="ModulePathTitleStatus__status">
+        <SvgIcon name={MODULE_STATUS_ICON[moduleStatus]} />
+        <span className="a11y-hidden">{moduleStatusLabel}</span>
+      </span>
+    );
+  }
+
+  const actionLabel = `Modifier le module associé (statut : ${moduleStatusLabel})`;
+
+  return (
+    <>
+      <button
+        type="button"
+        className="ModulePathTitleStatus__button"
+        onClick={() => {
+          setIsDialogOpen(true);
+        }}
+        aria-label={actionLabel}
+        title={actionLabel}
+        aria-haspopup="dialog"
+        aria-expanded={isDialogOpen}
+      >
+        <SvgIcon name={MODULE_STATUS_ICON[moduleStatus]} />
+      </button>
+
+      <Dialog
+        open={isDialogOpen}
+        onOpenChange={setIsDialogOpen}
+        title="Modifier le module associé"
+      >
+        <AssociateModuleOfForm
+          module={content.module}
+          trainingAgencyId={content.trainingAgency.trainingAgencyId}
+          onSubmitSuccess={() => {
+            setIsDialogOpen(false);
+            onSubmitSuccess();
+          }}
+          allowEdit={allowEdit}
+          disableModule
+        />
+      </Dialog>
+    </>
+  );
+}

