+type TrainingAgencyModuleInput = {
+  moduleId: string;
+  status: TrainerStatusValue;
+  nbrFinancingRequest: number | null;
+  startDate?: string | null;
+  endDate?: string | null;
+};
+
+interface AssociateModuleInput extends TrainingAgencyModuleInput {
+  trainingAgencyId: string;
+}
+
+export function useAssociateModuleTrainingAgency({ onSuccess }: UseMutationCallbacks = {}) {
+  return useMutation<void, ApiErrors, AssociateModuleInput>({
+    mutationFn: ({ trainingAgencyId, ...moduleInput }) => {
+      return fetcher({
+        endpoint: endpoints.trainingAgenciesModules(trainingAgencyId),
+        method: HttpVerb.PUT,
+        params: {
+          body: moduleInput,
+        },
+      });
+    },
+    onSuccess: () => {
+      toast.success('Module associé avec succès.');
+
+      if (onSuccess) {
+        onSuccess();
+      }
+    },
+  });
+}

