+import DocumentViewer from '../DocumentViewer';
+
+const NO_PREVIEW = "Aucune prévisualisation n'est disponible pour ce document.";
+const ZOOM_IN = 'Agrandir';
+const ZOOM_OUT = 'Réduire';
+const ROTATE = 'Pivoter';
+const NEXT_PAGE = 'Page suivante';
+const PREVIOUS_PAGE = 'Page précédente';
+const DOWNLOAD = 'Télécharger le fichier';
+const PDF_ERROR = 'Impossible de charger le PDF.';
+
+describe('<DocumentViewer />', () => {
+  test('should display actions and render the document for PDF', async () => {
+    await render(
+      <DocumentViewer
+        documentName="test.pdf"
+        documentUrl="/test.pdf"
+        file={new File([pdfSampleMock()], 'test.pdf', { type: 'application/pdf' })}
+      />,
+    );
+
+    await expect.element(page.getByText(PDF_SAMPLE_TEXT)).toBeVisible();
+
+    await expect
+      .element(page.getByRole('heading', { name: 'test.pdf - Pages : 1/1' }))
+      .toBeVisible();
+    await expect.element(page.getByTitle(ZOOM_IN)).toBeVisible();
+    await expect.element(page.getByTitle(ZOOM_OUT)).toBeVisible();
+    await expect.element(page.getByTitle(ROTATE)).toBeVisible();
+    await expect.element(page.getByTitle(NEXT_PAGE)).toBeVisible();
+    await expect.element(page.getByTitle(PREVIOUS_PAGE)).toBeVisible();
+    await expect.element(page.getByText(NO_PREVIEW)).not.toBeInTheDocument();
+    await expect
+      .element(page.getByRole('link', { name: DOWNLOAD }))
+      .toHaveAttribute('href', '/test.pdf');
+  });
+
+  test('should display the error boundary fallback when the PDF is invalid', async () => {
+    await render(
+      <DocumentViewer
+        documentName="test.pdf"
+        documentUrl="/test.pdf"
+        file={new File(['not a pdf'], 'test.pdf', { type: 'application/pdf' })}
+      />,
+    );
+
+    await expect.element(page.getByText(PDF_ERROR)).toBeVisible();
+
+    await expect.element(page.getByText(PDF_SAMPLE_TEXT)).not.toBeInTheDocument();
+    await expect
+      .element(page.getByRole('heading', { name: 'test.pdf - Pages : 1/1' }))
+      .toBeVisible();
+    await expect
+      .element(page.getByRole('link', { name: DOWNLOAD }))
+      .toHaveAttribute('href', '/test.pdf');
+  });
+
+  test('should display actions and render the document for images', async () => {
+    await render(
+      <DocumentViewer
+        documentName="test.png"
+        documentUrl="/test.png"
+        file={new File(['foo'], 'test.png', { type: 'image/png' })}
+      />,
+    );
+
+    await expect.element(page.getByRole('heading', { name: 'test.png' })).toBeVisible();
+    await expect.element(page.getByTitle(ZOOM_IN)).toBeVisible();
+    await expect.element(page.getByTitle(ZOOM_OUT)).toBeVisible();
+    await expect.element(page.getByTitle(ROTATE)).toBeVisible();
+    await expect.element(page.getByTitle(NEXT_PAGE)).not.toBeInTheDocument();
+    await expect.element(page.getByTitle(PREVIOUS_PAGE)).not.toBeInTheDocument();
+    await expect.element(page.getByText(NO_PREVIEW)).not.toBeInTheDocument();
+    await expect
+      .element(page.getByRole('link', { name: DOWNLOAD }))
+      .toHaveAttribute('href', '/test.png');
+  });
+
+  test('should only display the download action for unsupported documents', async () => {
+    await render(
+      <DocumentViewer
+        documentName="test.docx"
+        documentUrl="/test.docx"
+        file={
+          new File(['foo'], 'test.docx', {
+            type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
+          })
+        }
+      />,
+    );
+
+    await expect.element(page.getByText(NO_PREVIEW)).toBeVisible();
+
+    await expect.element(page.getByRole('heading', { name: 'test.docx' })).toBeVisible();
+    await expect.element(page.getByTitle(ZOOM_IN)).not.toBeInTheDocument();
+    await expect.element(page.getByTitle(ZOOM_OUT)).not.toBeInTheDocument();
+    await expect.element(page.getByTitle(ROTATE)).not.toBeInTheDocument();
+    await expect.element(page.getByTitle(NEXT_PAGE)).not.toBeInTheDocument();
+    await expect.element(page.getByTitle(PREVIOUS_PAGE)).not.toBeInTheDocument();
+    await expect
+      .element(page.getByRole('link', { name: DOWNLOAD }))
+      .toHaveAttribute('href', '/test.docx');
+  });
+
+  test('should render RestrictedViewer when isRestrictedAccess is true', async () => {
+    await render(
+      <DocumentViewer
+        documentName="test.pdf"
+        documentUrl="/test.pdf"
+        file={new File([pdfSampleMock()], 'test.pdf', { type: 'application/pdf' })}
+        isRestrictedAccess
+      />,
+    );
+
+    await expect.element(page.getByRole('heading', { name: 'test.pdf' })).toBeVisible();
+    await expect
+      .element(
+        page.getByText(
+          'Vous ne disposez pas des permissions suffisantes pour visionner ce document.',
+        ),
+      )
+      .toBeVisible();
+    await expect.element(page.getByRole('link', { name: DOWNLOAD })).not.toBeInTheDocument();
+  });
+});

