+import { Component } from 'react';
+
+type PdfErrorBoundaryProps = {
+  children: React.ReactNode;
+  fallback: React.ReactNode;
+};
+
+type PdfErrorBoundaryState = {
+  hasError: boolean;
+};
+
+/**
+ * React only exposes error-catching via class lifecycle methods (no hook equivalent),
+ * so this must remain a class component.
+ */
+export class PdfErrorBoundary extends Component<PdfErrorBoundaryProps, PdfErrorBoundaryState> {
+  state: PdfErrorBoundaryState = { hasError: false };
+
+  static getDerivedStateFromError(): PdfErrorBoundaryState {
+    return { hasError: true };
+  }
+
+  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
+    // oxlint-disable-next-line no-console
+    console.error('Erreur lors du chargement du PDF:', error, errorInfo);
+  }
+
+  render() {
+    if (this.state.hasError) {
+      return this.props.fallback;
+    }
+
+    return this.props.children;
+  }
+}

