+import { NumericFormat, type NumericFormatProps } from 'react-number-format';
+
+export const UNIT_SEPARATOR = '\u00A0';
+
+export type NumberTextProps = Omit<
+  NumericFormatProps,
+  'displayType' | 'suffix' | 'customInput' | 'getInputRef' | 'onValueChange' | 'isAllowed' | 'value'
+> & {
+  /**
+   * Same type as the lib's `value` but mandatory: it must be passed explicitly.
+   */
+  value: number | string | null | undefined;
+  unit?: string;
+};
+
+/**
+ * Display-only formatting of a number. `displayType` is locked to `text`:
+ * for form integration use `InputNumberV2`.
+ */
+export function NumberText({ unit, value, ...rest }: Readonly<NumberTextProps>) {
+  return (
+    <NumericFormat
+      displayType="text"
+      thousandSeparator=" "
+      decimalScale={2}
+      suffix={unit ? `${UNIT_SEPARATOR}${unit}` : undefined}
+      value={value}
+      {...rest}
+    />
+  );
+}

