+import { describe, test, expect } from 'vitest';
+import { http, HttpResponse } from 'msw';
+import type { UnknownAction } from '@reduxjs/toolkit';
+
+import { getCallAPIAction } from '../http';
+import { server } from '@/msw/node/setup';
+import { setupStore } from '@/test/test-utils/testSetupStore';
+import { HttpVerb } from '@/api/http/httpVerb';
+import type { AppStore } from '@/redux/store';
+import type { CallAPIActionPayload } from '@/helpers/reduxCustomTypes';
+
+/**
+ * Non-regression harness for the `getCallAPIAction` facade, written against the
+ * implementation it replaced. Every assertion targets the observable contract
+ * (dispatched actions, resolved value, outgoing request) so this file stays untouched
+ * when the engine behind the facade changes.
+ */
+
+type RecordedAction = {
+  type: string;
+  payload?: unknown;
+  meta?: unknown;
+  error?: boolean;
+};
+
+/** Shape the legacy reducers actually read from an error action payload. */
+type LegacyErrorPayload = {
+  status?: number;
+  response?: unknown;
+  message?: string;
+};
+
+const ENDPOINT = 'https://iperia-dev.yoda.net/legacy-api-contract';
+
+const REQUEST = 'CONTRACT_REQUEST';
+const SUCCESS = 'CONTRACT_REQUEST_SUCCESS';
+const ERROR = 'CONTRACT_REQUEST_ERROR';
+
+// oxlint-disable-next-line default-param-last
+function actionRecorderReducer(state: RecordedAction[] = [], action: UnknownAction) {
+  return [...state, action as RecordedAction];
+}
+
+function setupContractStore() {
+  return setupStore(undefined, {
+    useReduxApiMiddleware: true,
+    reducers: { costs: actionRecorderReducer },
+  });
+}
+
+function getRecordedActions(store: AppStore, type?: string) {
+  const actions = store.getState().costs as unknown as RecordedAction[];
+
+  return actions.filter((action) =>
+    type ? action.type === type : action.type.startsWith('CONTRACT_'),
+  );
+}
+
+function getRecordedTypes(store: AppStore) {
+  return getRecordedActions(store).map((action) => action.type);
+}
+
+describe('getCallAPIAction', () => {
+  describe('success flow', () => {
+    test('dispatches the request then the success action and resolves with the success action', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      expect(getRecordedTypes(store)).toEqual([REQUEST, SUCCESS]);
+      expect(result).toEqual({ type: SUCCESS, payload: { result: { id: '42' } } });
+    });
+
+    test('dispatches the request action synchronously', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      const pendingCall = store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      expect(getRecordedTypes(store)).toEqual([REQUEST]);
+
+      // Assert the request action is emitted before the promise resolves, then let the request finish.
+      await pendingCall;
+    });
+
+    test('removes nil values from a GET payload', async () => {
+      server.use(
+        http.get(ENDPOINT, () =>
+          HttpResponse.json({ result: { id: '42', label: null, nested: { keep: 1, drop: null } } }),
+        ),
+      );
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toEqual({ result: { id: '42', nested: { keep: 1 } } });
+    });
+
+    test('keeps nil values on a POST payload', async () => {
+      server.use(
+        http.post(ENDPOINT, () => HttpResponse.json({ result: { id: '42', label: null } })),
+      );
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.POST, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toEqual({ result: { id: '42', label: null } });
+    });
+
+    test('removes nil values on a POST when sanitizeNil is enabled', async () => {
+      server.use(
+        http.post(ENDPOINT, () => HttpResponse.json({ result: { id: '42', label: null } })),
+      );
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.POST, [REQUEST, SUCCESS, ERROR], undefined, true),
+      );
+
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toEqual({ result: { id: '42' } });
+    });
+
+    test('resolves with an undefined payload on a 204 response', async () => {
+      server.use(http.delete(ENDPOINT, () => new HttpResponse(null, { status: 204 })));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.DELETE, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      expect(getRecordedTypes(store)).toEqual([REQUEST, SUCCESS]);
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toBeUndefined();
+    });
+
+    test('resolves with an undefined payload when the response is not JSON', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.text('plain text')));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      expect(getRecordedTypes(store)).toEqual([REQUEST, SUCCESS]);
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toBeUndefined();
+    });
+
+    test('passes a static meta through to the success action', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [
+          REQUEST,
+          { type: SUCCESS, meta: { token: 'a-token' } },
+          ERROR,
+        ]),
+      );
+
+      expect(getRecordedActions(store, SUCCESS)[0]!.meta).toEqual({ token: 'a-token' });
+    });
+
+    test('resolves a meta function against the state left by the request action', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.GET, [
+          REQUEST,
+          {
+            type: SUCCESS,
+            meta: (_, state) => {
+              const recordedActions = state.costs as unknown as RecordedAction[];
+
+              return { searchText: recordedActions.at(-1)?.type ?? '' };
+            },
+          },
+          ERROR,
+        ]),
+      );
+
+      expect(getRecordedActions(store, SUCCESS)[0]!.meta).toEqual({ searchText: REQUEST });
+    });
+
+    test('lets a static descriptor payload override the parsed response', async () => {
+      server.use(http.put(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.PUT, [
+          REQUEST,
+          { type: SUCCESS, payload: { success: true } as unknown as CallAPIActionPayload },
+          ERROR,
+        ]),
+      );
+
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toEqual({ success: true });
+    });
+
+    test('gives a descriptor payload function access to the raw response', async () => {
+      server.use(http.post(ENDPOINT, () => HttpResponse.json({ result: { id: '42' } })));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.POST, [
+          REQUEST,
+          {
+            type: SUCCESS,
+            payload: async (_, __, response) => {
+              const data = (await response.json()) as { result: { id: string } };
+
+              return { id: data.result.id } as unknown as CallAPIActionPayload;
+            },
+          },
+          ERROR,
+        ]),
+      );
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.payload).toEqual({ id: '42' });
+    });
+  });
+
+  describe('error flow', () => {
+    test('dispatches the error action with the status and the parsed response', async () => {
+      const responseBody = { messages: { GENERIC_ERROR: ['boom'] } };
+      server.use(http.post(ENDPOINT, () => HttpResponse.json(responseBody, { status: 400 })));
+      const store = setupContractStore();
+
+      const result = await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.POST, [REQUEST, SUCCESS, ERROR]),
+      );
+
+      expect(getRecordedTypes(store)).toEqual([REQUEST, ERROR]);
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      expect(result.error).toBe(true);
+      // @ts-expect-error: CallAPIAction is not typed with the CallAPIActionDispatchResult interface
+      const payload = result.payload as LegacyErrorPayload;
+      expect(payload.status).toBe(400);
+      expect(payload.response).toEqual(responseBody);
+    });
+
+    test('keeps the error meta on the error action', async () => {
+      server.use(http.post(ENDPOINT, () => HttpResponse.json({ messages: {} }, { status: 500 })));
+      const store = setupContractStore();
+
+      await store.dispatch(
+        getCallAPIAction(ENDPOINT, HttpVerb.POST, [
+          REQUEST,
+          SUCCESS,
+          { type: ERROR, meta: { token: 'a-token' } },
+        ]),
+      );
+
+      expect(getRecordedActions(store, ERROR)[0]!.meta).toEqual({ token: 'a-token' });
+    });
+
+    test('dispatches the error action without a response on a network failure', async () => {
+      server.use(http.get(ENDPOINT, () => HttpResponse.error()));
