+function runApiCall(action: CallAPIAction, next: NextDispatch, getState: () => unknown) {
+  const call: LegacyApiCall = action[LEGACY_API_CALL];
+  const [requestDescriptor, successDescriptor, errorDescriptor] = call.types;
+
+  function getRootState() {
+    return getState() as RootState;
+  }
+
+  async function performCall() {
+    let response: Response;
+
+    try {
+      response = await fetch(call.endpoint, {
+        method: call.method,
+        body: call.body,
+        credentials: call.credentials,
+        headers: call.headers,
+      });
+    } catch (error) {
+      /* The request was malformed, or there was a network error. */
+      return next(
+        await resolveAction(
+          {
+            ...errorDescriptor,
+            payload: getErrorPayload('RequestError', error),
+            error: true,
+          },
+          [action, getRootState()],
+        ),
+      );
+    }
