+    if (response.ok) {
+      return next(await resolveAction(successDescriptor, [action, getRootState(), response]));
+    }
+
+    return next(
+      await resolveAction({ ...errorDescriptor, error: true }, [action, getRootState(), response]),
+    );
+  }
