+import type {
+  CallAPIAction,
+  LegacyApiCall,
+  LegacyApiErrorPayload,
+} from '@/helpers/reduxCustomTypes';
+import type { RootState } from '@/redux/store';
+
+type LegacyApiMiddlewareApi = {
+  getState: () => unknown;
+};
+type NextDispatch = (action: unknown) => unknown;
+
+/**
+ * Key carrying the API call description interpreted by `legacyApiMiddleware`.
+ *
+ * @note Implementation detail of `getCallAPIAction`: nothing outside the facade
+ * and this middleware should read or write it.
+ */
+export const LEGACY_API_CALL = '@@iperia/legacy-api-call';
+
+/**
+ * Runs the API calls described by actions created with `getCallAPIAction` and
+ * dispatches the request, success and error actions they declare.
+ *
+ * @deprecated Bridge kept for the legacy Redux data fetching. Use TanStack Query
+ * with `fetcher` for anything new.
+ */
+export function legacyApiMiddleware({ getState }: LegacyApiMiddlewareApi) {
+  return function wrapDispatch(next: NextDispatch) {
+    return function handleAction(action: unknown) {
+      if (!isLegacyApiAction(action)) {
+        return next(action);
+      }
+
+      return runApiCall(action, next, getState);
+    };
+  };
+}
+
+function isLegacyApiAction(action: unknown): action is CallAPIAction {
+  return typeof action === 'object' && action !== null && LEGACY_API_CALL in action;
