+import { useQueries, type UseQueryOptions } from '@tanstack/react-query';
+
+import type { AddressInput, PlaceDTO } from '@/model/AddressDTO';
+import type { TrainingMomentDTO } from '@/model/TrainingMomentDTO';
+import type { Directions } from '@/components/presentational/ItinerarySynthesis/types';
+import { uniqBy } from '@/helpers/utils/lodashHelpers';
+import { QUERY_KEYS } from '@/api/queryClient/queryKeys';
+import { fetchDirection } from './fetchHandlers/fetchDirection';
+import { STALE_TIME } from '@/api/queryClient/staleTime';
+
+const RETRY_LIMIT = 3;
+
+type GoogleMapsDirectionsResult = UseQueryOptions<google.maps.DirectionsResult, Error>[];
+
+interface UseItineraryDirectionsParams {
+  presentielMoments: TrainingMomentDTO[];
+  learnerAddress: AddressInput;
+  enabled: boolean;
+}
+
+export function useItineraryDirections({
+  presentielMoments,
+  learnerAddress,
+  enabled,
+}: UseItineraryDirectionsParams) {
+  const origin = learnerAddress.googlePlaceId
+    ? { placeId: learnerAddress.googlePlaceId }
+    : learnerAddress.label;
+
+  // Get unique places from the presentiel moments to avoid redundant requests.
+  const uniquePlaceMoments = uniqBy(
+    presentielMoments,
+    (presentielMoment) => presentielMoment.place?.placeId,
+  );
+
+  const queries = useQueries<GoogleMapsDirectionsResult>({
+    queries: uniquePlaceMoments.map((moment) => {
+      const placeId = moment.place?.placeId;
+      const destination = toDestination(moment.place);
+
+      return {
+        queryKey: [...QUERY_KEYS.googleDirections, origin, placeId ?? destination],
+        queryFn: () => {
+          return fetchDirection(origin, destination);
+        },
+        enabled,
+        staleTime: STALE_TIME.FOREVER,
+        retry: (failureCount, error) => {
+          return (
+            failureCount < RETRY_LIMIT &&
+            error instanceof google.maps.MapsNetworkError &&
+            error.code === window.google.maps.DirectionsStatus.OVER_QUERY_LIMIT
+          );
+        },
+        gcTime: STALE_TIME.THIRTY_MINUTES,
+      };
+    }),
+  });
+
+  const directions: Directions[] = uniquePlaceMoments.flatMap((moment, index) => {
+    const data = queries[index]?.data;
+
+    if (!data) {
+      return [];
+    }
+
+    return {
+      ...data,
+      placeId: moment.place?.placeId ?? '',
+      repetition:
+        presentielMoments.filter((item) => item.place?.placeId === moment.place?.placeId).length ||
+        1,
+    };
+  });
+
+  return {
+    directions,
+    isItineraryLoading: queries.some((query) => query.isLoading),
+    hasItineraryError: queries.some((query) => query.isError),
+  };
+}
+
+function toDestination(place: PlaceDTO | undefined): google.maps.Place | string {
+  return place?.googlePlaceId ? { placeId: place.googlePlaceId } : (place?.displayAddress ?? '');
+}

