+import { describe, test, expect, vi } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import type { SearchBillDTO } from '@/model/BillDTO';
+import type { BillCreditPermissions } from '../../types';
+import { BillActionsOverflowMenu } from '../BillActionsOverflowMenu';
+import { BILL_CREDIT_ACTION_LABEL } from '../../constants';
+
+const BILL_NUMBER = 'FACTURE-UDD-2026-001';
+const FILE_ID = 'file-123';
+
+const SUBMIT_TO_YOOZ_LABEL = 'Transmettre à la plateforme agréée';
+const DOWNLOAD_LABEL = 'Télécharger la facture';
+
+const NO_PERMISSIONS: BillCreditPermissions = {
+  PEDAGOGIC: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+  TRAINING_SUPERVISION: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+  ADMINISTRATIVE_CONTROL: { canGenerateCredit: false, canGenerateBillFromCredit: false },
+};
+
+const ALL_PERMISSIONS: BillCreditPermissions = {
+  PEDAGOGIC: { canGenerateCredit: true, canGenerateBillFromCredit: true },
+  TRAINING_SUPERVISION: { canGenerateCredit: true, canGenerateBillFromCredit: true },
+  ADMINISTRATIVE_CONTROL: { canGenerateCredit: true, canGenerateBillFromCredit: true },
+};
+
+function buildBill(overrides: Partial<SearchBillDTO> = {}): SearchBillDTO {
+  return {
+    billNumber: BILL_NUMBER,
+    childId: null,
+    childPreview: false,
+    invoiceCredit: false,
+    costTypes: ['PEDAGOGIC'],
+    file: { id: FILE_ID },
+    yoozSubmissionStatus: 'NOT_SUBMITTED',
+    ...overrides,
+  } as SearchBillDTO;
+}
+
+type RenderOptions = Partial<Parameters<typeof BillActionsOverflowMenu>[0]>;
+
+async function renderMenu(options: RenderOptions = {}) {
+  const props = {
+    data: buildBill(),
+    canSubmitToYooz: false,
+    billCreditPermissions: NO_PERMISSIONS,
+    getFileLink: vi.fn(),
+    onGenerateCredit: vi.fn(),
+    onGenerateBillFromCredit: vi.fn(),
+    onSubmitToYooz: vi.fn(),
+    ...options,
+  };
+
+  await render(<BillActionsOverflowMenu {...props} />);
+  await page.getByRole('button', { name: `Actions pour la facture ${BILL_NUMBER}` }).click();
+
+  return props;
+}
+
+function getMenuItem(name: string) {
+  return page.getByRole('menuitem', { name });
+}
+
+describe('<BillActionsOverflowMenu />', () => {
+  describe('Yooz submission', () => {
+    test('should hide the submission item when the user cannot submit to Yooz', async () => {
+      await renderMenu({ canSubmitToYooz: false });
+
+      await expect.element(getMenuItem(DOWNLOAD_LABEL)).toBeVisible();
+      await expect.element(getMenuItem(SUBMIT_TO_YOOZ_LABEL)).not.toBeInTheDocument();
+    });
+
+    test('should call onSubmitToYooz when the bill has not been submitted yet', async () => {
+      const { onSubmitToYooz } = await renderMenu({ canSubmitToYooz: true });
+
+      await getMenuItem(SUBMIT_TO_YOOZ_LABEL).click();
+
+      expect(onSubmitToYooz).toHaveBeenCalledOnce();
+    });
+
+    test('should disable the submission item when the bill is already submitted', async () => {
+      const { onSubmitToYooz } = await renderMenu({
+        canSubmitToYooz: true,
+        data: buildBill({ yoozSubmissionStatus: 'SUBMITTED' }),
+      });
+
+      const submitItem = getMenuItem(SUBMIT_TO_YOOZ_LABEL);
+      await expect.element(submitItem).toBeDisabled();
+
+      await submitItem.click({ force: true });
+
+      expect(onSubmitToYooz).not.toHaveBeenCalled();
+    });
+
+    test('should keep the submission item enabled when a previous submission failed', async () => {
+      await renderMenu({
+        canSubmitToYooz: true,
+        data: buildBill({ yoozSubmissionStatus: 'FAILED' }),
+      });
+
+      await expect.element(getMenuItem(SUBMIT_TO_YOOZ_LABEL)).toBeEnabled();
+    });
+  });
+
+  describe('Bill download', () => {
+    test('should call getFileLink with the bill file id', async () => {
+      const { getFileLink } = await renderMenu();
+
+      await getMenuItem(DOWNLOAD_LABEL).click();
+
+      expect(getFileLink).toHaveBeenCalledWith(FILE_ID);
+    });
+
+    test('should disable the download item when the bill has no file', async () => {
+      const { getFileLink } = await renderMenu({ data: buildBill({ file: undefined }) });
+
+      const downloadItem = getMenuItem(DOWNLOAD_LABEL);
+      await expect.element(downloadItem).toBeDisabled();
+
+      await downloadItem.click({ force: true });
+
+      expect(getFileLink).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('Credit generation', () => {
+    test.each(['PEDAGOGIC', 'TRAINING_SUPERVISION', 'ADMINISTRATIVE_CONTROL'] as const)(
+      'should call onGenerateCredit with the %s family on an invoice',
+      async (family) => {
+        const { onGenerateCredit } = await renderMenu({
+          data: buildBill({ costTypes: [family] }),
+          billCreditPermissions: ALL_PERMISSIONS,
+        });
+
+        await getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT).click();
+
+        expect(onGenerateCredit).toHaveBeenCalledWith(family);
+      },
+    );
+
+    test('should disable the credit item when the user lacks the credit permission', async () => {
+      const { onGenerateCredit } = await renderMenu({
+        billCreditPermissions: NO_PERMISSIONS,
+      });
+
+      const creditItem = getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT);
+      await expect.element(creditItem).toBeDisabled();
+
+      await creditItem.click({ force: true });
+
+      expect(onGenerateCredit).not.toHaveBeenCalled();
+    });
+
+    test('should disable the credit item when the invoice already has a child bill', async () => {
+      await renderMenu({
+        data: buildBill({ childId: 'child-bill-id' }),
+        billCreditPermissions: ALL_PERMISSIONS,
+      });
+
+      await expect.element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT)).toBeDisabled();
+    });
+
+    test('should disable the credit item for LIFE bills, which belong to no family', async () => {
+      await renderMenu({
+        data: buildBill({ costTypes: ['LIFE'] }),
+        billCreditPermissions: ALL_PERMISSIONS,
+      });
+
+      await expect.element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT)).toBeDisabled();
+    });
+  });
+
+  describe('Bill generation from credit', () => {
+    test('should hide the bill from credit item on an invoice', async () => {
+      await renderMenu({ billCreditPermissions: ALL_PERMISSIONS });
+
+      await expect.element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT)).toBeVisible();
+      await expect
+        .element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT))
+        .not.toBeInTheDocument();
+    });
+
+    test('should call onGenerateBillFromCredit on a pedagogic credit and disable the credit item', async () => {
+      const { onGenerateBillFromCredit } = await renderMenu({
+        data: buildBill({ invoiceCredit: true }),
+        billCreditPermissions: ALL_PERMISSIONS,
+      });
+
+      await expect.element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_CREDIT)).toBeDisabled();
+
+      await getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT).click();
+
+      expect(onGenerateBillFromCredit).toHaveBeenCalledWith('PEDAGOGIC');
+    });
+
+    test('should hide the bill from credit item when the pedagogic credit was already rebilled', async () => {
+      await renderMenu({
+        data: buildBill({ invoiceCredit: true, childId: 'child-bill-id', childPreview: false }),
+        billCreditPermissions: ALL_PERMISSIONS,
+      });
+
+      await expect
+        .element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT))
+        .not.toBeInTheDocument();
+    });
+
+    test('should show the bill from credit item when the pedagogic credit child bill is only a preview', async () => {
+      await renderMenu({
+        data: buildBill({ invoiceCredit: true, childId: 'child-bill-id', childPreview: true }),
+        billCreditPermissions: ALL_PERMISSIONS,
+      });
+
+      await expect
+        .element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT))
+        .toBeVisible();
+    });
+
+    test('should hide the bill from credit item when the user lacks the permission', async () => {
+      await renderMenu({
+        data: buildBill({ invoiceCredit: true }),
+        billCreditPermissions: NO_PERMISSIONS,
+      });
+
+      await expect
+        .element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT))
+        .not.toBeInTheDocument();
+    });
+
+    test.each(['TRAINING_SUPERVISION', 'ADMINISTRATIVE_CONTROL'] as const)(
+      'should hide the bill from credit item on a %s credit, which is never rebilled from here',
+      async (family) => {
+        await renderMenu({
+          data: buildBill({ invoiceCredit: true, costTypes: [family] }),
+          billCreditPermissions: ALL_PERMISSIONS,
+        });
+
+        await expect
+          .element(getMenuItem(BILL_CREDIT_ACTION_LABEL.GENERATE_BILL_FROM_CREDIT))
+          .not.toBeInTheDocument();
+      },
+    );
+  });
+});

