+import type { SearchBillDTO } from '@/model/BillDTO';
+import type { BillCreditFamily, BillCreditPermissions } from '../types';
+
+import { resolveBillCreditAction } from '../billCreditRules';
+import { BILL_CREDIT_ACTION_LABEL } from '../constants';
+import { OverflowMenu, type OverflowMenuItem } from '@/components/ui/menu/OverflowMenu';
+
+import './BillActionsOverflowMenu.scss';
+
+interface BillActionsOverflowMenuProps {
+  data: SearchBillDTO;
+  canSubmitToYooz: boolean;
+  billCreditPermissions: BillCreditPermissions;
+  getFileLink: (fileId: string) => void;
+  onGenerateCredit: (family: BillCreditFamily) => void;
+  onGenerateBillFromCredit: (family: BillCreditFamily) => void;
+  onSubmitToYooz: () => void;
+}
+
+export function BillActionsOverflowMenu({
+  data,
+  canSubmitToYooz,
+  billCreditPermissions,
+  getFileLink,
+  onGenerateCredit,
+  onGenerateBillFromCredit,
+  onSubmitToYooz,
+}: Readonly<BillActionsOverflowMenuProps>) {
+  const fileId = data.file?.id;
+  const creditAction = resolveBillCreditAction(data, billCreditPermissions);
+
+  const isCreditAction = creditAction?.type === 'GENERATE_CREDIT';
+  const isBillFromCreditAction = creditAction?.type === 'GENERATE_BILL_FROM_CREDIT';
+
+  const isAlreadySubmittedToYooz = data.yoozSubmissionStatus === 'SUBMITTED';
+
+  const items: OverflowMenuItem[] = [
+    {
+      label: 'Transmettre à la plateforme agréée',
+      icon: 'Forward',
+      onClick: onSubmitToYooz,
+      disabled: isAlreadySubmittedToYooz,
+      visible: canSubmitToYooz,
+    },
+    {
+      label: 'Télécharger la facture',
+      icon: 'Download',
+      onClick: () => getFileLink(fileId),
+      disabled: !fileId,
+    },
+    {
+      label: BILL_CREDIT_ACTION_LABEL['GENERATE_CREDIT'],
+      icon: 'FileMinus',
+      onClick: () => {
+        if (!isCreditAction) {
+          return;
+        }
+
+        onGenerateCredit(creditAction.family);
+      },
+      disabled: !isCreditAction,
+    },
+    {
+      label: BILL_CREDIT_ACTION_LABEL['GENERATE_BILL_FROM_CREDIT'],
+      icon: 'FileText',
+      onClick: () => {
+        if (isBillFromCreditAction) {
+          onGenerateBillFromCredit(creditAction.family);
+        }
+      },
+      visible: isBillFromCreditAction,
+    },
+  ];
+
+  return (
+    <div className="BillActionsOverflowMenu">
+      <OverflowMenu
+        items={items}
+        ariaLabel={`Actions pour la facture ${data.billNumber}`}
+      />
+    </div>
+  );
+}

