+import { useState } from 'react';
+
+import type { UseMutationCallbacks } from '@/api/http/types';
+import type { SearchBillDTO } from '@/model/BillDTO';
+import { useYoozPermissions } from './useYoozPermissions';
+import { useYoozSubmission } from '@/hooks/data/bill/yooz/useYoozSubmission';
+
+export function useYoozSubmissionAction({
+  onSuccess,
+}: Pick<UseMutationCallbacks, 'onSuccess'> = {}) {
+  const [billTarget, setBillTarget] = useState<SearchBillDTO | null>(null);
+  const [isDialogOpen, setIsDialogOpen] = useState(false);
+
+  const { canResendYoozSubmission } = useYoozPermissions();
+
+  const yoozSubmission = useYoozSubmission({
+    onSettled: () => setIsDialogOpen(false),
+    onSuccess,
+  });
+
+  function openDialog(bill: SearchBillDTO) {
+    setBillTarget(bill);
+    setIsDialogOpen(true);
+  }
+
+  return {
+    billTarget,
+    canResendYoozSubmission,
+    confirmYoozSubmissionDialog: {
+      isOpen: isDialogOpen,
+      open: openDialog,
+      close: () => setIsDialogOpen(false),
+    },
+    yoozSubmission,
+  };
+}

