+import { Menu } from '@base-ui/react/menu';
+
+import { SvgIcon, type SvgIconName } from '@/components/ui/svg/SvgIcon';
+
+import './OverflowMenu.scss';
+
+export interface OverflowMenuItem {
+  /**
+   * Text label for the menu item.
+   */
+  label: string;
+  /**
+   * Callback function invoked when the menu item is clicked.
+   */
+  onClick: () => void;
+  /**
+   * Optional icon displayed before the label, if provided.
+   */
+  icon?: SvgIconName;
+  /**
+   * Disables the item and prevents interaction.
+   */
+  disabled?: boolean;
+  /**
+   * Hides the item from the menu when explicitly set to `false`. Defaults to `true`.
+   */
+  visible?: boolean;
+}
+
+interface OverflowMenuProps {
+  items: OverflowMenuItem[];
+  ariaLabel: string;
+}
+
+export function OverflowMenu({ items, ariaLabel }: Readonly<OverflowMenuProps>) {
+  return (
+    <Menu.Root>
+      <Menu.Trigger
+        aria-label={ariaLabel}
+        title={ariaLabel}
+        className="OverflowMenu__trigger"
+      >
+        <SvgIcon name="EllipsisVertical" />
+      </Menu.Trigger>
+      <Menu.Portal>
+        <Menu.Positioner
+          className="OverflowMenu__positioner"
+          side="bottom"
+          align="end"
+          sideOffset={4}
+        >
+          <Menu.Popup className="OverflowMenu__popup">
+            {items
+              .filter((item) => item.visible !== false)
+              .map((item) => (
+                <Menu.Item
+                  key={item.label}
+                  disabled={item.disabled}
+                  className="OverflowMenu__item"
+                  onClick={item.onClick}
+                >
+                  {item.icon && (
+                    <SvgIcon
+                      name={item.icon}
+                      size={16}
+                    />
+                  )}
+                  {item.label}
+                </Menu.Item>
+              ))}
+          </Menu.Popup>
+        </Menu.Positioner>
+      </Menu.Portal>
+    </Menu.Root>
+  );
+}

