+import { useMutation } from '@tanstack/react-query';
+import { toast } from 'react-hot-toast';
+
+import type { YoozSubmissionResultDTO } from '@/model/Yooz';
+import type { ApiErrors } from '@/helpers/commonTypes';
+import type { UseMutationCallbacks } from '@/api/http/types';
+import { fetcher } from '@/api/http/fetcher';
+import endpoints from '@/constants/api-endpoints';
+import { HttpVerb } from '@/api/http/httpVerb';
+
+export function useYoozSubmission({ onSuccess, onSettled }: UseMutationCallbacks = {}) {
+  return useMutation<YoozSubmissionResultDTO, ApiErrors, { billId: string }>({
+    mutationFn: ({ billId }) => {
+      return fetcher({
+        endpoint: endpoints.billingYoozSubmission(billId),
+        method: HttpVerb.POST,
+      });
+    },
+    onSuccess: (data) => {
+      onSuccess?.();
+
+      if (data.outcome === 'SUBMITTED') {
+        toast.success('Facture transmise avec succès');
+      } else {
+        toast(
+          "La transmission a bien été envoyée, mais n'a pas pu être traitée sur la plateforme.",
+          { style: { background: '#1cb7d0' } },
+        );
+      }
+    },
+    onError: () => {
+      toast.error('La transmission a échoué.');
+    },
+    onSettled,
+  });
+}

