+import './YoozProcessingStatusBadge.scss';
+
+interface YoozProcessingStatusBadgeProps {
+  canViewStatus: boolean;
+  lastYoozDocumentStatus: YoozDocumentStatus | null;
+}
+
+export function YoozProcessingStatusBadge({
+  canViewStatus,
+  lastYoozDocumentStatus,
+}: Readonly<YoozProcessingStatusBadgeProps>) {
+  if (!canViewStatus || !lastYoozDocumentStatus) {
+    return null;
+  }
+
+  const processingStatus = YOOZ_DOCUMENT_STATUS_TO_PROCESSING_STATUS[lastYoozDocumentStatus];
+  const config = YOOZ_PROCESSING_STATUS_CONFIG[processingStatus];
+
+  return (
+    <StatusBadge
+      className="YoozProcessingStatusBadge"
+      color={config.color}
+      icon={config.icon}
+      label={config.label}
+    />
+  );
+}

