+import { describe, expect } from 'vitest';
+import { page } from 'vitest/browser';
+import { delay, http, HttpResponse } from 'msw';
+
+import { testMsw } from '@/test/browser-test-utils/test-extend';
+import { renderWithQuery } from '@/test/browser-test-utils/renderWithQuery';
+import type { YoozDocumentStatus, YoozTrackingDTO } from '@/model/Yooz';
+import endpoints from '@/constants/api-endpoints';
+import { yoozTrackingMocks } from '@/mocks/billing/yoozTrackingDtoMock';
+import { YoozTrackingDetails } from '../YoozTrackingDetails';
+
+const BILL_ID = 'bill-00026';
+
+function mockYoozTracking(tracking: YoozTrackingDTO) {
+  return http.get(endpoints.billingYoozEvents(BILL_ID), () => {
+    return HttpResponse.json({ result: tracking });
+  });
+}
+
+function renderYoozTrackingDetails() {
+  return renderWithQuery(<YoozTrackingDetails billId={BILL_ID} />);
+}
+
+describe('<YoozTrackingDetails />', () => {
+  testMsw(
+    'should announce the loading and keep the headings visible while the tracking is loading',
+    async ({ worker }) => {
+      worker.use(
+        http.get(endpoints.billingYoozEvents(BILL_ID), async () => {
+          await delay('infinite');
+        }),
+      );
+      await renderYoozTrackingDetails();
+
+      await expect
+        .element(page.getByRole('heading', { name: 'Statut de traitement de la facture' }))
+        .toBeVisible();
+
+      await expect
+        .element(page.getByRole('status'))
+        .toHaveTextContent("Chargement de l'historique de transmission en cours...");
+    },
+  );
+
+  testMsw(
+    'should display the processing status and the history sorted from newest to oldest',
+    async ({ worker }) => {
+      worker.use(mockYoozTracking(yoozTrackingMocks.handled));
+      await renderYoozTrackingDetails();
+
+      await expect.element(page.getByText('Prise en charge')).toBeVisible();
+      await expect.element(page.getByRole('status')).not.toBeInTheDocument();
+
+      const historyItems = page.getByRole('listitem');
+      await expect.element(historyItems).toHaveLength(7);
+      await expect
+        .element(historyItems.nth(0).getByText('APPROVED — Facture validée pour paiement'))
+        .toBeVisible();
+      await expect
+        .element(historyItems.nth(0).getByText('24 septembre 2026 à 14:38'))
+        .toBeVisible();
+      await expect
+        .element(
+          historyItems
+            .nth(6)
+            .getByText('TRANSMIS — System a transmis la facture à la plateforme agréée'),
+        )
+        .toBeVisible();
+    },
+  );
+
+  testMsw('should display the raw status for an unknown platform status', async ({ worker }) => {
+    worker.use(mockYoozTracking(yoozTrackingMocks.anomaly));
+    await renderYoozTrackingDetails();
+
+    await expect.element(page.getByText('En anomalie')).toBeVisible();
+    await expect
+      .element(page.getByRole('listitem').nth(0).getByText('ON_HOLD_BY_BUYER — Statut inconnu'))
+      .toBeVisible();
+  });
+
+  testMsw(
+    'should fall back to the raw status and a generic description for an undocumented status',
+    async ({ worker }) => {
+      const trackingWithUnmappedStatus: YoozTrackingDTO = {
+        ...yoozTrackingMocks.anomaly,
+        events: yoozTrackingMocks.anomaly.events.map((event) => {
