+import cs from 'classnames';
+
+import type { YoozEventDTO } from '@/model/Yooz';
+import { DateFormat } from '@/model/DateFormatEnum';
+import { date } from '@/helpers/formats/formatDateHelpers';
+import { Disclosure } from '@/components/ui/accordion/Disclosure';
+import { YOOZ_DOCUMENT_STATUS_DESCRIPTION, getYoozEventCode } from '../yoozTrackingEventLabels';
+
+import './YoozTrackingEventItem.scss';
+
+interface YoozTrackingEventItemProps {
+  event: YoozEventDTO;
+  isLatest?: boolean;
+}
+
+export function YoozTrackingEventItem({
+  event,
+  isLatest = false,
+}: Readonly<YoozTrackingEventItemProps>) {
+  return (
+    <article
+      className={cs('YoozTrackingEventItem', {
+        'YoozTrackingEventItem--latest': isLatest,
+      })}
+    >
+      <p className="YoozTrackingEventItem__message">
+        <span className="YoozTrackingEventItem__code">{getYoozEventCode(event)}</span>
+        {' — '}
+        <YoozTrackingEventDescription event={event} />
+      </p>
+
+      <time
+        className="YoozTrackingEventItem__date"
+        dateTime={event.effectiveDate}
+      >
+        {date.toDateTimeFR(event.effectiveDate, {
+          dateFormat: DateFormat.DATE_TIME_LONG_FR,
+        })}
+      </time>
+
+      {event.type === 'SUBMISSION_ERROR' && event.error?.message && (
+        <Disclosure
+          summary={`Détail de l'erreur (${event.error.errorCode} · ${event.error.status})`}
+          className="YoozTrackingEventItem__errorDetail"
+        >
+          <code>{event.error.message}</code>
+        </Disclosure>
+      )}
+    </article>
+  );
+}
+
+function YoozTrackingEventDescription({ event }: Readonly<{ event: YoozEventDTO }>) {
+  switch (event.type) {
+    case 'STATUS_RECEIVED':
+      return (
+        YOOZ_DOCUMENT_STATUS_DESCRIPTION[event.status] ?? YOOZ_DOCUMENT_STATUS_DESCRIPTION.UNKNOWN
+      );
+    case 'SUBMISSION_SUCCESS':
+      return (
+        <>
+          <b>{event.user.displayName}</b> a transmis la facture à la plateforme agréée
+        </>
+      );
+    case 'SUBMISSION_ERROR':
+      return (
+        <>
+          <b>{event.user.displayName}</b> n'a pas pu transmettre la facture à la plateforme agréée
+        </>
+      );
+  }
+}

