+import { sortByDate } from '@/helpers/utils/dateUtils';
+import { useYoozEventTracking } from '@/hooks/data/bill/yooz/useYoozEventTracking';
+import TitlePart from '@/components/presentational/common/TitlePart/TitlePart';
+import Messages from '@/components/presentational/common/Messages/Messages';
+import { YoozProcessingStatusBadge } from '@/components/presentational/common/ServiceBilling/components/YoozProcessingStatusBadge';
+import { YoozTrackingEventItem } from './components/YoozTrackingEventItem';
+import { YoozTrackingEventListSkeleton } from './components/YoozTrackingEventListSkeleton';
+import { getYoozEventCode } from './yoozTrackingEventLabels';
+
+import './YoozTrackingDetails.scss';
+
+interface YoozTrackingDetailsProps {
+  billId: string;
+}
+
+export function YoozTrackingDetails({ billId }: Readonly<YoozTrackingDetailsProps>) {
+  const {
+    isPending: isYoozTrackingPending,
+    data: yoozTracking,
+    error: yoozTrackingError,
+  } = useYoozEventTracking(billId);
+
+  const sortedEvents = yoozTracking ? sortByDate(yoozTracking.events, 'effectiveDate') : [];
+
+  return (
+    <section className="YoozTrackingDetails">
+      <TitlePart title="Transmission des factures" />
+
+      {yoozTrackingError && (
+        <Messages
+          type="error"
+          content={yoozTrackingError}
+        />
+      )}
+
+      {(isYoozTrackingPending || yoozTracking) && (
+        <>
+          <h4 className="YoozTrackingDetails__subtitle">Statut de traitement de la facture</h4>
+          <div className="YoozTrackingDetails__status">
+            {isYoozTrackingPending && (
+              <div
+                className="skeleton YoozTrackingDetails__badgeSkeleton"
+                aria-hidden="true"
+              />
+            )}
+
+            {yoozTracking?.lastDocumentStatus && (
+              <YoozProcessingStatusBadge
+                canViewStatus
+                lastYoozDocumentStatus={yoozTracking.lastDocumentStatus}
+              />
+            )}
+
+            {yoozTracking && !yoozTracking.lastDocumentStatus && (
+              <p className="YoozTrackingDetails__empty">Aucun statut disponible.</p>
+            )}
+          </div>
+
+          <h4 className="YoozTrackingDetails__subtitle">
+            Historique des statuts de la plateforme agréée
+          </h4>
+
+          {isYoozTrackingPending && <YoozTrackingEventListSkeleton />}
+
+          {sortedEvents.length > 0 && (
+            <ul className="YoozTrackingDetails__list">
+              {sortedEvents.map((event, index) => (
+                <li key={`${getYoozEventCode(event)}-${event.effectiveDate}`}>
+                  <YoozTrackingEventItem
+                    event={event}
+                    isLatest={index === 0}
+                  />
+                </li>
+              ))}
+            </ul>
+          )}
+
+          {yoozTracking && sortedEvents.length === 0 && (
+            <p className="YoozTrackingDetails__empty">Aucun événement de transmission.</p>
+          )}
+        </>
+      )}
+    </section>
+  );
+}

