+import type { YoozDocumentStatus, YoozEventDTO, YoozEventType } from '@/model/Yooz';
+
+export const YOOZ_DOCUMENT_STATUS_DESCRIPTION = {
+  FILED: 'Facture déposée sur la plateforme agréée',
+  ISSUED: 'Facture émise par la plateforme agréée',
+  SEND_ERROR: "Erreur lors de l'envoi de la facture",
+  RECEIVED: 'Facture reçue par la plateforme destinataire',
+  REJECTED: 'Facture rejetée pour cause de format ou données erronées',
+  PROVIDED: "Facture mise à disposition de l'acheteur",
+  REFUSED: 'Facture refusée',
+  SUPPORTED: 'Facture acceptée pour traitement ou paiement',
+  APPROVED: 'Facture validée pour paiement',
+  PARTIALLY_APPROVED: 'Facture partiellement validée',
+  LITIGATION: 'Facture en litige ou incident signalé',
+  CANCELLED: 'Facture annulée',
+  SUSPENDED: 'Traitement temporairement interrompu',
+  PAID: 'Paiement émis',
+  COLLECTED: 'Paiement reçu et enregistré',
+  COMPLETED: 'Toutes les étapes de traitement sont terminées',
+  UNKNOWN: 'Statut inconnu',
+} as const satisfies Record<YoozDocumentStatus, string>;
+
+const YOOZ_SUBMISSION_EVENT_CODE = {
+  SUBMISSION_SUCCESS: 'TRANSMIS',
+  SUBMISSION_ERROR: 'ÉCHEC DE TRANSMISSION',
+} as const satisfies Record<Exclude<YoozEventType, 'STATUS_RECEIVED'>, string>;
+
+export function getYoozEventCode(event: YoozEventDTO) {
+  if (event.type === 'STATUS_RECEIVED') {
+    const isDocumentedStatus =
+      event.status !== 'UNKNOWN' && event.status in YOOZ_DOCUMENT_STATUS_DESCRIPTION;
+
+    return isDocumentedStatus ? event.status : event.rawStatus;
+  }
+
+  return YOOZ_SUBMISSION_EVENT_CODE[event.type];
+}

