+import { describe, expect, test, vi } from 'vitest';
+import { render } from 'vitest-browser-react';
+import { page } from 'vitest/browser';
+
+import { Dialog } from '@/components/ui/dialog/Dialog';
+import { YesOrNoConfirmationModal } from '../YesOrNoConfirmationModal';
+
+const message = 'Are you sure you want to proceed?';
+
+describe('<YesOrNoConfirmationModal />', () => {
+  test('should render the message and call the confirmation and cancel handlers', async () => {
+    const onCancel = vi.fn();
+    const onConfirm = vi.fn();
+
+    await render(
+      <YesOrNoConfirmationModal
+        message={message}
+        onCancel={onCancel}
+        onConfirm={onConfirm}
+      />,
+    );
+
+    const yesButton = page.getByRole('button', { name: 'Oui', exact: true });
+    const noButton = page.getByRole('button', { name: 'Non', exact: true });
+
+    await expect.element(page.getByText(message)).toBeVisible();
+    await expect.element(yesButton).toBeVisible();
+    await expect.element(noButton).toBeVisible();
+
+    await yesButton.click();
+    expect(onConfirm).toHaveBeenCalledOnce();
+    expect(onCancel).not.toHaveBeenCalled();
+
+    await noButton.click();
+    expect(onCancel).toHaveBeenCalledOnce();
+    expect(onConfirm).toHaveBeenCalledOnce();
+  });
+
+  test('should render warning message if provided', async () => {
+    const warningMessage = <p>Warning message !</p>;
+    await render(
+      <YesOrNoConfirmationModal
+        message={message}
+        onCancel={vi.fn()}
+        onConfirm={vi.fn()}
+        warningMessage={warningMessage}
+      />,
+    );
+
+    await expect.element(page.getByText('Warning message !')).toBeVisible();
+  });
+
+  test.each([false, true])(
+    'should disable both buttons while pending with onCancel provided: %s',
+    async (withOnCancel) => {
+      const onCancel = vi.fn();
+      const onConfirm = vi.fn();
+
+      await render(
+        <Dialog
+          title="Modal Title"
+          defaultOpen
+        >
+          <YesOrNoConfirmationModal
+            message={message}
+            onCancel={withOnCancel ? onCancel : undefined}
+            onConfirm={onConfirm}
+            isPending
+          />
+        </Dialog>,
+      );
+
+      await expect.element(page.getByRole('button', { name: 'Oui', exact: true })).toBeDisabled();
+      await expect.element(page.getByRole('button', { name: 'Non', exact: true })).toBeDisabled();
+      expect(onConfirm).not.toHaveBeenCalled();
+      expect(onCancel).not.toHaveBeenCalled();
+    },
+  );
+
+  test('should close the dialog without confirming when no cancel handler is provided', async () => {
+    const onConfirm = vi.fn();
+
+    await render(
+      <Dialog
+        title="Modal Title"
+        defaultOpen
+      >
+        <YesOrNoConfirmationModal
+          message={message}
+          onConfirm={onConfirm}
+        />
+      </Dialog>,
+    );
+
+    await expect.element(page.getByRole('dialog', { name: 'Modal Title' })).toBeVisible();
+    await page.getByRole('button', { name: 'Non', exact: true }).click();
+
+    await expect.element(page.getByRole('dialog', { name: 'Modal Title' })).not.toBeInTheDocument();
+    expect(onConfirm).not.toHaveBeenCalled();
+  });
+});

