+import { useState } from 'react';
+
+import type { DialogProps } from '@/components/ui/dialog/Dialog';
+import type { SearchTrainingDepartureDTO } from '@/model/TrainingDepartureDTO';
+import { formatPhysicalPerson } from '@/helpers/formats/formatPhysicalPersonDtoHelpers';
