+/**
+ * Manages the open state and target learner of the "delete learner" confirmation dialog
+ * shared by the training and evaluation departure lists.
+ */
+export function useDeleteLearnerDialog(items: SearchTrainingDepartureDTO[]) {
+  const [learnerToDeleteId, setLearnerToDeleteId] = useState<string | null>(null);
+  const [isOpen, setIsOpen] = useState(false);
+
+  function openDeleteDialog(departureId: string) {
+    setLearnerToDeleteId(departureId);
+    setIsOpen(true);
+  }
+
+  function closeDeleteDialog() {
+    setIsOpen(false);
+  }
+
+  const learnerToDelete = items.find((item) => item.id === learnerToDeleteId);
+
+  const deleteDialogProps: DialogProps = {
+    title: `Apprenant : ${formatPhysicalPerson(learnerToDelete?.learner.physicalPersonDto).fullName}`,
+    open: isOpen,
+    onOpenChange: (open) => {
+      if (!open) {
+        closeDeleteDialog();
+      }
+    },
+  };
+
+  return {
+    learnerToDeleteId,
+    openDeleteDialog,
+    closeDeleteDialog,
+    deleteDialogProps,
+  };
+}

