+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Navigation\HookHandler;
+
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\RequestStack;
+
+final class PreprocessPager implements ContainerInjectionInterface {
+
+  public function __construct(
+    private readonly RequestStack $requestStack,
+  ) {
+  }
+
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('request_stack')
+    );
+  }
+
+  public function preprocess(array &$variables): void {
+    $currentRequest = $this->requestStack->getCurrentRequest();
+    if (NULL === $currentRequest) {
+      return;
+    }
+
+    $firstPageUrl = $this->getFirstPageUrl($currentRequest);
+
+    $variables['items']['pages'][1]['href'] = $firstPageUrl;
+    if (isset($variables['items']['first'])) {
+      $variables['items']['first']['href'] = $firstPageUrl;
+    }
+    if (FALSE === isset($variables['items']['previous']) || 2 !== $variables['current']) {
+      return;
+    }
+
+    $variables['items']['previous']['href'] = $firstPageUrl;
+  }
+
+  private function getFirstPageUrl(Request $currentRequest): string {
+    $queryParams = $currentRequest->query->all();
+    if (isset($queryParams['page'])) {
+      unset($queryParams['page']);
+    }
+
+    $requestUri = $currentRequest->getRequestUri();
+    $url = \parse_url($requestUri, \PHP_URL_PATH);
+    if (FALSE === \is_string($url)) {
+      return $requestUri;
+    }
+
+    $queryString = \http_build_query($queryParams);
+
+    return ('' === $queryString) ? $url : \implode('?', [
+      $url,
+      $queryString,
+    ]);
+  }
+
+}

