+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\Navigation\HookHandler;
+
+use Drupal\Tests\UnitTestCase;
+use Drupal\rgds_core\Navigation\HookHandler\PreprocessPager;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\RequestStack;
+
+/**
+ * Class PreprocessPagerTest.
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ *
+ * @package Drupal\Tests\rgds_core\Unit\Navigation
+ */
+final class PreprocessPagerTest extends UnitTestCase {
+
+  /**
+   * @dataProvider preprocessProvider
+   */
+  public function testPreprocess(
+    string $currentRequestUri,
+    array $currentRequestQueryArgs,
+    int $numberOfPages,
+    bool $expectedFirstPageItem,
+    bool $expectedPreviousPageItem,
+    string $expectedFirstPageUrl,
+    ?string $expectedPreviousPageUrl = NULL,
+  ): void {
+    $requestStack = new RequestStack();
+    $request = Request::create($currentRequestUri, 'GET', $currentRequestQueryArgs);
+    $requestStack->push($request);
+
+    $pagerVariables = [
+      'current' => $currentRequestQueryArgs['page'] + 1,
+      'items' => $this->getDefaultPagerItemsForActivePage(
+        $numberOfPages,
+        $currentRequestQueryArgs,
+      ),
+    ];
+
+    $preprocessPager = new PreprocessPager($requestStack);
+    $preprocessPager->preprocess($pagerVariables);
+
+    if (TRUE === $expectedFirstPageItem) {
+      self::assertEquals(
+        $expectedFirstPageUrl,
+        $pagerVariables['items']['first']['href'],
+      );
+    }
+    else {
+      self::assertArrayNotHasKey('first', $pagerVariables['items']);
+    }
+
+    if (TRUE === $expectedPreviousPageItem) {
+      self::assertEquals(
+        $expectedPreviousPageUrl,
+        $pagerVariables['items']['previous']['href'],
+      );
+    }
+    else {
+      self::assertArrayNotHasKey('previous', $pagerVariables['items']);
+    }
+
+    self::assertEquals(
+      $expectedFirstPageUrl,
+      $pagerVariables['items']['pages'][1]['href'],
+    );
+  }
+
+  public static function preprocessProvider(): \Generator {
+    yield 'Only one page for /actualites with no extra args' => [
+      'currentRequestUri' => '/actualites',
+      'currentRequestQueryArgs' => ['page' => 0],
+      'numberOfPages' => 1,
+      'expectedFirstPageItem' => FALSE,
+      'expectedPreviousPageItem' => FALSE,
+      'expectedFirstPageUrl' => '/actualites',
+      'expectedPreviousPageUrl' => NULL,
+    ];
+
+    yield 'first page of many for /actualites with no extra args' => [
+      'currentRequestUri' => '/actualites?page=0',
+      'currentRequestQueryArgs' => ['page' => 0],
+      'numberOfPages' => 4,
+      'expectedFirstPageItem' => FALSE,
+      'expectedPreviousPageItem' => FALSE,
+      'expectedFirstPageUrl' => '/actualites',
+      'expectedPreviousPageUrl' => NULL,
+    ];
+
+    yield 'first page of many for /actualites with extra args' => [
+      'currentRequestUri' => '/actualites?page=0&test=toto',
+      'currentRequestQueryArgs' => ['page' => 0, 'test' => 'toto'],
+      'numberOfPages' => 4,
+      'expectedFirstPageItem' => FALSE,
+      'expectedPreviousPageItem' => FALSE,
+      'expectedFirstPageUrl' => '/actualites?test=toto',
+      'expectedPreviousPageUrl' => NULL,
+    ];
+
+    yield 'second page of many for /actualites with extra args' => [
+      'currentRequestUri' => '/actualites?page=1&test=toto',
+      'currentRequestQueryArgs' => ['page' => 1, 'test' => 'toto'],
+      'numberOfPages' => 4,
+      'expectedFirstPageItem' => TRUE,
+      'expectedPreviousPageItem' => TRUE,
+      'expectedFirstPageUrl' => '/actualites?test=toto',
+      'expectedPreviousPageUrl' => '/actualites?test=toto',
+    ];
+
+    yield 'last page of many for /actualites with extra args' => [
+      'currentRequestUri' => '/actualites?page=3&test=toto',
+      'currentRequestQueryArgs' => ['page' => 3, 'test' => 'toto'],
+      'numberOfPages' => 4,
+      'expectedFirstPageItem' => TRUE,
+      'expectedPreviousPageItem' => TRUE,
+      'expectedFirstPageUrl' => '/actualites?test=toto',
+      'expectedPreviousPageUrl' => '?page=2&test=toto',
+    ];
+  }
+
+  private function getDefaultPagerItemsForActivePage(int $numberOfPages, array $queryArgs): array {
+    $items = [
+      'pages' => [],
+    ];
+    $activePage = (int) $queryArgs['page'] ?? 0;
+
+    if (isset($queryArgs['page'])) {
+      unset($queryArgs['page']);
+    }
+    $queryString = \http_build_query($queryArgs);
+
+    for ($pageId = 1; $pageId <= $numberOfPages; $pageId++) {
+      $items['pages'][$pageId] = [
+        'href' => \sprintf('?page=%d', $pageId - 1),
+      ];
+      if ('' === $queryString) {
+        continue;
+      }
+      $items['pages'][$pageId]['href'] .= \sprintf('&%s', $queryString);
+    }
+
+    $lastPageId = $numberOfPages - 1;
+    if ($activePage > 0) {
+      $items['first'] = [
+        'href' => '?page=0',
+      ];
+      $items['previous'] = [
+        'href' => \sprintf('?page=%d', $activePage - 1),
+      ];
+      if ('' !== $queryString) {
+        $items['first']['href'] .= \sprintf('&%s', $queryString);
+        $items['previous']['href'] .= \sprintf('&%s', $queryString);
+      }
+    }
+    if ($activePage < $lastPageId) {
+      $items['next'] = [
+        'href' => \sprintf('?page=%d', $activePage + 1),
+      ];
+      $items['last'] = [
+        'href' => \sprintf('?page=%d', $lastPageId),
+      ];
+      if ('' !== $queryString) {
+        $items['next']['href'] .= \sprintf('&%s', $queryString);
+        $items['last']['href'] .= \sprintf('&%s', $queryString);
+      }
+    }
+
+    return $items;
+  }
+
+}

