+<?php
+
+declare(strict_types=1);
+
+namespace src\Kernel\Emergency;
+
+use Drupal\Core\Site\Settings;
+use Drupal\Core\Test\AssertMailTrait;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\micro_site\Entity\Site;
+use Drupal\rgds_core\Emergency\Client\EmergencyClientInterface;
+use Drupal\rgds_core\Emergency\Commands\EmergencyWaitingTimeImportCommands;
+use Drupal\rgds_core\Emergency\Model\WaitingTime;
+use Drush\Commands\DrushCommands;
+use Drush\Log\DrushLoggerManager;
+
+class CommandImportTest extends KernelTestBase {
+
+  use AssertMailTrait;
+
+  /**
+   * {@inheritdoc}
+   */
+  public static $modules = [
+    'micro_site',
+  ];
+
+  protected function setUp(): void {
+    parent::setUp();
+    $this->installEntitySchema('site_information_setting');
+  }
+
+  /**
+   * Testing e-mail is send when failure.
+   *
+   * @dataProvider siteDataProvider
+   */
+  public function testEmergencyWaitingTimesCommandSendReport(array $siteValues): void {
+    Site::create($siteValues)->save();
+    $command = $this->createCommandWithClientMock(\Drupal::service('rgds_core.emergency.emergency_client'));
+
+    $result = $command->importEmergencyWaitingTime(['report' => TRUE]);
+
+    $this->assertEquals(DrushCommands::EXIT_SUCCESS, $result->getExitCode());
+    $this->assertMail('subject', 'Ramsay Sante - Rapport d\'erreur temps d\'attentes urgences');
+    $this->assertMail('from', $this->config('system.site')->get('mail'));
+    $this->assertMail('to', 'test@me.pls');
+    $this->assertMailPattern('body', 'http:\/\/localhost\/broken-url(?!\?.+)', 1);
+  }
+
+  public function siteDataProvider(): \Generator {
+    yield 'not found import url' => [
+      'site values' => $this->siteValuesWithWsUrl('http://localhost/broken-url'),
+    ];
+    yield 'not found import url with query' => [
+      'site values' => $this->siteValuesWithWsUrl('http://localhost/broken-url?param=secret'),
+    ];
+  }
+
+  /**
+   * Testing content in body email when failure or warning.
+   *
+   * @dataProvider reportDataProvider
+   */
+  public function testEmergencyReportContent(array $siteValues, array $responseValues, array $expectedContents): void {
+    Site::create($siteValues)->save();
+    $emergencyClientMock = $this->createMock(EmergencyClientInterface::class);
+    $emergencyClientMock->method('with')->willReturnSelf();
+    $emergencyClientMock->method('getEmergencyWaitingTimes')->willReturn($responseValues);
+    $command = $this->createCommandWithClientMock($emergencyClientMock);
+
+    $result = $command->importEmergencyWaitingTime(['report' => TRUE]);
+
+    $this->assertEquals(DrushCommands::EXIT_SUCCESS, $result->getExitCode());
+    $this->assertMail('subject', 'Ramsay Sante - Rapport d\'erreur temps d\'attentes urgences');
+    $this->assertMail('from', $this->config('system.site')->get('mail'));
+    $this->assertMail('to', 'test@me.pls');
+    self::assertNotEmpty($expectedContents);
+    foreach ($expectedContents as $expected) {
+      $this->assertMailPattern('body', $expected,);
+    }
+  }
+
+  public function reportDataProvider(): \Generator {
+    yield 'Invalid import' => [
+      'site values' => $this->siteValuesWithWsUrl('http://localhost/valid-url'),
+      'client response values' => [
+        $this->aNullWaitingTime(),
+        $this->aNullWaitingTime(),
+        $this->aNullWaitingTime(),
+      ],
+      'expected body' => [
+        'Alertes lors de la synchronisation',
+        'timestamp: [-0-9]+',
+        'averageWaitingTime: [-0-9]+',
+        'averageWaitingPatients: 0',
+        'averageTreatedPatients: 0',
+        'averageTraumatologyTime: 0',
+        'averageMedicineTime: 0',
+      ],
+    ];
+  }
+
+  private function createCommandWithClientMock(
+    EmergencyClientInterface $emergencyClient,
+  ): EmergencyWaitingTimeImportCommands {
+    $command = new EmergencyWaitingTimeImportCommands(
+      \Drupal::service('rgds_core.emergency.calculator.waiting_time_calculator'),
+      \Drupal::service('database'),
+      \Drupal::service('rgds_core.emergency.helper.legacy_json_file'),
+      \Drupal::service('rgds_core.emergency.finder.institution'),
+      $emergencyClient,
+      new Settings(['rgds_import_report_emails' => 'test@me.pls']),
+      \Drupal::service('plugin.manager.mail'),
+      \Drupal::service('language_manager'),
+    );
+    $command->setLogger($this->createMock(DrushLoggerManager::class));
+
+    return $command;
+  }
+
+  private function siteValuesWithWsUrl(string $wsUrl): array {
+    return [
+      'type' => 'institution',
+      'field_emergencies_ws' => $wsUrl,
+      'field_legacy_hospital_nid' => '1',
+      'status' => 1,
+      'site_url' => 'foo.com',
+      'name' => 'Test',
+      'id' => \random_int(1, 1000),
+      'registered' => 1,
+    ];
+  }
+
+  private function aNullWaitingTime(): WaitingTime {
+    $datetime = new \DateTimeImmutable(\random_int(2020, 2050) . '-12-01');
+
+    return new WaitingTime(
+      $datetime,
+      NULL,
+      NULL,
+      $datetime,
+      NULL,
+      NULL
+    );
+  }
+
+}

