+  public function testEmergencyWaitingTimesCommandSendReport(array $siteValues): void {
+    Site::create($siteValues)->save();
+    $command = $this->createCommandWithClientMock(\Drupal::service('rgds_core.emergency.emergency_client'));
+
+    $result = $command->importEmergencyWaitingTime(['report' => TRUE]);
+
+    $this->assertEquals(DrushCommands::EXIT_SUCCESS, $result->getExitCode());
+    $this->assertMail('subject', 'Ramsay Sante - Rapport d\'erreur temps d\'attentes urgences');
+    $this->assertMail('from', $this->config('system.site')->get('mail'));
+    $this->assertMail('to', 'test@me.pls');
+    $this->assertMailPattern('body', 'http:\/\/localhost\/broken-url(?!\?.+)', 1);
+  }
+
