+final class PaymentLinkImportForm extends FormBase {
+
+  public function __construct(
+    private readonly AccountProxyInterface $currentUser,
+    private readonly FileSystemInterface $fileSystem,
+    private readonly PaymentLinkXlsxFileParser $paymentLinkXlsxFileParser,
+    private readonly PaymentLinkRepository $paymentLinkRepository,
+    TranslationInterface $stringTranslation,
+  ) {
+    $this->setStringTranslation($stringTranslation);
+  }
+
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('current_user'),
+      $container->get('file_system'),
+      $container->get('rgds_core.payment_link.parser.file_xlsx'),
+      $container->get('rgds_core.payment_link.repository'),
+      $container->get('string_translation'),
