+  /**
+   * {@inheritdoc}
+   */
+  public function getFormId(): string {
+    return 'rgds_payment_link_import_form';
+  }
+
+  /**
+   * {@inheritdoc}
+   *
+   * phpcs:disable SlevomatCodingStandard.Functions.UnusedParameter
+   */
+  public function buildForm(array $form, FormStateInterface $form_state): array {
+    $form['import_file'] = [
+      '#required' => TRUE,
+      '#type' => 'file',
+      '#title' => $this->t('Fichier contenant les liens de paiement à importer par établissement', [], ['context' => 'rgds: payment-link import']),
+      '#description' => $this->t('Extensions supportées: @extensions.', ['@extensions' => 'xlsx'], ['context' => 'rgds: payment-link import']),
+    ];
+
+    $form['submit'] = [
+      '#type' => 'submit',
+      '#value' => $this->t('Importer', [], ['context' => 'rgds: payment-link import']),
+    ];
+
+    return $form;
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public function validateForm(array &$form, FormStateInterface $form_state): void {
+    parent::validateForm($form, $form_state);
+
+    $allFiles = $this->getRequest()->files->get('files', []);
+    if (FALSE === \is_array($allFiles)) {
+      $form_state->setErrorByName('import_file', $this->t('Le fichier n\'a pas pu être uploadé.', [], ['context' => 'rgds: payment-link import']));
+      return;
+    }
+    $file = $allFiles['import_file'] ?? NULL;
+
+    if (!$file instanceof UploadedFile) {
+      $form_state->setErrorByName('import_file', $this->t('Le fichier n\'a pas pu être uploadé.', [], ['context' => 'rgds: payment-link import']));
+      return;
+    }
+
+    if (!$file->isValid()) {
+      $form_state->setErrorByName('import_file', $this->t('Le fichier n\'a pas pu être uploadé.', [], ['context' => 'rgds: payment-link import']));
+      return;
+    }
+
+    $filePath = $file->getRealPath();
+    if (FALSE === $filePath) {
+      $form_state->setErrorByName('import_file', $this->t('Le fichier n\'a pas pu être uploadé.', [], ['context' => 'rgds: payment-link import']));
+      return;
+    }
+
+    if ('xlsx' !== $file->getClientOriginalExtension()) {
+      $form_state->setErrorByName('import_file', $this->t('Fichier invalide: veuillez importer un xlsx.', [], ['context' => 'rgds: payment-link import']));
+      $this->fileSystem->unlink($filePath);
+      return;
+    }
+
+    $form_state->setValue('import_file', $file->getRealPath());
+
+    try {
+      $paymentLinks = $this->paymentLinkXlsxFileParser->parseToPaymentLinks(
+        $filePath,
+        $this->currentUser,
+        new \DateTimeImmutable(),
+      );
+    }
+    catch (\Throwable $throwable) {
+      $form_state->setErrorByName('import_file', $this->t('Le fichier ne peut pas être traité. Veuillez vérifier si les données sont correctement formatées.', [], ['context' => 'rgds: payment-link import']));
+      return;
+    }
+
+    $form_state->setValue('payment_links', $paymentLinks);
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public function submitForm(array &$form, FormStateInterface $form_state): void {
+    $filePath = $form_state->getValue('import_file');
+    if (TRUE === \is_string($filePath)) {
+      $this->fileSystem->unlink($filePath);
+    }
+
+    $paymentLinks = $form_state->getValue('payment_links');
+    if (FALSE === \is_array($paymentLinks)) {
+      return;
+    }
+
+    $this->paymentLinkRepository->deleteAll();
+
+    foreach ($paymentLinks as $paymentLink) {
+      if (FALSE === $paymentLink instanceof PaymentLink) {
+        continue;
+      }
+      $this->paymentLinkRepository->insertOrUpdate($paymentLink, $this->currentUser);
+    }
+
+    $this->messenger()->addStatus($this->t('Les liens de paiement de @count établissements ont été importés.', ['@count' => \count($paymentLinks)], ['context' => 'rgds: payment-link import']));
+  }
+
+}

