+   * @param array $data
+   *   The data we need to create the PaymentLink.
+   *
+   * @return self
+   *   The PaymentLink we want to create.
+   */
+  public static function fromDbRow(array $data): self {
+    return new self(
+      $data['institution_trigram'],
+      $data['payment_link_url'],
+      (int) $data['uid'],
+      (new \DateTimeImmutable())->setTimestamp((int) $data['created']),
