+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\PaymentLink\Repository;
+
+use Drupal\Core\Database\Connection;
+use Drupal\Core\Session\AccountProxyInterface;
+use Drupal\rgds_core\PaymentLink\Model\PaymentLink;
+
+class PaymentLinkRepository {
+
+  private const string PAYMENT_LINK_BASE_TABLE = 'payment_link';
+  private const array PAYMENT_LINK_FIELDS = [
+    'institution_trigram',
+    'payment_link_url',
+    'uid',
+    'created',
+    'changed',
+  ];
+
+  public function __construct(
+    private readonly Connection $database,
+  ) {
+  }
+
+  public function deleteAll(): void {
+    $this->database->delete(self::PAYMENT_LINK_BASE_TABLE)
+      ->execute();
+  }
+
+  public function insertOrUpdate(PaymentLink $paymentLink, AccountProxyInterface $user): void {
+    $existingPaymentLink = $this->fetchByTrigram($paymentLink->getTrigram());
+    if ($existingPaymentLink instanceof PaymentLink) {
+      $this->update($existingPaymentLink, $user);
+      return;
+    }
+    $this->insert($paymentLink);
+  }
+
+  public function fetchByTrigram(string $trigram): ?PaymentLink {
+    $query = $this->database->select(self::PAYMENT_LINK_BASE_TABLE, 'ipl')
+      ->fields('ipl')
+      ->condition('ipl.institution_trigram', $trigram);
+
+    $data = $query->execute()?->fetchAssoc();
+    if (FALSE === \is_array($data)) {
+      return NULL;
+    }
+
+    return PaymentLink::fromDbRow($data);
+  }
+
+  private function insert(PaymentLink $paymentLink): void {
+    $this->database->insert(self::PAYMENT_LINK_BASE_TABLE)
+      ->fields(self::PAYMENT_LINK_FIELDS, [
+        $paymentLink->getTrigram(),
+        $paymentLink->getPaymentLinkUrl(),
+        $paymentLink->getUid(),
+        $paymentLink->getCreated()->format('U'),
+        $paymentLink->getChanged()->format('U'),
+      ])
+      ->execute();
+  }
+
+  private function update(PaymentLink $paymentLink, AccountProxyInterface $user): void {
+    $paymentLink = $paymentLink
+      ->withChanged(new \DateTimeImmutable())
+      ->withUid((int) $user->id());
+    $this->database->update(self::PAYMENT_LINK_BASE_TABLE)
+      ->fields([
+        'payment_link_url' => $paymentLink->getPaymentLinkUrl(),
+        'changed' => $paymentLink->getChanged()->format('U'),
+        'uid' => $paymentLink->getUid(),
+      ])
+      ->condition('institution_trigram', $paymentLink->getTrigram())
+      ->execute();
+  }
+
+}

