+namespace Drupal\rgds_core\PaymentLink\Controller;
+
+use Drupal\Component\Utility\UrlHelper;
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Messenger\MessengerInterface;
+use Drupal\Core\Messenger\MessengerTrait;
+use Drupal\Core\Routing\TrustedRedirectResponse;
+use Drupal\rgds_core\PaymentLink\Repository\PaymentLinkRepository;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\RedirectResponse;
+use Symfony\Component\HttpFoundation\Response;
+use Symfony\Component\HttpKernel\Exception\BadRequestHttpException;
+use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
+
+final class PaymentLinkRedirectionController implements ContainerInjectionInterface {
+
+  use MessengerTrait;
+
+  public function __construct(
+    private PaymentLinkRepository $paymentLinkRepository,
+    MessengerInterface $messenger,
+  ) {
+    $this->setMessenger($messenger);
+  }
+
+  public static function create(ContainerInterface $container): self {
+    return new static(
+      $container->get('rgds_core.payment_link.repository'),
+      $container->get('messenger'),
+    );
+  }
+
+  public function __invoke(string $trigram): Response {
+    if (0 === \preg_match('/^[a-zA-Z]{3}$/', $trigram)) {
+      throw new BadRequestHttpException();
+    }
+
+    $paymentLink = $this->paymentLinkRepository->fetchByTrigram($trigram);
+    if (NULL === $paymentLink) {
+      throw new NotFoundHttpException();
+    }
+
+    $linkUrl = $paymentLink->getPaymentLinkUrl();
+    if (UrlHelper::isExternal($linkUrl) && UrlHelper::isValid($linkUrl)) {
+      return new TrustedRedirectResponse($linkUrl);
+    }
+
+    $this->messenger()->addError("La redirection vers votre lien de paiement n'a pas pu être effectuée.");
+
+    return new RedirectResponse('/');
+  }
+
+}

