+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\PaymentLink\DataTransformer;
+
+use Drupal\Component\Utility\UrlHelper;
+use Drupal\Core\Url;
+use Drupal\rgds_core\PaymentLink\Exception\InvalidInstitutionTrigramException;
+use Drupal\rgds_core\PaymentLink\Exception\InvalidPaymentUrlException;
+use Drupal\rgds_core\PaymentLink\Exception\MissingMandatoryValueException;
+use Drupal\rgds_core\PaymentLink\Model\PaymentLink;
+use PhpOffice\PhpSpreadsheet\Cell\Cell;
+use PhpOffice\PhpSpreadsheet\Worksheet\Row;
+
+final class PhpSpreadsheetRowToPaymentLinkTransformer {
+
+  private const string TRIGRAM_COLUMN = 'C';
+  private const string PAYMENT_LINK_URL_COLUMN = 'F';
+
+  public function transform(Row $row, int $userId, \DateTimeImmutable $now): PaymentLink {
+    $cellIterator = $row->getCellIterator();
+    $cellIterator->setIterateOnlyExistingCells(FALSE);
+
+    $cells = [];
+    foreach ($cellIterator as $cell) {
+      if (!$cell instanceof Cell) {
+        continue;
+      }
+
+      $cells[$cell->getColumn()] = $cell->getValue();
+    }
+
+    return PaymentLink::fromUserInput(
+      $this->getTrigramFromCells($cells),
+      $this->getPaymentLinkUrlFromCells($cells)->toUriString(),
+      $userId,
+      $now,
+      $now,
+    );
+  }
+
+  private function getTrigramFromCells(array $cells): string {
+    $trigram = $cells[self::TRIGRAM_COLUMN] ?? NULL;
+    if (empty($trigram)) {
+      throw new MissingMandatoryValueException('Institution trigram is mandatory.');
+    }
+
+    if (0 === \preg_match('/^[a-zA-Z]{3}$/', $trigram)) {
+      throw new InvalidInstitutionTrigramException(\sprintf('Institution trigram should be a valid trigram, %s given.', $trigram));
+    }
+
+    return (string) $trigram;
+  }
+
+  private function getPaymentLinkUrlFromCells(array $cells): Url {
+    $urlValue = $cells[self::PAYMENT_LINK_URL_COLUMN] ?? NULL;
+    if (empty($urlValue)) {
+      throw new MissingMandatoryValueException('Payment URL is mandatory.');
+    }
+
+    if (FALSE === UrlHelper::isValid($urlValue, TRUE)) {
+      throw new InvalidPaymentUrlException(\sprintf('Payment URL must be valid and external, %s given.', $urlValue));
+    }
+
+    return Url::fromUri($urlValue);
+  }
+
+}

