+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\PaymentLink\Parser;
+
+use Drupal\Core\Logger\RfcLogLevel;
+use Drupal\Core\Session\AccountProxyInterface;
+use Drupal\Core\Utility\Error;
+use Drupal\rgds_core\PaymentLink\DataTransformer\PhpSpreadsheetRowToPaymentLinkTransformer;
+use PhpOffice\PhpSpreadsheet\Reader\Xlsx;
+use Psr\Log\LoggerInterface;
+
+final readonly class PaymentLinkXlsxFileParser {
+
+  /**
+   * We consider that the first row is the "header" so we skip it.
+   */
+  private const int START_ROW = 2;
+
+  public function __construct(
+    private PhpSpreadsheetRowToPaymentLinkTransformer $phpSpreadsheetRowToPaymentLinkTransformer,
+    private LoggerInterface $logger,
+  ) {
+  }
+
+  /**
+   * Parse a Xlsx file into an array of PaymentLink objects.
+   *
+   * @param string $filePath
+   *   Path of the file we want to parse.
+   * @param \Drupal\Core\Session\AccountProxyInterface $user
+   *   The current user that trigger this file parsing.
+   * @param \DateTimeImmutable $now
+   *   The current time when this file is being parsed.
+   *
+   * @return \Drupal\rgds_core\PaymentLink\Model\PaymentLink[]
+   *   List of PaymentLink objects.
+   *
+   * @throws \JsonException
+   * @throws \Throwable
+   */
+  public function parseToPaymentLinks(string $filePath, AccountProxyInterface $user, \DateTimeImmutable $now): array {
+    $reader = new Xlsx();
+    // Settings to read only data and do not read empty cells allow to
+    // skip rows with only null values.
+    $reader->setReadDataOnly(TRUE);
+    $reader->setReadEmptyCells(FALSE);
+    $spreadsheet = $reader->load($filePath);
+    $sheet = $spreadsheet->getSheet(0);
+
+    $items = [];
+    $userId = (int) $user->id();
+
+    try {
+      foreach ($sheet->getRowIterator(self::START_ROW) as $row) {
+        $cellIterator = $row->getCellIterator();
+        $cellIterator->setIterateOnlyExistingCells(FALSE);
+
+        try {
+          $items[] = $this->phpSpreadsheetRowToPaymentLinkTransformer->transform($row, $userId, $now);
+        }
+        catch (\Throwable $throwable) {
+          $this->logger->log(RfcLogLevel::ERROR, '%type: @message in %function (line %line of %file).', Error::decodeException($throwable));
+          continue;
+        }
+      }
+    }
+    catch (\Throwable $throwable) {
+      $this->logger->log(RfcLogLevel::ERROR, '%type: @message in %function (line %line of %file).', Error::decodeException($throwable));
+      throw $throwable;
+    }
+    finally {
+      $spreadsheet->disconnectWorksheets();
+      unset($spreadsheet);
+    }
+
+    return $items;
+  }
+
+}

