+use Drupal\rgds_core\PaymentLink\Controller\PaymentLinkRedirectionController;
+use Drupal\rgds_core\PaymentLink\Model\PaymentLink;
+use Drupal\rgds_core\PaymentLink\Repository\PaymentLinkRepository;
+use Symfony\Component\HttpFoundation\RedirectResponse;
+use Symfony\Component\HttpKernel\Exception\BadRequestHttpException;
+use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
+
+/**
+ * Class PaymentLinkRedirectionControllerTest.
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ *
+ * @package Drupal\Tests\rgds_core\Unit\PaymentLink
+ */
+final class PaymentLinkRedirectionControllerTest extends UnitTestCase {
+
+  private readonly PaymentLinkRedirectionController $paymentLinkRedirectionController;
+
+  private readonly PaymentLinkRepository $paymentLinkRepository;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->messenger = self::createMock(MessengerInterface::class);
+    $this->paymentLinkRepository = self::createMock(PaymentLinkRepository::class);
+    $this->paymentLinkRedirectionController = new PaymentLinkRedirectionController(
+      $this->paymentLinkRepository,
+      $this->messenger,
+    );
+  }
+
+  public function testRedirectForHappyPath(): void {
+    $this->paymentLinkRepository->expects($this->once())
+      ->method('fetchByTrigram')
+      ->willReturn($this->createValidPaymentLink(
+        'ABC',
+        'https://example.com/',
+      ));
+
+    $response = ($this->paymentLinkRedirectionController)('ABC');
+
+    self::assertInstanceOf(
+      TrustedRedirectResponse::class,
+      $response,
+    );
+    self::assertEquals(
+      'https://example.com/',
+      $response->getTargetUrl(),
+    );
+    self::assertEquals(
+      302,
+      $response->getStatusCode(),
+    );
+  }
+
+  public function testRedirectInvalidPaymentUrlShouldRedirectToFrontpage(): void {
+    $this->paymentLinkRepository->expects($this->once())
+      ->method('fetchByTrigram')
+      ->willReturn($this->createValidPaymentLink(
+        'ABC',
+        '/test',
+      ));
+
+    $response = ($this->paymentLinkRedirectionController)('ABC');
+
+    self::assertInstanceOf(
+      RedirectResponse::class,
+      $response,
+    );
+    self::assertEquals(
+      '/',
+      $response->getTargetUrl(),
+    );
+    self::assertEquals(
+      302,
+      $response->getStatusCode(),
+    );
+  }
+
+  public function testRedirectForMissingTrigram(): void {
+    $this->paymentLinkRepository->expects($this->once())
+      ->method('fetchByTrigram')
+      ->willReturn(NULL);
+
+    self::expectException(NotFoundHttpException::class);
+
+    ($this->paymentLinkRedirectionController)('ABC');
+  }
+
+  /**
+   * @dataProvider redirectForInvalidTrigramProvider()
+   */
+  public function testRedirectForInvalidTrigram(string $invalidTrigram): void {
+    self::expectException(BadRequestHttpException::class);
+
+    ($this->paymentLinkRedirectionController)($invalidTrigram);
+  }
+
+  public static function redirectForInvalidTrigramProvider(): \Generator {
+    yield 'Empty trigram' => [''];
+    yield '4 letters' => ['ABCD'];
+    yield '2 letters' => ['AB'];
+    yield 'At least 1 digit' => ['AB1'];
+  }
+
+  private function createValidPaymentLink(string $trigram, string $url): PaymentLink {
+    $now = new \DateTimeImmutable();
+
+    return PaymentLink::fromUserInput(
+      $trigram,
+      $url,
+      1,
+      $now,
+      $now,
+    );
+  }
+
+}

