+  public function testItParsesValidFileToPaymentLinks(): void {
+    $now = new \DateTimeImmutable();
+    $this->assertEquals(
+      [
+        $this->createValidPaymentLink('AAA', 'https://example.payment/etab-a', $now),
+        $this->createValidPaymentLink('AAB', 'https://example.payment/etab-b', $now),
