+
+// phpcs:disable Drupal.Commenting.DocComment.MissingShort
+class AverageTimesMonitoringCommandTest extends KernelTestBase {
+
+  use AssertMailTrait;
+
+  private const string EMERGENCY_WAITING_TIME_TABLE = 'emergency_average_waiting_time';
+
+  private const array WAITING_TIME_FIELDS = [
+    'time',
+    'site_id',
+    'average_waiting_time',
+    'average_waiting_patients',
+    'average_treated_patients',
+    'average_traumatology_time',
+    'average_medecine_time',
+  ];
+
+  private Connection $database;
+
+  private AverageTimeMonitoringCommands $command;
+
+  protected function setUp(): void {
+    parent::setUp();
+    $this->installEntitySchema('site_information_setting');
+    $this->installSchema('rgds_core', [self::EMERGENCY_WAITING_TIME_TABLE]);
+    $this->database = \Drupal::database();
+    $this->command = new AverageTimeMonitoringCommands(
+      \Drupal::service('rgds_core.emergency.finder.institution'),
+      \Drupal::service('rgds_core.emergency.storage.waiting_time'),
+      \Drupal::service('rgds_core.emergency.validator.average_time'),
+      \Drupal::service('language_manager'),
+      \Drupal::service('plugin.manager.mail'),
+      new Settings(['rgds_import_report_emails' => 'test@me.pls']),
+    );
+  }
+
+  /**
+   * @dataProvider siteDataProvider
+   */
+  public function testCommandSendMonitoring($totalAverageTimes, $expectedMessage, $expired = FALSE): void {
+    $site = $this->aSite(10);
+    $site->save();
+    for ($i = 0; $i < $totalAverageTimes; ++$i) {
+      // It Removes one day when expired, anyway it always removes minutes to avoid unique constraint error.
+      $baseTimestamp = \time() - ($expired ? 86401 : 0) - ($i * 100);
+      $this->insertAverageTimes($baseTimestamp, (int) $site->id());
+    }
+
+    $result = $this->command->checkEmergencyWaitingTime();
+
+    $this->assertEquals(DrushCommands::EXIT_SUCCESS, $result->getExitCode());
+    $this->assertCount(1, $emails = $this->getMails());
+    $this->assertMail('subject', 'Ramsay Sante - Monitoring temps d\'attente urgences');
+    $this->assertMail('from', $this->config('system.site')->get('mail'));
+    $this->assertMail('to', 'test@me.pls');
+    $this->assertMailString('body', $expectedMessage, 1, $emails[0]['body']);
+  }
+
+  public function siteDataProvider(): \Generator {
+    yield 'no data' => [
+      'total average times' => 0,
+      'message' => 'Le site n\'a pas de mise à jour depuis plus de 24 heures.',
+    ];
+    yield 'not enough average times' => [
+      'total average times' => 100,
+      'message' => 'De nombreuses mises à jour ont échoué pour le site (données invalides ou manquantes).',
+    ];
+    yield 'enough average times but expired' => [
+      'total average times' => 288,
+      'message' => 'Le site n\'a pas de mise à jour depuis plus de 24 heures.',
+      'expired' => TRUE,
+    ];
+  }
+
+  public function testCommandWithEnoughAverageTimes(): void {
+    $site = $this->aSite(1);
+    $site->save();
+    for ($i = 0; $i < 288; ++$i) {
+      $this->insertAverageTimes(\time() - ($i * 100), (int) $site->id());
+    }
+
+    $result = $this->command->checkEmergencyWaitingTime();
+
+    $this->assertEquals(DrushCommands::EXIT_SUCCESS, $result->getExitCode());
+    $this->assertCount(0, $this->getMails());
+  }
+
+  private function aSite(?int $siteId = NULL): SiteInterface {
+    return Site::create([
+      'type' => 'institution',
+      'field_emergencies_ws' => 'http://localhost/an-url',
+      'field_legacy_hospital_nid' => '1',
+      'status' => 1,
+      'site_url' => 'foo.com',
+      'name' => 'Test',
+      'id' => $siteId ?? \random_int(1, 1000),
+      'registered' => 1,
+    ]);
+  }
+
+  private function insertAverageTimes(?int $timestamp = NULL, ?int $siteId = NULL): void {
+    $this->database
+      ->insert(self::EMERGENCY_WAITING_TIME_TABLE)
+      ->fields(self::WAITING_TIME_FIELDS, [$timestamp ?? \time(), $siteId ?? '1', '1', '2', '3', '4', '5'])
+      ->execute();
+  }
+
+}

