+// phpcs:disable Drupal.Commenting.DocComment.MissingShort
+class AverageTimesValidatorTest extends UnitTestCase {
+
+  /**
+   * @dataProvider averageTimeProvider
+   */
+  public function testWaitingValidTimeLifeTime(
+    \DateTimeImmutable $aDateTime,
+    string $expectedConstraint,
+  ): void {
+    $waitingTime[] = $this->getAverageTimesArray($aDateTime->getTimestamp());
+    $sutAverageTimeValidator = new AverageTimeValidator();
+
+    $result = $sutAverageTimeValidator->validate($waitingTime);
+
+    $this->assertCount(1, $result);
+    foreach ($result as $violation) {
+      self::assertSame($expectedConstraint, $violation->getConstraint());
+    }
+  }
+
+  public function averageTimeProvider(): \Generator {
+    $now = \time();
+    yield 'is fresh average time' => [
+      'datetime' => \DateTimeImmutable::createFromFormat('U', (string) $now),
+      'violations' => 'ReliableRate',
+    ];
+    yield 'is almost exceed average time' => [
+      'datetime' => new \DateTimeImmutable('23 hours 59 minutes ago'),
+      'violations' => 'ReliableRate',
+    ];
+    yield 'is exceeded average time' => [
+      'datetime' => new \DateTimeImmutable('-2 days'),
+      'violations' => 'NotObsolete',
+    ];
+    yield 'is just exceeded average time' => [
+      'datetime' => new \DateTimeImmutable('24 hours ago'),
+      'violations' => 'NotObsolete',
+    ];
+    yield 'is in the future average time' => [
+      'datetime' => new \DateTimeImmutable('+2 days'),
+      'violations' => 'ReliableRate',
+    ];
+  }
+
+  /**
+   * @dataProvider averageTimeQuantityProvider
+   */
+  public function testWaitingTimeAllowedFailureRate(int $totalAverageTimes, int $expected): void {
+    $waitingTimeList = [];
+    for ($i = 0; $i < $totalAverageTimes; $i++) {
+      $waitingTimeList[] = $this->getAverageTimesArray();
+    }
+    $sut = new AverageTimeValidator();
+    $result = $sut->validate($waitingTimeList);
+    $this->assertCount($expected, $result);
+  }
+
+  public function averageTimeQuantityProvider(): \Generator {
+    yield 'no average time failure' => [
+      'totalAverageTimes' => 288,
+      'expected failure' => 0,
+    ];
+    yield 'just enough average time failure' => [
+      'totalAverageTimes' => 288 - 29,
+      'expected failure' => 0,
+    ];
+    yield 'too few average time items' => [
+      'totalAverageTimes' => 1,
+      'expected failure' => 1,
+    ];
+    yield 'exceed limit average time allowed failures' => [
+      'totalAverageTimes' => 288 - 30,
+      'expected failure' => 1,
+    ];
+  }
+
+  public function getAverageTimes(?int $now = NULL): AverageTimes {
+    return new AverageTimes(
+      $now ?? \time(),
+      1,
+      1,
+      2,
+      5,
+      1,
+    );
+  }
+
+  public function getAverageTimesArray(?int $aTime = NULL): array {
+    return [
+      'time' => $aTime ?? \time(),
+      'average_waiting_time' => 1,
+      'average_waiting_patients' => 1,
+      'average_treated_patients' => 2,
+      'average_traumatology_time' => 5,
+      'average_medicine_time' => 1,
+    ];
+  }
