+export async function cropImage({
+  url,
+  x,
+  y,
+  width,
+  height,
+}: {
+  url: string;
+  x: number;
+  y: number;
+  width: number;
+  height: number;
+}): Promise<string> {
+  const response = await fetch(`/ckeditor5-cropper/image_crop`, {
+    method: 'POST',
+    headers: {
+      'Content-Type': 'application/json',
+    },
+    body: JSON.stringify({
+      image: url,
+      cropDefinition: {
+        width,
+        height,
+        x,
+        y,
+      },
+    }),
+  });
+
+  const data = await response.json();
+  return data.cropped_image.url;
+}

