+import { Plugin, ButtonView, Dialog, ImageBlock } from 'ckeditor5';
+
+import { CropperDialogView } from './cropper-modal-view';
+import { cropImage } from './api';
+import { getHTMLImageElementFromCKImageElement } from './utils';
+import { CROPPER_CROPPED_IMAGE_ID } from './constants';
+import cropperSvg from '../../../../icons/cropper.svg?raw';
