+                          src: croppedImageUrl,
+                          width: croppedImage.dataset.cropWidth || '',
+                          height: croppedImage.dataset.cropHeight || '',
+
+                          // custom crop attributes
+                          dataCropX: croppedImage.dataset.cropX || '',
+                          dataCropY: croppedImage.dataset.cropY || '',
+                          dataCropWidth: croppedImage.dataset.cropWidth || '',
+                          dataCropHeight: croppedImage.dataset.cropHeight || '',
+                          dataOriginalSrc:
+                            htmlImageElement.dataset.originalSrc ||
+                            htmlImageElement.getAttribute('src') ||
+                            '',
+                        },
+                        selectedElement!,
+                      );
+                    });
+                  }
+
+                  cropperDialogView.destroy();
+                  dialog.hide();
+                },
+              },
+            ],
+            onHide: () => {
+              cropperDialogView.destroy();
+            },
+          });
+        }
+      });
+
+      return button;
+    });
+
+    const extraAttributesMap = {
+      dataCropX: 'data-crop-x',
+      dataCropY: 'data-crop-y',
+      dataCropWidth: 'data-crop-width',
+      dataCropHeight: 'data-crop-height',
+      dataOriginalSrc: 'data-original-src',
+    };
+
+    editor.model.schema.extend('imageBlock', {
+      allowAttributes: Object.keys(extraAttributesMap),
+    });
+
+    for (const [modelAttribute, viewAttribute] of Object.entries(
+      extraAttributesMap,
+    )) {
+      editor.conversion.for('upcast').attributeToAttribute({
+        view: viewAttribute,
+        model: modelAttribute,
+      });
+
+      editor.conversion.for('dataDowncast').attributeToAttribute({
+        model: modelAttribute,
+        view: viewAttribute,
+        converterPriority: 'high',
+      });
+    }
+
+    editor.conversion.for('dataDowncast').attributeToAttribute({
+      model: {
+        name: 'imageBlock',
+        key: 'source',
+      },
+      view: 'src',
+      converterPriority: 'high',
+    });
+
+    editor.conversion.for('downcast').add((dispatcher) => {
+      for (const [modelAttribute, viewAttribute] of Object.entries(
+        extraAttributesMap,
+      )) {
+        dispatcher.on(
+          `attribute:${modelAttribute}:imageBlock`,
+          (_, data, conversionApi) => {
+            const viewWriter = conversionApi.writer;
+            const viewFigure = conversionApi.mapper.toViewElement(data.item);
+            const viewImage = viewFigure.getChild(0);
+
+            if (!viewImage) {
+              return;
+            }
+
+            if (data.attributeNewValue !== null) {
+              viewWriter.setAttribute(
+                viewAttribute,
+                data.attributeNewValue,
+                viewImage,
+              );
+            } else {
+              viewWriter.removeAttribute(viewAttribute, viewImage);
+            }
+          },
+          { priority: 'low' },
+        );
+      }
+    });
+  }
+}

