+import { Editor, Element, ViewEmptyElement, ViewUIElement } from 'ckeditor5';
+
+export function getHTMLImageElementFromCKImageElement(
+  editor: Editor,
+  ckImageElement: Element,
+): HTMLImageElement | null {
+  const imageElement = editor.editing.mapper.toViewElement(ckImageElement);
+
+  if (!imageElement) {
+    throw new Error('Image element not found');
+  }
+
+  // ckeditor5 typings are incorrect, so we need to cast the type
+  const children = Array.from(imageElement.getChildren()) as unknown as (
+    | ViewEmptyElement
+    | ViewUIElement
+  )[];
+  const img = children.find(
+    (child) => child.name === 'img',
+  ) as ViewEmptyElement;
+
+  return editor.editing.view.domConverter.mapViewToDom(
+    img!,
+  ) as HTMLImageElement;
+}

