+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Controller;
+
+use Drupal\Core\Controller\ControllerBase;
+use Drupal\Core\File\FileUrlGeneratorInterface;
+use Drupal\ckeditor5_cropper\Cropper\ImageCropperInterface;
+use Drupal\ckeditor5_cropper\Dto\ImageCropDefinition;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\JsonResponse;
+use Symfony\Component\HttpFoundation\RequestStack;
+
+final class ImageCropController extends ControllerBase {
+
+  public function __construct(
+    private readonly RequestStack $requestStack,
+    private readonly FileUrlGeneratorInterface $fileUrlGenerator,
+    private readonly ImageCropperInterface $imageCropper,
+  ) {
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public static function create(ContainerInterface $container): self {
+    return new static(
+      $container->get('request_stack'),
+      $container->get('file_url_generator'),
+      $container->get('ckeditor5_cropper.image_cropper'),
+    );
+  }
+
+  public function __invoke(): JsonResponse {
+    try {
+      $data = $this->getDataFromInput();
+      $imageCropDefinition = ImageCropDefinition::fromInput($data['cropDefinition'] ?? []);
+      if (FALSE === isset($data['image'])) {
+        throw new \InvalidArgumentException('Image must be set.');
+      }
+
+      $file = $this->imageCropper->crop($data['image'], $imageCropDefinition);
+
+      return new JsonResponse([
+        'success' => TRUE,
+        'message' => 'Image croppée avec succès',
+        'original_path' => (string) $data['image'],
+        'cropped_image' => [
+          'file_id' => $file->id(),
+          'filename' => $file->getFilename(),
+          'uri' => $file->getFileUri(),
+          'url' => $this->fileUrlGenerator->generateAbsoluteString($file->getFileUri() ?? ''),
+        ],
+      ]);
+    }
+    catch (\Exception $exception) {
+      return new JsonResponse([
+        'data' => [],
+        'error' => $exception->getMessage(),
+      ],
+        JsonResponse::HTTP_BAD_REQUEST,
+      );
+    }
+  }
+
+  private function getDataFromInput(): array {
+    $rawData = $this->requestStack->getCurrentRequest()?->getContent();
+    if (FALSE === \is_string($rawData)) {
+      throw new \InvalidArgumentException('Invalid JSON string.');
+    }
+
+    try {
+      $decoded = \json_decode($rawData, TRUE, 512, \JSON_THROW_ON_ERROR);
+      return (FALSE === \is_array($decoded)) ? [] : $decoded;
+    }
+    catch (\JsonException $exception) {
+      throw new \InvalidArgumentException('Invalid JSON string.');
+    }
+  }
+
+}

