+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Cropper;
+
+use Drupal\Core\File\FileSystem;
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Image\ImageFactory;
+use Drupal\Core\Image\ImageInterface;
+use Drupal\ckeditor5_cropper\Dto\ImageCropDefinition;
+use Drupal\ckeditor5_cropper\Resolver\ImageResolverChain;
+use Drupal\file\Entity\File;
+use Drupal\file\FileInterface;
+
+class ImageCropper implements ImageCropperInterface {
+
+  public function __construct(
+    private readonly ImageFactory $imageFactory,
+    private readonly FileSystem $fileSystem,
+    private readonly ImageResolverChain $imageResolverChain,
+  ) {
+  }
+
+  public function crop(string $imageData, ImageCropDefinition $imageCropDefinition): FileInterface {
+    $localFilePath = $this->imageResolverChain->resolve($imageData);
+    if (NULL === $localFilePath) {
+      throw new \RuntimeException('Unable to resolve image data.');
+    }
+
+    $image = $this->imageFactory->get($localFilePath);
+
+    if (FALSE === $image->isValid()) {
+      throw new \InvalidArgumentException('Image seems not to be valid.');
+    }
+
+    // Actually do the image crop.
+    $success = $image->crop(
+      $imageCropDefinition->getPositionX(),
+      $imageCropDefinition->getPositionY(),
+      $imageCropDefinition->getWidth(),
+      $imageCropDefinition->getHeight(),
+    );
+
+    if (FALSE === $success) {
+      throw new \Exception('Échec du crop de l\'image');
+    }
+
+    return $this->saveCroppedImage($image, $localFilePath);
+  }
+
+  private function saveCroppedImage(ImageInterface $image, string $localFilePath): FileInterface {
+    // Get a unique name for the cropped file.
+    $croppedFilename = \sprintf(
+      'cropped_%s.%s',
+      \uniqid(),
+      \pathinfo($localFilePath, \PATHINFO_EXTENSION),
+    );
+    $croppedPath = 'public://ckeditor5_cropper' . $croppedFilename;
+
+    // Check that the directory exists.
+    $directory = \dirname($croppedPath);
+    $this->fileSystem->prepareDirectory($directory, FileSystemInterface::CREATE_DIRECTORY);
+
+    // Save the cropped image.
+    if (FALSE === $image->save($croppedPath)) {
+      throw new \LogicException('Impossible de sauvegarder l\'image croppée');
+    }
+
+    // Create a File entity for the cropped image.
+    $file = File::create([
+      'filename' => $croppedFilename,
+      'uri' => $croppedPath,
+      'status' => 1,
+    ]);
+    $file->save();
+
+    return $file;
+  }
+
+}

