+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Dto;
+
+class ImageCropDefinition {
+
+  private function __construct(
+    private readonly int $width,
+    private readonly int $height,
+    private readonly int $positionX,
+    private readonly int $positionY,
+  ) {
+  }
+
+  public static function fromInput(array $data): self {
+    $positiveIntegerFields = ['width', 'height'];
+    foreach ($positiveIntegerFields as $positiveIntegerFieldKey) {
+      if (FALSE === self::isPositiveInteger($data, $positiveIntegerFieldKey)) {
+        throw new \InvalidArgumentException(\sprintf('%s must be a positive integer.', $positiveIntegerFieldKey));
+      }
+    }
+
+    $notNegativeIntegerFields = ['x', 'y'];
+    foreach ($notNegativeIntegerFields as $notNegativeIntegerFieldKey) {
+      if (FALSE === self::isNotNegativeInteger($data, $notNegativeIntegerFieldKey)) {
+        throw new \InvalidArgumentException(\sprintf('%s must be a non-negative integer.', $notNegativeIntegerFieldKey));
+      }
+    }
+
+    return new self(
+      (int) $data['width'],
+      (int) $data['height'],
+      (int) $data['x'],
+      (int) $data['y'],
+    );
+  }
+
+  public function getWidth(): int {
+    return $this->width;
+  }
+
+  public function getHeight(): int {
+    return $this->height;
+  }
+
+  public function getPositionX(): int {
+    return $this->positionX;
+  }
+
+  public function getPositionY(): int {
+    return $this->positionY;
+  }
+
+  private static function isPositiveInteger(array $data, string $key): bool {
+    return !(FALSE === isset($data[$key])
+      || FALSE === \is_int($data[$key])
+      || $data[$key] < 1);
+  }
+
+  private static function isNotNegativeInteger(array $data, string $key): bool {
+    return !(FALSE === isset($data[$key])
+      || FALSE === \is_int($data[$key])
+      || $data[$key] < 0);
+  }
+
+}

