+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Resolver;
+
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\ckeditor5_cropper\Util\ImageExtensionDetector;
+
+class Base64ImageResolver implements ImageResolverInterface {
+
+  public function __construct(
+    private FileSystemInterface $fileSystem,
+  ) {
+  }
+
+  public function getOrder(): int {
+    return 90;
+  }
+
+  public function applies(string $imagePath): bool {
+    // Checks if an image path starts with data:image/.
+    if (\preg_match('/^data:image\/([a-zA-Z0-9+\/]+);base64,/', $imagePath)) {
+      return TRUE;
+    }
+
+    // Checks if it's pure base64 (without data: prefix),
+    // and once decoded, it looks like an image.
+    if (\preg_match('/^[a-zA-Z0-9\/\r\n+]*={0,2}$/', $imagePath)) {
+      $decoded = \base64_decode($imagePath, TRUE);
+      if (FALSE !== $decoded) {
+        // Detects Image Format based on its magic bytes.
+        return NULL !== $this->getExtension($decoded);
+      }
+    }
+
+    return FALSE;
+  }
+
+  /**
+   * Treats a base64 encoded image and temporarily saves it.
+   *
+   * @param string $imagePath
+   *   The base64 encoded string.
+   *
+   * @return string|null
+   *   Path of the temporary file or NULL if error.
+   */
+  public function resolve(string $imagePath): ?string {
+    return $this->pipeline($imagePath, [
+      fn($path) => $this->extractImageData($path),
+      fn($data) => $this->validateSize($data),
+      fn($data) => $this->validateExtension($data),
+      fn($data) => $this->createAndWriteFile($data),
+      fn($file) => $this->validateFile($file),
+    ]);
+  }
+
+  private function pipeline(mixed $input, array $steps): ?string {
+    try {
+      foreach ($steps as $step) {
+        $input = $step($input);
+        if (NULL === $input) {
+          return NULL;
+        }
+      }
+      return $input;
+    }
+    catch (\Exception $exception) {
+      return NULL;
+    }
+  }
+
+  /**
+   * Detects Image Format based on its magic bytes.
+   *
+   * @param string $imageData
+   *   Binary data of the image.
+   *
+   * @return string|null
+   *   Format extension that has been detected.
+   */
+  private function getExtension(string $imageData): ?string {
+    return ImageExtensionDetector::fromBase64($imageData);
+  }
+
+  private function extractImageData(string $imagePath): ?array {
+    if (TRUE === $this->isDataUri($imagePath)) {
+      return $this->processDataUri($imagePath);
+    }
+
+    return $this->processBase64($imagePath);
+  }
+
+  private function processDataUri(string $imagePath): ?array {
+    if (FALSE === \preg_match('/^data:image\/([a-zA-Z0-9+\/]+);base64,(.+)$/', $imagePath, $matches)) {
+      return NULL;
+    }
+
+    $mimeType = $matches[1];
+    $base64Data = $matches[2];
+
+    $extension = ImageExtensionDetector::fromMimeType($mimeType);
+
+    $imageData = \base64_decode($base64Data, TRUE);
+    if (FALSE === $imageData) {
+      return NULL;
+    }
+
+    return ['data' => $imageData, 'extension' => $extension];
+  }
+
+  private function isDataUri(string $imagePath): bool {
+    return 1 === \preg_match('/^data:image\/([a-zA-Z0-9+\/]+);base64,(.+)$/', $imagePath);
+  }
+
+  private function processBase64(string $imagePath): ?array {
+    $imageData = \base64_decode($imagePath, TRUE);
+    if (FALSE === $imageData) {
+      return NULL;
+    }
+
+    $extension = $this->getExtension($imageData);
+    if (NULL === $extension) {
+      return NULL;
+    }
+
+    return ['data' => $imageData, 'extension' => $extension];
+  }
+
+  private function validateSize(array $imageData): ?array {
+    if (\strlen($imageData['data']) > self::MAX_FILE_SIZE) {
+      return NULL;
+    }
+    return $imageData;
+  }
+
+  private function validateExtension(array $imageData): ?array {
+    $extension = $imageData['extension'] ?? '';
+    if (FALSE === \in_array($extension, self::ALLOWED_EXTENSIONS, TRUE)) {
+      return NULL;
+    }
+
+    return $imageData;
+  }
+
+  private function createAndWriteFile(array $imageData): ?string {
+    $tempFile = $this->createTempFile($imageData['extension'] ?? '');
+    if (NULL === $tempFile) {
+      return NULL;
+    }
+
+    if (FALSE === $this->writeImageData($tempFile, $imageData['data'])) {
+      return NULL;
+    }
+
+    return $tempFile;
+  }
+
+  private function createTempFile(string $extension): ?string {
+    $tempFile = $this->fileSystem->tempnam('temporary://', 'base64_image_');
+
+    if (FALSE === \is_string($tempFile)) {
+      return NULL;
+    }
+
+    return $tempFile . '.' . $extension;
+  }
+
+  private function validateFile(string $tempFile): ?string {
+    if (TRUE === $this->validateImageFile($tempFile)) {
+      return $tempFile;
+    }
+
+    $this->cleanupFile($tempFile);
+    return NULL;
+  }
+
+  private function writeImageData(string $tempFile, string $imageData): bool {
+    return FALSE !== \file_put_contents($tempFile, $imageData);
+  }
+
+  private function validateImageFile(string $tempFile): bool {
+    return FALSE !== \getimagesize($tempFile);
+  }
+
+  private function cleanupFile(string $tempFile): void {
+    if (FALSE === \file_exists($tempFile)) {
+      return;
+    }
+    \unlink($tempFile);
+  }
+
+}

