+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Resolver;
+
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Http\ClientFactory;
+use Drupal\ckeditor5_cropper\Util\ImageExtensionDetector;
+use Psr\Http\Message\ResponseInterface;
+use Symfony\Component\HttpFoundation\RequestStack;
+
+class ExternalImageResolver implements ImageResolverInterface {
+
+  public function __construct(
+    private readonly ClientFactory $clientFactory,
+    private readonly FileSystemInterface $fileSystem,
+    private readonly RequestStack $requestStack,
+  ) {
+  }
+
+  public function getOrder(): int {
+    return 10;
+  }
+
+  public function applies(string $imagePath): bool {
+    if (FALSE === \filter_var($imagePath, \FILTER_VALIDATE_URL)) {
+      return FALSE;
+    }
+
+    $urlHost = \parse_url($imagePath, \PHP_URL_HOST);
+    $currentHost = $this->requestStack->getCurrentRequest()?->getHost();
+
+    // If it's the same domain, it's not "external".
+    return $urlHost !== $currentHost;
+  }
+
+  /**
+   * Download an external image in a temporary file.
+   *
+   * @param string $imagePath
+   *   URL we want to download.
+   *
+   * @return string|null
+   *   Temporary file path, or NULL if error.
+   */
+  public function resolve(string $imagePath): ?string {
+    return $this->pipeline($imagePath, [
+      fn($path) => $this->downloadImage($path),
+      fn($response) => $this->validateContentType($response),
+      fn($response) => $this->createAndWriteFile($response),
+    ]);
+  }
+
+  private function pipeline(mixed $input, array $steps): ?string {
+    try {
+      foreach ($steps as $step) {
+        $input = $step($input);
+        if (NULL === $input) {
+          return NULL;
+        }
+      }
+      return $input;
+    }
+    catch (\Exception $exception) {
+      return NULL;
+    }
+  }
+
+  /**
+   * Downloads the image via HTTP request.
+   */
+  private function downloadImage(string $imagePath): ?ResponseInterface {
+    $client = $this->clientFactory->fromOptions([
+      'verify' => TRUE,
+      'timeout' => 30,
+    ]);
+
+    $response = $client->get($imagePath);
+    if (200 !== $response->getStatusCode()) {
+      return NULL;
+    }
+
+    return $response;
+  }
+
+  /**
+   * Validates the Content-Type header of the response.
+   */
+  private function validateContentType(ResponseInterface $response): ?ResponseInterface {
+    $contentType = $response->getHeaderLine('Content-Type');
+    if (FALSE === \str_starts_with($contentType, 'image/')) {
+      return NULL;
+    }
+
+    return $response;
+  }
+
+  /**
+   * Creates a temporary file with the image content.
+   */
+  private function createAndWriteFile(ResponseInterface $response): ?string {
+    $responseBody = (string) $response->getBody();
+
+    $tempFile = $this->createTempFile($this->getExtension($responseBody));
+    if (NULL === $tempFile) {
+      return NULL;
+    }
+
+    if (FALSE === $this->writeImageData($tempFile, $responseBody)) {
+      return NULL;
+    }
+
+    return $tempFile;
+  }
+
+  private function createTempFile(?string $extension): ?string {
+    if (NULL === $extension || '' === $extension) {
+      return NULL;
+    }
+
+    // Create temp file with appropriate extension.
+    $tempFile = $this->fileSystem->tempnam('temporary://', 'image_crop_');
+    if (FALSE === \is_string($tempFile)) {
+      return NULL;
+    }
+
+    // Add extension to the temp file.
+    $newTempFile = $tempFile . '.' . $extension;
+    $this->fileSystem->move($tempFile, $newTempFile);
+
+    return $newTempFile;
+  }
+
+  private function writeImageData(string $tempFile, string $responseBody): bool {
+    return FALSE !== \file_put_contents($tempFile, $responseBody);
+  }
+
+  private function getExtension(string $content): ?string {
+    return ImageExtensionDetector::fromBinary($content);
+  }
+
+}

