+namespace Drupal\ckeditor5_cropper\Resolver;
+
+final class ImageResolverChain {
+
+  /**
+   * An array of ImageResolvers.
+   *
+   * @var ImageResolverInterface[]
+   */
+  private array $resolvers = [];
+
+  public function addResolver(ImageResolverInterface $resolver): void {
+    $this->resolvers[] = $resolver;
+    // Order by priority.
+    \usort($this->resolvers, static fn($resolverA, $resolverB) => $resolverA->getOrder() <=> $resolverB->getOrder());
+  }
+
+  public function resolve(string $imagePath): ?string {
+    foreach ($this->resolvers as $resolver) {
+      if (FALSE === $resolver->applies($imagePath)) {
+        continue;
+      }
+      return $resolver->resolve($imagePath);
+    }
+    return NULL;
+  }
+
+}

