+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Resolver;
+
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\StreamWrapper\StreamWrapperManagerInterface;
+
+class LocalImageResolver implements ImageResolverInterface {
+
+  public function __construct(
+    private readonly FileSystemInterface $fileSystem,
+    private readonly StreamWrapperManagerInterface $streamWrapperManager,
+  ) {
+  }
+
+  public function getOrder(): int {
+    return 0;
+  }
+
+  public function applies(string $imagePath): bool {
+    return (\str_starts_with($imagePath, '/sites/') ||
+      $this->streamWrapperManager->isValidUri($imagePath));
+  }
+
+  public function resolve(string $imagePath): ?string {
+    if (\str_starts_with($imagePath, '/sites/')) {
+      $localPath = \DRUPAL_ROOT . $imagePath;
+      return \file_exists($localPath) ? $localPath : NULL;
+    }
+
+    if ($this->streamWrapperManager->isValidUri($imagePath)) {
+      $localPath = $this->fileSystem->realpath($imagePath);
+      return $localPath && \file_exists($localPath) ? $localPath : NULL;
+    }
+
+    $publicPath = 'public://' . \ltrim($imagePath, '/');
+    $localPath = $this->fileSystem->realpath($publicPath);
+
+    return $localPath && \file_exists($localPath) ? $localPath : NULL;
+  }
+
+}

