+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Resolver;
+
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\File\FileUrlGeneratorInterface;
+use Symfony\Component\HttpFoundation\RequestStack;
+
+class SameDomainImageResolver implements ImageResolverInterface {
+
+  public function __construct(
+    protected readonly FileSystemInterface $fileSystem,
+    protected readonly FileUrlGeneratorInterface $fileUrlGenerator,
+    protected readonly RequestStack $requestStack,
+  ) {}
+
+  public function getOrder(): int {
+    return 50;
+  }
+
+  public function applies(string $imagePath): bool {
+    if (FALSE === \filter_var($imagePath, \FILTER_VALIDATE_URL)) {
+      return FALSE;
+    }
+
+    $urlHost = \parse_url($imagePath, \PHP_URL_HOST);
+    if (FALSE === \is_string($urlHost)) {
+      return FALSE;
+    }
+
+    return $urlHost === $this->requestStack->getCurrentRequest()?->getHost();
+  }
+
+  public function resolve(string $imagePath): ?string {
+    try {
+      // Validate that this is an image based on the extension.
+      $path = \parse_url($imagePath, \PHP_URL_PATH);
+      if (FALSE === \is_string($path)) {
+        return NULL;
+      }
+
+      $extension = \strtolower(\pathinfo($path, \PATHINFO_EXTENSION));
+      if (FALSE === \in_array($extension, self::ALLOWED_EXTENSIONS, TRUE)) {
+        return NULL;
+      }
+
+      // Extracts path from URL.
+      $path = \parse_url($imagePath, \PHP_URL_PATH);
+      if (FALSE === \is_string($path)) {
+        return NULL;
+      }
+
+      // Try to find local file.
+      $localPath = $this->findLocalFile($path);
+
+      if (NULL !== $localPath && TRUE === \file_exists($localPath)) {
+        return $this->copyToTemporary($localPath, $extension);
+      }
+
+      return NULL;
+
+    }
+    catch (\Exception $e) {
+      \Drupal::logger('image_crop')->error('Erreur lors de la résolution same-domain: @message', [
+        '@message' => $e->getMessage(),
+      ]);
+      return NULL;
+    }
+  }
+
+  /**
+   * Finds the local file based on URL path.
+   *
+   * @param string $urlPath
+   *   URL path we want to finds the local file from.
+   */
+  protected function findLocalFile(string $urlPath): ?string {
+    // Try to get it directly from the Drupal root.
+    $directPath = \DRUPAL_ROOT . $urlPath;
+    if (\file_exists($directPath)) {
+      return $directPath;
+    }
+
+    // Try with public:// for sites/default/files pattern.
+    if (\str_starts_with($urlPath, '/sites/default/files/')) {
+      $relativePath = \str_replace('/sites/default/files/', '', $urlPath);
+      $publicUri = 'public://' . $relativePath;
+      $realPath = $this->fileSystem->realpath($publicUri);
+      if ($realPath && \file_exists($realPath)) {
+        return $realPath;
+      }
+    }
+
+    // Try to get local file for image styles pattern.
+    if (\preg_match('#/files/styles/([^/]+)/public/(.+)#', $urlPath, $matches)) {
+      $originalPath = 'public://' . $matches[2];
+      $realPath = $this->fileSystem->realpath($originalPath);
+      if ($realPath && \file_exists($realPath)) {
+        return $realPath;
+      }
+    }
+
+    // Fallback: try to get the files directly from sites/default directory.
+    if (TRUE === \str_starts_with($urlPath, '/sites/default/')) {
+      $withoutPrefix = \str_replace('/sites/default/', '/', $urlPath);
+      return $this->findLocalFile($withoutPrefix);
+    }
+
+    return NULL;
+  }
+
+  /**
+   * Copies the file to a temporary one.
+   *
+   * @param string $sourcePath
+   *   Path to the source path.
+   * @param string $extension
+   *   Extension to be added to the temporary file name.
+   *
+   * @return string|null
+   *   The temporary file name.
+   */
+  protected function copyToTemporary(string $sourcePath, string $extension): ?string {
+    $tempFile = $this->fileSystem->tempnam('temporary://', 'same_domain_');
+    if (FALSE === \is_string($tempFile)) {
+      return NULL;
+    }
+
+    $tempFile .= '.' . $extension;
+    if (FALSE === \copy($sourcePath, $tempFile)) {
+      return NULL;
+    }
+
+    return $tempFile;
+  }
+
+}

