+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\ckeditor5_cropper\Util;
+
+/**
+ * Utility class to detect image formats.
+ */
+class ImageExtensionDetector {
+
+  private const array MIME_TO_EXTENSION = [
+    'jpeg' => 'jpg',
+    'jpg' => 'jpg',
+    'png' => 'png',
+    'gif' => 'gif',
+    'webp' => 'webp',
+    'bmp' => 'bmp',
+  ];
+
+  public static function fromMimeType(string $mimeType): ?string {
+    return self::MIME_TO_EXTENSION[$mimeType] ?? NULL;
+  }
+
+  /**
+   * Detects image format from binary data.
+   *
+   * @param string $data
+   *   Raw binary image data.
+   *
+   * @return string|null
+   *   File extension or NULL if format couldn't be determined.
+   */
+  public static function fromBinary(string $data): ?string {
+    if (\strlen($data) < 12) {
+      return NULL;
+    }
+
+    $signature = \substr($data, 0, 12);
+
+    // JPEG.
+    if (0 === \strncmp($signature, "\xFF\xD8\xFF", 3)) {
+      return 'jpg';
+    }
+
+    // PNG.
+    if (0 === \strncmp($signature, "\x89\x50\x4E\x47\x0D\x0A\x1A\x0A", 8)) {
+      return 'png';
+    }
+
+    // GIF.
+    if (0 === \strncmp($signature, "GIF87a", 6)|| 0 === \strncmp($signature, "GIF89a", 6)) {
+      return 'gif';
+    }
+
+    // WebP.
+    if (0 === \strncmp($signature, "RIFF", 4) && 0 === \strncmp(\substr($data, 8, 4), "WEBP", 4)) {
+      return 'webp';
+    }
+
+    // BMP.
+    if (0 === \strncmp($signature, "BM", 2)) {
+      return 'bmp';
+    }
+
+    return NULL;
+  }
+
+  /**
+   * Detects image format from data URI or base64 string.
+   *
+   * @param string $dataString
+   *   Data URI or raw base64 string.
+   *
+   * @return string|null
+   *   File extension or NULL if format couldn't be determined.
+   */
+  public static function fromBase64(string $dataString): ?string {
+    // Handle data URI.
+    if (\preg_match('/^data:image\/([a-zA-Z0-9+\/]+);base64,(.+)$/', $dataString, $matches)) {
+      $mimeType = $matches[1];
+      $base64Data = $matches[2];
+
+      // Try to extract from MIME type first.
+      $mimeToExtension = [
+        'jpeg' => 'jpg',
+        'jpg' => 'jpg',
+        'png' => 'png',
+        'gif' => 'gif',
+        'webp' => 'webp',
+        'bmp' => 'bmp',
+      ];
+
+      if (isset($mimeToExtension[$mimeType])) {
+        return $mimeToExtension[$mimeType];
+      }
+
+      // Decode and analyze the content.
+      $data = \base64_decode($base64Data, TRUE);
+    }
+    else {
+      // Treat as raw base64.
+      $data = \base64_decode($dataString, TRUE);
+    }
+
+    if (FALSE === $data) {
+      return NULL;
+    }
+
+    return self::fromBinary($data);
+  }
+
+}

