+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Commands;
+
+use Consolidation\AnnotatedCommand\CommandResult;
+use Drupal\Core\Language\LanguageManagerInterface;
+use Drupal\Core\Mail\MailManagerInterface;
+use Drupal\Core\Site\Settings;
+use Drupal\rgds_core\Commands\Result\MaintenanceModeCommandResult;
+use Drupal\rgds_core\Emergency\Finder\EmergencyInstitutionFinder;
+use Drupal\rgds_core\Emergency\Storage\EmergencyWaitingTimeStorage;
+use Drupal\rgds_core\Emergency\Validator\AverageTimeValidator;
+use Drupal\rgds_core\Model\Admin\MaintenanceMode;
+use Drush\Commands\DrushCommands;
+
+/**
+ * Class AverageTimeMonitoringCommands.
+ *
+ * @SuppressWarnings(PHPMD.CouplingBetweenObjects)
+ *
+ * @final
+ *
+ * @package Drupal\rgds_core\Emergency\Commands
+ */
+final class AverageTimeMonitoringCommands extends DrushCommands {
+
+  public function __construct(
+    private readonly EmergencyInstitutionFinder $emergencyInstitutionFinder,
+    private readonly EmergencyWaitingTimeStorage $waitingTimeStorage,
+    private readonly AverageTimeValidator $averageTimeValidator,
+    private readonly LanguageManagerInterface $languageManager,
+    private readonly MailManagerInterface $mailer,
+    private readonly Settings $settings,
+  ) {
+    parent::__construct();
+  }
+
+  /**
+   * Check if there is something wrong with emergency waiting times import.
+   *
+   * @command emergency:monitoring
+   * @usage drush emergency:monitoring
+   */
+  public function checkEmergencyWaitingTime(): CommandResult {
+    if (MaintenanceMode::isOn()) {
+      return MaintenanceModeCommandResult::exit();
+    }
+
+    $commandStartTime = new \DateTimeImmutable();
+    $sitesWithEmergencyWs = $this->emergencyInstitutionFinder->findAllByEmergencyWebService();
+
+    if ([] === $sitesWithEmergencyWs) {
+      $this->logger()->debug('No emergency webservice has been set');
+
+      return CommandResult::exitCode(self::EXIT_SUCCESS);
+    }
+
+    /** @var array<string, array<string>> $violationList */
+    $violationList = [];
+    try {
+      foreach ($sitesWithEmergencyWs as $site) {
+        $averageTimesList = $this->waitingTimeStorage->queryEmergencyWaitingTimeBySiteStartingFrom(
+          (string) $site->id(),
+          (string) (new \DateTimeImmutable('-1 day'))->getTimestamp()
+        )
+          ->execute()
+          ?->fetchAll(\PDO::FETCH_ASSOC);
+
+        if (NULL === $averageTimesList) {
+          throw new \DomainException('Database error when trying to get average time for monitoring');
+        }
+
+        /** @var array<\Drupal\rgds_core\Emergency\Violation\AverageTimeViolation> $averageTimesSiteViolations */
+        $averageTimesSiteViolations = $this->averageTimeValidator->validate($averageTimesList);
+        if (empty($averageTimesSiteViolations)) {
+          continue;
+        }
+
+        foreach ($averageTimesSiteViolations as $violation) {
+          $violationList[$violation->getConstraint()][] = $site->getName();
+        }
+      }
+    }
+    catch (\Throwable $exception) {
+      $this->logger()->error(
+        \sprintf(
+          '[%s] %s',
+          (new \DateTimeImmutable())->format('Y-m-d H:i:s'),
+          $exception->getMessage(),
+        )
+      );
+
+      return CommandResult::exitCode(self::EXIT_FAILURE);
+    }
+
+    if ([] !== $violationList) {
+      $this->mail($violationList, $commandStartTime);
+    }
+
+    return CommandResult::exitCode(self::EXIT_SUCCESS);
+  }
+
+  private function mail(array $errors, \DateTimeImmutable $initTime): void {
+    /** @var string $recipients */
+    $recipients = $this->settings::get('rgds_import_report_emails', 'team.ramsay@ekino.com');
+
+    $this->mailer->mail(
+      'rgds_core',
+      'emergency_waiting_time_monitoring',
+      $recipients,
+      $this->languageManager->getDefaultLanguage()->getId(),
+      [
+        'violations' => $errors,
+        'html' => TRUE,
+        'started_at' => $initTime,
+      ],
+    );
+  }
+
+}

