+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Validator;
+
+use Drupal\rgds_core\Emergency\Violation\AverageTimeViolation;
+
+final readonly class AverageTimeValidator {
+
+  // There is a synchro each 5 minutes.
+  private const int DAILY_SYNCHRO_NUMBER = (60 / 5) * 24;
+
+  // 10% allowed failure rate.
+  private const float ALLOWED_RATE_FAILURE = 10 / 100;
+
+  private const float MAX_FAILURES = self::DAILY_SYNCHRO_NUMBER * self::ALLOWED_RATE_FAILURE;
+
+  public function __construct() {}
+
+  public function validate(array $averageTimesList): array {
+    $violationList = [];
+    $lastAverageTimes = \array_reduce(
+      $averageTimesList,
+      static fn(
+        ?array $laterAverageTime,
+        array $averageTimes
+      ) => $laterAverageTime['time'] ?? 0 > $averageTimes['time'] ? $laterAverageTime : $averageTimes
+    );
+
+    if (NULL === $lastAverageTimes) {
+      $violationList[] = new AverageTimeViolation(
+        'Site has no emergency import',
+        'NotEmpty',
+      );
+
+      return $violationList;
+    }
+
+    if ($this->isExceedingMaxLifeTime(new \DateTimeImmutable(), $lastAverageTimes)) {
+      $violationList[] = new AverageTimeViolation(
+        'Site has no emergency import update since 24 hours',
+        'NotObsolete',
+      );
+
+      return $violationList;
+    }
+
+    if ($this->hasHighFailureRate($averageTimesList)) {
+      $violationList[] = new AverageTimeViolation(
+        'Too many update imports are missing',
+        'ReliableRate',
+      );
+    }
+
+    return $violationList;
+  }
+
+  private function isExceedingMaxLifeTime(\DateTimeImmutable $now, array $averageTimes): bool {
+    if (FALSE === isset($averageTimes['time'])) {
+      throw new \LogicException('Unable to retrieve timestamp from AverageTimes data');
+    }
+
+    $dateTimeAverageTime = \DateTimeImmutable::createFromFormat('U', (string) $averageTimes['time']);
+    if (FALSE === $dateTimeAverageTime) {
+      throw new \LogicException('Invalid Timestamp: ' . $averageTimes['time']);
+    }
+    $interval = $now->diff($dateTimeAverageTime);
+
+    return $interval->days >= 1 && 1 === $interval->invert;
+  }
+
+  private function hasHighFailureRate(array $averageTimesList): bool {
+    return self::DAILY_SYNCHRO_NUMBER - \count($averageTimesList) > \round(self::MAX_FAILURES);
+  }
+
+}

