+    $others = \array_filter($errorMessageByConstraint, static fn($message) => $message !== $currentMessage);
+    $preparedStrings = \array_map(static fn ($message) => \sprintf('(%s)', \preg_quote($message)), $others);
+    return \implode('|', $preparedStrings);
+  }
