+  $query = $connection->query('CREATE INDEX IF NOT EXISTS path_alias__alias_trgm_gist_idx ON {path_alias} USING gist (alias gist_trgm_ops)');
+  if ($query instanceof StatementInterface) {
+    $query->execute();
+  }
+
+  $query = $connection->query('CREATE INDEX IF NOT EXISTS path_alias__path_trgm_gist_idx ON {path_alias} USING gist (path gist_trgm_ops)');
+  if ($query instanceof StatementInterface) {
+    $query->execute();
+  }
+
+  $query = $connection->query('ANALYZE {path_alias}');
+  if ($query instanceof StatementInterface) {
+    $query->execute();
+  }
