+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\HookHandler\Form\Node;
+
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\node\NodeInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+
+final readonly class FaqStructuredDataHookHandler implements ContainerInjectionInterface {
+
+  public function __construct(private EntityTypeManagerInterface $entityTypeManager) {}
+
+  public static function create(ContainerInterface $container): self {
+    $entityTypeManager = $container->get('entity_type.manager');
+
+    return new self($entityTypeManager);
+  }
+
+  public function alter(array &$build, NodeInterface $node): void {
+    $paragraphStorage = $this->entityTypeManager->getStorage('paragraph');
+
+    $ids = $paragraphStorage->getQuery()
+      ->condition('parent_id', $node->id())
+      ->condition('type', 'faq_group')
+      ->accessCheck()
+      ->execute();
+
+    if ([] === $ids) {
+      return;
+    }
+
+    $itemIds = $paragraphStorage->getQuery()
+      ->condition('parent_id', $ids, 'IN')
+      ->condition('type', 'faq_item')
+      ->accessCheck()
+      ->execute();
+
+    if ([] === $itemIds) {
+      return;
+    }
+
+    /** @var array<\Drupal\paragraphs\Entity\Paragraph> $faqItems */
+    $faqItems = $paragraphStorage->loadMultiple($itemIds);
+    $mainEntity = [];
+
+    foreach ($faqItems as $faqItem) {
+      $mainEntity[] = [
+        '@type' => 'Question',
+        'name' => $faqItem->get('field_faq_item_question')->value,
+        'acceptedAnswer' => [
+          '@type' => 'Answer',
+          'text' => $faqItem->get('field_faq_item_answer')->value,
+        ],
+      ];
+    }
+
+    $build['#attached']['html_head'][] = [
+      [
+        '#tag' => 'script',
+        '#attributes' => [
+          "type" => "application/ld+json",
+        ],
+        '#value' => \json_encode([
+          '@context' => 'https://schema.org',
+          '@type' => 'FAQPage',
+          'mainEntity' => $mainEntity,
+        ], \JSON_THROW_ON_ERROR),
+      ],
+      'rgds_core_faq_jsonld',
+    ];
+  }
+
+}

