+    // Required for path auto.
+    'datetime',
+    'telephone',
+  ];
+
+  private EntityTypeManagerInterface $entityTypeManager;
+
+  protected function setUpBeforeInstallSiteConfig(): void {
+    parent::setUpBeforeInstallSiteConfig();
+
+    $this->installSchema('file', ['file_usage']);
+    $this->installEntitySchema('file');
+    $this->installEntitySchema('media');
+    $this->installEntitySchema('paragraph');
+    $this->installEntitySchema('paragraphs_library_item');
+    $this->installEntitySchema('taxonomy_term');
+  }
+
+  protected function setUp(): void {
+    parent::setUp();
+    $this->entityTypeManager = $this->container->get('entity_type.manager');
+    $this->fixtureBuilder = new FixtureBuilder(
+      $this->entityTypeManager,
+      $this->container->get('file_system'),
+      $this->container->get('state'),
+      $this->container->get('extension.path.resolver'),
+      $this->container->get('rgds_core.legal_notice.finder')
+    );
+  }
+
+  /**
+   * @dataProvider faqDataProvider
+   */
+  public function testFaqParagraphHookHandler($faq, $expected) {
+    $faq = $this->generateFaq($faq);
+    $node = $this->fixtureBuilder->addBasicPage(['paragraphs' => [$faq]]);
+    $build = [];
+    $sut = new FaqStructuredDataHookHandler($this->entityTypeManager);
+
+    $sut->alter($build, $node);
+
+    $this->assertArrayHasKey('#attached', $build, \json_encode($build));
+    $this->assertArrayHasKey('html_head', $build['#attached'], \json_encode($build));
+    $this->assertNotEmpty($build['#attached']['html_head'], \json_encode($build));
+    $this->assertSame($expected, $build['#attached']['html_head'][0], \json_encode($build));
+  }
+
+  public function faqDataProvider(): \Generator {
+    yield 'happy_path' => [
+      'faq' => [
+        'section_title' => 'Happy Path',
+        'faq_items' => [
+          [
+            'question' => 'What is the meaning of the life, universe and stuffs?',
+            'answer' => '<p>42</p>',
+          ],
+        ],
+      ],
+      'expected_structured_data' => [
+        [
+          '#tag' => 'script',
+          '#attributes' => [
+            "type" => "application/ld+json",
+          ],
+          '#value' => \json_encode([
+            "@context" => "https://schema.org",
+            "@type" => "FAQPage",
+            'mainEntity' => [
+              [
+                "@type" => "Question",
+                "name" => 'What is the meaning of the life, universe and stuffs?',
+                "acceptedAnswer" => [
+                  "@type" => "Answer",
+                  "text" => "<p>42</p>",
+                ],
+              ],
+            ],
+          ]),
+        ],
+        'rgds_core_faq_jsonld',
+      ],
+    ];
+  }
+
+  private function generateFaq(array $data = []) {
+    $mergedData = \array_replace(['section_title' => 'Section title'], $data);
+
+    $faqItems = [];
+    foreach ($mergedData['faq_items'] ?? [] as $faqItemData) {
+      $faqItems[] = $this->fixtureBuilder->addParagraphFaqItem($faqItemData);
+    }
+    /** @var \Drupal\paragraphs\Entity\Paragraph $faqGroup */
+    $faqGroup = $this->entityTypeManager->getStorage('paragraph')->create(
+      [
+        'type' => 'faq_group',
+        'field_faq_section_title' => [
+          'value' => $mergedData['section_title'],
+          'format' => 'plain_text',
+        ],
+        'field_faq_items' => $faqItems,
+      ]
+    );
+    $faqGroup->save();
+
+    return $faqGroup;
+  }
+
+}

