+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\File\HookHandler;
+
+use Drupal\Component\Transliteration\TransliterationInterface;
+use Drupal\Core\Database\Query\Condition;
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Language\LanguageInterface;
+use Drupal\micro_site\SiteNegotiatorInterface;
+use Drupal\views\Plugin\views\query\QueryPluginBase;
+use Drupal\views\Plugin\views\query\Sql;
+use Drupal\views\ViewExecutable;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+
+final readonly class ViewFilesOverviewHookHandler implements ContainerInjectionInterface {
+
+  private const string PUBLIC_FILES_DIR = 'public://biblio/public';
+
+  private const string INSTITUTION_FILES_ROOT_DIR = 'public://biblio/domaines';
+
+  private const string WEBFORM_FILES_DIR = 'private://webform';
+
+  public function __construct(
+    private SiteNegotiatorInterface $siteNegotiator,
+    private TransliterationInterface $transliteration,
+  ) {}
+
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('micro_site.negotiator'),
+      $container->get('transliteration'),
+    );
+  }
+
+  public function alter(ViewExecutable $view, QueryPluginBase $query): void {
+    if ('files' !== $view->id()) {
+      return;
+    }
+
+    if (FALSE === $query instanceof Sql) {
+      return;
+    }
+
+    $user = $view->getUser();
+    if ($user->hasPermission('access full files overview')) {
+      return;
+    }
+
+    /** @var \Drupal\micro_site\Entity\SiteInterface|null $currentSite */
+    $currentSite = $this->siteNegotiator->getActiveSite();
+    /** @var \Drupal\Core\Database\Query\Condition $orConditions */
+    $orConditions = $query->getConnection()->condition('OR');
+
+    // $currentSite is NULL when Corporate Site is the active site.
+    if (NULL !== $currentSite) {
+      $siteName = $this->generateMachineNameFromSiteName($currentSite->getName());
+      $this->addInstitutionFilesCondition($orConditions, $siteName);
+    }
+    else {
+      $this->addCorporateFilesCondition($orConditions);
+    }
+
+    $this->addCommonFilesCondition($orConditions);
+
+    if ($user->hasPermission('access private files overview')) {
+      $this->addPrivateFilesCondition($orConditions);
+    }
+    else {
+      $queryWhereClause = $currentSite ? \sprintf('site_id = %s', $currentSite->id()) : 'IS NULL';
+      $siteSubmissionsQuery = \sprintf('SELECT sid FROM webform_submission WHERE %s', $queryWhereClause);
+
+      /** @var \Drupal\Core\Database\StatementInterface $currentSiteSubmissionStatement */
+      $currentSiteSubmissionStatement = $query->getConnection()->query($siteSubmissionsQuery);
+      $submissionIds = $currentSiteSubmissionStatement->fetchCol();
+
+      /** @var \Drupal\Core\Database\Query\Condition $nestedWebformConditions */
+      $nestedWebformConditions = $query->getConnection()->condition('AND');
+      $this->addSubmissionFilesConditions($nestedWebformConditions, $submissionIds);
+      $orConditions->condition($nestedWebformConditions);
+    }
+
+    $query->addWhere(0, $orConditions);
+  }
+
+  private function addInstitutionFilesCondition(Condition $orConditions, null|string $siteName): void {
+    if (NULL === $siteName) {
+      return;
+    }
+
+    $orConditions->condition(
+      'uri',
+      \sprintf('%s/%s/%%', self::INSTITUTION_FILES_ROOT_DIR, $siteName),
+      'LIKE',
+    );
+  }
+
+  private function addCorporateFilesCondition(Condition $orConditions): void {
+    $orConditions->condition('uri', 'public://20__-__/%', 'LIKE');
+  }
+
+  private function addCommonFilesCondition(Condition $orConditions): void {
+    $orConditions->condition('uri', self::PUBLIC_FILES_DIR . '/%', 'LIKE');
+  }
+
+  private function addPrivateFilesCondition(Condition $orConditions): void {
+    $orConditions->condition('uri', 'private://%', 'LIKE');
+  }
+
+  private function addSubmissionFilesConditions(Condition $condition, array $submissionIds): void {
+    $condition
+      ->condition('file_usage_file_managed.type', 'webform_submission')
+      ->condition('file_usage_file_managed.id', $submissionIds, 'IN')
+      ->condition('uri', self::WEBFORM_FILES_DIR . '/%', 'LIKE');
+  }
+
+  private function generateMachineNameFromSiteName(string $siteName): null|string {
+    $transliteratedSiteName = $this->transliteration->transliterate($siteName, LanguageInterface::LANGCODE_DEFAULT, '');
+
+    return \preg_replace('/[^a-z0-9_]+/', '_', \strtolower($transliteratedSiteName));
+  }
+
+}

