+use Drupal\webform\Entity\WebformSubmission;
+use Drupal\webform\WebformSubmissionAccessControlHandler;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+
+final class SiteWebformSubmissionAccessControlHandler extends WebformSubmissionAccessControlHandler {
+
+  private SiteNegotiator $siteNegotiator;
+
+  public static function createInstance(ContainerInterface $container, EntityTypeInterface $entity_type): self {
+    $instance = parent::createInstance($container, $entity_type);
+    $instance->siteNegotiator = $container->get('micro_site.negotiator');
+
+    return $instance;
+  }
+
+  public function checkAccess(EntityInterface $entity, $operation, AccountInterface $account) {
+    $accessResult = parent::checkAccess($entity, $operation, $account);
+
+    if (FALSE === $entity instanceof WebformSubmission) {
+      return $accessResult;
+    }
+
+    if ($accessResult->isAllowed()) {
+      return $accessResult;
+    }
+
+    if ('view' !== $operation) {
+      return $accessResult;
+    }
+
+    if ($account->hasPermission("view site webform submission") && $this->isEntitySite($entity)) {
+      return WebformAccessResult::allowed($entity, TRUE);
+    }
+
+    return $accessResult;
+  }
+
+  public function isEntitySite(WebformSubmission $entity): bool {
+    /** @var null|\Drupal\micro_site\Entity\SiteInterface $currentSite */
+    $currentSite = $this->siteNegotiator->getActiveSite();
+
+    return $entity->get('site_id')->value === $currentSite?->id();
+  }
+
+}

