+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Form\Element;
+
+use Drupal\Core\Render\Element\Select;
+
+/**
+ * Provides a select element enhanced with Choices.js.
+ *
+ * @phpstan-type ChoicesElement array{
+ *   "#attached": array{"library": array<string>},
+ *   "#attributes":array{"class": array<string>,
+ *   "data-placeholder": string},
+ *   "#placeholder": null|string,
+ *   "#wrapper_attributes": array<string, array<string>>
+ * }
+ *
+ * @FormElement("rgds_core_select_text_filter")
+ */
+final class SelectText extends Select {
+
+  public function getInfo(): array {
+    /** @var array<string, array> $info */
+    $info = parent::getInfo();
+    $info['#pre_render'][] = [__CLASS__, 'preRenderChoices'];
+
+    return $info;
+  }
+
+  /**
+   * Pre render for to a Choices JS element.
+   *
+   * @param ChoicesElement $element
+   *   Form element render array.
+   */
+  public static function preRenderChoices(array $element): array {
+    $element['#attached']['library'][] = 'rgds_core/select_text_filter';
+    $element['#attributes']['class'][] = 'js-choices';
+    $element['#attributes']['data-placeholder'] = $element['#placeholder'] ?? '';
+    $element['#wrapper_attributes']['class'][] = 'rgds-select-wrapper';
+    $element['#wrapper_attributes']['style'][] = 'max-width:800px';
+
+    return $element;
+  }
+
+}

