+
+final class WebformSubmissionFilesVisibilityTest extends EndToEndTestBase {
+
+  use AuthenticationTrait;
+
+  public function testWebformSubmissionListingIsAvailable(): void {
+    $this->loginAsAdmin($this->client(), Site::Corporate);
+
+    $crawler = $this->client()->request(
+      'GET',
+      \sprintf('%s/admin/webform/submissions/manage', Site::Corporate->baseUrl()),
+    );
+
+    $this->assertMatchesRegularExpression(
+      '/The Submissions page lists all incoming submissions for all webforms\./',
+      $crawler->getText(),
+    );
+
+    $submissionLines = $crawler->filterXPath('//table/tbody/tr');
+    self::assertSame(1, $submissionLines->count());
+
+    $submissionLines->findElement(WebDriverBy::tagName('td'))->click();
+
+    $fileLinkElement = $this->client()->refreshCrawler()
+      ->filterXPath('//a[@type="image/jpeg"]');
+    self::assertTrue($fileLinkElement->isDisplayed());
+    self::assertMatchesRegularExpression(
+    // File can be suffixed when uploaded with webform submission.
+      '/\/sites\/default\/files\/fixtures\/webform_submission_image(_\d+)?.jpg/',
+      $fileLinkElement->getAttribute('href'),
+    );
+  }
+
+  public function testWebmasterNoAccessToWebformSubmissionListing(): void {
+    $this->loginAsUserA($this->client(), Site::SiteA);
+
+    $crawler = $this->client()->request(
+      'GET',
+      \sprintf('%s/admin/webform/submissions/manage', Site::SiteA->baseUrl()),
+    );
+
+    $this->assertMatchesRegularExpression(
+      '/You are not authorized to access this page\./',
+      $crawler->getText(),
+    );
+  }
+
+  /** @dataProvider filePageDataProvider */
+  public function testFileListingIsAvailable(Site $site, string $username, int $expectedFileMatch): void {
+    match ($username) {
+      'admin' => $this->loginAsAdminWithEmptySession($this->client(), $site),
+      'user-a' => $this->loginAsUserAWithEmptySession($this->client(), $site),
+    };
+
+    $crawler = $this->client()->request('GET', \sprintf('%s/admin/content/files', $site->baseUrl()));
+
+    $this->assertSame('Fichiers', $this->getDisplayedPageTitle($crawler));
+    $this->assertSame($username, $this->getDisplayedUsername($crawler));
+
+    $crawler = $this->filterPageContentWithSubmissionImage($crawler);
+    $expectedSubmissionFile = $this->getFileSubmissionMatches($crawler);
+
+    $this->assertCount($expectedFileMatch, $expectedSubmissionFile);
+  }
+
+  public function filePageDataProvider(): \Generator {
+    yield 'Admin Corporate' => [
+      'site' => Site::Corporate,
+      'username' => 'admin',
+      'expected file matches' => 1,
+    ];
+    yield 'User Site A' => [
+      'site' => Site::SiteA,
+      'username' => 'user-a',
+      'expected file matches' => 0,
+    ];
+  }
+
+  private function getDisplayedUsername(Crawler $crawler): string {
+    return $crawler->filter('#toolbar-item-user')->text();
+  }
+
+  private function getDisplayedPageTitle(Crawler $crawler): string {
+    return $crawler->filter('h1')->text();
+  }
+
+  private function filterPageContentWithSubmissionImage(Crawler $crawler
+  ): Crawler {
+    $formAdmin = $crawler->filter('.view-filters form')->form();
+    $formAdmin->setValues(['filename' => 'webform_submission_image']);
+    $this->client()->submit($formAdmin);
+    $crawler = $this->client()->refreshCrawler();
+
+    return $crawler;
+  }
+
+  private function getFileSubmissionMatches(Crawler $crawler): array {
+    $filterAResultElements = $crawler->findElements(
+      WebDriverBy::cssSelector('.view-content tbody tr .views-field-filename'),
+    );
+
+    return array_filter($filterAResultElements, function (WebDriverElement $filter) {
+      return \str_contains($filter->getText(), 'webform_submission_image');
+    });
+  }
+
+}

