+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Submission\EntityHandler;
+
+use Drupal\Core\Database\Query\Select;
+use Drupal\Core\Entity\EntityTypeInterface;
+use Drupal\micro_site\Entity\SiteInterface;
+use Drupal\micro_site\SiteNegotiator;
+use Drupal\webform\WebformEntityListBuilder;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+
+final class SiteWebformListBuilder extends WebformEntityListBuilder {
+
+  private SiteNegotiator $siteNegotiator;
+
+  /**
+   * {@inheritdoc}
+   */
+  public static function createInstance(
+    ContainerInterface $container,
+    EntityTypeInterface $entity_type,
+  ): WebformEntityListBuilder {
+    $instance = parent::createInstance($container, $entity_type);
+    $instance->siteNegotiator = $container->get('micro_site.negotiator');
+
+    return $instance;
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  protected function getEntityIds(): int|array {
+    $entity_ids = parent::getEntityIds();
+
+    if (0 === \count($entity_ids)) {
+      return $entity_ids;
+    }
+
+    // Recalculate total results by webform for current site.
+    /** @var \Drupal\Core\Database\Query\Select $query */
+    // @phpstan-ignore-next-line
+    $query = $this->database->select('webform_submission', 'ws');
+    $query->fields('ws', ['webform_id']);
+    $query->condition('webform_id', $entity_ids, 'IN');
+    $query->addExpression('COUNT(sid)', 'results');
+    $query->groupBy('webform_id');
+
+    $this->addSiteConditionToQuery($query);
+
+    /** @var \Drupal\Core\Database\StatementInterface $statement */
+    $statement = $query->execute();
+    $totals = \array_map('intval', $statement->fetchAllKeyed());
+    foreach ($totals as $entity_id => $total) {
+      $this->totalNumberOfResults[$entity_id] = $total;
+    }
+
+    return $entity_ids;
+  }
+
+  private function addSiteConditionToQuery(Select $query): void {
+    if (FALSE === isset($this->siteNegotiator)) {
+      return;
+    }
+
+    /** @var null|SiteInterface $currentSite */
+    $currentSite = $this->siteNegotiator->getActiveSite();
+
+    if ($currentSite instanceof SiteInterface) {
+      $query->condition('site_id', $currentSite->id());
+
+      return;
+    }
+
+    $query->isNull('site_id');
+  }
+
+}

