+    /** @var null|\Drupal\micro_site\Entity\SiteInterface $site */
+    $site = $this->siteNegotiator->getActiveSite();
+    $webformSubmission->set('site_id', $site?->id());
+  }
+
+  public function alter(array &$entity_types): void {
+    /** @var \Drupal\Core\Config\Entity\ConfigEntityType|NULL $webform */
+    $webform = $entity_types['webform'] ?? NULL;
