+
+    /** @var \Drupal\Core\Entity\ContentEntityType|NULL $webformSubmission */
+    $webformSubmission = $entity_types['webform_submission'] ?? NULL;
+    $webformSubmission?->setListBuilderClass(SiteWebformSubmissionListBuilder::class);
+    $webformSubmission?->setAccessClass(SiteWebformSubmissionAccessControlHandler::class);
+  }
+
+}

