+/**
+ * Close other item when opening an FAQ item
+ */
+(function ($, Drupal) {
+  Drupal.behaviors.rgdsThemeAccordion = {
+    attach: function () {
+      $(once('rgdsThemeAccordion', '.paragraph--faq-group-container')).each(
+        function () {
+          const faqItems = $(this).children('.paragraph--faq-item');
+
+          faqItems.each(function () {
+            const currentTargetedElement = $(this);
+
+            currentTargetedElement.on('click', function () {
+              faqItems.each(function () {
+                if (false === $(this).is(currentTargetedElement)) {
+                  $(this).removeAttr('open');
+                }
+              });
+            });
+          });
+        },
+      );
+    },
+  };
+})(jQuery, Drupal, once);

