+class RobotsTxtContentBuilder {
+
+  /**
+   * Inits a Content Builder for the robots.txt file.
+   *
+   * @param string[] $parts
+   *   An array of strings to be aggregated in the final robots.txt file.
+   */
+  public function __construct(
+    private array $parts = [],
+  ) {
+  }
+
+  public function build(): string {
+    if ([] === $this->parts) {
+      return '';
+    }
+    return \implode(
+      \PHP_EOL . \PHP_EOL,
+      $this->parts,
+    );
+  }
+
+  public function addContent(ContentProviderInterface $contentProvider): void {
+    $this->parts[] = $contentProvider->getContent();
+  }
+
+}

