+
+/**
+ * Class RobotsTxtAppendForm.
+ *
+ * Helps administrators to append content to robots.txt file.
+ *
+ * @package Drupal\rgds_core\Seo\Form
+ */
+final class RobotsTxtAppendForm extends FormBase {
+
+  public function __construct(
+    private readonly RobotsTxtCustomContentProvider $robotsTxtCustomContentProvider,
+  ) {}
+
+  #[\Override]
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('rgds_core.robotstxt.content_provider.custom'),
+    );
+  }
+
+  #[\Override]
+  public function getFormId(): string {
+    return 'robotstxt_append_form';
+  }
+
+  #[\Override]
+  /**
+   * {@inheritdoc}
+   *
+   * phpcs:disable SlevomatCodingStandard.Functions.UnusedParameter
+   */
+  public function buildForm(array $form, FormStateInterface $form_state): array {
+    $form['robotstxt_content'] = [
+      '#type' => 'textarea',
+      '#title' => $this->t('Content to append to robots.txt'),
+      '#default_value' => $this->robotsTxtCustomContentProvider->getContent(),
+      '#description' => $this->t('Content from this form will be included in all the sites robots.txt. If you want to learn more about robots.txt syntax, you can check <a href="https://developers.google.com/search/docs/crawling-indexing/robots/create-robots-txt?hl=fr#create_rules">this link</a>.'),
+      '#cols' => 60,
+      '#rows' => 20,
+    ];
+
+    $form['actions']['#type'] = 'actions';
+    $form['actions']['submit'] = [
+      '#type' => 'submit',
+      '#value' => $this->t('Save configuration'),
+      '#button_type' => 'primary',
+    ];
+
+    return $form;
+  }
+
+  public function validateForm(array &$form, FormStateInterface $form_state): void {
+    $robotsTxtContent = $form_state->getValue('robotstxt_content');
+    if (FALSE === \is_string($robotsTxtContent)) {
+      $form_state->setError($form['robotstxt_content'], $this->t('Robots.txt content must be a string.'));
+      return;
+    }
+
+    if (TRUE === $this->robotsTxtContentIsValid($robotsTxtContent)) {
+      return;
+    }
+
+    $form_state->setError($form['robotstxt_content'], $this->t('Robots.txt content is invalid. Each line must start with either User-agent:, Allow:, Disallow: or Sitemap:'));
+  }
+
+  #[\Override]
+  public function submitForm(array &$form, FormStateInterface $form_state): void {
+    $robotsTxtContent = $form_state->getValue('robotstxt_content');
+
+    if (FALSE === \is_string($robotsTxtContent)) {
+      $this->messenger()->addError($this->t('robotstxt_content should be string')->render());
+      $this->logger('rgds_core')->error('robotstxt_content should be string');
+      return;
+    }
+
+    $this->robotsTxtCustomContentProvider->write($robotsTxtContent);
+    $this->messenger()->addStatus($this->t('The custom robots.txt content has been saved.'));
+  }
+
+  private function robotsTxtContentIsValid(string $robotsTxtContent): bool {
+    $lines = \explode("\n", $robotsTxtContent);
+    $regex = '/^(User-agent|Allow|Disallow|Sitemap):/i';
+
+    foreach ($lines as $line) {
+      $line = \trim($line);
+      if ('' === $line) {
+        continue;
+      }
+      if (0 === \preg_match($regex, $line)) {
+        return FALSE;
+      }
+    }
+
+    return TRUE;
+  }
+
+}

