+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Batch\Admin;
+
+use Drupal\Core\Url;
+use Drupal\micro_site\Entity\SiteInterface;
+use Drupal\node\NodeInterface;
+
+final class WorkshopRegistrationExportBatch {
+
+  private const int INITIAL_ROW = 2;
+
+  private const int BATCH_LIMIT = 50;
+
+  public static function export(
+    string $siteId,
+    string $workshopId,
+    \DateTimeImmutable $workshopDate,
+    string $fileType,
+    array &$context,
+  ): void {
+    /** @var \Drupal\rgds_core\Workshop\Export\SpreadsheetFileExporter $spreadsheetExport */
+    $spreadsheetExport = \Drupal::service('rgds_core.workshop.export.SpreadsheetExporter');
+    $spreadsheetExport->setStrategy($fileType);
+
+    if (!isset($context['results']['file_path'])) {
+      $file = $spreadsheetExport->prepareExportFile();
+      $spreadsheetExport->createFile($file->getPathname());
+      $context['results']['file_path'] = $file->getPathname();
+    }
+
+    /** @var \Drupal\rgds_core\Workshop\Query\WorkshopRegistrationQuery $workshopRegistrationQuery */
+    $workshopRegistrationQuery = \Drupal::service('rgds_core.workshop.query.workshop_registration_export_query');
+    $query = $workshopRegistrationQuery->getWorkshopRegistrationQuery($siteId, $workshopId, $workshopDate);
+
+    if (NULL === $query) {
+      $context['sandbox']['progress'] = 0;
+      $context['sandbox']['total'] = 0;
+      $context['finished'] = 1;
+
+      return;
+    }
+
+    if (!isset($context['sandbox']['progress'])) {
+      $context['sandbox']['progress'] = 0;
+      $countQuery = clone $query;
+      $context['sandbox']['total'] = (int) $countQuery->count()->execute();
+    }
+
+    $workshopRegistrations = $query->range(
+      $context['sandbox']['progress'],
+      $context['sandbox']['progress'] + self::BATCH_LIMIT
+    )->execute();
+
+    if (FALSE === \is_array($workshopRegistrations) || [] === $workshopRegistrations) {
+      $context['finished'] = 1;
+
+      return;
+    }
+
+    $spreadsheet = $spreadsheetExport->loadSpreadsheet($context['results']['file_path']);
+    $row = $context['sandbox']['row'] ?? self::INITIAL_ROW;
+
+    foreach ($workshopRegistrations as $workshopRegistrationId) {
+      $workshopRegistration = $workshopRegistrationQuery->getWorkshopRegistration($workshopRegistrationId);
+      $workshop = $workshopRegistrationQuery->getWorkshop($workshopRegistration);
+      $workshopSlot = $workshopRegistrationQuery->getWorkshopSlot($workshopRegistration);
+
+      $rowData = $spreadsheetExport->prepareRow(
+        $row,
+        $workshopRegistration,
+        (string) $workshop->label(),
+        // @phpstan-ignore-next-line
+        $workshopSlot->get('field_date_range')->start_date->getTimestamp(),
+        self::getValidSiteName($workshop)
+      );
+
+      $spreadsheetExport->writeRow($rowData, $spreadsheet);
+
+      $context['sandbox']['progress']++;
+      $row++;
+    }
+
+    $context['message'] = \t(
+      'Exporting workshop registrations (@count/@total)',
+      [
+        '@count' => $context['sandbox']['progress'],
+        '@total' => $context['sandbox']['total'],
+      ],
+      [
+        'context' => 'rgds: batch',
+      ]
+    );
+
+    $spreadsheetExport->writeSpreadsheet($context['results']['file_path'], $spreadsheet);
+
+    $context['sandbox']['row'] = $row;
+
+    if ($context['sandbox']['progress'] === $context['sandbox']['total']) {
+      $context['finished'] = 1;
+
+      return;
+    }
+
+    $context['finished'] = $context['sandbox']['progress'] / $context['sandbox']['total'];
+  }
+
+  public static function exportFinishedCallback(bool $success, array $results): void {
+    if ($success && isset($results['file_path']) && \file_exists($results['file_path'])) {
+      $token = \Drupal::service('csrf_token')->get($results['file_path']);
+      $download_url = Url::fromRoute(
+        'rgds_core.workshop_registration.export_download',
+        [],
+        [
+          'query' => [
+            'token' => $token,
+            'file' => $results['file_path'],
+          ],
+        ]
+      )->toString();
+
+      \Drupal::messenger()->addStatus(
+        \t(
+          'Export successful. Click to <a href="@download_url">download</a>.',
+          [
+            '@download_url' => $download_url,
+          ],
+          [
+            'context' => 'rgds: batch',
+          ]
+        )
+      );
+    }
+    else {
+      $message = \t('An error has occurred. Please contact an administrator.', [], ['context' => 'rgds: batch']);
+      \Drupal::messenger()->addError($message);
+    }
+  }
+
+  private static function getValidSiteName(NodeInterface $workshop): string {
+    /** @var NULL|SiteInterface $site */
+    $site = $workshop->get('site_id')->entity;
+
+    if (NULL === $site) {
+      throw new \LogicException('$site should not be null');
+    }
+
+    if (!$site instanceof SiteInterface) {
+      throw new \LogicException(
+        \sprintf(
+          '$site should be an instance of "%s": "%s" given',
+          SiteInterface::class,
+          \get_class($site)
+        )
+      );
+    }
+
+    return $site->getName();
+  }
+
+}

