+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\RobotsTxt\File;
+
+use Drupal\Core\File\FileExists;
+use Drupal\Core\File\FileSystemInterface;
+
+final readonly class RobotsTxtFileSystem {
+
+  public function __construct(
+    private FileSystemInterface $fileSystem,
+  ) {
+  }
+
+  public function read(string $path): string {
+    $realPath = \str_starts_with($path, '/')
+      ? $path
+      : $this->fileSystem->realpath($path);
+
+    if (FALSE === $realPath || FALSE === \file_exists($realPath) || FALSE === \is_readable($realPath)) {
+      return '';
+    }
+
+    return \file_get_contents($realPath) ?: '';
+  }
+
+  public function initFile(string $directory, string $filePath): void {
+    $this->fileSystem->prepareDirectory($directory);
+    $this->fileSystem->saveData('', $filePath, FileExists::Error);
+  }
+
+  public function write(string $content, string $filePath): void {
+    $this->fileSystem->saveData($content, $filePath, FileExists::Replace);
+  }
+
+}

