+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\RobotsTxt\Provider;
+
+use Drupal\rgds_core\RobotsTxt\File\RobotsTxtFileSystem;
+
+readonly class RobotsTxtCustomContentProvider implements ContentProviderInterface {
+
+  public const string PATH_ROBOTSTXT_CUSTOM_FILE_DIRECTORY = 'public://seo';
+  public const string PATH_ROBOTSTXT_CUSTOM_FILE = self::PATH_ROBOTSTXT_CUSTOM_FILE_DIRECTORY . '/rgds_core_custom_robots.txt';
+
+  public function __construct(
+    private RobotsTxtFileSystem $fileSystem,
+  ) {
+  }
+
+  public function getContent(): string {
+    return $this->fileSystem->read(self::PATH_ROBOTSTXT_CUSTOM_FILE);
+  }
+
+  public function write(string $content): void {
+    if (FALSE === $this->fileExists()) {
+      $this->initFile();
+    }
+
+    $this->fileSystem->write(
+      $content,
+      self::PATH_ROBOTSTXT_CUSTOM_FILE,
+    );
+  }
+
+  private function fileExists(): bool {
+    return \file_exists(self::PATH_ROBOTSTXT_CUSTOM_FILE);
+  }
+
+  private function initFile(): void {
+    $this->fileSystem->initFile(
+      self::PATH_ROBOTSTXT_CUSTOM_FILE_DIRECTORY,
+      self::PATH_ROBOTSTXT_CUSTOM_FILE,
+    );
+  }
+
+}

