+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\RobotsTxt\Provider;
+
+use Drupal\rgds_core\RobotsTxt\Exception\RobotsTxtNotFoundException;
+use Drupal\rgds_core\RobotsTxt\File\RobotsTxtFileSystem;
+
+readonly class RobotsTxtScaffoldContentProvider implements ContentProviderInterface {
+
+  public function __construct(
+    private string $appRoot,
+    private RobotsTxtFileSystem $fileSystem,
+  ) {
+  }
+
+  public function getContent(): string {
+    $robotsTxtContent = $this->fileSystem->read($this->getRobotsTxtFilePath());
+    if ('' === $robotsTxtContent) {
+      throw new RobotsTxtNotFoundException('Scaffold content not found for Robots.txt file.');
+    }
+    return $this->fileSystem->read(self::getRobotsTxtFilePath());
+  }
+
+  private function getRobotsTxtFilePath(): string {
+    return $this->appRoot . '/robots.txt';
+  }
+
+}

