+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\RobotsTxt\Controller;
+
+use Drupal\Tests\UnitTestCase;
+use Drupal\rgds_core\RobotsTxt\Builder\RobotsTxtContentBuilder;
+use Drupal\rgds_core\RobotsTxt\Controller\RobotsTxtController;
+use Drupal\rgds_core\RobotsTxt\Exception\RobotsTxtNotFoundException;
+use Drupal\rgds_core\RobotsTxt\Provider\RobotsTxtCustomContentProvider;
+use Drupal\rgds_core\RobotsTxt\Provider\RobotsTxtScaffoldContentProvider;
+use Drupal\rgds_core\RobotsTxt\Provider\RobotsTxtSitemapContentProvider;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\Response;
+use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
+
+final class RobotsTxtControllerTest extends UnitTestCase {
+
+  private RobotsTxtScaffoldContentProvider $scaffoldContentProvider;
+  private RobotsTxtCustomContentProvider $customContentProvider;
+  private RobotsTxtSitemapContentProvider $sitemapContentProvider;
+  private RobotsTxtContentBuilder $contentBuilder;
+  private LoggerInterface $logger;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->scaffoldContentProvider = $this->createMock(RobotsTxtScaffoldContentProvider::class);
+    $this->customContentProvider = $this->createMock(RobotsTxtCustomContentProvider::class);
+    $this->sitemapContentProvider = $this->createMock(RobotsTxtSitemapContentProvider::class);
+    $this->contentBuilder = $this->createMock(RobotsTxtContentBuilder::class);
+    $this->logger = $this->createMock(LoggerInterface::class);
+  }
+
+  public function testInvokeReturnsResponseWithContent(): void {
+    $expectedContent = 'User-agent: *' . \PHP_EOL . 'Sitemap: https://example.com/sitemap.xml';
+
+    $this->contentBuilder
+      ->expects($this->exactly(3))
+      ->method('addContent');
+    $this->contentBuilder
+      ->expects($this->once())
+      ->method('build')
+      ->willReturn($expectedContent);
+
+    $this->logger
+      ->expects($this->never())
+      ->method('error');
+
+    $contentProviders = [
+      $this->scaffoldContentProvider,
+      $this->customContentProvider,
+      $this->sitemapContentProvider,
+    ];
+
+    $controller = new RobotsTxtController($this->contentBuilder, $contentProviders, $this->logger);
+    $response = $controller();
+
+    $this->assertInstanceOf(Response::class, $response);
+    $this->assertSame($expectedContent, $response->getContent());
+    $this->assertSame(Response::HTTP_OK, $response->getStatusCode());
+    $this->assertSame('text/plain', $response->headers->get('content-type'));
+  }
+
+  public function testInvokeThrowsNotFoundHttpExceptionOnError(): void {
+    $exceptionMessage = 'Scaffold content not found for Robots.txt file.';
+    $exception = new RobotsTxtNotFoundException($exceptionMessage);
+
+    $this->contentBuilder
+      ->expects($this->once())
+      ->method('addContent')
+      ->willThrowException($exception);
+
+    $this->logger
+      ->expects($this->once())
+      ->method('error')
+      ->with('Failed to build robots.txt: @message', [
+        '@message' => $exceptionMessage,
+      ]);
+
+    $contentProviders = [
+      $this->scaffoldContentProvider,
+      $this->customContentProvider,
+      $this->sitemapContentProvider,
+    ];
+
+    $controller = new RobotsTxtController($this->contentBuilder, $contentProviders, $this->logger);
+
+    $this->expectException(NotFoundHttpException::class);
+    $this->expectExceptionMessage($exceptionMessage);
+
+    $controller();
+  }
+
+  public function testInvokeReturnsEmptyContentWhenBuilderReturnsEmpty(): void {
+    $this->contentBuilder
+      ->expects($this->once())
+      ->method('build')
+      ->willReturn('');
+
+    $contentProviders = [
+      $this->scaffoldContentProvider,
+      $this->customContentProvider,
+      $this->sitemapContentProvider,
+    ];
+
+    $controller = new RobotsTxtController($this->contentBuilder, $contentProviders, $this->logger);
+    $response = $controller();
+
+    $this->assertSame('', $response->getContent());
+    $this->assertSame(Response::HTTP_OK, $response->getStatusCode());
+  }
+
+  public function testCreateReturnsControllerInstance(): void {
+    $container = $this->createMock(ContainerInterface::class);
+
+    $container
+      ->expects($this->exactly(5))
+      ->method('get')
+      ->willReturnMap([
+        ['rgds_core.robotstxt.content_builder', 1, $this->contentBuilder],
+        ['rgds_core.robotstxt.content_provider.scaffold', 1, $this->scaffoldContentProvider],
+        ['rgds_core.robotstxt.content_provider.custom', 1, $this->customContentProvider],
+        ['rgds_core.robotstxt.content_provider.sitemap', 1, $this->sitemapContentProvider],
+        ['rgds_core.logger.channel.robotstxt', 1, $this->logger],
+      ]);
+
+    $controller = RobotsTxtController::create($container);
+
+    $this->assertInstanceOf(RobotsTxtController::class, $controller);
+  }
+
+}

