+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\HookHandler\Form\Node;
+
+use Drupal\Core\Form\FormStateInterface;
+
+/**
+ * Add conditional behavior to display opacity input in Banner Page admin form.
+ */
+final class PageBannerFormHookHandler {
+
+  public function formAlter(array &$form, FormStateInterface $formState): void {
+    $formObject = $formState->getFormObject();
+    if ('node_page_edit_form' !== $formObject->getFormId()) {
+      return;
+    }
+
+    $form['field_overlay_opacity']['#states']['visible'] = [
+      ':input[name="field_is_fullwidth_banner[value]"]' => ['checked' => TRUE],
+      ':input[name="field_title_layout"]' => ['value' => 'image'],
+    ];
+  }
+
+}

