+
+#[FieldWidget(
+  id: 'range',
+  label: new TranslatableMarkup('Range field widget'),
+  field_types: [
+    'range',
+  ],
+)]
+final class RangeWidget extends NumberWidget {
+
+  /**
+   * {@inheritdoc}
+   *
+   * @param \Drupal\Core\Field\FieldItemListInterface<\Drupal\rgds_core\Plugin\Field\FieldType\RangeItem> $items
+   */
+  #[\Override]
+  public function formElement(
+    FieldItemListInterface $items,
+    $delta,
+    array $element,
+    array &$form,
+    FormStateInterface $form_state,
+  ): array {
+    $formElement = parent::formElement($items, $delta, $element, $form, $form_state);
+
+    $formElement['value']['#type'] = 'range';
+
+    return $formElement;
+  }
+
+}

