+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Export;
+
+use Drupal\Core\Datetime\DateFormatter;
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Site\Settings;
+use Drupal\rgds_core\Entity\WorkshopRegistration;
+use Drupal\rgds_core\Workshop\Export\Strategy\CsvFileStrategy;
+use Drupal\rgds_core\Workshop\Export\Strategy\XlsFileStrategy;
+use PhpOffice\PhpSpreadsheet\IOFactory;
+use PhpOffice\PhpSpreadsheet\Spreadsheet;
+
+class SpreadsheetFileExporter implements SpreadsheetExportStrategyInterface {
+
+  public const array HEADERS = [
+    'A1' => 'Date d\'inscriptions',
+    'B1' => 'Atelier',
+    'C1' => 'Date',
+    'D1' => 'Nom',
+    'E1' => 'Prénom',
+    'F1' => 'Courriel',
+    'G1' => 'Téléphone',
+    'H1' => 'Accompagnée',
+    'I1' => 'Date accouchement',
+    'J1' => 'Domain',
+    'K1' => 'SID',
+  ];
+
+  private const string EXPORT_DIRECTORY = 'workshop-exports';
+
+  private SpreadsheetExportStrategyInterface $strategy;
+
+  public function __construct(
+    private readonly DateFormatter $dateFormatter,
+    private readonly FileSystemInterface $fileSystem,
+  ) {}
+
+  public function setStrategy(string $fileType): void {
+    $this->strategy = match ($fileType) {
+      'csv' => new CsvFileStrategy(),
+      'xls' => new XlsFileStrategy(),
+      default => throw new \DomainException(\sprintf('File type %s is not supported', $fileType)),
+    };
+  }
+
+  public function getExtension(): string {
+    return $this->strategy->getExtension();
+  }
+
+  public function createFile(string $filepath, Spreadsheet $spreadsheet = new Spreadsheet()): void {
+    $this->writeRow(self::HEADERS, $spreadsheet);
+    $this->strategy->createFile($filepath, $spreadsheet);
+    $spreadsheet->disconnectWorksheets();
+  }
+
+  public function writeSpreadsheet(string $filepath, Spreadsheet $spreadsheet): void {
+    $this->strategy->writeSpreadsheet($filepath, $spreadsheet);
+    $spreadsheet->disconnectWorksheets();
+  }
+
+  public function loadSpreadsheet(string $filepath): Spreadsheet {
+    return IOFactory::load($filepath);
+  }
+
+  public function prepareExportFile(): \SplFileInfo {
+    /** @var NULL|string $privateFilesPath */
+    $privateFilesPath = Settings::get('file_private_path');
+    // In some case, for instance when running in Kernel Tests, "file_private_path" settings is empty.
+    if (NULL === $privateFilesPath) {
+      // Unique directory file path is needed for Para-test with kernel test.
+      $privateFilesPath = \sprintf('/app/var/files/private/default/%s', \dechex(\rand(10000, 1000000)));
+    }
+    $workshopDirectoryPath = \sprintf('%s/%s', $privateFilesPath, self::EXPORT_DIRECTORY);
+
+    $isDirectoryReady = $this->fileSystem->prepareDirectory(
+      $workshopDirectoryPath,
+      FileSystemInterface::CREATE_DIRECTORY
+    );
+    if (FALSE === $isDirectoryReady) {
+      throw new \RuntimeException(\sprintf('Cannot prepare the directory %s', $workshopDirectoryPath));
+    }
+    $filename = \sprintf('export_inscrit_%s.%s', \date('Ymd'), $this->getExtension());
+    $filepath = \sprintf('%s/%s', $workshopDirectoryPath, $filename);
+
+    return new \SplFileInfo($filepath);
+  }
+
+  public function writeRow(array $data, Spreadsheet $spreadsheet): void {
+    $worksheet = $spreadsheet->getActiveSheet();
+    foreach ($data as $cell => $value) {
+      $worksheet->setCellValue($cell, $value);
+    }
+  }
+
+  public function prepareRow(
+    int $row,
+    WorkshopRegistration $workshopRegistration,
+    string $workshopLabel,
+    int $workshopSlotTimestamp,
+    string $siteName,
+  ): array {
+    /** @var int|string $registrationTimestamp */
+    $registrationTimestamp = $workshopRegistration->get('registration_date')->value;
+    /** @var int|string $deliveryTimestamp */
+    $deliveryTimestamp = $workshopRegistration->get('delivery_date')->value;
+
+    return [
+      \sprintf('A%d', $row) => $this->dateFormatter->format((int) $registrationTimestamp, 'default'),
+      \sprintf('B%d', $row) => $workshopLabel,
+      \sprintf('C%d', $row) => $this->dateFormatter->format($workshopSlotTimestamp, 'custom_short'),
+      \sprintf('D%d', $row) => $workshopRegistration->get('lastname')->value,
+      \sprintf('E%d', $row) => $workshopRegistration->get('firstname')->value,
+      \sprintf('F%d', $row) => $workshopRegistration->get('email')->value,
+      \sprintf('G%d', $row) => $workshopRegistration->get('phone')->value,
+      \sprintf('H%d', $row) => $workshopRegistration->get('can_have_companion')->value ? 'OUI' : 'NON',
+      \sprintf('I%d', $row) => $this->dateFormatter->format((int) $deliveryTimestamp, 'default'),
+      \sprintf('J%d', $row) => $siteName,
+      \sprintf('K%d', $row) => $workshopRegistration->id(),
+    ];
+  }
+
+}

