+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Healthcheck;
+
+use Drupal\rgds_core\Emergency\Client\EmergencyClientInterface;
+
+final readonly class WebserviceHealthcheck {
+
+  public function __construct(private EmergencyClientInterface $emergencyClient) {}
+
+  /**
+   * Run emergency synchro against given webservice URL.
+   *
+   * @param string $wsUrl
+   *   webservice URL to synchronize with.
+   *
+   * @return array{'type': string, 'content': string}
+   *   Returns tuple like array containing status type and content message.
+   */
+  public function status(string $wsUrl): array {
+    $dedicatedWsHttpClient = $this->emergencyClient->with([
+      'base_uri' => $wsUrl,
+    ]);
+
+    try {
+      $waitingTimes = $dedicatedWsHttpClient->getEmergencyWaitingTimes();
+
+      return [
+        'type' => 'status',
+        'content' => \sprintf(
+          'Connexion au webservice des urgences réussie. Nombre d\'entrées reçues : %d',
+          \count($waitingTimes),
+        ),
+      ];
+    }
+    catch (\Throwable $thrown) {
+      return [
+        'type' => 'error',
+        'content' => \sprintf('Erreur lors de la connexion au webservice des urgences : %s', $thrown->getMessage()),
+      ];
+    }
+  }
+
+}

