+    yield 'malformed_url' => [
+      'webserviceUrl' => 'http://in valid.url',
+      'expected' => [
+        'type' => 'error',
+        'content' => 'L\'URL du webservice des urgences n\'est pas une URL absolue valide.',
+      ],
