+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\HookHandler\Entity\Access;
+
+use Drupal\Core\Access\AccessResult;
+use Drupal\Core\Access\AccessResultInterface;
+use Drupal\Core\Session\AccountInterface;
+use Drupal\node\NodeInterface;
+
+final readonly class LockedContentAccess {
+
+  public function checkLockedContentAccess(
+    NodeInterface $node,
+    string $operation,
+    AccountInterface $account,
+  ): AccessResultInterface {
+    if (FALSE === \in_array($operation, ['edit', 'update', 'delete'], TRUE)) {
+      return AccessResult::neutral();
+    }
+
+    if (FALSE === $node->hasField('field_lock_content')) {
+      return AccessResult::neutral();
+    }
+
+    $isLocked = (bool) $node->get('field_lock_content')->value;
+    if (TRUE === $isLocked && FALSE === $account->hasPermission('edit locked content')) {
+      return AccessResult::forbidden();
+    }
+
+    return AccessResult::neutral();
+  }
+
+}

