+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Healthcheck;
+
+use Drupal\Component\Utility\NestedArray;
+use Drupal\Core\StringTranslation\StringTranslationTrait;
+use Drupal\rgds_core\Emergency\Client\EmergencyClientInterface;
+use GuzzleHttp\Utils;
+
+final class EmergencyWebserviceChecker {
+
+  public function __construct(private readonly EmergencyClientInterface $emergencyClient) {}
+
+  use StringTranslationTrait;
+
+  private const array TRANSLATION_OPTIONS = [
+    'context' => 'rgds: emergency waiting times',
+  ];
+
+  /**
+   * Run emergency synchro against a given webservice URL.
+   *
+   * @param non-empty-string $wsUrl
+   *   webservice URL to synchronize with.
+   *
+   * @return array{'type': 'status'|'error', 'content': \Drupal\Core\StringTranslation\TranslatableMarkup}
+   *   Returns tuple like array containing status type and translatable content message.
+   */
+  public function status(string $wsUrl): array {
+    try {
+      $options = NestedArray::mergeDeep(
+        EmergencyClientInterface::EMERGENCY_WS_CLIENT_OPTIONS,
+        [
+          'headers' => [
+            'User-Agent' => \sprintf('RGDS CMS WS-CHECK %s', Utils::defaultUserAgent()),
+          ],
+          'base_uri' => $wsUrl,
+        ],
+      );
+      $waitingTimes = $this->emergencyClient->getEmergencyWaitingTimes($options);
+
+      return [
+        'type' => 'status',
+        'content' => $this->t(
+          'Emergency Webservice connection successfully. Total updated entries: @timesCount',
+          ['@timesCount' => \count($waitingTimes)],
+          self::TRANSLATION_OPTIONS,
+        ),
+      ];
+    }
+    catch (\Throwable $error) {
+      return [
+        'type' => 'error',
+        'content' => $this->t(
+          'An error occurred while connecting to the emergency web service: @message',
+          ['@message' => $error->getMessage()],
+          self::TRANSLATION_OPTIONS,
+        ),
+      ];
+    }
+  }
+
+}

