+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Client;
+
+use Drupal\rgds_core\Emergency\Storage\EmergencyFileWriter;
+use GuzzleHttp\ClientInterface;
+use GuzzleHttp\Promise\PromiseInterface;
+use Psr\Http\Message\RequestInterface;
+use Psr\Http\Message\ResponseInterface;
+use Psr\Http\Message\UriInterface;
+
+final readonly class ContentWriterHttpClient implements ClientInterface {
+
+  public function __construct(
+    private ClientInterface $emergencyClientDecorated,
+    private EmergencyFileWriter $emergencyFileWriter,
+  ) {}
+
+  public function getConfig(?string $option = NULL): mixed {
+    return $this->emergencyClientDecorated->getConfig($option);
+  }
+
+  public function send(RequestInterface $request, array $options = []): ResponseInterface {
+    return $this->emergencyClientDecorated->send($request, $options);
+  }
+
+  public function sendAsync(RequestInterface $request, array $options = []): PromiseInterface {
+    return $this->emergencyClientDecorated->sendAsync($request, $options);
+  }
+
+  public function requestAsync(string $method, $uri, array $options = []): PromiseInterface {
+    return $this->emergencyClientDecorated->requestAsync($method, $uri, $options);
+  }
+
+  public function request(string $method, $uri, array $options = []): ResponseInterface {
+    $response = $this->emergencyClientDecorated->request($method, $uri, $options);
+    $body = $response->getBody();
+
+    $wsUri = $options['base_uri'] ?? $uri;
+    if ($wsUri instanceof UriInterface) {
+      $wsUri = $wsUri->__toString();
+    }
+
+    if (FALSE === \is_string($wsUri) || '' === $wsUri) {
+      throw new \InvalidArgumentException(\sprintf('The uri must be a non-empty-string or a %s', UriInterface::class));
+    }
+
+    $this->emergencyFileWriter->write($wsUri, $body->getContents());
+    // The getContent method consumes the stream. To be able to read it again, we need to rewind it.
+    $body->rewind();
+
+    return $response;
+  }
+
+}

