+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\FormAjax;
+
+use Drupal\Component\Utility\UrlHelper;
+use Drupal\Core\Ajax\AjaxResponse;
+use Drupal\Core\Ajax\HtmlCommand;
+use Drupal\Core\Form\FormStateInterface;
+use Drupal\Core\StringTranslation\TranslatableMarkup;
+
+final class AjaxEmergencyWebservice {
+
+  public const string AJAX_EMERGENCY_HEALTHCHECK_WRAPPER_ID = 'siteform-ajax-wrapper-healthcheck';
+
+  private const string PRIVATE_TMP_FOLDER = 'private://tmp';
+
+  // phpcs:disable SlevomatCodingStandard.Functions.UnusedParameter
+  public static function healthCheckCallback(array &$form, FormStateInterface $form_state): AjaxResponse {
+    $formWsValue = $form_state->getValue('field_emergencies_ws');
+    if (FALSE === \is_array($formWsValue)) {
+      return self::sendErrorAjaxResponse(
+        self::translate('L\'URL du webservice des urgences n\'a pas pu être récupérée.'),
+      );
+    }
+
+    $formUri = $formWsValue[0]['uri'] ?? NULL;
+    if (FALSE === \is_string($formUri) || '' === $formUri) {
+      return self::sendErrorAjaxResponse(
+        self::translate('L\'URL du webservice des urgences est vide.'),
+      );
+    }
+
+    if (FALSE === UrlHelper::isValid($formUri, TRUE)) {
+      return self::sendErrorAjaxResponse(
+        self::translate('L\'URL du webservice des urgences n\'est pas une URL absolue valide.'),
+      );
+    }
+
+    /** @var \Drupal\rgds_core\Emergency\Healthcheck\EmergencyWebserviceChecker $wsHealthcheck */
+    $wsHealthcheck = \Drupal::service('rgds_core.emergency.webservice_checker');
+    $message = $wsHealthcheck->status($formUri);
+
+    $html = \sprintf(
+      '<div class="messages messages--%s">%s</div>',
+      $message['type'],
+      $message['content'],
+    );
+
+    if ('error' === $message['type']) {
+      return self::sendAjaxResponse($html);
+    }
+
+    $hostUri = \parse_url($formUri, \PHP_URL_HOST);
+    if (FALSE === \is_string($hostUri)) {
+      return self::sendErrorAjaxResponse(
+        self::translate('L\'URL du webservice des urgences n\'est pas une URL valide.'),
+      );
+    }
+
+    /** @var \Drupal\rgds_core\Helper\MachineNameTransliteration $machineNameTransliteration */
+    $machineNameTransliteration = \Drupal::service('rgds_core.helper.machine_name_transliteration');
+    $machineName = $machineNameTransliteration->transliterate($hostUri);
+    /** @var \Drupal\Core\File\FileUrlGenerator $fileUrlGenerator */
+    $fileUrlGenerator = \Drupal::service('file_url_generator');
+    $filepath = $fileUrlGenerator->generateString(\sprintf('%s/%s.csv', self::PRIVATE_TMP_FOLDER, $machineName));
+
+    $html .= \sprintf(
+      '<div>&lt; <a href="%s">%s</a> &gt;</div>',
+      $filepath,
+      self::translate('Télécharger le fichier importé'),
+    );
+
+    return self::sendAjaxResponse($html);
+  }
+
+  private static function sendAjaxResponse(string $html): AjaxResponse {
+    $selector = \sprintf('#%s', self::AJAX_EMERGENCY_HEALTHCHECK_WRAPPER_ID);
+
+    return (new AjaxResponse())->addCommand(
+      new HtmlCommand($selector, $html),
+    );
+  }
+
+  private static function sendErrorAjaxResponse(string|TranslatableMarkup $errorMessage): AjaxResponse {
+    $html = \sprintf('<div class="messages messages--error">%s</div>', $errorMessage);
+
+    return self::sendAjaxResponse($html);
+  }
+
+  private static function translate(string $message): TranslatableMarkup {
+    return new TranslatableMarkup($message, [], ['context' => 'rgds: emergency waiting times']);
+  }
+
+}

