+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Emergency\Storage;
+
+use Drupal\Component\Transliteration\TransliterationInterface;
+use Drupal\Core\File\FileExists;
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Logger\RfcLogLevel;
+use Drupal\Core\Utility\Error;
+use Drupal\file\FileRepositoryInterface;
+use Drupal\rgds_core\Emergency\Exception\FileSaveException;
+use Psr\Log\LoggerInterface;
+
+final readonly class EmergencyFileWriter {
+
+  private const string PRIVATE_TMP_FOLDER = 'private://tmp';
+
+  public function __construct(
+    private FileRepositoryInterface $fileRepository,
+    private FileSystemInterface $fileSystem,
+    private TransliterationInterface $transliteration,
+    private LoggerInterface $logger,
+  ) {}
+
+  /**
+   * Save the content into a file in the private tmp folder with the host name as a transliterated filename.
+   *
+   * @param non-empty-string $webServiceUri
+   *   The uri of the webservice that has been called.
+   * @param string $content
+   *   The content of the request to save in file.
+   *
+   * @throws \Drupal\rgds_core\Emergency\Exception\FileSaveException
+   */
+  public function write(string $webServiceUri, string $content): void {
+    $dirUri = self::PRIVATE_TMP_FOLDER;
+    $dirIsCreated = $this->fileSystem->prepareDirectory($dirUri, FileSystemInterface::CREATE_DIRECTORY);
+    if (FALSE === $dirIsCreated) {
+      throw new FileSaveException(\sprintf('Cannot prepare the directory %s', $dirUri));
+    }
+
+    try {
+      $filePath = $this->getPrivateTmpFolderForUri($webServiceUri);
+      $file = $this->fileRepository->writeData($content, $filePath, FileExists::Replace);
+      $file->setTemporary();
+      $file->save();
+    }
+    catch (\Throwable $exception) {
+      $this->logger->log(RfcLogLevel::ERROR, Error::DEFAULT_ERROR_MESSAGE, Error::decodeException($exception));
+
+      throw new FileSaveException(
+        \sprintf('File could not be saved correctly: %s', $exception->getMessage()),
+        $exception->getCode(),
+        $exception,
+      );
+    }
+  }
+
+  private function getPrivateTmpFolderForUri(string $uri): string {
+    $host = \parse_url($uri, \PHP_URL_HOST);
+    if (FALSE === \is_string($host)) {
+      throw new FileSaveException('The URL for the emergency web service is not a valid URL.');
+    }
+    $filename = $this->transliteration->transliterate($host);
+
+    return \sprintf('%s/%s.csv', self::PRIVATE_TMP_FOLDER, $filename);
+  }
+
+}

