+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Helper;
+
+use Drupal\Component\Transliteration\TransliterationInterface;
+
+final readonly class MachineNameTransliteration implements TransliterationInterface {
+
+  public function __construct(private TransliterationInterface $transliterationDecorated) {}
+
+  public function transliterate($string, $langcode = 'en', $unknown_character = '', $max_length = NULL): string {
+    $transliteration = $this->transliterationDecorated->transliterate(
+      $string,
+      $langcode,
+      $unknown_character,
+      $max_length,
+    );
+
+    $machineName = \preg_replace('/[^a-z0-9_]+/', '_', \strtolower($transliteration));
+
+    if (NULL === $machineName) {
+      throw new \LogicException(\sprintf('A problem has occurred while generating machine name for "%s".', $string));
+    }
+
+    return $machineName;
+  }
+
+  public function removeDiacritics($string): string {
+    return $this->transliterationDecorated->removeDiacritics($string);
+  }
+
+}

