+final readonly class SafeAliasRepositoryDecorator implements AliasRepositoryInterface {
+
+  public function __construct(private AliasRepositoryInterface $decoratedAliasRepository) {}
+
+  public function preloadPathAlias($preloaded, $langcode): array {
+    return $this->decoratedAliasRepository->preloadPathAlias($preloaded, $langcode);
+  }
+
+  public function lookupBySystemPath($path, $langcode): array|null {
+    return $this->decoratedAliasRepository->lookupBySystemPath($path, $langcode);
+  }
+
+  public function lookupByAlias($alias, $langcode): array|bool|null {
+    if (\function_exists('mb_convert_encoding')) {
+      // Transform invalid characters to question mark (?).
+      // Only ASCII/UTF8 characters are allowed in a path alias.
+      // Invalidate all other characters to prevent Postgres errors.
+      $alias = \mb_convert_encoding($alias, 'UTF-8', 'UTF-8');
+    }
+
+    return $this->decoratedAliasRepository->lookupByAlias($alias, $langcode);
+  }
+
+  public function pathHasMatchingAlias($initial_substring): bool {
+    return $this->decoratedAliasRepository->pathHasMatchingAlias($initial_substring);
+  }
+
+}

