+  public function testTempFileIsWritten(): void {
+    $response = $this->createMockResponse();
+    $this->registerMockClient($response);
+    $wsHealthcheck = $this->container->get('rgds_core.emergency.webservice_checker');
+
+    $result = $wsHealthcheck->status('http://www.valid.url');
+    $machineName = 'www_valid_url';
+    $expectedFilePath = \sprintf('%s/%s.csv', self::URI_PATH_TEST, $machineName);
+    $this->assertFileExists($this->fileSystem->realpath($expectedFilePath) ?: '');
+    $this->assertSame('status', $result['type'], (string) $result['content']);
+  }
+
+  private function createMockResponse(): ResponseInterface&MockObject {
+    $response = $this->createMock(ResponseInterface::class);
+    $stream = new Stream(\fopen(__DIR__ . '/fixtures/emergency_webservice_response.csv', 'r'));
+    $response->method('getBody')->willReturn($stream);
+    $response->method('getStatusCode')->willReturn(200);
+    $response->method('getHeader')->willReturn(['text/csv']);
+
+    return $response;
+  }
+
+  private function registerMockClient(MockObject&ResponseInterface $response): ClientInterface&MockObject {
+    $httpClientMock = $this->createMock(ClientInterface::class);
+    $httpClientMock->method('request')->willReturn($response);
+    $this->container->set('http_client', $httpClientMock);
+
+    return $httpClientMock;
+  }
+
+}

