+<?php
+
+declare(strict_types=1);
+
+namespace src\Kernel\PathAlias;
+
+use Drupal\Core\Language\LanguageInterface;
+use Drupal\Tests\Traits\Core\PathAliasTestTrait;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\path_alias\AliasRepositoryInterface;
+
+class SafeAliasRepositoryTest extends KernelTestBase {
+
+  use PathAliasTestTrait;
+
+  private AliasRepositoryInterface $sutRepository;
+
+  protected function setUp(): void {
+    parent::setUp();
+    // Decorated path_alias.repository by "rgds_core.safe_alias_repository.decorator".
+    $this->sutRepository = $this->container->get('path_alias.repository');
+  }
+
+  /**
+   * With pgsql non UTF-8 char could lead to a DB error. We want to be sure that no invalid UTF8 passes through URL.
+   *
+   * There is no exception thrown with Sqlite because non UTF-8 char doesn't trigger an error.
+   *
+   * @dataProvider providerTestLookUpByAlias
+   */
+  public function testLookUpByAlias(string $alias, ?string $expected): void {
+    $this->createPathAlias('/target/path', $alias);
+
+    $result = $this->sutRepository->lookupByAlias($alias, LanguageInterface::LANGCODE_NOT_SPECIFIED);
+
+    self::assertSame($expected, $result['path'] ?? $result);
+  }
+
+  public function providerTestLookUpByAlias() {
+    yield 'simple alias' => ['/foo', '/target/path'];
+    yield 'with french letters' => ['/éèàçùôîï', '/target/path'];
+    // ± symbol.
+    yield 'with symbol' => ["/foo\xB1bar", NULL];
+    // Invalid UTF-8 (Islandish "Eth" ð).
+    yield 'with invalid UTF-8 letter' => ["/foo/bar/" . \urldecode('%f0'), NULL];
+  }
+
+}

