+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Kernel;
+
+use Drupal\Core\DependencyInjection\ContainerBuilder;
+
+class FileTestBase extends KernelTestBase {
+
+  /**
+   * {@inheritdoc}
+   */
+  protected static $modules = [
+    'file_test',
+    'file_module_test',
+    'system',
+  ];
+
+  protected function setUpBeforeInstallSiteConfig(): void {
+    parent::setUpBeforeInstallSiteConfig();
+
+    $this->installSchema('file', ['file_usage']);
+    $this->installEntitySchema('file');
+  }
+
+  protected function setUp(): void {
+    parent::setUp();
+    // @see Drupal\KernelTests\Core\File\File.
+    unset($GLOBALS['config']['system.file']);
+    \Drupal::configFactory()->getEditable('system.file')->set('default_scheme', 'public')->save();
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public function register(ContainerBuilder $container): void {
+    parent::register($container);
+
+    $container
+      ->register('stream_wrapper.private', 'Drupal\Core\StreamWrapper\PrivateStream')
+      ->addTag('stream_wrapper', ['scheme' => 'private']);
+  }
+
+  protected function setUpFilesystem() {
+    $public_file_directory = $this->siteDirectory . '/files';
+    $private_file_directory = $this->siteDirectory . '/private';
+
+    \mkdir($this->siteDirectory, 0775);
+    \mkdir($this->siteDirectory . '/files', 0775);
+    \mkdir($this->siteDirectory . '/private', 0775);
+    \mkdir($this->siteDirectory . '/files/config/sync', 0775, TRUE);
+
+    $this->setSetting('file_public_path', $public_file_directory);
+    $this->setSetting('file_private_path', $private_file_directory);
+    $this->setSetting('config_sync_directory', $this->siteDirectory . '/files/config/sync');
+  }
+
+}

