+<?php
+
+declare(strict_types=1);
+
+namespace E2e\Tests\Content;
+
+use E2e\Tests\EndToEndTestBase;
+use E2e\Tests\ContentManager;
+use E2e\Tests\NodeBundle;
+use E2e\Tests\Site;
+use Facebook\WebDriver\WebDriverBy;
+use Facebook\WebDriver\Exception\NoSuchElementException;
+
+final class LockedContentAccessTest extends EndToEndTestBase {
+
+  /**
+   * @dataProvider bundleSiteWebmasterProvider
+   */
+  public function testWebmasterCannotSeeBlockFieldAndCannotEditLockedNode(
+    $bundle,
+    $site,
+    $webmasterLoginMethod
+  ): void {
+    $contentManager = new ContentManager($this->client());
+    $lockContentCheckboxSelector = 'input[name*="field_lock_content"]';
+
+    // 1) Create a blocked node as admin-rgds on the target site.
+    $this->loginAsAdminRgds($this->client(), $site);
+
+    // Try to open node add page for the bundle. If it does not exist on the
+    // site, skip the scenario.
+    $addPath = \sprintf('%s/node/add/%s', $site->baseUrl(), $bundle->value);
+    $this->client()->request('GET', $addPath);
+
+    //create a node.
+    $contentManager->fillContentTitle('E2E blocked ' . $bundle->value . ' ' . time());
+    $contentManager->saveContent();
+    // After saving, retrieve the created node URL.
+    $crawler = $this->client()->refreshCrawler();
+    $nodeUrl = $this->client()->getCurrentURL();
+    // Get the edit URL for the created node from admin quick nav.
+    $editElement = $crawler->findElement(
+      WebDriverBy::cssSelector('[data-e2e-selector="navigation-local-tasks"] > ul > li:nth-child(2) > a'),
+    );
+    $editPath = $editElement->getAttribute('href');
+    $editUrl = \sprintf('%s%s', $site->baseUrl(), $editPath);
+    $this->logoutAndClearSession($site);
+
+    // 2) Login as webmaster and verify the checkbox is not visible in edit form.
+    $this->{$webmasterLoginMethod}($this->client(), $site);
+
+    // Open the edit page for the node.
+    $crawler = $this->client()->request('GET', $editUrl);
+    try {
+      $hiddenInput = $crawler->findElement(WebDriverBy::cssSelector($lockContentCheckboxSelector));
+    }
+    catch (NoSuchElementException) {
+      $this->fail('The "field_lock_content" field was not found on the edit form.');
+    }
+    self::assertSame('hidden', $hiddenInput->getAttribute('type'));
+
+    //3) log as admin and block the content
+    $this->logoutAndClearSession($site);
+    $this->loginAsAdminRgds($this->client(), $site);
+    $crawler = $this->client()->request('GET', $editUrl);
+    // Try to check the block checkbox.
+    try {
+      $el = $crawler->findElement(WebDriverBy::cssSelector($lockContentCheckboxSelector));
+      self::assertSame('checkbox', $el->getAttribute('type'));
+      $el->click();
+    }
+    catch (NoSuchElementException) {
+      $this->logoutAndClearSession($site);
+      $this->fail(
+        \sprintf(
+          'The "field_lock_content" checkbox was not found on the add form for bundle %s on site %s.',
+          $bundle->value,
+          $site->name,
+        ),
+      );
+    }
+    $this->logoutAndClearSession($site);
+
+    // 4) The webmaster must NOT be able to edit the blocked node page.
+    $this->{$webmasterLoginMethod}($this->client(), $site);
+    $crawler = $this->client()->request('GET', $editUrl);
+
+    try {
+      $navAdmin = $crawler->findElement(WebDriverBy::cssSelector('[data-e2e-selector="navigation-local-tasks"]'));
+      // If the navigation exists, ensure it does not contain an edit action.
+      $this->assertStringNotContainsString('edit', strtolower($navAdmin->getText()));
+    }
+    catch (NoSuchElementException) {
+      // Navigation local tasks not present: expected when the user has no
+      // permission to edit the node.
+      $this->assertTrue(TRUE);
+    }
+
+    $this->logoutAndClearSession($site);
+
+    // 4) Cleanup: delete the created node as admin-rgds.
+    $this->loginAsAdminRgds($this->client(), $site);
+    $this->client()->request('GET', $nodeUrl);
+    $contentManager->deleteContent();
+    $this->logoutAndClearSession($site);
+  }
+
+  public function bundleSiteWebmasterProvider(): array {
+    return [
+      [NodeBundle::NewsPage, Site::Corporate, 'loginAsWebmasterCorporate'],
+      [NodeBundle::Page, Site::Corporate, 'loginAsWebmasterCorporate'],
+      [NodeBundle::FinancePage, Site::Corporate, 'loginAsWebmasterCorporate'],
+    ];
+  }
+
+}

