+
+  public function alter(array &$bundles): void {
+    $this->useBundleClassForWorkshopList($bundles);
+  }
+
+  private function useBundleClassForWorkshopList(array &$bundles): void {
+    if (FALSE === isset($bundles['node'])) {
+      return;
+    }
+
+    if (FALSE === \is_array($bundles['node'])) {
+      return;
+    }
+
+    if (FALSE === isset($bundles['node']['workshop_list'])) {
+      return;
+    }
+
+    if (FALSE === \is_array($bundles['node']['workshop_list'])) {
+      return;
+    }
+
+    $bundles['node']['workshop_list']['class'] = WorkshopList::class;
+  }
+
+}

