+<?php
+
+declare(strict_types=1);
+
+namespace src\Kernel\Workshop\Controller;
+
+use Drupal\Component\EventDispatcher\ContainerAwareEventDispatcher;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\micro_site\Entity\SiteInterface;
+use Drupal\node\Entity\Node;
+use Drupal\paragraphs\Entity\Paragraph;
+use Drupal\rgds_core\Model\Drupal\Field\Boolean;
+use Drupal\rgds_core\Workshop\Controller\WorkshopController;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\Response;
+
+/**
+ * Class WorkshopControllerTest.
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ */
+class WorkshopControllerTest extends KernelTestBase {
+
+  /**
+   * {@inheritdoc}
+   */
+  protected static $modules = [
+    'datetime',
+    'datetime_range',
+    'entity_reference_revisions',
+    'telephone',
+    'paragraphs',
+    'paragraphs_limits',
+  ];
+
+  private WorkshopController $workshopController;
+
+  protected function setUpBeforeInstallSiteConfig(): void {
+    parent::setUpBeforeInstallSiteConfig();
+
+    $this->installEntitySchema('paragraph');
+    $this->installEntitySchema('site_information_setting');
+    $this->installEntitySchema('workshop_registration');
+  }
+
+  public function setup(): void {
+    parent::setUp();
+
+    $this->workshopController = new WorkshopController(
+      $this->container->get('entity_type.manager'),
+      $this->container->get('plugin.manager.mail'),
+      $this->container->get('messenger'),
+      $this->createStub(ContainerAwareEventDispatcher::class),
+      $this->container->get('micro_site.negotiator'),
+      $this->container->get('rgds_core.workshop.helper.workshop_registration')
+    );
+  }
+
+  /**
+   * @dataProvider MaternityWorkshopDataProvider
+   */
+  public function testMaternityWorkshopRegistrationIsSaved(array $requestData, int $expectedStatus): void {
+    $fooSite = $this->createFooSiteInstitution();
+    $this->switchSite('http://foo.com');
+    $workshop = $this->createMaternityWorkshop($fooSite);
+    $slot = $this->createWorkshopSlot();
+    $workshopIds = [
+      'workshop_id' => $workshop->id(),
+      'workshop_slot_id' => $slot->id(),
+    ];
+
+    $request = Request::create('http://foo.com', Request::METHOD_POST, $requestData + $workshopIds);
+
+    $response = $this->workshopController->save($request);
+
+    $this->assertSame($expectedStatus, $response->getStatusCode(), $response->getContent());
+  }
+
+  public static function maternityWorkshopDataProvider(): \Generator {
+    yield 'with childbirth date' => [
+      'requestData' => [
+        'lastname' => 'test',
+        'firstname' => 'test',
+        'phone' => '0610203040',
+        'email' => 'test@test.com',
+        'delivery_date' => '25/12/3000',
+
+      ],
+      'expectedStatusCode' => Response::HTTP_CREATED,
+    ];
+    yield 'without childbirth' => [
+      'requestData' => [
+        'lastname' => 'test',
+        'firstname' => 'test',
+        'phone' => '0610203040',
+        'email' => 'test@test.com',
+      ],
+      'expectedStatusCode' => Response::HTTP_INTERNAL_SERVER_ERROR,
+    ];
+    yield 'with bad email' => [
+      'requestData' => [
+        'lastname' => 'test',
+        'firstname' => 'test',
+        'phone' => '0610203040',
+        'email' => 'pouet',
+      ],
+      'expectedStatusCode' => Response::HTTP_INTERNAL_SERVER_ERROR,
+    ];
+    yield 'missing phone number' => [
+      'requestData' => [
+        'lastname' => 'test',
+        'firstname' => 'test',
+        'email' => 'test@test.com',
+        'delivery_date' => '25/12/3000',
+      ],
+      'expectedStatusCode' => Response::HTTP_INTERNAL_SERVER_ERROR,
+    ];
+    yield 'bad childbirth delivery date' => [
+      'requestData' => [
+        'lastname' => 'test',
+        'firstname' => 'test',
+        'email' => 'test@test.com',
+        'delivery_date' => '25123000',
+      ],
+      'expectedStatusCode' => Response::HTTP_INTERNAL_SERVER_ERROR,
+    ];
+  }
+
+  public function testGenericWorkshopRegistrationIsSaved(): void {
+    $fooSite = $this->createFooSiteInstitution();
+    $this->switchSite('http://foo.com');
+    $workshop = $this->createGenericWorkshop($fooSite);
+    $slot = $this->createWorkshopSlot();
+
+    $request = Request::create('http://foo.com', Request::METHOD_POST, [
+      'lastname' => 'test',
+      'firstname' => 'test',
+      'phone' => '0610203040',
+      'email' => 'test@test.com',
+      'workshop_id' => $workshop->id(),
+      'workshop_slot_id' => $slot->id(),
+    ]);
+    $response = $this->workshopController->save($request);
+
+    $this->assertSame(201, $response->getStatusCode(), $response->getContent());
+  }
+
+  public function createMaternityWorkshop(SiteInterface $fooSite): Node {
+    $workshop = Node::create([
+      'type' => 'workshop',
+      'title' => 'a Maternity workshop',
+      'site_id' => $fooSite->id(),
+      'field_weight' => 0,
+      'changed' => (new \DateTimeImmutable('2020/07/31 12:13:00'))->getTimestamp(),
+    ]);
+    $workshop->save();
+
+    return $workshop;
+  }
+
+  private function createGenericWorkshop(SiteInterface $fooSite): Node {
+    $workshop = Node::create([
+      'type' => 'workshop',
+      'title' => 'a Maternity workshop',
+      'site_id' => $fooSite->id(),
+      'field_weight' => 1,
+      'field_is_generic_workshop' => Boolean::true()->value,
+      'changed' => (new \DateTimeImmutable('2025/07/31 12:13:00'))->getTimestamp(),
+    ]);
+    $workshop->save();
+
+    return $workshop;
+  }
+
+  private function createWorkshopSlot(): Paragraph {
+    $workshopSlot = Paragraph::create([
+      'type' => 'workshop_slot',
+      'field_date_range' => [
+        'value' => '2026-03-26T13:55:46',
+        'end_value' => '2026-03-26T13:55:46',
+      ],
+      'field_number_places' => '10',
+    ]);
+    $workshopSlot->save();
+
+    return $workshopSlot;
+  }
+
+}

