+namespace src\Kernel\PaymentLink;
+
+use Drupal\Core\Session\AccountInterface;
+use Drupal\Core\Session\AccountProxyInterface;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\rgds_core\PaymentLink\Model\PaymentLink;
+use Drupal\rgds_core\PaymentLink\Repository\PaymentLinkRepository;
+use PHPUnit\Framework\Attributes\DataProvider;
+
+class PaymentLinkTest extends KernelTestBase {
+
+  private PaymentLinkRepository $paymentLinkRepository;
+
+  protected function setUp(): void {
+    parent::setUp();
+    $this->installSchema('rgds_core', ['payment_link']);
+    $this->paymentLinkRepository = $this->container->get('rgds_core.payment_link.repository');
+  }
+
+  #[DataProvider('trigramProvider')]
+  public function testPaymentLinkTrigramIsCaseInsensitive(string $trigram): void {
+    $user = $this->createMock(AccountProxyInterface::class);
+    $rgdsAccount = $this->createAdminRgdsUserAndSwitchToItsAccount();
+    $user->method('id')->willReturn($rgdsAccount->id());
+    $paymentLink = $this->createPaymentLink($trigram, $rgdsAccount);
+
+    $this->paymentLinkRepository->insertOrUpdate($paymentLink, $user);
+    $result = $this->paymentLinkRepository->fetchByTrigram('abc');
+
+    $this->assertInstanceOf(PaymentLink::class, $result);
+    $expectedTrigram = \strtoupper($trigram);
+    $this->assertEquals($expectedTrigram, $result->getTrigram());
+  }
+
+  public static function trigramProvider(): \Generator {
+    yield 'lower case' => ['abc'];
+    yield 'upper case' => ['ABC'];
+    yield 'mixed cases' => ['abC'];
+  }
+
+  private function createPaymentLink(string $trigram, AccountInterface $user): PaymentLink {
+    return PaymentLink::fromUserInput(
+      $trigram,
+      'https://example.com/',
+      // Can return string despite phpdoc declaration.
+      (int) $user->id(),
+      new \DateTimeImmutable(),
+      new \DateTimeImmutable(),
+    );
+  }
+
+}

