+use Drupal\Core\TypedData\DataDefinition;
+
+#[FieldType(
+  id: 'rgds_json',
+  label: new TranslatableMarkup('JSON (raw)'),
+  description: [
+    new TranslatableMarkup('Allows JSON data to be stored in the database. Stores the data in a JSON column in the database.'),
+  ],
+  no_ui: true,
+  constraints: ['RgdsValidJson' => []],
+)]
+final class JsonItem extends FieldItemBase {
+
+  /**
+   * {@inheritdoc}
+   */
+  public static function schema(FieldStorageDefinitionInterface $field_definition): array {
+    return [
+      'columns' => [
+        'value' => [
+          'type' => 'json',
+          'pgsql_type' => 'json',
+          'mysql_type' => 'json',
+          'sqlite_type' => 'text',
+          'not null' => FALSE,
+        ],
+      ],
+    ];
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public function isEmpty(): bool {
+    $value = $this->get('value')->getValue();
+    return NULL === $value || '' === $value;
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public static function propertyDefinitions(FieldStorageDefinitionInterface $field_definition): array {
+    $properties = [];
+
+    $properties['value'] = DataDefinition::create('string')
+      ->setLabel(\t('JSON value'));
+
+    return $properties;
+  }
+}

