+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Entity\Workshop;
+
+use Drupal\rgds_core\Exception\NotSupportedException;
+use Drupal\rgds_core\Workshop\Entity\Workshop\ExtraInput\Type;
+
+/**
+ * The definition of an extra input defined by the contributor.
+ *
+ * @phpstan-type ExtraInputDefinitionShape array{
+ *   id: non-empty-string,
+ *   label: non-empty-string,
+ *   isRequired: bool,
+ *   type: non-empty-string,
+ * }
+ *
+ * @package Drupal\rgds_core\Workshop\Entity\Workshop
+ */
+final readonly class ExtraInputDefinition implements \JsonSerializable {
+  private const int COLUMN_COUNT = 4;
+
+  public function __construct(
+    /**
+     * The unique identifier.
+     *
+     * @var non-empty-string
+     */
+    public string $id,
+    /**
+     * The human-readable label.
+     *
+     * @var non-empty-string
+     */
+    public string $label,
+    public bool $isRequired,
+    public Type $type = Type::Text,
+  ) {}
+
+  /**
+   * Create multiple ExtraInput instances from a raw CSV string.
+   *
+   * @param string $raw
+   *   The raw CSV string.
+   *
+   * @throws \Drupal\rgds_core\Exception\NotSupportedException
+   *
+   * @return array<self>
+   *   The parsed extra inputs.
+   */
+  public static function createMany(string $raw): array {
+    $raw = \trim($raw);
+    if ('' === $raw) {
+      return [];
+    }
+
+    $stream = \fopen('php://memory', 'r+');
+    if (FALSE === \is_resource($stream)) {
+      throw new NotSupportedException('Failed to open memory stream for parsing extra inputs.');
+    }
+    \fwrite($stream, $raw);
+    \rewind($stream);
+
+    $extraInputs = [];
+    $seenIds = [];
+    try {
+      while (FALSE !== ($row = \fgetcsv($stream))) {
+        if ([NULL] === $row) {
+          continue;
+        }
+
+        $extraInput = self::fromRow($row);
+
+        if (TRUE === \in_array($extraInput->id, $seenIds, TRUE)) {
+          throw new NotSupportedException(\sprintf('Duplicate extra input id "%s".', $extraInput->id));
+        }
+
+        $seenIds[] = $extraInput->id;
+        $extraInputs[] = $extraInput;
+      }
+    } finally {
+      \fclose($stream);
+    }
+
+    return $extraInputs;
+  }
+
+  /**
+   * Create an ExtraInput from a parsed CSV row.
+   *
+   * @param array<int, string|null> $row
+   *   The CSV row as an array of column values.
+   *
+   * @throws \Drupal\rgds_core\Exception\NotSupportedException
+   * @throws \ValueError
+   */
+  private static function fromRow(array $row): self {
+    if (self::COLUMN_COUNT !== \count($row)) {
+      throw new NotSupportedException(
+        \sprintf('Invalid extra input row. Expected %d columns, got %d.', self::COLUMN_COUNT, \count($row)),
+      );
+    }
+
+    [$label, $id, $isRequired, $typeValue] = $row;
+
+    $label = \trim((string) $label);
+    $id = \trim((string) $id);
+    $isRequired = \trim((string) $isRequired);
+    $typeValue = \trim((string) $typeValue);
+
+    if ('' === $label) {
+      throw new NotSupportedException('Extra input label cannot be empty.');
+    }
+
+    if ('' === $id) {
+      throw new NotSupportedException('Extra input id cannot be empty.');
+    }
+
+    if (FALSE === \in_array($isRequired, ['0', '1'], TRUE)) {
+      throw new NotSupportedException(\sprintf('Extra input isRequired must be "0" or "1", got "%s".', $isRequired));
+    }
+
+    return new self(
+      id: $id,
+      label: $label,
+      isRequired: '1' === $isRequired,
+      type: Type::from($typeValue),
+    );
+  }
+
+  /**
+   * JSON representation for front-end consumption.
+   *
+   * @return ExtraInputDefinitionShape
+   *   The JSON.
+   */
+  public function jsonSerialize(): array {
+    return [
+      'id' => $this->id,
+      'label' => $this->label,
+      'isRequired' => $this->isRequired,
+      'type' => $this->type->value,
+    ];
+  }
+
+}

