+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Entity\WorkshopRegistration;
+
+use Drupal\rgds_core\Workshop\Entity\Workshop\ExtraInput\Type;
+use Drupal\rgds_core\Workshop\Exception\InvalidExtraInputException;
+
+/**
+ * One answered input.
+ *
+ * @phpstan-type ExtraInputShape array{
+ *   id: non-empty-string,
+ *   label: non-empty-string,
+ *   type: non-empty-string,
+ *   required: bool,
+ *   value: string|null,
+ *   }
+ */
+final class ExtraInput implements \JsonSerializable {
+
+  public function __construct(
+    /**
+     * The unique identifier.
+     *
+     * @var non-empty-string
+     */
+    public string $id,
+    /**
+     * The human-readable label.
+     *
+     * @var non-empty-string
+     */
+    public string $label,
+    public Type $type,
+    public bool $isRequired,
+    /**
+     * The submitted value.
+     *
+     * @var string|null
+     */
+    public string|null $value,
+  ) {}
+
+  /**
+   * Parses and validates a single decoded JSON entry.
+   *
+   * @param array<mixed> $entry
+   *   A decoded JSON value, expected to be an associative array.
+   *
+   * @throws \Drupal\rgds_core\Workshop\Exception\InvalidExtraInputException
+   *   When the entry is invalid.
+   *
+   * @SuppressWarnings("PHPMD.CyclomaticComplexity")
+   */
+  public static function fromArray(array $entry): self {
+    $id = $entry['id'] ?? '';
+    if (FALSE === \is_string($id) || '' === $id) {
+      throw new InvalidExtraInputException('Extra input id must be a non empty string.');
+    }
+
+    $label = $entry['label'] ?? '';
+    if (FALSE === \is_string($label) || '' === $label) {
+      throw new InvalidExtraInputException('Extra input label must be a non empty string.');
+    }
+
+    $type = $entry['type'] ?? '';
+    if (FALSE === \is_string($type) || '' === $type) {
+      throw new InvalidExtraInputException('Extra input type must be a non empty string.');
+    }
+
+    $required = $entry['required'] ?? NULL;
+    if (FALSE === \is_bool($required)) {
+      throw new InvalidExtraInputException('Extra input required must be a boolean.');
+    }
+
+    $value = $entry['value'] ?? NULL;
+    if (NULL !== $value && FALSE === \is_string($value)) {
+      throw new InvalidExtraInputException('Extra input value must be a string or null.');
+    }
+
+    return new self(
+      id: $id,
+      label: $label,
+      type: Type::from($type),
+      isRequired: $required,
+      value: $value,
+    );
+  }
+
+  /**
+   * Serializes the input to an array.
+   *
+   * @return ExtraInputShape
+   *   The serialized input.
+   */
+  public function jsonSerialize(): array {
+    return [
+      'id' => $this->id,
+      'label' => $this->label,
+      'type' => $this->type->value,
+      'required' => $this->isRequired,
+      'value' => $this->value,
+    ];
+  }
+
+}

