+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\Workshop\Plugin\Validation\Constraint;
+
+use App\Tests\Unit\UnitTestCase;
+use Drupal\Core\Field\FieldItemListInterface;
+use Drupal\rgds_core\Workshop\Plugin\Validation\Constraint\WorkshopExtraInputsConstraint;
+use Drupal\rgds_core\Workshop\Plugin\Validation\Constraint\WorkshopExtraInputsConstraintValidator;
+use PHPUnit\Framework\Attributes\TestWith;
+use Psr\Log\NullLogger;
+use Symfony\Component\Validator\Context\ExecutionContextInterface;
+
+final class WorkshopExtraInputsConstraintValidatorTest extends UnitTestCase {
+
+  private WorkshopExtraInputsConstraintValidator $validator;
+  private ExecutionContextInterface $executionContext;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->validator = new WorkshopExtraInputsConstraintValidator(new NullLogger());
+    $this->executionContext = $this->createMock(ExecutionContextInterface::class);
+    $this->validator->initialize($this->executionContext);
+  }
+
+  public function testItDoesNothingWhenValueIsNotFieldItemList(): void {
+    $this->executionContext->expects(self::never())->method('addViolation');
+
+    $this->validator->validate(NULL, new WorkshopExtraInputsConstraint());
+  }
+
+  public function testItDoesNothingWhenFieldIsEmpty(): void {
+    $fieldItemList = $this->createMock(FieldItemListInterface::class);
+    $fieldItemList->method('isEmpty')->willReturn(TRUE);
+
+    $this->executionContext->expects(self::never())->method('addViolation');
+
+    $this->validator->validate($fieldItemList, new WorkshopExtraInputsConstraint());
+  }
+
+  #[TestWith(['My Label,my_id,1,text'])]
+  #[TestWith(["Label One,id_one,1,text\nLabel Two,id_two,0,text"])]
+  public function testItDoesNotAddViolationWhenFieldValueIsValid(mixed $fieldValue): void {
+    $fieldItemList = $this->createFieldItemListWithValue($fieldValue);
+
+    $this->executionContext->expects(self::never())->method('addViolation');
+
+    $this->validator->validate($fieldItemList, new WorkshopExtraInputsConstraint());
+  }
+
+  #[TestWith([NULL])]
+  #[TestWith([123])]
+  #[TestWith(['invalid,csv'])]
+  #[TestWith(["Label One,same_id,1,text\nLabel Two,same_id,0,text"])]
+  public function testItAddsViolationWhenFieldValueIsInvalid(mixed $fieldValue): void {
+    $fieldItemList = $this->createFieldItemListWithValue($fieldValue);
+
+    $this->executionContext->expects(self::once())
+      ->method('addViolation')
+      ->with('The defined extra inputs are not formatted correctly.');
+
+    $this->validator->validate($fieldItemList, new WorkshopExtraInputsConstraint());
+  }
+
+  private function createFieldItemListWithValue(mixed $value): FieldItemListInterface {
+    $fieldItemList = $this->createMock(FieldItemListInterface::class);
+    $fieldItemList->method('isEmpty')->willReturn(FALSE);
+    $fieldItemList
+      ->method('__get')
+      ->with('value')
+      ->willReturn($value);
+
+    return $fieldItemList;
+  }
+
+}

