+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Entity\WorkshopRegistration;
+
+use Drupal\rgds_core\Workshop\Exception\ExtraInputNotFoundException;
+use Drupal\rgds_core\Workshop\Exception\InvalidExtraInputException;
+
+/**
+ * Collection of answered extra inputs for a workshop registration.
+ *
+ * @phpstan-import-type ExtraInputShape from ExtraInput
+ *
+ * @implements \IteratorAggregate<string, ExtraInput>
+ */
+final class ExtraInputs implements \IteratorAggregate, \JsonSerializable {
+
+  public function __construct(
+    /**
+     * Items indexed by extra input ID.
+     *
+     * @var array<string, ExtraInput>
+     */
+    private array $items,
+  ) {}
+
+  /**
+   * Creates an empty instance.
+   */
+  public static function empty(): self {
+    return new self([]);
+  }
+
+  /**
+   * Deserializes from JSON stored in the database.
+   *
+   * @param non-empty-string $raw
+   *   The raw JSON string.
+   */
+  public static function fromJson(string $raw): self {
+    $decoded = \json_decode(json: $raw, associative: TRUE, flags: \JSON_THROW_ON_ERROR);
+    if (FALSE === \is_array($decoded)) {
+      throw new InvalidExtraInputException('Extra inputs JSON must decode to an array.');
+    }
+
+    $items = [];
+    foreach ($decoded as $entry) {
+      if (FALSE === \is_array($entry)) {
+        throw new InvalidExtraInputException('Extra input entry must be an array.');
+      }
+
+      $extraInput = ExtraInput::fromArray($entry);
+      if (TRUE === \array_key_exists($extraInput->id, $items)) {
+        throw new InvalidExtraInputException(\sprintf('Duplicate extra input id "%s".', $extraInput->id));
+      }
+
+      $items[$extraInput->id] = $extraInput;
+    }
+
+    return new self($items);
+  }
+
+  /**
+   * Builds from submitted form values and workshop extra input definitions.
+   *
+   * @param array $raw
+   *   Submitted values keyed by extra input ID.
+   * @param array<\Drupal\rgds_core\Workshop\Entity\Workshop\ExtraInputDefinition> $definitions
+   *   The workshop's extra input definitions (the "template").
+   */
+  public static function fromRequest(array $raw, array $definitions): self {
+    $items = [];
+
+    foreach ($definitions as $definition) {
+      $value = $raw[$definition->id] ?? NULL;
+      if (FALSE === \is_string($value) && NULL !== $value) {
+        throw new InvalidExtraInputException(\sprintf('Extra input "%s" value must be a string or null.', $definition->id));
+      }
+      if (TRUE === \is_string($value)) {
+        $value = \trim($value);
+      }
+      if ('' === $value) {
+        $value = NULL;
+      }
+
+      if (TRUE === $definition->isRequired && NULL === $value) {
+        throw new InvalidExtraInputException(
+          \sprintf('Extra input "%s" is required.', $definition->id),
+        );
+      }
+
+      $items[$definition->id] = new ExtraInput(
+        id: $definition->id,
+        label: $definition->label,
+        type: $definition->type,
+        isRequired: $definition->isRequired,
+        value: $value,
+      );
+    }
+
+    return new self($items);
+  }
+
+  /**
+   * Serializes to a plain JSON array.
+   *
+   * @return list<ExtraInput>
+   *   The list of extra inputs.
+   */
+  public function jsonSerialize(): array {
+    return \array_values($this->items);
+  }
+
+  /**
+   * Returns whether the given extra input ID exists.
+   */
+  public function has(string $id): bool {
+    return \array_key_exists($id, $this->items);
+  }
+
+  /**
+   * Returns the extra input with the given ID.
+   *
+   * @throws \Drupal\rgds_core\Workshop\Exception\ExtraInputNotFoundException
+   *   When the extra input ID is not found.
+   */
+  public function get(string $id): ExtraInput {
+    return $this->items[$id] ?? throw new ExtraInputNotFoundException(\sprintf('Extra input "%s" not found.', $id));
+  }
+
+  public function isEmpty(): bool {
+    return [] === $this->items;
+  }
+
+  /**
+   * Returns an iterator over the items keyed by ID.
+   *
+   * @return \ArrayIterator<string, ExtraInput>
+   *   The iterator.
+   */
+  public function getIterator(): \ArrayIterator {
+    return new \ArrayIterator($this->items);
+  }
+
+}

