+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Workshop\Plugin\Validation\Constraint;
+
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Field\FieldItemListInterface;
+use Drupal\Core\Utility\Error;
+use Drupal\rgds_core\Workshop\Entity\Workshop\ExtraInputDefinition;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\Validator\Constraint;
+use Symfony\Component\Validator\ConstraintValidator;
+
+final class WorkshopExtraInputsConstraintValidator extends ConstraintValidator implements ContainerInjectionInterface {
+
+  public function __construct(
+    private readonly LoggerInterface $logger,
+  ) {
+  }
+
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('rgds_core.logger.channel.workshop')
+    );
+  }
+
+  /**
+   * {@inheritdoc}
+   */
+  public function validate(mixed $value, Constraint $constraint): void {
+    if (FALSE === $constraint instanceof WorkshopExtraInputsConstraint) {
+      return;
+    }
+
+    if (FALSE === $value instanceof FieldItemListInterface) {
+      return;
+    }
+
+    if (TRUE === $value->isEmpty()) {
+      return;
+    }
+
+    $fieldValue = $value->value;
+    if (FALSE === \is_string($fieldValue)) {
+      $this->context->addViolation($constraint->message);
+      return;
+    }
+
+    try {
+      ExtraInputDefinition::createMany($fieldValue);
+    }
+    catch (\Throwable $throwable) {
+      $this->logger->error('%type: @message in %function (line %line of %file).', Error::decodeException($throwable));
+      $this->context->addViolation($constraint->message);
+    }
+  }
+
+}

