+use Drupal\rgds_core\Workshop\Exception\ExtraInputNotFoundException;
+use Drupal\rgds_core\Workshop\Exception\InvalidExtraInputException;
+
+final class ExtraInputsTest extends UnitTestCase {
+
+  public function testItShouldCreateEmptyInstance(): void {
+    self::assertTrue(ExtraInputs::empty()->isEmpty());
+  }
+
+  public function testItShouldSerializeToJsonAndDeserializeBack(): void {
+    $original = ExtraInputs::fromRequest(
+      raw: ['name' => 'Alice', 'city' => 'Paris', 'institution' => 'Hôpital privé Villeneuve d\'Ascq'],
+      definitions: [
+        $this->createTextDefinition('name', 'Full name', TRUE),
+        $this->createTextDefinition('city', 'City', FALSE),
+        $this->createTextDefinition('institution', 'Institution', FALSE),
+      ],
+    );
+
+    $restored = ExtraInputs::fromJson(\json_encode($original, \JSON_THROW_ON_ERROR));
+
+    self::assertTrue($restored->has('name'));
+    self::assertSame('Alice', $restored->get('name')->value);
+    self::assertSame('Full name', $restored->get('name')->label);
+    self::assertTrue($restored->get('name')->isRequired);
+
+    self::assertTrue($restored->has('city'));
+    self::assertSame('Paris', $restored->get('city')->value);
+    self::assertFalse($restored->get('city')->isRequired);
+    self::assertSame('City', $restored->get('city')->label);
+
+    self::assertTrue($restored->has('institution'));
+    self::assertSame('Hôpital privé Villeneuve d\'Ascq', $restored->get('institution')->value);
+    self::assertFalse($restored->get('institution')->isRequired);
+    self::assertSame('Institution', $restored->get('institution')->label);
+  }
+
+  public function testItShouldBuildFromRequestWhenAllValuesProvided(): void {
+    $extraInputs = ExtraInputs::fromRequest(
+      raw: ['email' => 'test@example.com'],
+      definitions: [
+        $this->createTextDefinition('email', 'Email', TRUE),
+      ],
+    );
+
+    self::assertFalse($extraInputs->isEmpty());
+    self::assertTrue($extraInputs->has('email'));
+    self::assertSame('test@example.com', $extraInputs->get('email')->value);
+  }
+
+  public function testItShouldBuildFromRequestWhenOptionalValueMissing(): void {
+    $extraInputs = ExtraInputs::fromRequest(
+      raw: [],
+      definitions: [
+        $this->createTextDefinition('comment', 'Comment', FALSE),
+      ],
+    );
+
+    self::assertTrue($extraInputs->has('comment'));
+    self::assertNull($extraInputs->get('comment')->value);
+  }
+
+  public function testItShouldThrowWhenRequiredFieldMissingInRequest(): void {
+    $this->expectException(InvalidExtraInputException::class);
+    $this->expectExceptionMessage('Extra input "name" is required.');
+
+    ExtraInputs::fromRequest(
+      raw: [],
+      definitions: [$this->createTextDefinition('name', 'Name', TRUE)],
+    );
+  }
+
+  public function testItShouldReturnTrueWhenHasCalledWithExistingId(): void {
+    $extraInputs = ExtraInputs::fromRequest(
+      raw: ['name' => 'Alice'],
+      definitions: [$this->createTextDefinition('name', 'Name', TRUE)],
+    );
+
+    self::assertTrue($extraInputs->has('name'));
+  }
+
+  public function testItShouldReturnFalseWhenHasCalledWithUnknownId(): void {
+    $extraInputs = ExtraInputs::fromRequest(
+      raw: ['name' => 'Alice'],
+      definitions: [$this->createTextDefinition('name', 'Name', TRUE)],
+    );
+
+    self::assertFalse($extraInputs->has('unknown'));
+  }
+
+  public function testItShouldReturnItemWhenGetCalledWithExistingId(): void {
+    $extraInputs = ExtraInputs::fromRequest(
+      raw: ['name' => 'Alice'],
+      definitions: [$this->createTextDefinition('name', 'Full name', TRUE)],
+    );
+    $item = $extraInputs->get('name');
+
+    self::assertInstanceOf(ExtraInput::class, $item);
+    self::assertSame('name', $item->id);
+    self::assertSame('Full name', $item->label);
+    self::assertSame(Type::Text, $item->type);
+    self::assertSame('Alice', $item->value);
+  }
+
+  public function testItShouldThrowWhenGetCalledWithUnknownId(): void {
+    $this->expectException(ExtraInputNotFoundException::class);
+    $this->expectExceptionMessage('Extra input "unknown" not found.');
+
+    ExtraInputs::empty()->get('unknown');
+  }
+
+  public function testItShouldYieldNothingWhenIteratingEmptyInstance(): void {
+    $count = 0;
+    foreach (ExtraInputs::empty() as $_) {
+      $count++;
+    }
+
+    self::assertSame(0, $count);
+  }
+
+  public function testItShouldYieldItemsKeyedByIdWhenIterating(): void {
+    $extraInputs = new ExtraInputs([
+      'first' => new ExtraInput(
+        id: 'first',
+        label: 'First',
+        isRequired: FALSE,
+        type: Type::Text,
+        value: 'A',
+      ),
+      'second' => new ExtraInput(
+        id: 'second',
+        label: 'Second',
+        isRequired: FALSE,
+        type: Type::Text,
+        value: 'B',
+      ),
+    ]);
+
+    $collected = [];
+    foreach ($extraInputs as $id => $item) {
+      $collected[$id] = $item->value;
+    }
+
+    self::assertSame(['first' => 'A', 'second' => 'B'], $collected);
+  }
+
+  public function testItShouldIsEmptyReturnFalseWhenItemsExist(): void {
+    $extraInputs = new ExtraInputs([
+      'name' => new ExtraInput(
+        id: 'name',
+        label: 'Name',
+        isRequired: FALSE,
+        type: Type::Text,
+        value: 'Alice',
+      ),
+    ]);
+
+    self::assertFalse($extraInputs->isEmpty());
+  }
+
+  /**
+   * Asserts that fromJson throws for collection-level invalid input.
+   *
+   * @param string $json
+   *   The raw JSON string to parse.
+   * @param string $exceptionMessage
+   *   The expected exception message (partial match).
+   *
+   * @dataProvider provideInvalidFromJsonCases
+   */
+  public function testItShouldThrowWhenFromJsonReceivesInvalidInput(
+    string $json,
+    string $exceptionMessage,
+  ): void {
+    $this->expectException(InvalidExtraInputException::class);
+    $this->expectExceptionMessage($exceptionMessage);
+
+    ExtraInputs::fromJson($json);
+  }
+
+  /**
+   * Provides collection-level invalid JSON inputs for fromJson.
+   *
+   * @return array<string, array{string, string}>
+   *   Tuples of [json, exceptionMessage].
+   */
+  public static function provideInvalidFromJsonCases(): array {
+    return [
+      'non-array root' => [
+        '"hello"',
+        'Extra inputs JSON must decode to an array.',
+      ],
+      'duplicate id' => [
+        '[{"id":"x","label":"L","type":"text","required":true,"value":null},{"id":"x","label":"L2","type":"text","required":false,"value":null}]',
+        'Duplicate extra input id "x".',
+      ],
+    ];
+  }
+
+  private function createTextDefinition(string $id, string $label, bool $isRequired): WorkshopExtraInput {
+    return new WorkshopExtraInput(
+      id: $id,
+      label: $label,
+      isRequired: $isRequired,
+      type: Type::Text,
+    );
+  }
+
+}

