+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Finance\Controller\Api\WiztrustPostFinancePage;
+
+use Symfony\Component\HttpFoundation\Request;
+
+/**
+ * Class Input.
+ *
+ * @SuppressWarnings("PHPMD.CyclomaticComplexity")
+ * @SuppressWarnings("PHPMD.NPathComplexity")
+ */
+final readonly class Input {
+
+  public function __construct(
+    /**
+     * The Wiztrust's publication identifier.
+     *
+     * @var non-empty-string
+     * */
+    public string $publicationId,
+    /**
+     * The title.
+     *
+     * @var non-empty-string
+     * */
+    public string $title,
+    /**
+     * The description.
+     *
+     * @var non-empty-string|null
+     * */
+    public string|null $description,
+    /**
+     * The categories.
+     *
+     * @var non-empty-string[]
+     * */
+    public array $categories,
+    /**
+     * The absolute URL of the image to download.
+     *
+     * @var non-empty-string|null
+     * */
+    public string|null $image,
+    /**
+     * The absolute URL of the PDF to download.
+     *
+     * @var non-empty-string|null
+     * */
+    public string|null $pdf,
+    public Langcode $langcode,
+  ) {}
+
+  public static function createFromRequestOrError(Request $request): Input|Error {
+    $data = \json_decode($request->getContent(), associative: TRUE);
+    if (\JSON_ERROR_NONE !== \json_last_error()) {
+      return new Error(\sprintf('Invalid JSON in request body: \'%s\'', \json_last_error_msg()));
+    }
+
+    if (FALSE === \is_array($data)) {
+      return new Error('Unexpected request body.');
+    }
+
+    $publicationId = $data['publication_id'] ?? '';
+    if (FALSE === \is_string($publicationId) || '' === $publicationId) {
+      return new Error(\sprintf('Invalid publication_id: expected non empty string got \'%s\'', \gettype($publicationId)));
+    }
+
+    $title = $data['title'] ?? '';
+    if (FALSE === \is_string($title) || '' === $title) {
+      return new Error(\sprintf('Invalid title: expected non empty string got \'%s\'', \gettype($title)));
+    }
+
+    $description = $data['description'] ?? NULL;
+    if (FALSE === \is_string($description) || '' === $description) {
+      $description = NULL;
+    }
+
+    $categories = $data['categories'] ?? [];
+    if (FALSE === \is_array($categories)) {
+      $categories = [];
+    }
+    foreach ($categories as $category) {
+      if (FALSE === \is_string($category) || '' === $category) {
+        return new Error(\sprintf('Invalid category: expected non empty string got \'%s\'', \gettype($category)));
+      }
+    }
+    /** @var non-empty-string[] $categories */
+
+    $image = $data['image'] ?? NULL;
+    if (FALSE === \is_string($image) || '' === $image) {
+      $image = NULL;
+    }
+
+    $pdf = $data['pdf'] ?? NULL;
+    if (FALSE === \is_string($pdf) || '' === $pdf) {
+      $pdf = NULL;
+    }
+
+    $langcode = $data['langcode'] ?? NULL;
+    if (FALSE === \is_string($langcode) || '' === $langcode) {
+      return new Error(\sprintf('Invalid langcode: expected one of \'%s\' got type \'%s\'', \implode(', ', Langcode::casesToString()), \gettype($langcode)));
+    }
+    $langcode = Langcode::tryFrom($langcode);
+    if (FALSE === $langcode instanceof Langcode) {
+      return new Error(\sprintf('Invalid langcode: expected one of \'%s\' got \'%s\'', \implode(', ', Langcode::casesToString()), $langcode));
+    }
+
+    return new Input(
+      publicationId: $publicationId,
+      title: $title,
+      description: $description,
+      categories: $categories,
+      image: $image,
+      pdf: $pdf,
+      langcode: $langcode,
+    );
+  }
+
+}

