+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Finance\Wiztrust;
+
+use Drupal\rgds_core\Finance\Controller\Api\WiztrustPostFinancePage\Input;
+use Drupal\rgds_core\Finance\Controller\Api\WiztrustPostFinancePage\Langcode;
+use Drupal\rgds_core\InternationalSite\Finder\InternationalSiteFinder;
+use Drupal\rgds_core\Wiztrust\Exception\WiztrustInvalidEntityException;
+use Psr\Log\LoggerInterface;
+
+final readonly class UpsertWiztrustFinancePage {
+
+  public function __construct(
+    private InternationalSiteFinder $internationalSiteFinder,
+    private WiztrustFinancePageFinder $finder,
+    private FinancePageNodeHydrator $nodeHydrator,
+    private LoggerInterface $logger,
+  ) {}
+
+  public function __invoke(Input $input): WiztrustResult {
+    [$bundle, $siteId, $langcode] = $this->resolveContext($input->langcode);
+
+    $node = $this->finder->findByPublicationId($input->publicationId, $bundle, $siteId);
+
+    $node = $this->nodeHydrator->hydrate($node, $input, $bundle, $langcode, $siteId);
+
+    $violations = $node->validate();
+    if ($violations->count() > 0) {
+      throw WiztrustInvalidEntityException::fromViolations($violations);
+    }
+
+    $status = $node->save();
+    $nodeId = (string) $node->id();
+
+    $this->logger->info('Finance page {action}: node {node_id} for publication_id {publication_id}', [
+      'action' => match ($status) {
+        \SAVED_NEW => 'created',
+        \SAVED_UPDATED => 'updated',
+        default => throw new WiztrustInvalidEntityException('Unexpected node save status: ' . $status),
+      },
+      'node_id' => $nodeId,
+      'publication_id' => $input->publicationId,
+    ]);
+
+    /** @var \SAVED_NEW|\SAVED_UPDATED $status */
+    return new WiztrustResult(id: $nodeId, status: $status);
+  }
+
+  /**
+   * Resolve bundle, site ID and Drupal langcode from the input langcode.
+   *
+   * @return array{string, string|null, string}
+   *   The bundle, optional site ID, and Drupal langcode string.
+   */
+  private function resolveContext(Langcode $langcode): array {
+    if (Langcode::Fr === $langcode) {
+      return ['finance_page', NULL, 'fr'];
+    }
+
+    return ['finance_page_international', (string) $this->internationalSiteFinder->find()->id(), 'en'];
+  }
+
+}

