+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust\Access;
+
+use Drupal\Core\Access\AccessResult;
+use Drupal\Core\Access\AccessResultInterface;
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Site\Settings;
+use Drupal\micro_site\SiteNegotiatorInterface;
+use Drupal\rgds_core\SiteFactory\Model\SiteType;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\Request;
+
+/**
+ * Check if the route is accessible on corporate using the Wiztrust Api key.
+ *
+ * We delibetately chose to not implement \Drupal\Core\Authentication\AuthenticationProviderInterface.
+ * Indeed, we don't want to authenticate a user.
+ * We want to restrict the access to some endpoints.
+ *
+ * @SuppressWarnings("PHPMD.LongClassName")
+ */
+final readonly class IsAccessibleOnCorporateUsingWiztrustApiKey implements ContainerInjectionInterface {
+
+  public function __construct(
+    private SiteNegotiatorInterface $siteNegotiator,
+    private Settings $settings,
+    private LoggerInterface $logger,
+  ) {}
+
+  /**
+   * {@inheritdoc}
+   */
+  public static function create(ContainerInterface $container): IsAccessibleOnCorporateUsingWiztrustApiKey {
+    return new static(
+      $container->get('micro_site.negotiator'),
+      $container->get('settings'),
+      $container->get('rgds_core.logger.channel.wiztrust'),
+    );
+  }
+
+  public function check(Request $request): AccessResultInterface {
+    if (FALSE === SiteType::fromSiteEntity($this->siteNegotiator->getActiveSite())->equals(SiteType::corporate())) {
+      $this->logger->warning('Trying to access MR API Wiztrust API endpoints on another site than corporate.');
+      return AccessResult::forbidden();
+    }
+
+    if (FALSE === $request->headers->has('X-WIZTRUST-API-KEY')) {
+      $this->logger->warning('Trying to access MR API Wiztrust API endpoints without API key header.');
+      return AccessResult::forbidden();
+    }
+
+    $apiKey = $request->headers->get('X-WIZTRUST-API-KEY');
+    if (NULL === $apiKey) {
+      $this->logger->warning('Trying to access MR API Wiztrust API endpoints without API key.');
+      return AccessResult::forbidden();
+    }
+
+    $expectedApiKey = $this->settings::get('mr_api_wiztrust.api_key', '');
+    if (FALSE === \is_string($expectedApiKey) || '' === $expectedApiKey) {
+      $this->logger->warning('Setting "mr_api_wiztrust.api_key" is not configured properly.');
+      return AccessResult::forbidden();
+    }
+
+    if (FALSE === \hash_equals($expectedApiKey, $apiKey)) {
+      $this->logger->warning('Trying to access MR API Wiztrust API endpoints using invalid API key.');
+      return AccessResult::forbidden();
+    }
+
+    return AccessResult::allowed();
+  }
+
+}

