+namespace Drupal\rgds_core\Wiztrust;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\file\FileInterface;
+use Drupal\media\MediaInterface;
+use Drupal\rgds_core\Wiztrust\Exception\WiztrustInvalidEntityException;
+
+final readonly class UpsertMediaImage {
+
+  public function __construct(
+    private RemoteFileDownloader $remoteFileDownloader,
+    private EntityTypeManagerInterface $entityTypeManager,
+  ) {}
+
+  /**
+   * Create or update a media image from a remote URL.
+   *
+   * @param non-empty-string $url
+   *   The absolute URL.
+   * @param non-empty-string $publicationId
+   *   The unique publication id.
+   * @param non-empty-string $name
+   *   The name.
+   */
+  public function __invoke(
+    string $url,
+    string $publicationId,
+    string $name,
+  ): MediaInterface {
+    $imageFile = $this->remoteFileDownloader->download($url, \sprintf('public://wiztrust/images/%s', $publicationId));
+
+    $existingIds = $this->entityTypeManager->getStorage('media')->getQuery()
+      ->accessCheck(FALSE)
+      ->range(0, 1)
+      ->condition('bundle', 'image')
+      ->condition('field_media_image.target_id', $imageFile->id())
+      ->execute();
+
+    $imageMedia = match ($existingIds) {
+      [] => $this->create($name, $imageFile),
+      default => $this->update(\reset($existingIds), $name, $imageFile),
+    };
+
+    $violations = $imageMedia->validate();
+    if ($violations->count() > 0) {
+      throw WiztrustInvalidEntityException::fromViolations($violations);
+    }
+    $imageMedia->save();
+
+    return $imageMedia;
+  }
+
+  private function create(string $name, FileInterface $imageFile): MediaInterface {
+    return $this->entityTypeManager->getStorage('media')->create([
+      'name' => $name,
+      'bundle' => 'image',
+      'field_media_image' => [
+        'target_id' => $imageFile->id(),
+        'alt' => $name,
+      ],
+    ]);
+  }
+
+  private function update(string $id, string $name, FileInterface $imageFile): MediaInterface {
+    $existingMedia = $this->entityTypeManager->getStorage('media')->load($id);
+    if (FALSE === $existingMedia instanceof MediaInterface) {
+      throw new WiztrustInvalidEntityException(\sprintf('Existing media "%s" cannot be loaded.', $id));
+    }
+
+    $existingMedia->set('name', $name);
+    $existingMedia->set('field_media_image', [
+      'target_id' => $imageFile->id(),
+      'alt' => $name,
+    ]);
+
+    return $existingMedia;
+  }
+
+}

