+ */
+final class UpsertWiztrustFinancePageTest extends UnitTestCase {
+
+  private InternationalSiteFinder&MockObject $internationalSiteFinder;
+  private WiztrustFinancePageFinder&MockObject $finder;
+  private FinancePageNodeHydrator&MockObject $nodeHydrator;
+  private UpsertWiztrustFinancePage $upsert;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    // Mandatory to access \SAVED_NEW and \SAVED_UPDATED.
+    include_once __DIR__ . '/../../../../../../../../../core/includes/common.inc';
+
+    $this->internationalSiteFinder = $this->createMock(InternationalSiteFinder::class);
+    $this->finder = $this->createMock(WiztrustFinancePageFinder::class);
+    $this->nodeHydrator = $this->createMock(FinancePageNodeHydrator::class);
+
+    $this->upsert = new UpsertWiztrustFinancePage(
+      $this->internationalSiteFinder,
+      $this->finder,
+      $this->nodeHydrator,
+      new NullLogger(),
+    );
+  }
+
+  private function makeInput(Langcode $langcode = Langcode::Fr): Input {
+    return new Input(
+      publicationId: 'pub-123',
+      title: 'Finance Page',
+      description: NULL,
+      categories: [],
+      image: NULL,
+      pdf: NULL,
+      langcode: $langcode,
+    );
+  }
+
+  private function makeNode(string $id, int $saveStatus): NodeInterface&Stub {
+    $node = $this->createStub(NodeInterface::class);
+    $node->method('validate')->willReturn(new ConstraintViolationList());
+    $node->method('save')->willReturn($saveStatus);
+    $node->method('id')->willReturn($id);
+
+    return $node;
+  }
+
+  public function testItShouldCreateFinancePageWhenNoExistingNodeForFrLangcode(): void {
+    $input = $this->makeInput(Langcode::Fr);
+    $node = $this->makeNode('42', \SAVED_NEW);
+
+    $this->finder
+      ->expects($this->once())
+      ->method('findByPublicationId')
+      ->with('pub-123', 'finance_page', NULL)
+      ->willReturn(NULL);
+
+    $this->nodeHydrator
+      ->expects($this->once())
+      ->method('hydrate')
+      ->with(NULL, $input, 'finance_page', 'fr', NULL)
+      ->willReturn($node);
+
+    $result = ($this->upsert)($input);
+
+    self::assertObjectEquals(new WiztrustResult(id: '42', status: \SAVED_NEW), $result);
+  }
+
+  public function testItShouldUpdateFinancePageWhenExistingNodeFoundForFrLangcode(): void {
+    $input = $this->makeInput(Langcode::Fr);
+    $existingNode = $this->makeNode('42', \SAVED_UPDATED);
+
+    $this->finder
+      ->expects($this->once())
+      ->method('findByPublicationId')
+      ->with('pub-123', 'finance_page', NULL)
+      ->willReturn($existingNode);
+
+    $this->nodeHydrator
+      ->expects($this->once())
+      ->method('hydrate')
+      ->with($existingNode, $input, 'finance_page', 'fr', NULL)
+      ->willReturn($existingNode);
+
+    $result = ($this->upsert)($input);
+
+    self::assertObjectEquals(new WiztrustResult(id: '42', status: \SAVED_UPDATED), $result);
+  }
+
+  public function testItShouldCreateInternationalFinancePageAndResolveSiteIdForEnLangcode(): void {
+    $input = $this->makeInput(Langcode::En);
+    $node = $this->makeNode('99', \SAVED_NEW);
+
+    $site = $this->createMock(SiteInterface::class);
+    $site->method('id')->willReturn('7');
+
+    $this->internationalSiteFinder
+      ->expects($this->once())
+      ->method('find')
+      ->willReturn($site);
+
+    $this->finder
+      ->expects($this->once())
+      ->method('findByPublicationId')
+      ->with('pub-123', 'finance_page_international', '7')
+      ->willReturn(NULL);
+
+    $this->nodeHydrator
+      ->expects($this->once())
+      ->method('hydrate')
+      ->with(NULL, $input, 'finance_page_international', 'en', '7')
+      ->willReturn($node);
+
+    $result = ($this->upsert)($input);
+
+    self::assertObjectEquals(new WiztrustResult(id: '99', status: \SAVED_NEW), $result);
+  }
+
+  public function testItShouldThrowWiztrustInvalidEntityExceptionWhenNodeValidationFails(): void {
+    $input = $this->makeInput(Langcode::Fr);
+    $node = $this->createStub(NodeInterface::class);
+
+    $node->method('validate')->willReturn(new EntityConstraintViolationList(
+      entity: $node,
+      violations: [
+        new ConstraintViolation('Required field missing.', '', [], NULL, 'title', NULL),
+      ],
+    ));
+
+    $this->finder->method('findByPublicationId')->willReturn(NULL);
+    $this->nodeHydrator->method('hydrate')->willReturn($node);
+
+    $this->expectException(WiztrustInvalidEntityException::class);
+    $this->expectExceptionMessage('Entity validation failed: title: Required field missing.');
+
+    ($this->upsert)($input);
+  }
+
+  public function testItShouldNotCallInternationalSiteFinderForFrLangcode(): void {
+    $input = $this->makeInput(Langcode::Fr);
+    $node = $this->makeNode('5', \SAVED_NEW);
+
+    $this->internationalSiteFinder
+      ->expects($this->never())
+      ->method('find');
+
+    $this->finder->method('findByPublicationId')->willReturn(NULL);
+    $this->nodeHydrator->method('hydrate')->willReturn($node);
+
+    ($this->upsert)($input);
+  }
+
+}

