+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\Wiztrust;
+
+use Drupal\Core\Entity\EntityConstraintViolationList;
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\Core\File\FileExists;
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Session\AccountProxyInterface;
+use Drupal\Tests\UnitTestCase;
+use Drupal\file\FileInterface;
+use Drupal\file\FileRepositoryInterface;
+use Drupal\rgds_core\Wiztrust\Exception\WiztrustFileDownloadException;
+use Drupal\rgds_core\Wiztrust\RemoteFileDownloader;
+use GuzzleHttp\ClientInterface;
+use GuzzleHttp\Exception\TransferException;
+use PHPUnit\Framework\MockObject\MockObject;
+use PHPUnit\Framework\MockObject\Stub;
+
+/**
+ * @covers \Drupal\rgds_core\Wiztrust\RemoteFileDownloader
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ */
+final class RemoteFileDownloaderTest extends UnitTestCase {
+
+  private ClientInterface&Stub $httpClient;
+
+  private FileRepositoryInterface&MockObject $fileRepository;
+
+  private FileSystemInterface&MockObject $fileSystem;
+
+  private AccountProxyInterface&Stub $currentUser;
+
+  private RemoteFileDownloader $downloader;
+
+  public function setup(): void {
+    parent::setUp();
+
+    $this->httpClient = $this->createStub(ClientInterface::class);
+    $this->fileRepository = $this->createMock(FileRepositoryInterface::class);
+    $this->fileSystem = $this->createMock(FileSystemInterface::class);
+    $this->currentUser = $this->createStub(AccountProxyInterface::class);
+    $this->currentUser->method('id')->willReturn('0');
+
+    $this->downloader = new RemoteFileDownloader(
+      $this->httpClient,
+      $this->fileRepository,
+      $this->fileSystem,
+      $this->currentUser,
+      $this->createStub(EntityTypeManagerInterface::class),
+    );
+  }
+
+  public function testItShouldDownloadFileAndReturnFileEntity(): void {
+    $url = 'https://example.com/files/document.pdf';
+    $destination = 'public://pdf';
+    $tempPath = 'temporary://wiztrust_abc123';
+    $realTempPath = '/tmp/wiztrust_abc123';
+    $finalUri = $destination . '/document.pdf';
+
+    $this->fileSystem
+      ->expects($this->once())
+      ->method('prepareDirectory')
+      ->with($destination, FileSystemInterface::CREATE_DIRECTORY);
+
+    $this->fileSystem
+      ->expects($this->once())
+      ->method('tempnam')
+      ->with('temporary://', 'wiztrust')
+      ->willReturn($tempPath);
+
+    $this->fileSystem
+      ->expects($this->once())
+      ->method('realpath')
+      ->with($tempPath)
+      ->willReturn($realTempPath);
+
+    $this->httpClient
+      ->expects($this->once())
+      ->method('request')
+      ->with('GET', $url, ['sink' => $realTempPath]);
+
+    $this->fileSystem
+      ->expects($this->once())
+      ->method('move')
+      ->with($tempPath, $finalUri, FileExists::Replace)
+      ->willReturn($finalUri);
+
+    $file = $this->createMock(FileInterface::class);
+    $file->expects($this->once())
+      ->method('validate')
+      ->willReturn(new EntityConstraintViolationList(
+        entity: $file,
+        violations: [],
+      ));
+    $file->expects($this->once())->method('setPermanent');
+    $file->expects($this->once())->method('save');
+
+    $this->fileRepository
+      ->expects($this->once())
+      ->method('loadByUri')
+      ->with($finalUri)
+      ->willReturn($file);
+
+    $result = $this->downloader->download($url, $destination);
+
+    self::assertSame($file, $result);
+  }
+
+  public function testItShouldExtractFilenameFromNestedUrlPath(): void {
+    $url = 'https://example.com/path/to/sub/image.jpg';
+    $destination = 'public://images';
+    $tempPath = 'temporary://wiztrust_abc123';
+    $finalUri = $destination . '/image.jpg';
+
+    $this->fileSystem->method('prepareDirectory');
+    $this->fileSystem->method('tempnam')->willReturn($tempPath);
+    $this->fileSystem->method('realpath')->willReturn('/tmp/wiztrust_abc123');
+    $this->fileSystem->method('move')->willReturn($finalUri);
+
+    $file = $this->createMock(FileInterface::class);
+    $file->expects($this->once())
+      ->method('validate')
+      ->willReturn(new EntityConstraintViolationList(
+        entity: $file,
+        violations: [],
+      ));
+
+    $this->fileRepository
+      ->expects($this->once())
+      ->method('loadByUri')
+      ->with($finalUri)
+      ->willReturn($file);
+
+    $this->downloader->download($url, $destination);
+  }
+
+  public function testItShouldThrowWiztrustFileDownloadExceptionWhenHttpClientFails(): void {
+    $url = 'https://example.com/files/document.pdf';
+    $networkError = new TransferException('Connection refused');
+
+    $this->fileSystem->method('prepareDirectory');
+    $this->fileSystem->method('tempnam')->willReturn('temporary://wiztrust_abc');
+    $this->fileSystem->method('realpath')->willReturn('/tmp/wiztrust_abc');
+
+    $this->httpClient
+      ->method('request')
+      ->willThrowException($networkError);
+
+    $this->expectException(WiztrustFileDownloadException::class);
+    $this->expectExceptionMessage("Failed to download Wiztrust file from URL: 'https://example.com/files/document.pdf'");
+
+    $this->downloader->download($url, 'public://pdf');
+  }
+
+  public function testItShouldPreserveOriginalExceptionWhenHttpClientFails(): void {
+    $url = 'https://example.com/files/document.pdf';
+    $networkError = new TransferException('Connection refused');
+
+    $this->fileSystem->method('prepareDirectory');
+    $this->fileSystem->method('tempnam')->willReturn('temporary://wiztrust_abc');
+    $this->fileSystem->method('realpath')->willReturn('/tmp/wiztrust_abc');
+
+    $this->httpClient
+      ->method('request')
+      ->willThrowException($networkError);
+
+    try {
+      $this->downloader->download($url, 'public://pdf');
+      self::fail('Expected WiztrustFileDownloadException was not thrown.');
+    }
+    catch (WiztrustFileDownloadException $e) {
+      self::assertSame($networkError, $e->getPrevious());
+    }
+  }
+
+  public function testItShouldThrowWiztrustFileDownloadExceptionOnUnparsableUrl(): void {
+    $this->expectException(WiztrustFileDownloadException::class);
+
+    $this->downloader->download('not-a-valid-url-scheme://', 'public://pdf');
+  }
+
+}

