+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust\HookHandler\Form\Node;
+
+use Drupal\Core\Form\FormStateInterface;
+use Drupal\node\Form\NodeForm;
+use Drupal\node\NodeInterface;
+use Drupal\rgds_core\Exception\NotSupportedException;
+
+final readonly class ReadonlyWiztrustPublicationIdHookHandler {
+  private const array SUPPORTED_BUNDLES = [
+    'finance_page',
+    'finance_page_international',
+  ];
+
+  public function formAlter(array &$form, FormStateInterface $formState): void {
+    $formObject = $formState->getFormObject();
+    if (FALSE === $formObject instanceof NodeForm) {
+      throw new NotSupportedException(\sprintf(
+        '$formObject should be an instance of "%s": "%s" given.',
+        NodeForm::class,
+        \get_class($formObject),
+      ));
+    }
+
+    $entity = $formObject->getEntity();
+
+    if (FALSE === $entity instanceof NodeInterface) {
+      throw new NotSupportedException(\sprintf(
+        '$entity should be an instance of "%s": "%s" given.',
+        NodeInterface::class,
+        \get_class($entity),
+      ));
+    }
+
+    if (FALSE === $this->isBundleSupported($entity)) {
+      return;
+    }
+
+    $form['field_wiztrust_publication_id']['#disabled'] = TRUE;
+  }
+
+  private function isBundleSupported(NodeInterface $node): bool {
+    return \in_array($node->bundle(), self::SUPPORTED_BUNDLES);
+  }
+
+}

