+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Field;
+
+enum ItemContentPreference: string {
+
+  case Image = 'image';
+  case Text = 'text';
+
+  /**
+   * The allowed values.
+   *
+   * @return array<string, string>
+   *   The allowed values.
+   */
+  public static function allowedValues(): array {
+    $options = [];
+
+    foreach (self::cases() as $case) {
+      $options[$case->value] = $case->getLabel();
+    }
+
+    return $options;
+  }
+
+  /**
+   * The label.
+   *
+   * @return non-empty-string
+   *   The label.
+   */
+  public function getLabel(): string {
+    return match($this) {
+      self::Image => 'Image',
+      self::Text => 'Texte',
+    };
+  }
+
+}

