+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\HookHandler\Form;
+
+use Drupal\Tests\UnitTestCase;
+use Drupal\rgds_core\Field\ItemContentPreference;
+use Drupal\rgds_core\HookHandler\Form\DiscoverV2ItemContentPreferenceSelectionHookHandler;
+
+final class DiscoverV2ItemContentPreferenceSelectionHookHandlerTest extends UnitTestCase {
+
+  private const string SELECTOR = ':input[name="field_item[0][subform][field_item_content_preference]"]';
+
+  private DiscoverV2ItemContentPreferenceSelectionHookHandler $hookHandler;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->hookHandler = new DiscoverV2ItemContentPreferenceSelectionHookHandler();
+  }
+
+  public function testItShouldNotAlterElementWhenParagraphTypeIsNotDiscoverV2Item(): void {
+    $element = $this->buildElement();
+    $element['#paragraph_type'] = 'another_paragraph';
+    $original = $element;
+
+    $this->hookHandler->alter($element);
+
+    $this->assertSame($original, $element);
+  }
+
+  public function testItShouldNotAlterElementWhenPreferenceSelectHasNoParents(): void {
+    $element = $this->buildElement();
+    unset($element['subform']['field_item_content_preference']['widget']['#parents']);
+    $original = $element;
+
+    $this->hookHandler->alter($element);
+
+    $this->assertSame($original, $element);
+  }
+
+  public function testItShouldSetConditionalStatesForBothContentModes(): void {
+    $element = $this->buildElement();
+
+    $this->hookHandler->alter($element);
+
+    $this->assertSame(
+      [self::SELECTOR => ['value' => 'text']],
+      $element['subform']['field_description']['#states']['visible'],
+    );
+    $this->assertSame(
+      [self::SELECTOR => ['value' => 'text']],
+      $element['subform']['field_description']['widget'][0]['value']['#states']['required'],
+    );
+    $this->assertSame(
+      [self::SELECTOR => ['value' => 'image']],
+      $element['subform']['field_media_image']['#states']['visible'],
+    );
+  }
+
+  public function testItShouldNotSetDescriptionRequiredStateWhenTextareaIsMissing(): void {
+    $element = $this->buildElement();
+    unset($element['subform']['field_description']['widget'][0]['value']);
+
+    $this->hookHandler->alter($element);
+
+    $this->assertArrayNotHasKey('value', $element['subform']['field_description']['widget'][0]);
+    $this->assertSame(
+      [self::SELECTOR => ['value' => 'text']],
+      $element['subform']['field_description']['#states']['visible'],
+    );
+  }
+
+  public function testItShouldDefaultToImageAndBeOptionalWhenPreferenceHasNoDefaultValue(): void {
+    $element = $this->buildElement();
+
+    $this->hookHandler->alter($element);
+
+    $this->assertFalse($element['subform']['field_item_content_preference']['widget']['#required']);
+    $this->assertSame(
+      [ItemContentPreference::Image->value],
+      $element['subform']['field_item_content_preference']['widget']['#default_value'],
+    );
+  }
+
+  public function testItShouldDefaultToImageAndBeOptionalWhenPreferenceDefaultValueIsEmpty(): void {
+    $element = $this->buildElement(['#default_value' => []]);
+
+    $this->hookHandler->alter($element);
+
+    $this->assertFalse($element['subform']['field_item_content_preference']['widget']['#required']);
+    $this->assertSame(
+      [ItemContentPreference::Image->value],
+      $element['subform']['field_item_content_preference']['widget']['#default_value'],
+    );
+  }
+
+  public function testItShouldBeRequiredAndKeepDefaultValueWhenPreferenceAlreadyHasImage(): void {
+    $element = $this->buildElement(['#default_value' => [ItemContentPreference::Image->value]]);
+
+    $this->hookHandler->alter($element);
+
+    $this->assertTrue($element['subform']['field_item_content_preference']['widget']['#required']);
+    $this->assertSame(
+      [ItemContentPreference::Image->value],
+      $element['subform']['field_item_content_preference']['widget']['#default_value'],
+    );
+  }
+
+  public function testItShouldBeRequiredAndKeepDefaultValueWhenPreferenceAlreadyHasText(): void {
+    $element = $this->buildElement(['#default_value' => [ItemContentPreference::Text->value]]);
+
+    $this->hookHandler->alter($element);
+
+    $this->assertTrue($element['subform']['field_item_content_preference']['widget']['#required']);
+    $this->assertSame(
+      [ItemContentPreference::Text->value],
+      $element['subform']['field_item_content_preference']['widget']['#default_value'],
+    );
+  }
+
+  /**
+   * Builds a minimal discover_v2_item paragraph subform element.
+   *
+   * @param array<string, mixed> $preferenceWidgetOverrides
+   *   Extra keys to merge into the preference widget (e.g. an existing #default_value).
+   *
+   * @return array<string, mixed>
+   *   A minimal discover_v2_item paragraph subform element.
+   */
+  private function buildElement(array $preferenceWidgetOverrides = []): array {
+    return [
+      '#paragraph_type' => 'discover_v2_item',
+      'subform' => [
+        'field_item_content_preference' => [
+          'widget' => [
+            '#parents' => ['field_item', 0, 'subform', 'field_item_content_preference'],
+          ] + $preferenceWidgetOverrides,
+        ],
+        'field_description' => [
+          'widget' => [
+            0 => [
+              'value' => ['#type' => 'textarea'],
+            ],
+          ],
+        ],
+        'field_media_image' => [
+          'widget' => ['#type' => 'media_library_widget'],
+        ],
+      ],
+    ];
+  }
+
+}

