+        ],
+        '#title' => $this->t('Liste des publications.'),
+        '#empty' => $this->t('Il n\'y a pas encore d\'éléments.'),
+        '#cache' => [
+          'max-age' => 0,
+        ],
+      ],
+    ];
+
+    $filters = Filters::fromRequest($request);
+
+    try {
+      $logs = $this->rgdsApiWiztrustClient->getPublicationLogs([
+        RequestOptions::QUERY => [
+          'limit' => 50,
+          'page' => $request->query->getInt('page', 0) + 1,
+          ...$filters->toQueryParameters(),
+        ],
+      ]);
+    }
+    catch (\Exception $exception) {
+      $this->logger->log(RfcLogLevel::ERROR, '%type: @message in %function (line %line of %file).', Error::decodeException($exception));
+
+      $this->messenger->addError($this->t('Une erreur est survenue lors de la récupération des publications. Veuillez réessayer plus tard.'));
+
+      return $build;
+    }
+
+    $rows = [];
+    foreach ($logs->items as $log) {
