+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust\HttpClient\Item\PublicationLog;
+
+use Symfony\Component\HttpFoundation\Request;
+
+final readonly class Filters {
+
+  public function __construct(
+    /**
+     * The publication ids.
+     *
+     * @var string[]
+     */
+    public array $publicationIds = [],
+    public string $title = '',
+    public string $langcode = '',
+  ) {}
+
+  public static function fromRequest(Request $request): self {
+    /** @var string[] $publicationIds */
+    $publicationIds = $request->query->filter(
+      key: 'publication_id',
+      default: [],
+      options: [
+        'flags' => \FILTER_FORCE_ARRAY,
+      ],
+    );
+
+    return new self(
+      $publicationIds,
+      title: $request->query->getString('title'),
+      langcode: $request->query->getString('langcode'),
+    );
+  }
+
+  public function hasPublicationIds(): bool {
+    return [] !== $this->publicationIds;
+  }
+
+  public function hasTitle(): bool {
+    return '' !== $this->title;
+  }
+
+  public function hasLangcode(): bool {
+    return '' !== $this->langcode;
+  }
+
+  /**
+   * To query parameters.
+   *
+   * @return array{
+   *   publication_id?: array<string>,
+   *   title?: string,
+   *   langcode?: string
+   *   }
+   *   The query parameters.
+   */
+  public function toQueryParameters(): array {
+    $query = [];
+
+    if (TRUE === $this->hasPublicationIds()) {
+      $query['publication_id'] = $this->publicationIds;
+    }
+    if (TRUE === $this->hasTitle()) {
+      $query['title'] = $this->title;
+    }
+    if (TRUE === $this->hasLangcode()) {
+      $query['langcode'] = $this->langcode;
+    }
+
+    return $query;
+  }
+
+}

