+
+    $type = $data['type'] ?? NULL;
+    if (FALSE === \is_string($type) || '' === $type) {
+      throw new NotSupportedException(\sprintf('Invalid type: got type \'%s\'', \gettype($type)));
+    }
+    $type = PublicationType::tryFrom($type);
+    if (FALSE === $type instanceof PublicationType) {
+      throw new NotSupportedException(\sprintf('Invalid type: got type \'%s\'', \gettype($type)));
+    }
+
+    $title = $data['title'] ?? '';
+    if (FALSE === \is_string($title) || '' === $title) {
+      throw new NotSupportedException(\sprintf('Invalid title: expected non empty string got \'%s\'', \gettype($title)));
+    }
+
+    $langcode = $data['langcode'] ?? NULL;
+    if (FALSE === \is_string($langcode) || '' === $langcode) {
+      throw new NotSupportedException(\sprintf('Invalid langcode: got type \'%s\'', \gettype($langcode)));
+    }
+    $langcode = Langcode::tryFrom($langcode);
+    if (FALSE === $langcode instanceof Langcode) {
+      throw new NotSupportedException(\sprintf('Invalid langcode: expected one of \'%s\'', \implode(', ', Langcode::casesToString())));
+    }
+
+    $publishedAt = $data['published_at'] ?? '';
+    if (FALSE === \is_string($publishedAt) || '' === $publishedAt) {
+      throw new NotSupportedException(\sprintf('Invalid published_at: expected non empty string got \'%s\'', \gettype($publishedAt)));
+    }
