+use Drupal\rgds_core\Wiztrust\HttpClient\Item\Pagination;
+use Drupal\rgds_core\Wiztrust\HttpClient\Item\PublicationLog;
+use GuzzleHttp\Client as GuzzleHttpClient;
+use GuzzleHttp\Utils;
+use Psr\Http\Message\ResponseInterface;
+
+final class RgdsApiWiztrustClient {
+
+  public function __construct(
+    private GuzzleHttpClient $httpClient,
+  ) {}
+
+  public static function createFromSettings(Settings $settings): self {
+    return new static(
+      new GuzzleHttpClient(NestedArray::mergeDeep(
+        [
+          'verify' => TRUE,
+          'timeout' => 30,
+          'headers' => [
+            'User-Agent' => \sprintf('RGDS CMS %s', Utils::defaultUserAgent()),
+            'Content-Type' => 'application/json',
+            'Accept' => 'application/json',
+          ],
+          'proxy' => [
+            'http' => NULL,
+            'https' => NULL,
+            'no' => [],
+          ],
+        ],
+        $settings::get('rgds_api_client_config', [])
+      ))
+    );
+  }
+
+  /**
+   * Get Publication logs.
+   *
+   * @param array $options
+   *   The options.
+   *
+   * @return \Drupal\rgds_core\Wiztrust\HttpClient\Item\CollectionPaginated<\Drupal\rgds_core\Wiztrust\HttpClient\Item\PublicationLog>
+   *   The publication logs.
+   */
+  public function getPublicationLogs(array $options): CollectionPaginated {
+    $logs = [];
+
+    $response = $this->httpClient->request('GET', 'wiztrust/publication_logs', $options);
+    $data = $this->getResponseData($response);
+    foreach ($data as $datum) {
+      if (FALSE === \is_array($datum)) {
+        throw new NotSupportedException('Each item in the response data should be an array.');
+      }
+      $logs[] = PublicationLog::create($datum);
+    }
+
+    $pagination = Pagination::createFromResponse($response);
+
+    return new CollectionPaginated(
+      items: $logs,
+      pagination: $pagination,
+    );
+  }
+
+  private function getResponseData(ResponseInterface $response): array {
+    $data = \json_decode($response->getBody()->getContents(), associative: TRUE);
+    if (\JSON_ERROR_NONE !== \json_last_error()) {
+      throw new NotSupportedException(\sprintf('JSON error: "%s".', \json_last_error_msg()));
+    }
+
+    if (FALSE === \is_array($data)) {
+      throw new NotSupportedException('Decoded JSON should be an array.');
+    }
+
+    return $data;
+  }
+
+}

