+    self::assertSame(6, $pagination->totalPages);
+  }
+
+  public function testItShouldDefaultWhenHeadersAreMissing(): void {
+    $pagination = Pagination::createFromResponse($this->makeResponse([]));
+
+    self::assertSame(0, $pagination->totalItems);
+    self::assertSame(0, $pagination->currentPage);
+    self::assertSame(1, $pagination->perPage);
+    self::assertSame(0, $pagination->totalPages);
