+use GuzzleHttp\HandlerStack;
+use GuzzleHttp\Psr7\Response;
+
+/**
+ * @covers \Drupal\rgds_core\Wiztrust\HttpClient\RgdsApiWiztrustClient
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ */
+final class RgdsApiWiztrustClientTest extends UnitTestCase {
+
+  private function makeClient(Response $response): RgdsApiWiztrustClient {
+    $handlerStack = HandlerStack::create(new MockHandler([$response]));
+
+    return new RgdsApiWiztrustClient(new GuzzleHttpClient([
+      'handler' => $handlerStack,
+    ]));
+  }
+
+  /**
+   * @return array<string, mixed>
+   *   Valid publication log data with optional overrides.
+   */
+  private static function publicationLogData(array $overrides = []): array {
+    return $overrides + [
+      'id' => 'log-123',
+      'publication_id' => 'pub-456',
+      'type' => 'financial',
+      'title' => 'My Publication',
+      'langcode' => 'fr',
+      'published_at' => '2026-01-01T10:00:00+00:00',
+      'updated_at' => '2026-01-02T10:00:00+00:00',
+      'created_at' => '2026-01-03T10:00:00+00:00',
+    ];
+  }
+
+  public function testItShouldReturnPaginatedPublicationLogs(): void {
+    $body = (string) \json_encode([
+      self::publicationLogData(['id' => 'log-1']),
+      self::publicationLogData(['id' => 'log-2', 'type' => 'press', 'langcode' => 'en']),
+    ]);
+    $response = new Response(
+      200,
+      [
+        'X-Total-Count' => '2',
+        'X-Page' => '1',
+        'X-Per-Page' => '20',
+        'X-Total-Pages' => '1',
+      ],
+      $body,
+    );
+    $client = $this->makeClient($response);
+
+    $collection = $client->getPublicationLogs([]);
+
+    self::assertSame(2, $collection->itemsCount);
+    self::assertSame('log-1', $collection->items[0]->id);
+    self::assertSame(PublicationType::Financial, $collection->items[0]->type);
+    self::assertSame(Langcode::Fr, $collection->items[0]->langcode);
+    self::assertSame('log-2', $collection->items[1]->id);
+    self::assertSame(PublicationType::Press, $collection->items[1]->type);
+    self::assertSame(Langcode::En, $collection->items[1]->langcode);
+
+    self::assertSame(2, $collection->pagination->totalItems);
+    self::assertSame(1, $collection->pagination->currentPage);
+    self::assertSame(20, $collection->pagination->perPage);
+    self::assertSame(1, $collection->pagination->totalPages);
+  }
+
+  public function testItShouldReturnEmptyCollectionWhenResponseIsEmptyArray(): void {
+    $response = new Response(200, ['X-Per-Page' => '20'], '[]');
+    $client = $this->makeClient($response);
+
+    $collection = $client->getPublicationLogs([]);
+
+    self::assertSame([], $collection->items);
+    self::assertSame(0, $collection->itemsCount);
+  }
