+namespace Drupal\rgds_core\Finance\Controller\Api;
+
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\rgds_core\Finance\Wiztrust\UpsertWiztrustFinancePage;
+use Drupal\rgds_core\Wiztrust\HttpClient\Item\Error;
+use Drupal\rgds_core\Wiztrust\HttpClient\Item\Publication;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\JsonResponse;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\Response;
+
+final readonly class WiztrustPostFinancePageController implements ContainerInjectionInterface {
+
+  public function __construct(
+    private UpsertWiztrustFinancePage $upsertFinancePage,
+    private LoggerInterface $logger,
+  ) {}
+
+  public static function create(ContainerInterface $container): WiztrustPostFinancePageController {
+    return new static(
+      $container->get('rgds_core.finance.upsert_wiztrust_finance_page'),
+      $container->get('rgds_core.logger.channel.wiztrust'),
+    );
+  }
+
+  public function __invoke(Request $request): JsonResponse {
+    $input = Publication::createFromRequestOrError($request);
+    if (TRUE === $input instanceof Error) {
+      return new JsonResponse(
+        data: ['message' => $input->message],
+        status: Response::HTTP_BAD_REQUEST,
+      );
+    }
+
+    try {
+      $result = ($this->upsertFinancePage)($input);
+    }
+    catch (\Throwable $e) {
+      $this->logger->error('Failed to handle Wiztrust finance page request: {message}', [
+        'message' => $e->getMessage(),
+        'exception' => $e,
+      ]);
+
+      return new JsonResponse(
+        data: ['message' => 'Internal server error.'],
+        status: Response::HTTP_INTERNAL_SERVER_ERROR,
+      );
+    }
+
+    return new JsonResponse(
+      data: ['id' => $result->id],
+      status: \SAVED_NEW === $result->status ? Response::HTTP_CREATED : Response::HTTP_OK,
+    );
+  }
+
+}

