+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Finance\Wiztrust;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\Core\Session\AnonymousUserSession;
+use Drupal\datetime\Plugin\Field\FieldType\DateTimeItemInterface;
+use Drupal\file\FileInterface;
+use Drupal\media\MediaInterface;
+use Drupal\node\NodeInterface;
+use Drupal\rgds_core\Finance\Finder\WiztrustCategoryTermFinder;
+use Drupal\rgds_core\Wiztrust\HttpClient\Item\Publication;
+use Drupal\rgds_core\Wiztrust\RemoteFileDownloader;
+use Drupal\rgds_core\Wiztrust\UpsertMediaImage;
+
+final readonly class FinancePageNodeHydrator {
+
+  public function __construct(
+    private EntityTypeManagerInterface $entityTypeManager,
+    private WiztrustCategoryTermFinder $categoryTermFinder,
+    private RemoteFileDownloader $fileDownloader,
+    private UpsertMediaImage $upsertMediaImage,
+  ) {}
+
+  public function hydrate(NodeInterface|null $node, Publication $input, string $bundle, string $langcode, string|null $siteId): NodeInterface {
+    if (FALSE === $node instanceof NodeInterface) {
+      $node = $this->entityTypeManager->getStorage('node')->create([
+        'type' => $bundle,
+        'field_wiztrust_publication_id' => $input->publicationId,
+        'field_publication_date' => \gmdate(DateTimeItemInterface::DATETIME_STORAGE_FORMAT),
+        'uid' => (new AnonymousUserSession())->id(),
+        'status' => NodeInterface::PUBLISHED,
+      ]);
+    }
+
+    $node->set('langcode', $langcode);
+    $node->set('title', $input->title);
+    $node->set('field_description', $input->description);
+
+    $categories = $this->categoryTermFinder->findByNamesAccordingToLangcode($input->categories, $input->langcode);
+
+    $imageMedia = match(\is_string($input->image)) {
+      TRUE => ($this->upsertMediaImage)($input->image, $input->publicationId, $input->title),
+      FALSE => NULL,
+    };
+
+    $pdfFile = match (\is_string($input->pdf)) {
+      TRUE => $this->fileDownloader->download($input->pdf, \sprintf('public://wiztrust/pdf/%s', $input->publicationId)),
+      FALSE => NULL,
+    };
+
+    if (TRUE === $imageMedia instanceof MediaInterface) {
+      $node->set('field_media_image', $imageMedia);
+    }
+
+    if (TRUE === $pdfFile instanceof FileInterface) {
+      $node->set('field_pdf', $pdfFile);
+    }
+
+    if ([] !== $categories) {
+      $node->set('field_category', $categories);
+    }
+
+    if (NULL !== $siteId) {
+      $node->set('site_id', $siteId);
+    }
+
+    return $node;
+  }
+
+}

