+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Finance\Wiztrust;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\node\NodeInterface;
+
+final readonly class WiztrustFinancePageFinder {
+
+  public function __construct(
+    private EntityTypeManagerInterface $entityTypeManager,
+  ) {}
+
+  public function findByPublicationId(string $publicationId, string $bundle, string|null $siteId): NodeInterface|null {
+    $nodeStorage = $this->entityTypeManager->getStorage('node');
+    $query = $nodeStorage->getQuery()
+      ->accessCheck(FALSE)
+      ->condition('type', $bundle)
+      ->condition('field_wiztrust_publication_id', $publicationId);
+
+    match ($siteId) {
+      NULL => $query->notExists('site_id'),
+      default => $query->condition('site_id', $siteId),
+    };
+
+    $ids = $query->execute();
+
+    if ([] === $ids) {
+      return NULL;
+    }
+
+    $id = \reset($ids);
+    $node = $nodeStorage->load($id);
+
+    return $node instanceof NodeInterface ? $node : NULL;
+  }
+
+}

