+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\HookHandler\Form;
+
+use Drupal\rgds_core\Field\ItemContentPreference;
+
+final readonly class DiscoverV2ItemContentPreferenceSelectionHookHandler {
+
+  public function alter(array &$element): void {
+    if ('discover_v2_item' !== ($element['#paragraph_type'] ?? '')) {
+      return;
+    }
+
+    $selectParents = $element['subform']['field_item_content_preference']['widget']['#parents'] ?? NULL;
+    if (FALSE === \is_array($selectParents)) {
+      return;
+    }
+
+    $preferenceFieldSelector = \sprintf(':input[name="%s"]', $this->buildInputName($selectParents));
+    $textSelected = [$preferenceFieldSelector => ['value' => ItemContentPreference::Text->value]];
+    $imageSelected = [$preferenceFieldSelector => ['value' => ItemContentPreference::Image->value]];
+
+    // Legacy items were saved before this field existed, back when an image was mandatory.
+    // They keep the field optional and default to "image" so editors don't have to reselect it.
+    $isLegacyItem = $this->isLegacyItem($element);
+    $element['subform']['field_item_content_preference']['widget']['#required'] = FALSE === $isLegacyItem;
+    if (TRUE === $isLegacyItem) {
+      $element['subform']['field_item_content_preference']['widget']['#default_value'] = [ItemContentPreference::Image->value];
+    }
+
+    // The description is only shown when the "text" content is selected.
+    $element['subform']['field_description']['#states']['visible'] = $textSelected;
+
+    // The media image is only shown when the "image" content is selected.
+    // The media upload widget does not support the conditional required state.
+    $element['subform']['field_media_image']['#states']['visible'] = $imageSelected;
+  }
+
+  /**
+   * Tells whether the paragraph is a legacy item saved before this field existed.
+   *
+   * Such an item is an existing (non-new) paragraph whose preference is still empty.
+   */
+  private function isLegacyItem(mixed $element): bool {
+    return [] === ($element['subform']['field_item_content_preference']['widget']['#default_value'] ?? []);
+  }
+
+  /**
+   * Builds the HTML "name" attribute (e.g. field_item[0][subform][field_x]) from a #parents array.
+   *
+   * @param array<array-key, mixed> $parents
+   *   The form element #parents.
+   */
+  private function buildInputName(array $parents): string {
+    $name = '';
+    foreach (\array_values($parents) as $index => $parent) {
+      $name .= 0 === $index ? (string) $parent : '[' . (string) $parent . ']';
+    }
+
+    return $name;
+  }
+
+}

