+    $type = PublicationType::tryFrom($request->query->getString('type'));
+    if (FALSE === $type instanceof PublicationType) {
+      $this->messenger()->addError($this->t('Le type de publication est inconnue.', options: ['context' => 'rgds: wiztrust']));
