+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust\Controller;
+
+use Drupal\Core\DependencyInjection\ContainerInjectionInterface;
+use Drupal\Core\Routing\TrustedRedirectResponse;
+use Drupal\Core\Url;
+use Drupal\node\NodeInterface;
+use Drupal\rgds_core\Finance\Wiztrust\WiztrustFinancePageFinder;
+use Symfony\Component\DependencyInjection\ContainerInterface;
+use Symfony\Component\HttpFoundation\RedirectResponse;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\Response;
+use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
+use Symfony\Component\Routing\Exception\InvalidParameterException;
+
+readonly class WiztrustCampaignRedirectController implements ContainerInjectionInterface {
+
+  private const array ALLOWED_PAGE_BUNDLES = ['finance_page', 'finance_page_international'];
+
+  public function __construct(
+    private WiztrustFinancePageFinder $wiztrustFinancePageFinder,
+  ) {}
+
+  public static function create(ContainerInterface $container): self {
+    return new self(
+      $container->get('rgds_core.finance.wiztrust_finance_page_finder'),
+    );
+  }
+
+  public function __invoke(string $bundle, Request $request): RedirectResponse {
+    $publicationId = $request->attributes->get('publication_id');
+
+    if (FALSE === \is_string($publicationId)) {
+      throw new NotFoundHttpException('Valid publication id was not provided.');
+    }
+
+    if (FALSE === \in_array($bundle, self::ALLOWED_PAGE_BUNDLES, TRUE)) {
+      throw new InvalidParameterException(\sprintf('Route has miss configured parameter bundle %s', $bundle));
+    }
+
+    $publication = $this->wiztrustFinancePageFinder->findByPublicationId($publicationId, $bundle, NULL);
+
+    if (FALSE === $publication instanceof NodeInterface) {
+      throw new NotFoundHttpException(\sprintf('No Publication found for wiztrust id %s.', $publicationId));
+    }
+
+    $nodeId = (int) $publication->id();
+
+    // Non-numeric string or null case.
+    if (0 === $nodeId) {
+      throw new NotFoundHttpException('Invalid node ID.');
+    }
+
+    $redirectUrl = Url::fromRoute('entity.node.canonical', ['node' => $nodeId], ['absolute' => TRUE],);
+    return new TrustedRedirectResponse($redirectUrl->toString(), Response::HTTP_FOUND);
+  }
+
+}

