+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust\HttpClient\Item;
+
+use Psr\Http\Message\ResponseInterface;
+
+final readonly class Pagination {
+
+  public function __construct(
+    public int $totalItems,
+    public int $currentPage,
+    public int $perPage,
+    public int $totalPages,
+  ) {}
+
+  public static function createFromResponse(ResponseInterface $response): self {
+    $totalItems = $response->getHeaderLine('X-Total-Count');
+    $totalItems = match (\is_numeric($totalItems)) {
+      TRUE => (int) $totalItems,
+        FALSE => 0,
+    };
+
+    $currentPage = $response->getHeaderLine('X-Page');
+    $currentPage = match (\is_numeric($currentPage)) {
+      TRUE => (int) $currentPage,
+        FALSE => 0,
+    };
+
+    $perPage = $response->getHeaderLine('X-Per-Page');
+    $perPage = match (\is_numeric($perPage)) {
+      TRUE => \max(1, (int) $perPage),
+        FALSE => 1,
+    };
+
+    $totalPages = $response->getHeaderLine('X-Total-Pages');
+    $totalPages = match (\is_numeric($totalPages)) {
+      TRUE => (int) $totalPages,
+        FALSE => 0,
+    };
+
+    return new self($totalItems, $currentPage, $perPage, $totalPages);
+  }
+
