+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Wiztrust;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\Core\File\FileExists;
+use Drupal\Core\File\FileSystemInterface;
+use Drupal\Core\Session\AccountProxyInterface;
+use Drupal\file\FileInterface;
+use Drupal\file\FileRepositoryInterface;
+use Drupal\rgds_core\Wiztrust\Exception\WiztrustFileDownloadException;
+use Drupal\rgds_core\Wiztrust\Exception\WiztrustInvalidEntityException;
+use GuzzleHttp\ClientInterface;
+
+final class RemoteFileDownloader {
+
+  public function __construct(
+    private readonly ClientInterface $httpClient,
+    private readonly FileRepositoryInterface $fileRepository,
+    private readonly FileSystemInterface $fileSystem,
+    private readonly AccountProxyInterface $currentUser,
+    private readonly EntityTypeManagerInterface $entityTypeManager,
+  ) {}
+
+  /**
+   * Download a file.
+   *
+   * This method is heavily inspired by \Drupal\file\FileRepository::writeData
+   * and \Drupal\file\FileRepository::createOrUpdate
+   * and \Drupal\file\Plugin\rest\resource\FileUploadResource::post.
+   *
+   * To support downloading large file without exhausting PHP memory limits,
+   * we stream the file directly to a temporary file on disk
+   * instead of loading it into memory.
+   * It is expected, to do the whole process within the same request and so
+   * within the same process, so that the temporary file is on the same webhost.
+   * It is a little bit more complicated than just FileRepository::writeData
+   * but it worth handling the case.
+   * (An idea may be to contribute to Drupal Core to add bricks for that.)
+   *
+   * @param string $url
+   *   The absolute url.
+   * @param string $destinationDirectory
+   *   Where to store the file.
+   *
+   * @return \Drupal\file\FileInterface
+   *   The downloaded file.
+   */
+  public function download(string $url, string $destinationDirectory): FileInterface {
+    $urlPath = \parse_url($url, \PHP_URL_PATH);
+    if (FALSE === \is_string($urlPath)) {
+      throw WiztrustFileDownloadException::forUrl($url);
+    }
+    $filename = \basename($urlPath);
+
+    $this->fileSystem->prepareDirectory($destinationDirectory, FileSystemInterface::CREATE_DIRECTORY);
+
+    $tempFilePath = $this->fileSystem->tempnam('temporary://', 'wiztrust');
+    if (FALSE === \is_string($tempFilePath)) {
+      throw new WiztrustFileDownloadException('Failed to create a temporary file for downloading.');
+    }
+
+    $realTempPath = $this->fileSystem->realpath($tempFilePath);
+    if (FALSE === $realTempPath) {
+      throw new WiztrustFileDownloadException('Failed to resolve temporary file path for downloading.');
+    }
+
+    try {
+      $this->httpClient->request('GET', $url, ['sink' => $realTempPath]);
+    }
+    catch (\Throwable $e) {
+      throw WiztrustFileDownloadException::forUrl($url, $e);
+    }
+
+    $destination = $destinationDirectory . '/' . $filename;
+    $uri = $this->fileSystem->move($tempFilePath, $destination, FileExists::Replace);
+
+    $file = $this->fileRepository->loadByUri($uri);
+    if (FALSE === $file instanceof FileInterface) {
+      $file = $this->entityTypeManager->getStorage('file')->create(['uri' => $uri]);
+      $file->setOwnerId($this->currentUser->id());
+    }
+
+    $file->setFilename($filename);
+    $file->setPermanent();
+
+    $violations = $file->validate();
+    if ($violations->count() > 0) {
+      throw WiztrustInvalidEntityException::fromViolations($violations);
+    }
+
+    $file->save();
+
+    return $file;
+  }
+
+}

