+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Kernel\Wiztrust;
+
+use Drupal\Core\Routing\TrustedRedirectResponse;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\node\Entity\Node;
+use Drupal\node\NodeInterface;
+use Drupal\rgds_core\Finance\Wiztrust\WiztrustFinancePageFinder;
+use Drupal\rgds_core\Wiztrust\Controller\WiztrustCampaignRedirectController;
+use Drupal\taxonomy\Entity\Term;
+use PHPUnit\Framework\Attributes\CoversClass;
+use PHPUnit\Framework\Attributes\DataProvider;
+use Symfony\Component\HttpFoundation\Request;
+use Symfony\Component\HttpFoundation\Response;
+use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
+
+#[CoversClass(WiztrustCampaignRedirectController::class)]
+final class WiztrustCampaignRedirectControllerTest extends KernelTestBase {
+
+  private WiztrustFinancePageFinder $nodePublicationFinder;
+  private Term $term;
+
+  /**
+   * {@inheritdoc}
+   */
+  protected static $modules = [
+    'taxonomy',
+  ];
+
+  public function setup(): void {
+    parent::setUp();
+
+    $this->nodePublicationFinder = \Drupal::service('rgds_core.finance.wiztrust_finance_page_finder');
+    $this->term = \Drupal::service('entity_type.manager')
+      ->getStorage('taxonomy_term')
+      ->create(['vid' => 'term', 'name' => 'term']);
+    $this->term->save();
+  }
+
+  protected function setUpBeforeInstallSiteConfig(): void {
+    $this->installEntitySchema('taxonomy_term');
+  }
+
+  #[DataProvider('bundleProvider')]
+  public function testItShouldReturnTrustedRedirectResponseWithValidPublicationId($bundle): void {
+    $node = $this->createFinancePageWithPublicationId('abc', $bundle);
+    $campaignRedirectController = new WiztrustCampaignRedirectController($this->nodePublicationFinder);
+
+    $result = $campaignRedirectController($bundle, new Request(attributes: ['publication_id' => 'abc']));
+
+    $this->assertInstanceOf(TrustedRedirectResponse::class, $result);
+    $this->assertMatchesRegularExpression(\sprintf('#/node/%s$#', $node->id()), $result->getTargetUrl());
+    $this->assertSame(Response::HTTP_FOUND, $result->getStatusCode());
+  }
+
+  public function testItShouldThrowWhenPublicationIsNotSameBundle(): void {
+    $this->createFinancePageWithPublicationId('abc', 'finance_page');
+    $campaignRedirectController = new WiztrustCampaignRedirectController($this->nodePublicationFinder);
+
+    $this->expectException(NotFoundHttpException::class);
+    $this->expectExceptionMessage('No Publication found for wiztrust id abc');
+    $campaignRedirectController('finance_page_international', new Request(attributes: ['publication_id' => 'abc']));
+  }
+
+  #[DataProvider('bundleProvider')]
+  public function testItShouldReturnAnExceptionWithBadValues($bundle): void {
+    $this->createFinancePageWithPublicationId('abc', $bundle);
+    $campaignRedirectController = new WiztrustCampaignRedirectController($this->nodePublicationFinder);
+
+    $this->expectException(NotFoundHttpException::class);
+    $this->expectExceptionMessage('No Publication found for wiztrust id def');
+    $campaignRedirectController($bundle, new Request(attributes: ['publication_id' => 'def']));
+  }
+
+  public static function bundleProvider(): \Generator {
+    yield 'corporate' => ['finance_page'];
+    yield 'international' => ['finance_page_international'];
+  }
+
+  private function createFinancePageWithPublicationId(
+    string $publicationId,
+    string $bundle = 'finance_page',
+  ): NodeInterface {
+    $node = Node::create([
+      'type' => $bundle,
+      'title' => 'test',
+      'field_description' => 'description',
+      'field_publication_date' => new \DateTimeImmutable(),
+      'field_wiztrust_publication_id' => $publicationId,
+      'field_category' => $this->term,
+    ]);
+    $node->save();
+
+    return $node;
+  }
+
+}

