+    self::assertSame($expectedHttpStatusCode, $response->getStatusCode());
+    self::assertJsonStringEqualsJsonString('{"id":"42"}', $response->getContent());
+  }
+
+  private function validRequest(): Request {
+    return new Request(content: '{"publication_id": "pub-123", "title": "Finance Page", "langcode": "fr"}');
+  }
+
+}

