+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\HookHandler\Form;
+
+use Drupal\Tests\UnitTestCase;
+use Drupal\rgds_core\Field\ItemContentPreference;
+use Drupal\rgds_core\HookHandler\Form\DiscoverV2ItemContentPreferenceSelectionHookHandler;
+
+final class DiscoverV2ItemContentPreferenceSelectionHookHandlerTest extends UnitTestCase {
+
+  private const string SELECTOR = ':input[name="field_item[0][subform][field_item_content_preference]"]';
+
+  private DiscoverV2ItemContentPreferenceSelectionHookHandler $hookHandler;
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->hookHandler = new DiscoverV2ItemContentPreferenceSelectionHookHandler();
+  }
+
+  public function testItShouldNotAlterElementWhenParagraphTypeIsNotDiscoverV2Item(): void {
+    $element = $this->buildElement();
+    $element['#paragraph_type'] = 'another_paragraph';
+    $original = $element;
+
+    $this->hookHandler->alter($element);
+
+    $this->assertSame($original, $element);
+  }
+
+  public function testItShouldNotAlterElementWhenPreferenceSelectHasNoParents(): void {
+    $element = $this->buildElement();
+    unset($element['subform']['field_item_content_preference']['widget']['#parents']);
+    $original = $element;
+
+    $this->hookHandler->alter($element);
+
+    $this->assertSame($original, $element);
+  }
+
+  public function testItShouldSetConditionalStatesForBothContentModes(): void {
+    $element = $this->buildElement();
+
