+  private function buildElement(array $preferenceWidgetOverrides = []): array {
+    return [
+      '#paragraph_type' => 'discover_v2_item',
+      'subform' => [
+        'field_item_content_preference' => [
+          'widget' => [
+            '#parents' => ['field_item', 0, 'subform', 'field_item_content_preference'],
