+  public function testItShouldReportWhenLangcodeIsPresent(): void {
+    self::assertTrue((new Filters(langcode: 'fr'))->hasLangcode());
+    self::assertFalse((new Filters(langcode: ''))->hasLangcode());
+  }
+
+  public function testItShouldReturnEmptyQueryParametersWhenNoFilterIsSet(): void {
+    self::assertSame([], (new Filters())->toQueryParameters());
