+
+  /**
+   * @return array<string, mixed>
+   *   Valid publication log data with optional overrides.
+   */
+  private static function publicationLogData(array $overrides = []): array {
+    return $overrides + [
+      'id' => 'log-123',
+      'publication_id' => 'pub-456',
+      'type' => 'financial',
+      'title' => 'My Publication',
+      'langcode' => 'fr',
+      'published_at' => '2026-01-01T10:00:00+00:00',
+      'updated_at' => '2026-01-02T10:00:00+00:00',
+      'created_at' => '2026-01-03T10:00:00+00:00',
+    ];
+  }
+
+  /**
+   * @return array<string, mixed>
