+  public function testItShouldReturnPaginatedLogsWhenGettingPublicationLogs(): void {
+    $body = (string) \json_encode([
+      self::publicationLogData(['id' => 'log-1']),
+      self::publicationLogData(['id' => 'log-2', 'type' => 'press', 'langcode' => 'en']),
+    ]);
+    $response = new Response(
+      200,
+      [
+        'X-Total-Count' => '2',
+        'X-Page' => '1',
+        'X-Per-Page' => '20',
+        'X-Total-Pages' => '1',
+      ],
+      $body,
+    );
+    $client = $this->makeClient($response);
+
+    $collection = $client->getPublicationLogs([]);
+
+    self::assertSame(2, $collection->itemsCount);
+    self::assertSame('log-1', $collection->items[0]->id);
+    self::assertSame(PublicationType::Financial, $collection->items[0]->type);
+    self::assertSame(Langcode::Fr, $collection->items[0]->langcode);
+    self::assertSame('log-2', $collection->items[1]->id);
+    self::assertSame(PublicationType::Press, $collection->items[1]->type);
+    self::assertSame(Langcode::En, $collection->items[1]->langcode);
+
+    self::assertSame(2, $collection->pagination->totalItems);
+    self::assertSame(1, $collection->pagination->currentPage);
+    self::assertSame(20, $collection->pagination->perPage);
+    self::assertSame(1, $collection->pagination->totalPages);
+  }
