+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\Csp\EventSubscriber;
+
+use Drupal\Core\Site\Settings;
+use Drupal\csp\Csp;
+use Drupal\csp\CspEvents;
+use Drupal\csp\Event\PolicyAlterEvent;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\EventDispatcher\EventSubscriberInterface;
+
+/**
+ * Appends environment dependent sources to the CSP policy at runtime.
+ *
+ * Some sources depend on the environment and must not be hard coded in the
+ * version controlled csp.settings.yml: the Partoo store locator proxy
+ * (RGDS_API_PROXY_BASE_URI) and the micro_sso master origin (micro_site
+ * public_url). They are declared as plain references in settings under
+ * $settings['rgds_csp']['directives'] and appended here, normalized to CSP
+ * origins.
+ *
+ * Sources are only appended to a policy when the target directive (or one of
+ * its fallbacks, typically default-src) is already enabled, so enabling the
+ * enforced policy later automatically includes them without ever manufacturing
+ * a directive that would unexpectedly restrict a policy.
+ *
+ * @final
+ */
+final class DynamicSourcesPolicyAlterSubscriber implements EventSubscriberInterface {
+
+  /**
+   * The settings key holding the dynamic CSP directives.
+   */
+  private const string SETTINGS_KEY = 'rgds_csp';
+
+  /**
+   * Memoized normalized directives, keyed by valid directive name.
+   *
+   * @var array<string, list<string>>|null
+   */
+  private array|NULL $normalizedDirectives = NULL;
+
+  public function __construct(
+    private readonly Settings $settings,
+    private readonly LoggerInterface $logger,
+  ) {}
+
+  public static function getSubscribedEvents(): array {
+    return [
+      CspEvents::POLICY_ALTER => 'onPolicyAlter',
+    ];
+  }
+
+  /**
+   * Append the configured dynamic sources to the altered policy.
+   *
+   * @param \Drupal\csp\Event\PolicyAlterEvent $event
+   *   The policy alter event.
+   */
+  public function onPolicyAlter(PolicyAlterEvent $event): void {
+    $directives = $this->getNormalizedDirectives();
+    if ([] === $directives) {
+      return;
+    }
+
+    $policy = $event->getPolicy();
+    foreach ($directives as $name => $sources) {
+      $policy->fallbackAwareAppendIfEnabled($name, $sources);
+    }
+  }
+
+  /**
+   * Build, once per instance, the normalized directive name => sources map.
+   *
+   * Invalid directive names are skipped and logged instead of being handed to
+   * the Csp object: it would throw an \InvalidArgumentException and break every
+   * response.
+   *
+   * @return array<string, list<string>>
+   *   The normalized directives.
+   */
+  private function getNormalizedDirectives(): array {
+    if (NULL !== $this->normalizedDirectives) {
+      return $this->normalizedDirectives;
+    }
+
+    $normalized = [];
+    foreach ($this->readRawDirectives() as $name => $sources) {
+      if (FALSE === \is_string($name) || FALSE === Csp::isValidDirectiveName($name)) {
+        $this->logger->warning('Unknown CSP directive %directive declared in settings key %key was ignored.', [
+          '%directive' => \is_string($name) ? $name : \gettype($name),
+          '%key' => self::SETTINGS_KEY,
+        ]);
+
+        continue;
+      }
+
+      // Only source-list directives (connect-src, script-src, ...) accept the
+      // host expressions produced here. Appending a normalized list to a
+      // boolean directive such as upgrade-insecure-requests would reach
+      // array_merge() with a boolean and throw once the base policy enables it,
+      // so incompatible schemas are rejected up front rather than at runtime.
+      if (Csp::DIRECTIVE_SCHEMA_SOURCE_LIST !== Csp::getDirectiveSchema($name)) {
+        $this->logger->warning('CSP directive %directive declared in settings key %key does not accept source expressions and was ignored.', [
+          '%directive' => $name,
+          '%key' => self::SETTINGS_KEY,
+        ]);
+
+        continue;
+      }
+
+      $directiveSources = $this->normalizeSources($name, (array) $sources);
+      if ([] === $directiveSources) {
+        continue;
+      }
+
+      $normalized[$name] = $directiveSources;
+    }
+
+    $this->normalizedDirectives = $normalized;
+
+    return $normalized;
+  }
+
+  /**
+   * Read the raw directives declared in settings.
+   *
+   * @return array<mixed>
+   *   The raw directives map, or an empty array when unset or malformed.
+   */
+  private function readRawDirectives(): array {
+    $config = $this->settings::get(self::SETTINGS_KEY, []);
+    if (FALSE === \is_array($config)) {
+      return [];
+    }
+
+    $directives = $config['directives'] ?? [];
+
+    return \is_array($directives) ? $directives : [];
+  }
+
+  /**
+   * Normalize a list of raw sources to CSP origins, dropping empty ones.
+   *
+   * @param string $directive
+   *   The directive the sources belong to, used for diagnostics only.
+   * @param array<mixed> $sources
+   *   The raw source values from settings.
+   *
+   * @return list<string>
+   *   The normalized, de-duplicated origins.
+   */
+  private function normalizeSources(string $directive, array $sources): array {
+    $normalized = [];
+    foreach ($sources as $source) {
+      if (FALSE === \is_string($source)) {
+        continue;
+      }
+
+      $origin = $this->normalizeSource($directive, $source);
+      if (NULL === $origin || TRUE === \in_array($origin, $normalized, TRUE)) {
+        continue;
+      }
+
+      $normalized[] = $origin;
+    }
+
+    return $normalized;
+  }
+
+  /**
+   * Normalize a single raw source to a CSP origin, or NULL when unusable.
+   *
+   * Empty values are dropped silently because environment variables are often
+   * absent. A nonempty value that cannot yield a safe origin is dropped and
+   * logged: once the policy is enforced a deployment typo would otherwise turn
+   * into a broken browser feature with no server-side trace.
+   *
+   * @param string $directive
+   *   The directive the source belongs to, used for diagnostics only.
+   * @param string $source
+   *   The raw source value.
+   *
+   * @return string|null
+   *   The normalized origin, or NULL when empty or rejected.
+   */
+  private function normalizeSource(string $directive, string $source): ?string {
+    $source = \trim($source);
+    if ('' === $source) {
+      return NULL;
+    }
+
+    $origin = $this->extractOrigin($source);
+    if (NULL === $origin) {
+      $this->logMalformed($directive, $source, 'not a host based source');
+
+      return NULL;
+    }
+
+    // parse_url() is a parser, not a validator: it leaves CSP structural
+    // characters inside the host component. A ';' separates directives and a
+    // ',' separates sources, so a value such as "https://example.com;
+    // script-src *" would inject a new directive and silently weaken the
+    // header. Whitespace and control bytes are never valid in an origin
+    // either, so any origin carrying those bytes is rejected rather than
+    // emitted.
+    if (1 === \preg_match('/[\x00-\x20;,]/', $origin)) {
+      $this->logMalformed($directive, $source, 'contains illegal characters');
+
+      return NULL;
+    }
+
+    return $origin;
+  }
+
+  /**
+   * Extract a scheme://host:port (or bare host) origin from a raw source.
+   *
+   * A full URL keeps its scheme, host and port but drops the path and query
+   * ("https://api.example.com/proxy/" becomes "https://api.example.com"). A
+   * scheme less bare host is kept as-is ("cms.example.localdev/sso/check"
+   * becomes "cms.example.localdev") so it inherits the page scheme and forbids
+   * a protocol downgrade.
+   *
+   * @param string $source
+   *   The trimmed raw source value.
+   *
+   * @return string|null
+   *   The origin, or NULL when the value is not a host based source.
+   */
+  private function extractOrigin(string $source): ?string {
+    $parts = \parse_url($source);
+    if (FALSE === $parts) {
+      return NULL;
+    }
+
+    $scheme = $parts['scheme'] ?? '';
+    $host = $parts['host'] ?? '';
+
+    // A value carrying a scheme but no host is an opaque URI (javascript:,
+    // data:, mailto:), never a valid host source: reject it.
+    if ('' === $host && '' !== $scheme) {
+      return NULL;
+    }
+
+    // A scheme less value is parsed entirely as the path: keep the leading host
+    // segment ("cms.example.localdev/sso/check" becomes "cms.example.localdev").
+    if ('' === $host) {
+      $host = \explode('/', $parts['path'] ?? '')[0];
+
+      return '' !== $host ? $host : NULL;
+    }
+
+    $origin = '' === $scheme ? $host : \sprintf('%s://%s', $scheme, $host);
+    $port = $parts['port'] ?? NULL;
+
+    return NULL === $port ? $origin : \sprintf('%s:%d', $origin, $port);
+  }
+
+  /**
+   * Log a rejected nonempty source without leaking credentials or noise.
+   *
+   * @param string $directive
+   *   The directive the source belongs to.
+   * @param string $source
+   *   The raw source value that was rejected.
+   * @param string $reason
+   *   A short, non sensitive rejection reason.
+   */
+  private function logMalformed(string $directive, string $source, string $reason): void {
+    $this->logger->warning('Ignored CSP source for directive %directive in settings key %key (%reason): %source', [
+      '%directive' => $directive,
+      '%key' => self::SETTINGS_KEY,
+      '%reason' => $reason,
+      '%source' => $this->sanitizeForLog($source),
+    ]);
+  }
+
+  /**
+   * Reduce a rejected source to a safe, bounded token for logging.
+   *
+   * Embedded credentials are stripped, control bytes are rendered as a visible
+   * \xNN token so a forged value cannot rewrite an operator's terminal, and the
+   * result is length capped to keep the log readable.
+   *
+   * @param string $value
+   *   The raw source value.
+   *
+   * @return string
+   *   The sanitized value.
+   */
+  private function sanitizeForLog(string $value): string {
+    $value = \preg_replace('#^([a-zA-Z][a-zA-Z0-9+.\-]*://)[^@/]*@#', '$1', $value) ?? $value;
+    $value = \preg_replace_callback(
+      '/[\x00-\x1F\x7F]/',
+      static fn (array $matches): string => \sprintf('\\x%02X', \ord($matches[0])),
+      $value,
+    ) ?? $value;
+
+    return \mb_strlen($value) > 120 ? \mb_substr($value, 0, 120) . '…' : $value;
+  }
+
+}

