+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Unit\Csp\EventSubscriber;
+
+use Drupal\Core\Site\Settings;
+use Drupal\Tests\UnitTestCase;
+use Drupal\csp\Csp;
+use Drupal\csp\CspEvents;
+use Drupal\csp\Event\PolicyAlterEvent;
+use Drupal\rgds_core\Csp\EventSubscriber\DynamicSourcesPolicyAlterSubscriber;
+use PHPUnit\Framework\Attributes\DataProvider;
+use Psr\Log\LoggerInterface;
+use Symfony\Component\HttpFoundation\Response;
+
+/**
+ * Class DynamicSourcesPolicyAlterSubscriberTest.
+ *
+ * phpcs:disable Drupal.Commenting.DocComment
+ *
+ * @package Drupal\Tests\rgds_core\Unit\Csp\EventSubscriber
+ */
+final class DynamicSourcesPolicyAlterSubscriberTest extends UnitTestCase {
+
+  private LoggerInterface $logger;
+
+  public function setUp(): void {
+    parent::setUp();
+
+    $this->logger = $this->createMock(LoggerInterface::class);
+  }
+
+  public function testItShouldSubscribeToThePolicyAlterEvent(): void {
+    $events = DynamicSourcesPolicyAlterSubscriber::getSubscribedEvents();
+
+    $this->assertArrayHasKey(CspEvents::POLICY_ALTER, $events);
+    $this->assertSame('onPolicyAlter', $events[CspEvents::POLICY_ALTER]);
+  }
+
+  public function testItShouldNormalizeAndAppendSourcesToAnEnabledDirective(): void {
+    $settings = new Settings([
+      'rgds_csp' => [
+        'directives' => [
+          'connect-src' => [
+            'cms.rgds.localdev',
+            'https://webapi.ramsaysante.fr/proxy/',
+          ],
+        ],
+      ],
+    ]);
+
+    $policy = new Csp();
+    $policy->setDirective('connect-src', [Csp::POLICY_SELF]);
+
+    $this->subscriber($settings)->onPolicyAlter(new PolicyAlterEvent($policy, new Response()));
+
+    $this->assertSame(
+      [Csp::POLICY_SELF, 'cms.rgds.localdev', 'https://webapi.ramsaysante.fr'],
+      \array_values($policy->getDirective('connect-src')),
+    );
+  }
+
+  public function testItShouldInheritFromDefaultSrcWhenConnectSrcIsNotEnabled(): void {
+    $settings = new Settings([
+      'rgds_csp' => [
+        'directives' => [
+          'connect-src' => ['cms.rgds.localdev'],
+        ],
+      ],
+    ]);
+
+    $policy = new Csp();
+    $policy->setDirective('default-src', [Csp::POLICY_SELF]);
+
+    $this->subscriber($settings)->onPolicyAlter(new PolicyAlterEvent($policy, new Response()));
+
+    $this->assertTrue($policy->hasDirective('connect-src'));
+    $this->assertSame(
+      [Csp::POLICY_SELF, 'cms.rgds.localdev'],
+      \array_values($policy->getDirective('connect-src')),
+    );
+  }
+
+  public function testItShouldLeaveConnectSrcUnsetWithoutAnEnabledFallback(): void {
+    $settings = new Settings([
+      'rgds_csp' => [
+        'directives' => [
+          'connect-src' => ['cms.rgds.localdev'],
+        ],
+      ],
+    ]);
+
+    $policy = new Csp();
+    $policy->setDirective('img-src', [Csp::POLICY_SELF]);
+
+    $this->subscriber($settings)->onPolicyAlter(new PolicyAlterEvent($policy, new Response()));
+
+    $this->assertFalse($policy->hasDirective('connect-src'));
+  }
+
+  public function testItShouldIgnoreAndLogAnUnknownDirectiveOnlyOnce(): void {
+    $settings = new Settings([
+      'rgds_csp' => [
+        'directives' => [
+          'not-a-directive' => ['example.com'],
+          'connect-src' => ['cms.rgds.localdev'],
+        ],
+      ],
+    ]);
+
+    $this->logger->expects($this->once())
+      ->method('warning')
+      ->with(
+        $this->stringContains('Unknown CSP directive'),
+        $this->callback(static fn (array $context): bool => 'not-a-directive' === $context['%directive']),
+      );
+
+    $subscriber = $this->subscriber($settings);
+
+    $firstPolicy = new Csp();
+    $firstPolicy->setDirective('connect-src', [Csp::POLICY_SELF]);
+    $subscriber->onPolicyAlter(new PolicyAlterEvent($firstPolicy, new Response()));
+
+    // A request builds both the report-only and enforced policies, so the
+    // event fires twice: the memoized result must not log the warning again.
+    $secondPolicy = new Csp();
+    $secondPolicy->setDirective('connect-src', [Csp::POLICY_SELF]);
+    $subscriber->onPolicyAlter(new PolicyAlterEvent($secondPolicy, new Response()));
+
+    $this->assertSame(
+      [Csp::POLICY_SELF, 'cms.rgds.localdev'],
+      \array_values($firstPolicy->getDirective('connect-src')),
+    );
+    $this->assertSame(
+      [Csp::POLICY_SELF, 'cms.rgds.localdev'],
+      \array_values($secondPolicy->getDirective('connect-src')),
+    );
+  }
+
+  public function testItShouldDoNothingWhenNoDynamicSourcesAreConfigured(): void {
+    $this->logger->expects($this->never())->method('warning');
+
+    $policy = new Csp();
