+#!/usr/bin/env php
+<?php
+
+/**
+ * @file
+ * Parse and summarize CSP (Content-Security-Policy) violation reports.
+ *
+ * Reads RGDS "reporting" Monolog log files where each line embeds a Reporting
+ * API payload as pretty-printed JSON wrapped in <pre>...</pre>, e.g.:
+ *
+ *   [2026-09-14T18:27:06+02:00] reporting.INFO: default <br/> <pre>{ "type":
+ *   "csp-violation", "body": { "effectiveDirective": "style-src-attr", ... } }
+ *   </pre> [] {"ip":"...","request_uri":"...","uid":"1","user":"admin"}
+ *
+ * The script streams input line by line (constant memory, safe on multi-GB /
+ * multi-million-line logs), transparently reads gzip-rotated files (*.gz), and
+ * accepts several files and/or stdin. It has no Drupal dependency so it can run
+ * on the production server with a plain PHP CLI.
+ *
+ * Usage examples:
+ *   scripts/csp-report.php app/logs/reporting/reporting-handler-2026-09-14.log
+ *   scripts/csp-report.php --top=20 /var/log/reporting/*.log*
+ *   scripts/csp-report.php --mode=json /var/log/reporting/*.log*  # for agents/CI
+ *   zcat /var/log/reporting/*.gz | scripts/csp-report.php -
+ *   scripts/csp-report.php --mode=tsv logs/*.log | sort | uniq -c | sort -rn
+ *   scripts/csp-report.php --mode=ndjson logs/*.gz | json_pp   # clean NDJSON
+ *
+ * See --help for all options.
+ */
+
+declare(strict_types=1);
+
+const EXIT_OK = 0;
+const EXIT_USAGE = 2;
+const EXIT_NO_INPUT = 3;
+
+/**
+ * Print usage and exit.
+ */
+function usage(int $code = EXIT_OK): never
+{
+    $self = \basename($GLOBALS['argv'][0] ?? 'csp-report.php');
+    \fwrite(\STDERR, <<<TXT
+Parse and summarize CSP violation reports from RGDS reporting logs.
+
+Usage:
+    {$self} [options] [FILE ...]
+
+FILE may be a plain or gzip (*.gz) log file. Use '-' or no FILE to read stdin.
+Several files may be given; they are processed as one stream.
+
+Options:
+    -m, --mode=MODE      summary (default) | json | tsv | ndjson
+                           summary : aggregated top-N tables (human readable)
+                           json    : single aggregated JSON object (agent friendly)
+                           tsv     : one row per report, streamed (pipe to sort/awk)
+                           ndjson  : one compact JSON object per report, streamed
+    -n, --top=N          Rows kept per table in summary mode (default: 15)
+    -t, --type=TYPE      Report 'type' to keep (default: csp-violation; 'all' = any)
+    -f, --fields=LIST    Comma-separated body fields for tsv / summary tables.
+                         Default tsv    : effectiveDirective,disposition,blockedURL,
+                                           sourceFile,lineNumber,documentURL,sample
+                         Default summary: disposition,effectiveDirective,blockedURL,
+                                           sourceFile,documentURL
+    -q, --strip-query    Strip ?query and #fragment from URL fields (lowers cardinality).
+        --max-keys=N     Distinct keys tracked per table before overflow bucket
+                         (summary only, protects memory; default: 200000).
+        --progress       Print progress to stderr every 100k lines.
+    -h, --help           Show this help.
+
+Exit codes: 0 ok, 2 usage error, 3 no readable input.
+
+TXT);
+    exit($code);
+}
+
+/**
+ * Open a path as a readable stream, transparently handling gzip and stdin.
+ *
+ * @return resource|null
+ */
+function open_input(string $path)
+{
+    if ('-' === $path) {
+        return \STDIN;
+    }
+    if (!\is_file($path)) {
+        \fwrite(\STDERR, "warning: not a file, skipping: {$path}\n");
+
+        return null;
+    }
+    $url = \str_ends_with($path, '.gz') ? 'compress.zlib://' . $path : $path;
+    $handle = @\fopen($url, 'rb');
+    if (false === $handle) {
+        \fwrite(\STDERR, "warning: cannot open, skipping: {$path}\n");
+
+        return null;
+    }
+
+    return $handle;
+}
+
+/**
+ * Extract the JSON payload embedded between <pre> and </pre> on a log line.
+ *
+ * Uses strpos/substr rather than a regex: it is measurably faster on very large
+ * files and the CSP payload never contains a literal "</pre>".
+ */
+function extract_payload(string $line): ?string
+{
+    $start = \strpos($line, '<pre>');
+    if (false === $start) {
+        return null;
+    }
+    $start += 5;
+    $end = \strpos($line, '</pre>', $start);
+
+    return false === $end ? \substr($line, $start) : \substr($line, $start, $end - $start);
+}
+
+/**
+ * Resolve a body field to a display string, optionally stripping URL query/frag.
+ */
+function field_value(array $body, string $field, bool $stripQuery): string
+{
+    $value = $body[$field] ?? '(none)';
+    if (\is_array($value)) {
+        $value = \json_encode($value, \JSON_UNESCAPED_SLASHES);
+    }
+    $value = (string) $value;
+
+    $isUrlField = \str_ends_with($field, 'URL') || 'sourceFile' === $field;
+    if ($stripQuery && $isUrlField && '' !== $value) {
+        $value = \preg_replace('/[?#].*$/', '', $value) ?? $value;
+    }
+
+    return $value;
+}
+
+/**
+ * Increment a counter table, funnelling overflow into a bounded bucket.
+ */
+function bump(array &$table, string $key, int $maxKeys): void
+{
+    if (isset($table[$key])) {
+        ++$table[$key];
+
+        return;
+    }
+    if (\count($table) >= $maxKeys) {
+        $table['(overflow: cardinality capped)'] = ($table['(overflow: cardinality capped)'] ?? 0) + 1;
+
+        return;
+    }
+    $table[$key] = 1;
+}
+
+/**
+ * Print a sorted top-N table.
+ */
+function print_table(string $title, array $table, int $top): void
+{
+    \arsort($table);
+    $distinct = \count($table);
+    echo "\n== {$title} ({$distinct} distinct) ==\n";
+    $i = 0;
+    foreach ($table as $key => $count) {
+        if ($i++ >= $top) {
+            $rest = $distinct - $top;
+            echo \sprintf("       … (%d more)\n", $rest);
+            break;
+        }
+        echo \sprintf("%8d  %s\n", $count, '' === $key ? '(empty)' : sanitize_controls((string) $key));
+    }
+}
+
+/**
+ * Build a machine-readable view of a counter table for --mode=json.
+ *
+ * Returns the sorted top-N rows plus an explicit account of the omitted tail,
+ * so an agent never has to guess what a truncated table hides. Pair separators
+ * are rendered as ASCII ("<=") to keep the output free of multi-byte glyphs.
+ *
+ * @param array<string, int> $table
+ *
+ * @return array{distinct: int, omitted: int, omitted_count: int, items: list<array{value: string, count: int}>}
+ */
+function table_report(array $table, int $top): array
+{
+    \arsort($table);
+    $distinct = \count($table);
+    $items = [];
+    $shown = 0;
+    $shownCount = 0;
+    $totalCount = 0;
+    foreach ($table as $value => $count) {
+        $totalCount += $count;
+        if ($shown < $top) {
+            $items[] = ['value' => \str_replace('  ⇐  ', ' <= ', (string) $value), 'count' => $count];
+            ++$shown;
+            $shownCount += $count;
+        }
+    }
+
+    return [
+        'distinct' => $distinct,
+        'omitted' => \max(0, $distinct - $shown),
+        'omitted_count' => $totalCount - $shownCount,
+        'items' => $items,
+    ];
+}
+
+/**
+ * Parse a strictly positive integer option value or abort with a usage error.
+ */
+function positive_int(string $raw, string $flag): int
+{
+    if (!\ctype_digit($raw) || 0 === (int) $raw) {
+        \fwrite(\STDERR, "error: {$flag} expects a positive integer, got '{$raw}'\n");
+        usage(EXIT_USAGE);
+    }
+
+    return (int) $raw;
+}
+
+/**
+ * Neutralize terminal control characters from untrusted report values.
+ *
+ * Report bodies are attacker influenced: any page, or a direct POST to the
+ * reporting endpoint, can forge them. Printed verbatim, bytes such as ESC
+ * (0x1B) let a forged report emit ANSI sequences that recolor, hide, or rewrite
+ * an operator's terminal while they review logs. Every C0 control, DEL, and
+ * (UTF-8 encoded) C1 control is rendered as a visible \xNN token. JSON and
+ * NDJSON modes are left untouched because json_encode already escapes these
+ * bytes as \uXXXX, which no terminal interprets.
+ */
+function sanitize_controls(string $value): string
+{
+    // C0 controls (tab, newline, CR included) and DEL: single bytes that never
+    // occur inside a valid UTF-8 multi-byte sequence, so a raw byte match is safe.
+    $value = \preg_replace_callback(
+        '/[\x00-\x1F\x7F]/',
+        static fn (array $m): string => \sprintf('\\x%02X', \ord($m[0])),
+        $value,
+    ) ?? $value;
+
+    // C1 controls only in their valid UTF-8 form 0xC2 0x80..0x9F, so legitimate
+    // multi-byte characters (e.g. accented letters, 0xC3 0xA9) stay intact.
+    return \preg_replace_callback(
+        '/\xC2[\x80-\x9F]/',
+        static fn (array $m): string => \sprintf('\\x%02X', \ord($m[0][1])),
+        $value,
+    ) ?? $value;
+}
+
+/**
+ * Reduce an absolute URL to its CSP source origin (scheme://host[:port]).
+ *
+ * CSP host allowlisting matches on scheme, host, and optional port, never on
+ * the path or query, so exact blocked URLs otherwise fragment one policy
+ * decision across many rows (e.g. dozens of Partoo /proxy/... pages). Sentinel
+ * and non-URL tokens (inline, eval, data, blob, (none), ...) are kept verbatim.
+ */
+function csp_origin(string $value): string
+{
+    if ('' === $value || !\str_contains($value, '://')) {
+        return $value;
+    }
+    $parts = \parse_url($value);
+    if (false === $parts || !isset($parts['scheme'], $parts['host'])) {
+        return $value;
+    }
+    $origin = $parts['scheme'] . '://' . $parts['host'];
+
+    return isset($parts['port']) ? $origin . ':' . $parts['port'] : $origin;
+}
+
+// --- Argument parsing --------------------------------------------------------
+
+$options = \getopt('m:n:t:f:qh', [
+    'mode:',
+    'top:',
+    'type:',
+    'fields:',
+    'strip-query',
+    'max-keys:',
+    'progress',
+    'help',
+], $restIndex);
+
+if (false === $options) {
+    usage(EXIT_USAGE);
+}
+if (isset($options['h']) || isset($options['help'])) {
+    usage(EXIT_OK);
+}
+
+// getopt silently ignores unknown long options; reject them so a typo is a
+// clear usage error instead of being quietly discarded.
+$knownLong = ['fields', 'help', 'max-keys', 'mode', 'progress', 'strip-query', 'top', 'type'];
+for ($i = 1; $i < $restIndex; ++$i) {
+    $arg = (string) $GLOBALS['argv'][$i];
+    if (!\str_starts_with($arg, '--')) {
+        continue;
+    }
+    $name = \explode('=', \substr($arg, 2), 2)[0];
+    if ('' !== $name && !\in_array($name, $knownLong, true)) {
+        \fwrite(\STDERR, "error: unknown option '--{$name}'\n");
+        usage(EXIT_USAGE);
+    }
+}
+
+$mode = (string) ($options['m'] ?? $options['mode'] ?? 'summary');
+$type = (string) ($options['t'] ?? $options['type'] ?? 'csp-violation');
+$stripQuery = isset($options['q']) || isset($options['strip-query']);
+$progress = isset($options['progress']);
+$fieldsRaw = (string) ($options['f'] ?? $options['fields'] ?? '');
+$top = positive_int((string) ($options['n'] ?? $options['top'] ?? '15'), '--top');
+$maxKeys = positive_int((string) ($options['max-keys'] ?? '200000'), '--max-keys');
+
+if (!\in_array($mode, ['summary', 'json', 'tsv', 'ndjson'], true)) {
+    \fwrite(\STDERR, "error: unknown --mode '{$mode}'\n");
+    usage(EXIT_USAGE);
+}
+
+$defaultTsvFields = ['effectiveDirective', 'disposition', 'blockedURL', 'sourceFile', 'lineNumber', 'documentURL', 'sample'];
+$defaultSummaryFields = ['disposition', 'effectiveDirective', 'blockedURL', 'sourceFile', 'documentURL'];
+
+$fields = '' !== $fieldsRaw
+    ? \array_values(\array_filter(\array_map('trim', \explode(',', $fieldsRaw))))
+    : ('tsv' === $mode ? $defaultTsvFields : $defaultSummaryFields);
+
+$files = \array_slice($GLOBALS['argv'], $restIndex);
+foreach ($files as $file) {
+    // PHP getopt stops at the first positional, so any option after it lands
+    // here silently. Treat a dash-prefixed file (other than '-') as a misplaced
+    // option rather than a missing file.
+    if ('-' !== $file && \str_starts_with((string) $file, '-')) {
+        \fwrite(\STDERR, "error: options must precede FILE arguments, got '{$file}'\n");
+        usage(EXIT_USAGE);
+    }
+}
+if ([] === $files) {
+    $files = ['-'];
+}
+
+// Cheap pre-filter needle: the quoted type value appears verbatim in the JSON.
+$typeNeedle = 'all' === $type ? '' : '"' . $type . '"';
+
+// TSV header goes to stderr so stdout stays a clean data stream for piping.
+if ('tsv' === $mode) {
+    \fwrite(\STDERR, '# ' . \implode("\t", $fields) . "\n");
+}
+
+// --- Main streaming loop -----------------------------------------------------
+
+$startedAt = \microtime(true);
+$linesRead = 0;
+$reports = 0;
+$malformed = 0;
+
+$summaryTables = [];
+foreach ($fields as $field) {
+    $summaryTables[$field] = [];
+}
+$pairDirectiveSource = [];
+$pairDirectiveBlocked = [];
+
+$opened = 0;
+foreach ($files as $path) {
+    $handle = open_input($path);
+    if (null === $handle) {
+        continue;
+    }
+    ++$opened;
+
+    while (false !== ($line = \fgets($handle))) {
+        ++$linesRead;
+
+        if ($progress && 0 === $linesRead % 100000) {
+            \fwrite(\STDERR, \sprintf(
+                "\rprogress: %d lines, %d reports, %.1f MB peak ",
+                $linesRead,
+                $reports,
+                \memory_get_peak_usage(true) / 1048576,
+            ));
+        }
+
+        // Fast gate: skip lines that cannot hold the wanted report type.
+        if ('' !== $typeNeedle && !\str_contains($line, $typeNeedle)) {
+            continue;
+        }
+
+        $payload = extract_payload($line);
+        if (null === $payload) {
+            continue;
+        }
+
+        $data = \json_decode($payload, true);
+        if (!\is_array($data) || !isset($data['body']) || !\is_array($data['body'])) {
+            ++$malformed;
+            continue;
+        }
+        if ('all' !== $type && ($data['type'] ?? null) !== $type) {
+            // The line-level type needle above already discards most
+            // non-matching reports before decoding, so an accurate skipped
+            // count is impossible without decoding every line. The metric is
+            // therefore intentionally not reported.
+            continue;
+        }
+
+        ++$reports;
+        $body = $data['body'];
+
+        if ('ndjson' === $mode) {
+            echo \json_encode($data, \JSON_UNESCAPED_SLASHES), "\n";
+            continue;
+        }
+
+        if ('tsv' === $mode) {
+            $row = [];
+            foreach ($fields as $field) {
+                // Neutralize control bytes: keeps one record per line (tab/newline
+                // become \x09/\x0A) and defuses terminal escape injection.
+                $row[] = sanitize_controls(field_value($body, $field, $stripQuery));
+            }
+            echo \implode("\t", $row), "\n";
+            continue;
+        }
+
+        // summary mode
+        foreach ($fields as $field) {
+            bump($summaryTables[$field], field_value($body, $field, $stripQuery), $maxKeys);
+        }
+        $directive = field_value($body, 'effectiveDirective', $stripQuery);
+        $blockedOrigin = csp_origin(field_value($body, 'blockedURL', $stripQuery));
+        $disposition = field_value($body, 'disposition', $stripQuery);
+        bump($pairDirectiveSource, $directive . '  ⇐  ' . field_value($body, 'sourceFile', $stripQuery), $maxKeys);
+        bump($pairDirectiveBlocked, $directive . '  ⇐  ' . $blockedOrigin . '  [' . $disposition . ']', $maxKeys);
+    }
+
+    if (\STDIN !== $handle) {
+        \fclose($handle);
+    }
+}
+
+if ($progress) {
+    \fwrite(\STDERR, "\n");
+}
+
+if (0 === $opened) {
+    \fwrite(\STDERR, "error: no readable input\n");
+    exit(EXIT_NO_INPUT);
+}
+
+// --- Output ------------------------------------------------------------------
+
+if ('summary' === $mode) {
+    echo \sprintf("CSP report summary — %d report(s) from %d line(s)\n", $reports, $linesRead);
+    if ('all' !== $type) {
+        echo "type filter: {$type}\n";
+    }
+    foreach ($fields as $field) {
+        print_table($field, $summaryTables[$field], $top);
+    }
+    print_table('effectiveDirective ⇐ sourceFile', $pairDirectiveSource, $top);
+    print_table('effectiveDirective ⇐ blocked origin [disposition]', $pairDirectiveBlocked, $top);
+}
+
+if ('json' === $mode) {
+    $overflowKey = '(overflow: cardinality capped)';
+    $capped = isset($pairDirectiveSource[$overflowKey]) || isset($pairDirectiveBlocked[$overflowKey]);
+
+    $tables = [];
+    foreach ($fields as $field) {
+        $tables[$field] = table_report($summaryTables[$field], $top);
+        $capped = $capped || isset($summaryTables[$field][$overflowKey]);
+    }
+    $pairs = [
+        'effectiveDirective<=sourceFile' => table_report($pairDirectiveSource, $top),
+        'effectiveDirective<=blockedOrigin' => table_report($pairDirectiveBlocked, $top),
+    ];
+
+    $truncated = $capped;
+    foreach (\array_merge($tables, $pairs) as $report) {
+        if ($report['omitted'] > 0) {
+            $truncated = true;
+            break;
+        }
+    }
+
+    $document = [
+        'meta' => [
+            'generated_at' => \date('c'),
+            'type' => $type,
+            'files' => $opened,
+            'lines' => $linesRead,
+            'reports' => $reports,
+            'malformed' => $malformed,
+            'top' => $top,
+            'strip_query' => $stripQuery,
+            'max_keys' => $maxKeys,
+            'capped' => $capped,
+            'truncated' => $truncated,
+            'elapsed_s' => \round(\microtime(true) - $startedAt, 3),
+            'peak_mb' => \round(\memory_get_peak_usage(true) / 1048576, 1),
+        ],
+        'tables' => $tables,
+        'pairs' => $pairs,
+    ];
+    echo \json_encode($document, \JSON_PRETTY_PRINT | \JSON_UNESCAPED_SLASHES), "\n";
+}
+
+// Processing stats always go to stderr so they never pollute piped stdout.
+\fwrite(\STDERR, \sprintf(
+    "\n[stats] lines=%d reports=%d malformed=%d elapsed=%.2fs peak_mem=%.1fMB\n",
+    $linesRead,
+    $reports,
+    $malformed,
+    \microtime(true) - $startedAt,
+    \memory_get_peak_usage(true) / 1048576,
+));
+
+exit(EXIT_OK);

