+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\rgds_core\HookHandler\Form;
+
+use Drupal\Component\Utility\NestedArray;
+use Drupal\Core\Form\FormStateInterface;
+use Drupal\Core\StringTranslation\TranslatableMarkup;
+use Drupal\rgds_core\Enum\AllowedValues\HeroLayoutAllowedValues;
+
+final readonly class ToggleHeroBackgroundColorVisibilityHookHandler {
+
+  private const string LAYOUT_FIELD = 'field_image_display';
+
+  private const string BACKGROUND_COLOR_FIELD = 'field_background_color';
+
+  /**
+   * Carries the layout select #parents up to the validation callback.
+   */
+  private const string LAYOUT_PARENTS_PROPERTY = '#rgds_layout_parents';
+
+  /**
+   * Add conditional behavior in admin Hero paragraph form.
+   */
+  public function formAlter(array &$element): void {
+    if ('hero' !== ($element['#paragraph_type'] ?? '')) {
+      return;
+    }
+
+    $layoutParents = $element['subform'][self::LAYOUT_FIELD]['widget']['#parents'] ?? NULL;
+    if (FALSE === \is_array($layoutParents)) {
+      return;
+    }
+
+    $iconSelected = [
+      \sprintf(':input[name="%s"]', $this->buildInputName($layoutParents)) => [
+        'value' => HeroLayoutAllowedValues::BackgroundIcon->value,
+      ],
+    ];
+
+    // The background color is only relevant for the "icon on color" layout.
+    $element['subform'][self::BACKGROUND_COLOR_FIELD]['#states']['visible'] = $iconSelected;
+
+    // #states only handles the client side: the server side requirement is
+    // enforced by the element validate callback below.
+    $element['subform'][self::BACKGROUND_COLOR_FIELD]['widget']['#states']['required'] = $iconSelected;
+    $element['subform'][self::BACKGROUND_COLOR_FIELD]['widget'][self::LAYOUT_PARENTS_PROPERTY] = $layoutParents;
+    $element['subform'][self::BACKGROUND_COLOR_FIELD]['widget']['#element_validate'][] = [
+      self::class,
+      'validateBackgroundColor',
+    ];
+  }
+
+  /**
+   * Requires the background color only when the icon layout is selected.
+   */
+  public static function validateBackgroundColor(array $element, FormStateInterface $formState): void {
+    $layoutParents = $element[self::LAYOUT_PARENTS_PROPERTY] ?? NULL;
+    if (FALSE === \is_array($layoutParents)) {
+      return;
+    }
+
+    // We validate not empty choice for background color only with background icon as layout.
+    $layoutFromInput = NestedArray::getValue($formState->getUserInput(), $layoutParents);
+    $heroLayoutChoice = HeroLayoutAllowedValues::tryFrom(\is_string($layoutFromInput) ? $layoutFromInput : '');
+    $layoutIsBackgroundIcon = $heroLayoutChoice && HeroLayoutAllowedValues::BackgroundIcon === $heroLayoutChoice;
+    if (FALSE === $layoutIsBackgroundIcon) {
+      return;
+    }
+
+    $value = $element['#value'] ?? '';
+    if ('' !== $value && '_none' !== $value) {
+      return;
+    }
+
+    $formState->setError(
+      $element,
+      new TranslatableMarkup(
+        '@name field is required.',
+        ['@name' => $element['#title']],
+      ),
+    );
+  }
+
+  /**
+   * Builds the HTML "name" attribute (e.g. field_item[0][subform][field_x]) from a #parents array.
+   */
+  private function buildInputName(array $parents): string {
+    $name = '';
+    foreach (\array_values($parents) as $index => $parent) {
+      $name .= 0 === $index ? (string) $parent : '[' . (string) $parent . ']';
+    }
+
+    return $name;
+  }
+
+}

