+
+  /**
+   * Create a container with the supplied enabled modules.
+   *
+   * @param array<string, string> $modules
+   *   The enabled modules, keyed by machine name.
+   */
+  private function containerWithModules(array $modules): ContainerBuilder {
+    $container = new ContainerBuilder();
+    $container->setParameter('container.modules', $modules);
+    $container->register(self::CSP_EVENT_SUBSCRIBER_SERVICE);
+
+    return $container;
