+
+    return;
+  }
+
+  foreach ($bannerItems as $banner) {
+    if (FALSE === $banner->hasField('field_subtitle') || FALSE === $banner->hasField('field_rich_subtitle')) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $subtitleField = $banner->get('field_subtitle');
+    if ($subtitleField->isEmpty()) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $subtitleValue = $subtitleField->value;
+    if (FALSE === \is_string($subtitleValue) || '' === $subtitleValue) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    if (FALSE === $banner->get('field_rich_subtitle')->isEmpty()) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $banner->set('field_rich_subtitle', [
+      'value' => \sprintf('<p>%s</p>', Html::escape($subtitleValue)),
+      'format' => 'rte_minimal',
+    ]);
+
+    $banner->save();
+    $sandbox['progress']++;
+  }
+
+  if ($sandbox['progress'] === $sandbox['total']) {
+    $sandbox['#finished'] = 1;
+
+    return;
+  }
+
+  $sandbox['#finished'] = $sandbox['progress'] / $sandbox['total'];
+}

