+/*
+ * Couche base partagée : parité avec le Preflight de Tailwind 3, variables de thème runtime
+ * et règles globales. Consommé via ./preset.css.
+ */
+
+@layer base {
+  /* Preflight v3 : curseur pointeur sur les boutons (v4 : `cursor: default`). */
+  button:not(:disabled),
+  [role='button']:not(:disabled) {
+    cursor: pointer;
+  }
+
+  /* Preflight v3 : couleur de bordure par défaut = gray-300 (v4 : `currentColor`). */
+  *,
+  ::after,
+  ::before,
+  ::backdrop,
+  ::file-selector-button {
+    border-color: var(--color-gray-300, #ededed);
+  }
+
+  /* Preflight v3 : placeholder gray-400 (v4 : couleur courante à 50 %). */
+  input::placeholder,
+  textarea::placeholder {
+    color: var(--color-gray-400, #e0e0e0);
+  }
+
+  /* Preflight v3 : fond des champs laissé au navigateur (v4 : `background-color: transparent`). */
+  input,
+  select,
+  textarea {
+    background-color: revert-layer;
+  }
+
+  :root {
+    --content-primary: #3f3f3f;
+    --background-brand-primary: #0d3050;
+    --shadow-level-0: '0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)';
+  }
+}
+
+/* Parité v3 : `hover:` s'applique sans `@media (hover: hover)`. */
+@custom-variant hover (&:hover);
+
+/* ===== MISCELLANOUS ===== */
+
+html {
+  font-size: 100%;
+  letter-spacing: 0.03rem;
+  @apply leading-tight font-default;
+}
+
+.font-semibold,
+.font-medium {
+  @apply tracking-normal;
+}
+
+input,
+textarea {
+  letter-spacing: 0.03rem;
+  @apply font-default;
+}
+
+body {
+  font-size: 1rem;
+}
+
+button:focus,
+a:focus {
+  outline: 2px solid blue;
+}
+
+/* ===== THEMES ===== */
+
+/*
+ * Volontairement hors `@layer base` : en v4 les couches de cascade sont réelles, et une règle
+ * layered perdrait face au CSS non-layered des composants (Select.css injecté au runtime),
+ * quelle que soit sa spécificité.
+ */
+html[data-theme='ramsayservices'] {
+  --content-primary: #222222;
+  --background-brand-primary: #1469d6;
+  --shadow-level-0: 0px 4px 30px rgb(0 0 0 / 10%);
+
+  .Form_Select__Wrapper .Form_Select__control {
+    @apply rounded min-h-70;
+  }
+
+  .Form_Select__Wrapper .Form_Select__indicators {
+    @apply bg-white rounded;
+  }
+
+  .Form_Select__Action {
+    bottom: 28px;
+  }
+}

