+#!/usr/bin/env php
+<?php
+
+/**
+ * @file
+ * Parse and summarize CSP (Content-Security-Policy) violation reports.
+ *
+ * Reads RGDS "reporting" Monolog log files where each line embeds a Reporting
+ * API payload as pretty-printed JSON wrapped in <pre>...</pre>, e.g.:
+ *
+ *   [2026-09-14T18:27:06+02:00] reporting.INFO: default <br/> <pre>{ "type":
+ *   "csp-violation", "body": { "effectiveDirective": "style-src-attr", ... } }
+ *   </pre> [] {"ip":"...","request_uri":"...","uid":"1","user":"admin"}
+ *
+ * The script streams input line by line (constant memory, safe on multi-GB /
+ * multi-million-line logs), transparently reads gzip-rotated files (*.gz), and
+ * accepts several files and/or stdin. It has no Drupal dependency so it can run
+ * on the production server with a plain PHP CLI.
+ *
+ * Usage examples:
+ *   scripts/csp-report.php app/logs/reporting/reporting-handler-2026-09-14.log
+ *   scripts/csp-report.php --top=20 /var/log/reporting/*.log*
+ *   scripts/csp-report.php --mode=json /var/log/reporting/*.log*  # for agents/CI
+ *   zcat /var/log/reporting/*.gz | scripts/csp-report.php -
+ *   scripts/csp-report.php --mode=tsv logs/*.log | sort | uniq -c | sort -rn
+ *   scripts/csp-report.php --mode=ndjson logs/*.gz | json_pp   # clean NDJSON
+ *
+ * See --help for all options.
+ */
+
+declare(strict_types=1);
+
+const EXIT_OK = 0;
+const EXIT_USAGE = 2;
+const EXIT_NO_INPUT = 3;
+
+/**
+ * Print usage and exit.
+ */
+function usage(int $code = EXIT_OK): never
+{
+    $self = \basename($GLOBALS['argv'][0] ?? 'csp-report.php');
+    \fwrite(\STDERR, <<<TXT
+Parse and summarize CSP violation reports from RGDS reporting logs.
+
+Usage:
+    {$self} [options] [FILE ...]
+
+FILE may be a plain or gzip (*.gz) log file. Use '-' or no FILE to read stdin.
+Several files may be given; they are processed as one stream.
+
+Options:
+    -m, --mode=MODE      summary (default) | json | tsv | ndjson
+                           summary : aggregated top-N tables (human readable)
+                           json    : single aggregated JSON object (agent friendly)
+                           tsv     : one row per report, streamed (pipe to sort/awk)
+                           ndjson  : one compact JSON object per report, streamed
+    -n, --top=N          Rows kept per table in summary mode (default: 15)
+    -t, --type=TYPE      Report 'type' to keep (default: csp-violation; 'all' = any)
+    -f, --fields=LIST    Comma-separated body fields for tsv / summary tables.
+                         Default tsv    : effectiveDirective,disposition,blockedURL,
+                                           sourceFile,lineNumber,documentURL,sample
+                         Default summary: disposition,effectiveDirective,blockedURL,
+                                           sourceFile,documentURL
+    -q, --strip-query    Strip ?query and #fragment from URL fields (lowers cardinality).
+        --max-keys=N     Distinct keys tracked per table before overflow bucket
+                         (summary only, protects memory; default: 200000).
+        --progress       Print progress to stderr every 100k lines.
+    -h, --help           Show this help.
+
+Exit codes: 0 ok, 2 usage error, 3 no readable input.
+
+TXT);
+    exit($code);
+}
+
+/**
+ * Open a path as a readable stream, transparently handling gzip and stdin.
+ *
+ * @return resource|null
+ */
+function open_input(string $path)
+{
+    if ('-' === $path) {
+        return \STDIN;
+    }
+    if (!\is_file($path)) {
+        \fwrite(\STDERR, "warning: not a file, skipping: {$path}\n");
+
+        return null;
+    }
+    $url = \str_ends_with($path, '.gz') ? 'compress.zlib://' . $path : $path;
+    $handle = @\fopen($url, 'rb');
+    if (false === $handle) {
+        \fwrite(\STDERR, "warning: cannot open, skipping: {$path}\n");
