+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\Tests\rgds_core\Kernel\PostUpdate;
+
+use Drupal\Core\Entity\EntityStorageInterface;
+use Drupal\Tests\rgds_core\Kernel\KernelTestBase;
+use Drupal\paragraphs\ParagraphInterface;
+
+// phpcs:disable Drupal.Commenting.DocComment
+final class BannerFieldSubtitleToFieldRichSubtitleTest extends KernelTestBase {
+
+  /**
+   * {@inheritdoc}
+   */
+  protected static $modules = [
+    // Required to use editor format with fields.
+    'editor',
+    'filter',
+    'linkit',
+    // Used in test.
+    'paragraphs',
+    'paragraphs_limits',
+    'entity_reference_revisions',
+    'media',
+  ];
+
+  private EntityStorageInterface $paragraphStorage;
+
+  protected function setUpBeforeInstallSiteConfig(): void {
+    $this->installSchema('file', ['file_usage']);
+    $this->installEntitySchema('file');
+    $this->installEntitySchema('media');
+    $this->installEntitySchema('paragraph');
+  }
+
+  protected function setUp(): void {
+    parent::setUp();
+
+    $this->paragraphStorage = \Drupal::entityTypeManager()->getStorage('paragraph');
+
+    require_once __DIR__ . '/../../../../rgds_core.post_update.php';
+  }
+
+  public function testItShouldMigrateEverySubtitleWhenMoreBannersThanTheBatchLimitExist(): void {
+    $batchLimit = 10;
+    $numberOfBanners = $batchLimit * 2 + 3;
+
+    for ($i = 0; $i < $numberOfBanners; $i++) {
+      $this->createBanner(\sprintf('Sous-titre %d', $i));
+    }
+
+    $numberOfPasses = $this->runPostUpdate($numberOfBanners);
+
+    self::assertSame(3, $numberOfPasses, 'The batch limit should be honoured.');
+
+    foreach ($this->loadBanners() as $banner) {
+      self::assertSame(
+        \sprintf('<p>%s</p>', $banner->get('field_subtitle')->value),
+        $banner->get('field_rich_subtitle')->value,
+      );
+      self::assertSame('rte_minimal', $banner->get('field_rich_subtitle')->format);
+    }
+  }
+
+  public function testItShouldEscapeTheSubtitleWhenItContainsMarkup(): void {
+    $this->createBanner('Maternité & <b>pédiatrie</b>');
+
+    $this->runPostUpdate(1);
+
+    $banner = $this->loadTheOnlyBanner();
+    self::assertSame(
+      '<p>Maternité &amp; &lt;b&gt;pédiatrie&lt;/b&gt;</p>',
+      $banner->get('field_rich_subtitle')->value,
+    );
+  }
+
+  public function testItShouldLeaveTheRichSubtitleUntouchedWhenItIsAlreadyFilled(): void {
+    $this->createBanner('Sous-titre', [
+      'value' => '<p>Déjà rédigé</p>',
+      'format' => 'rte_minimal',
+    ]);
+
+    $this->runPostUpdate(1);
+
+    $banner = $this->loadTheOnlyBanner();
+    self::assertSame('<p>Déjà rédigé</p>', $banner->get('field_rich_subtitle')->value);
+  }
+
+  public function testItShouldLeaveTheRichSubtitleEmptyWhenThereIsNoSubtitle(): void {
+    $this->createBanner(NULL);
+
+    $this->runPostUpdate(1);
+
+    self::assertTrue($this->loadTheOnlyBanner()->get('field_rich_subtitle')->isEmpty());
+  }
+
+  public function testItShouldIgnoreParagraphsOfAnotherType(): void {
+    $contact = $this->paragraphStorage->create([
+      'type' => 'contact',
+      'field_title' => 'Titre du contact',
+    ]);
+    $contact->save();
+
+    $sandbox = [];
+    \rgds_core_post_update_banner_field_subtitle_to_field_rich_subtitle($sandbox);
+
+    self::assertSame(1, $sandbox['#finished']);
+    self::assertSame(0, $sandbox['total']);
+
+    $this->paragraphStorage->resetCache();
+    /** @var \Drupal\paragraphs\ParagraphInterface $contact */
+    $contact = $this->paragraphStorage->load($contact->id());
+    self::assertTrue($contact->get('field_rich_subtitle')->isEmpty());
+  }
+
+  public function testItShouldFinishImmediatelyWhenThereIsNoBanner(): void {
+    $sandbox = [];
+    \rgds_core_post_update_banner_field_subtitle_to_field_rich_subtitle($sandbox);
+
+    self::assertSame(1, $sandbox['#finished']);
+    self::assertSame(0, $sandbox['total']);
+  }
+
+  /**
+   * Run the post update until it reports being finished.
+   *
+   * @return int
+   *   The number of passes it took.
+   */
+  private function runPostUpdate(int $expectedTotal): int {
+    $sandbox = [];
+    $numberOfPasses = 0;
+
+    do {
+      \rgds_core_post_update_banner_field_subtitle_to_field_rich_subtitle($sandbox);
+      $numberOfPasses++;
+
+      self::assertSame($expectedTotal, $sandbox['total']);
+      self::assertLessThanOrEqual($expectedTotal, $sandbox['progress']);
+      self::assertLessThan(50, $numberOfPasses, 'The post update does not converge.');
+    } while (1 !== ($sandbox['#finished'] ?? 1));
+
+    self::assertSame($expectedTotal, $sandbox['progress']);
+    $this->paragraphStorage->resetCache();
+
+    return $numberOfPasses;
+  }
+
+  private function createBanner(?string $subtitle, string|array|null $richSubtitle = NULL): ParagraphInterface {
+    /** @var \Drupal\paragraphs\ParagraphInterface $banner */
+    $banner = $this->paragraphStorage->create([
+      'type' => 'banner',
+      'field_subtitle' => $subtitle,
+      'field_rich_subtitle' => $richSubtitle,
+    ]);
+    $banner->save();
+
+    return $banner;
+  }
+
+  private function loadBanners(): array {
+    return $this->paragraphStorage->loadByProperties(['type' => 'banner']);
+  }
+
+  private function loadTheOnlyBanner(): ParagraphInterface {
+    $banners = $this->loadBanners();
+    self::assertCount(1, $banners);
+
+    return \reset($banners);
+  }
+
+}

