+/**
+ * Migrate banner short text field_subtitle field to long rich text field_rich_subtitle.
+ *
+ * @param array{"total"?: int, "progress": int, "#finished"?: int|float} $sandbox
+ *   Batch state.
+ *
+ * @SuppressWarnings("PHPMD.CyclomaticComplexity")
+ * @SuppressWarnings("PHPMD.NPathComplexity")
+ */
+function rgds_core_post_update_banner_field_subtitle_to_field_rich_subtitle(array &$sandbox): void {
+  $batchLimit = 10;
+
+  $database = \Drupal::database();
+  $baseQuery = $database->select('paragraphs_item');
+  $baseQuery->addField('paragraphs_item', 'id');
+  $baseQuery->condition('type', 'banner');
+
+  if (FALSE === isset($sandbox['total'])) {
+    $sandbox['progress'] = 0;
+    $countQuery = clone $baseQuery;
+
+    $countStatement = $countQuery->countQuery()->execute();
+
+    if (!$countStatement instanceof StatementInterface) {
+      $sandbox['#finished'] = 1;
+
+      return;
+    }
+
+    /** @var string $count */
+    $count = $countStatement->fetchField();
+    $sandbox['total'] = (int) $count;
+  }
+
+  $statement = $baseQuery
+    ->range($sandbox['progress'], $batchLimit)
+    ->orderBy('id')
+    ->execute();
+
+  if (FALSE === ($statement instanceof StatementInterface)) {
+    $sandbox['#finished'] = 1;
+
+    return;
+  }
+  /** @var array<int|string> $bannerItemsIds */
+  $bannerItemsIds = $statement->fetchAll(\PDO::FETCH_COLUMN);
+  $paragraphStorage = \Drupal::entityTypeManager()->getStorage('paragraph');
+  $bannerItems = $paragraphStorage->loadMultiple($bannerItemsIds);
+
+  if ([] === $bannerItems) {
+    $sandbox['#finished'] = 1;
+
+    return;
+  }
+
+  foreach ($bannerItems as $banner) {
+    if (FALSE === $banner->hasField('field_subtitle') || FALSE === $banner->hasField('field_rich_subtitle')) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $subtitleField = $banner->get('field_subtitle');
+    if ($subtitleField->isEmpty()) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $subtitleValue = $subtitleField->value;
+    if (FALSE === \is_string($subtitleValue) || '' === $subtitleValue) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    if (FALSE === $banner->get('field_rich_subtitle')->isEmpty()) {
+      $sandbox['progress']++;
+      continue;
+    }
+
+    $banner->set('field_rich_subtitle', [
+      'value' => \sprintf('<p>%s</p>', Html::escape($subtitleValue)),
+      'format' => 'rte_minimal',
+    ]);
+
+    $banner->save();
+    $sandbox['progress']++;
+  }
+
+  if ($sandbox['progress'] === $sandbox['total']) {
+    $sandbox['#finished'] = 1;
+
+    return;
+  }
+
+  $sandbox['#finished'] = $sandbox['progress'] / $sandbox['total'];
