+/*
+ * Utilitaires custom et composants partagés (BEM, utilisés notamment par les templates Twig
+ * du repo Drupal). Consommé via ./preset.css.
+ */
+
+/* ===== CUSTOM UTILITIES ===== */
+
+@utility flex-basis {
+  flex-basis: 100%;
+  height: 0;
+}
+
+/* ex `theme.transitionProperty.space` : comme en v3, ne fixe que la propriété
+   (durée et timing via `duration-*` / `ease-*`). */
+@utility transition-space {
+  transition-property: width, height, padding;
+}
+
+/*
+ * ex `theme.container.padding` : complète le `container` natif (max-width par breakpoint).
+ * Dans la couche `components` et non en `@utility container` : en v3 ce padding vivait dans les
+ * composants, donc n'importe quel utilitaire de padding (`p-10`, `px-0`…) posé à côté de `container`
+ * l'emportait. Un `@utility container` serait trié parmi les utilitaires, après `p-*`, et gagnerait.
+ */
+@layer components {
+  .container {
+    padding-inline: 1rem;
+  }
+}
+
+/* ===== CONTRIBUTION UTILITIES ===== */
+
+.rich-contribution ul li::before {
+  content: '\2022';
+  @apply inline-block w-4 mr-12 font-semibold tracking-normal text-orange-500;
+}
+
+.rich-contribution a {
+  @apply underline;
+}
+
+.rich-contribution a:hover {
+  @apply text-orange-500;
+}
+
+/* ===== BUTTON UTILITIES ===== */
+
+/** BASE **/
+/* Base commune aux boutons React (Button.css) : sans padding ni justify, gérés par Button.tsx. */
+@utility btn-base {
+  @apply inline-flex items-center font-semibold leading-none tracking-normal transition duration-200 ease-in-out border-2 rounded-full;
+}
+
+/* Base des boutons BEM (`btn btn--primary`, templates Twig). */
+@utility btn {
+  @apply btn-base justify-between px-20;
+}
+
+/** SIZES **/
+.btn--big {
+  min-height: 56px;
+  min-width: 56px;
+}
+
+.btn--big > svg {
+  @apply text-24;
+}
+
+.btn--big > * + * {
+  @apply ml-12;
+}
+
+.btn--small {
+  min-height: 40px;
+  min-width: 40px;
+}
+
+.btn--small > svg {
+  @apply text-18;
+}
+
+.btn--small > * + * {
+  @apply ml-8;
+}
+
+/** VARIANTS **/
+/** VARIANTS - Primary **/
+.btn--primary {
+  @apply text-white bg-brand-500 border-brand-500 btn;
+}
+
+.btn--primary:hover {
+  @apply bg-transparent text-brand-500;
+}
+
+/** VARIANTS - Primary Ghost **/
+.btn--primary-ghost {
+  @apply bg-transparent text-brand-500 border-brand-500 btn;
+}
+
+.btn--primary-ghost:hover {
+  @apply text-white bg-brand-500;
+}
+
+/** VARIANTS - Secondary **/
+.btn--secondary {
+  @apply bg-white border-white text-brand-500 btn;
+}
+
+.btn--secondary:hover {
+  @apply text-white bg-brand-500;
+}
+
+/** VARIANTS - Secondary Ghost **/
+.btn--secondary-ghost {
+  @apply text-white bg-transparent border-white btn;
+}
+
+.btn--secondary-ghost:hover {
+  @apply bg-white text-brand-500;
+}
+
+/** VARIANTS - Tertiary **/
+.btn--tertiary {
+  @apply text-white border-secondaryblue-500 bg-secondaryblue-500 btn;
+}
+
+.btn--tertiary:hover {
+  @apply text-white bg-secondaryblue-800 border-secondaryblue-800;
+}
+
+/** VARIANTS - Tertiary Ghost **/
+.btn--tertiary-ghost {
+  @apply bg-transparent text-secondaryblue-500 border-secondaryblue-500 btn;
+}
+
+.btn--tertiary-ghost:hover {
+  @apply bg-white text-secondaryblue-500;
+}
+
+/** VARIANTS - Black **/
+.btn--black {
+  @apply text-white bg-black border-black btn;
+}
+
+.btn--black:hover {
+  @apply text-black bg-white border-black;
+}
+
+/** VARIANTS - Black Ghost **/
+.btn--black-ghost {
+  @apply text-black bg-transparent border-black btn;
+}
+
+.btn--black-ghost:hover {
+  @apply text-black bg-white;
+}
+
+/** VARIANTS - White **/
+.btn--white {
+  @apply bg-white border-white text-brand-500 btn;
+}
+
+.btn--white:hover {
+  @apply text-white bg-transparent border-white;
+}
+
+/** VARIANTS - White Ghost **/
+.btn--white-ghost {
+  @apply text-white bg-transparent border-white btn;
+}
+
+.btn--white-ghost:hover {
+  @apply bg-white border-white text-brand-500;
+}
+
+/** VARIANTS - Link **/
+.btn--link {
+  @apply leading-none text-blue-500 text-16;
+}
+
+.btn--link:hover {
+  @apply text-blue-800;
+}
+
+/* ===== DRUPAL HIDDEN ===== */
+
+/* Needed for compatibility with https://github.com/drupal/drupal/blob/9.4.x/core/modules/system/css/components/hidden.module.css */
+
+/**
+ * Hide elements visually, but keep them available for screen readers.
+ *
+ * Used for information required for screen reader users to understand and use
+ * the site where visual display is undesirable. Information provided in this
+ * manner should be kept concise, to avoid unnecessary burden on the user.
+ * "!important" is used to prevent unintentional overrides.
+ */
+.visually-hidden {
+  position: absolute !important;
+  overflow: hidden;
+  clip: rect(1px, 1px, 1px, 1px);
+  width: 1px;
+  height: 1px;
+  word-wrap: normal;
+}
+
+/**
+ * The .focusable class extends the .visually-hidden class to allow
+ * the element to be focusable when navigated to via the keyboard.
+ */
+.visually-hidden.focusable:active,
+.visually-hidden.focusable:focus {
+  position: static !important;
+  overflow: visible;
+  clip: auto;
+  width: auto;
+  height: auto;
+}

